/**
 * AI/ML 모델 레지스트리 엔터티입니다. 실서비스에 사용될 수 있는 머신러닝/딥러닝/알고리즘 모델을 관리하며, 각각 이름, 타입, 설명,
 * 소유 조직/관리자 등이 원자적으로 정규화됩니다. 모델 버전, deploy, evidence/audit 연동 필요. 자세한 필드는 요구분석과
 * Prisma schema의 ai_models를 참고하세요.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAiModel = {
  /** 모델 레코드 유일 식별자 */
  id: string & tags.Format<"uuid">;

  /** 소유 조직 UUID */
  organization_id: string & tags.Format<"uuid">;

  /** 모델 관리 담당 유저 UUID */
  owner_id: string & tags.Format<"uuid">;

  /** 모델명(조직 내 유일) */
  name: string;

  /** 모델 유형(추천/분류/가격/이상탐지 등), enum/string */
  model_type: string;

  /** 모델 설명, 운영∙거버넌스용 */
  description?: string;

  /** 생성 시각 */
  created_at: string & tags.Format<"date-time">;

  /** 마지막 업데이트 시각 */
  updated_at: string & tags.Format<"date-time">;
};
export namespace IAiModel {
  /**
   * AI 모델 카탈로그 리스트에서 사용되는 검색/필터/페이지네이션 요청 타입입니다. 모델 타입, 관리자(소유자), 조직,
   * 생성일/업데이트일 등 다양한 조건 검색을 지원합니다. 모델 운영·분석·컴플라이언스 대시보드, AI 거버넌스/감사요건, 버전 및
   * 멀티채널 모델 비교 등에 활용합니다.
   */
  export type IRequest = {
    /** AI/ML 모델 분류(예: 'recommendation', 'pricing', 'sentiment', 'fraud'). */
    model_type?: string;

    /** 모델명 부분/완전 일치 검색용. */
    name?: string;

    /** 해당 조직(tenant) 기준 필터; B2B, partner, 멀티테넌트 지원. */
    organization_id?: string & tags.Format<"uuid">;

    /** 모델 소유자/관리자(user id) 조건. */
    owner_id?: string & tags.Format<"uuid">;

    /** 생성일(이후/이상) 범위 필터. */
    created_from?: string & tags.Format<"date-time">;

    /** 생성일(이전/이하) 범위 필터. */
    created_to?: string & tags.Format<"date-time">;

    /** 업데이트일(이후) 필터. */
    updated_from?: string & tags.Format<"date-time">;

    /** 업데이트일(이전) 필터. */
    updated_to?: string & tags.Format<"date-time">;

    /** 페이지 번호(1-base). */
    page?: number & tags.Type<"int32"> & tags.Default<1>;

    /** 한 페이지당 최대 결과 수. */
    limit?: number & tags.Type<"int32"> & tags.Default<100>;
  };

  /**
   * AI 모델 메타데이터 신규 등록 시 사용되는 요청 타입입니다. 이름, 모델 타입, 조직/소유자, 설명 필수. 생성시점 이벤트는
   * evidence/audit 로그로 기록됩니다.
