import { tags } from "typia";

/**
 * AI 모델 artifact/버전 엔티티. 버전별 해시, artifact_url, 프레임워크, 메타데이터, 생성/배포일, 소속 모델을
 * atomic하게 보유. 모델 거버넌스, explainability, ML A/B 실험 및 감사에 필수.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAiModelVersion = {
  /** 모델버전 PK */
  id: string & tags.Format<"uuid">;

  /** 부모 모델 FK */
  ai_model_id: string & tags.Format<"uuid">;

  /** 버전 레이블(v1.2.3 등, artifact 식별자) */
  version: string;

  /** 머신 해시(sha256 등), 솔루션 증적/evidence */
  version_hash: string;

  /** Artifact(모델) URI, external storage/S3 등 */
  artifact_url: string;

  /** ML프레임워크개발(예: TensorFlow, PyTorch) */
  framework: string;

  /** 에비던스+메타데이터(JSON) */
  metadata?: string;

  /** 등록시각 */
  created_at: string & tags.Format<"date-time">;

  /** 리스너 배포 적용시각(배포 전이면 null모드) */
  deployed_at?: string & tags.Format<"date-time">;
};
export namespace IAiModelVersion {
  /**
   * AI 모델 버전(artifact) 카탈로그 검색·룩업용 요청. 모형, 버전코드, 배포상태, 생성일자 등 필터링/페이징 지원.
   * MLOps, AI거버넌스 대시보드, 드리프트/배포 모니터링 등에서 사용.
   */
  export type IRequest = {
    /** 소속 모델(부모 ai_model) UUID. 특정 모델 버전만 쿼리 시 필수 */
    ai_model_id?: string & tags.Format<"uuid">;

    /** 버전코드(v1.2.3 등), partial match 풀이 지원 */
    version?: string;

    /** TensorFlow, PyTorch, sklearn 등 ML프레임워크 필터 */
    framework?: string;

    /** 생성시각(이후/이상) 필터 */
    created_from?: string & tags.Format<"date-time">;

    /** 생성시각(이전/이하) 필터 */
    created_to?: string & tags.Format<"date-time">;

    /** 배포여부(실서비스 사용 experience) */
    deployed?: boolean;
  };

  /**
   * AI 모델 artifact 신규 등록 시 사용(모델 버전레코드 추가). 필수: 버전명, 해시, artifact uri, 프레임워크,
   * parent 모델ID, 서버타임
   */
  export type ICreate = {
    /** 부모 모델 UUID, 필수. */
    ai_model_id: string & tags.Format<"uuid">;

    /** 버전코드(필수) */
    version: string;

    /** 모델 artifact 해시/증적(필수) */
    version_hash: string;

    /** 저장된(외부) artifact S3/계층 URI */
    artifact_url: string;

    /** 머신러닝 프레임워크 */
    framework: string;

    /** 메타/하이퍼파라, 설명등(JSON) */
    metadata?: string;
  };

  /**
   * 이미 등록된 모델 artifact(버전) 정보수정. 버전명, 해시, URI, 프레임워크, 메타데이터, 배포시각만 갱신 가능하며
   * audit chain 필요.
   */
  export type IUpdate = {
    /** 버전코드 갱신(유일/PK는 불변) */
    version?: string;

    /** Artifact 증적 변경 */
    version_hash?: string;

    /** URI 변경 */
    artifact_url?: string;

    /** 프레임워크 정보 */
    framework?: string;

    /** 메타데이터 수정(파라미터 등) */
    metadata?: string;

    /** 배포(혹은 생산배포) 시각 */
    deployed_at?: string & tags.Format<"date-time">;
  };
}

