src/api/structures/IAiTrainingData.ts:
import { tags } from "typia";

/**
 * Describes a dataset registered in the system for AI/ML training purposes, as
 * defined in the ai_training_data Prisma schema and requirements on continuous
 * learning and model explainability.
 *
 * Includes metadata for traceability (name, version, source_uri),
 * schema/evidence (schema_hash), and linkage to AI model registry
 * (ai_model_id).
 *
 * Supports data governance functions, including provenance, auditability,
 * regulatory/reporting, and feedback for ML lifecycle operations.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAiTrainingData = {
  /**
   * Primary Key. Unique identifier for the AI training dataset. References
   * ai_training_data.id in the AdvancedAI Prisma schema.
   *
   * This field is evidence-grade and immutable.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Optional reference to the associated AI model (ai_models.id). For
   * traceability and provenance, enabling tracking of datasets used for a
   * model family. Nullable if dataset is not bound to a specific model.
   */
  ai_model_id?: (string & tags.Format<"uuid">) | null;

  /**
   * Human-friendly dataset name (e.g., '2024Q1-purchases'). Required and
   * unique in combination with version and source_uri. Enables clear
   * identification in audit logs, reporting, and ML/analytics UI.
   */
  name: string;

  /**
   * Version identifier (e.g., 'v1', '202404'). Required to distinguish
   * individual dataset versions for reproducibility, evidence trace, and
   * compliance.
   */
  version: string;

  /**
   * URI to the immutable source dataset (e.g., S3, GCS, file path). Required
   * for provenance, legal/regulatory audits, and supporting data
   * reproducibility in ML.
   */
  source_uri: string;

  /**
   * Cryptographic hash of the dataset schema used for integrity, provenance,
   * and regulatory proof of structure. Aids in detecting dataset drift,
   * tampering, or schema upgrades.
   */
  schema_hash: string;

  /**
   * Optional. Number of records (rows) in the dataset. Provided for audit
   * evidence, reporting, and estimation of ML training scope. May be null if
   * not reported or for external datasets.
   */
  record_count?: (number & tags.Type<"int32">) | null;

  /**
   * Creation timestamp, capturing when the dataset registry entry was added.
   * Required for evidence, audit, and compliance reporting.
   */
  created_at: string & tags.Format<"date-time">;
};
export namespace IAiTrainingData {
  /**
   * AI 훈련 데이터셋 목록/검색 요청 스키마입니다. 데이터셋명, 버전, 모델, 생성일, 레코드수, 소스URI, 해시 등 검색과
   * 페이징을 지원합니다. 사용처: 데이터 거버넌스, 증적, MLOps 대시보드, AI 컴플라이언스 보고 등.
   */
  export type IRequest = {
    /** 데이터셋명(부분/정확검색) */
    name?: string;

    /** 버전명, 버전 범위, analytics 등 */
    version?: string;

    /** 참조 모델/알고리즘 id */
    ai_model_id?: string & tags.Format<"uuid">;

    /** 해시, JSON schema 등 구조의 증적 유효성 조사 */
    schema_hash?: string;

    /** 레코드수 하한 필터 */
    record_count_from?: number & tags.Type<"int32">;

    /** 레코드수 상한 필터 */
    record_count_to?: number & tags.Type<"int32">;

    /** 생성일 범위 하한 */
    created_from?: string & tags.Format<"date-time">;

    /** 생성일 범위 상한 */
    created_to?: string & tags.Format<"date-time">;

    /** 페이지 번호 */
    page?: number & tags.Type<"int32"> & tags.Default<1>;

    /** 한 페이지 최대 결과 수 */
    limit?: number & tags.Type<"int32"> & tags.Default<100>;
  };
}

