   * filtering by username, email, organizational context, RBAC assignment,
   * and lifecycle events. Pagination fields (page, limit) support
   * horizontally scalable result delivery. All queries are evidence-logged
   * for regulatory compliance.
   */
  export type IRequest = {
    /**
     * The username to search for. Referenced from Core.users.username. May
     * be a partial match, supports advanced search operations. Example:
     * 'john'.
     */
