    /**
     * Earliest user creation time (inclusive). Used as a lower bound for
     * Core.users.created_at. Example: '2025-01-01T00:00:00Z'.
     */
    created_from?: string & tags.Format<"date-time">;

    /**
     * Latest user creation time (inclusive). Used as an upper bound for
     * Core.users.created_at.
     */
    created_to?: string & tags.Format<"date-time">;

    /** Pagination: page number. Optional, defaults to 1. */
    page?: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /**
     * Pagination: maximum results per page. Optional, defaults to system
     * default (e.g., 25-100).
     */
    limit?: number &
      tags.Type<"int32"> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;
  };

  /**
   * Payload for user registration/onboarding (Core.users). Used in
   * conjunction with administrative and self-service flows. Raw credentials
   * handled by secure backend logic. Auditable for compliance per requirement
   * analysis, references atomic schema columns for full normalization.
