      tags.Minimum<1> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;

    /** Maximum results per page as per API default/rate limits. */
    limit?: number &
      tags.Type<"int32"> &
      tags.Default<100> &
      tags.Minimum<1> &
      tags.Maximum<1000> &
      tags.JsonSchemaPlugin<{
        format: "int32";
      }>;
