   * 추적 및 복구, 규정 컴플라이언스를 보장합니다.
   */
  export type IDeleteResult = {
    /** 삭제(아카이브) 적용된 제품의 고유 식별자 */
    id: string & tags.Format<"uuid">;

    /** 삭제(archived/retired) 후 제품의 상태값. 운영 뷰(ex: 'archived') */
    status: string;

    /** 소프트 삭제 또는 아카이브 적용 시 타임스탬프. 감사/증적/복구 근거로 활용 */
