     * import_feeds.imported_at. Effective for time-based analytics and
     * compliance reporting.
     */
    imported_from?: string & tags.Format<"date-time">;

    /**
     * Optional upper bound (inclusive) for filtering
     * import_feeds.imported_at. Enables analytics for import activity
     * within a time window.
     */
    imported_to?: string & tags.Format<"date-time">;

    /**
     * Optional general string search across source_name and source_uri,
     * using full-text or trigram indices for fuzzy matches.
     */
    search?: string;

    /** Page number for result pagination. Default is 1 if not supplied. */
    page?: number & tags.Type<"int32">;

    /**
     * Maximum number of results per page. Default and enforced limits per
     * API policy.
     */
    limit?: number & tags.Type<"int32">;

