     * Sort order for returned results. Supports imported_at/date or
     * source_name, asc/desc.
     */
    sort?:
      | "imported_at-asc"
      | "imported_at-desc"
      | "source_name-asc"
      | "source_name-desc";
  };

  /**
   * Payload for registering a new import feed. Sends all business/required
   * data needed for creation, excluding system-generated id and
   * relationships. All insertions must respect uniqueness and
   * audit/traceability requirements.
   */
  export type ICreate = {
    /**
     * Human-friendly name for this import feed source (required).
     * Uniqueness enforced.
     *
     * See import_feeds.source_name.
     */
    source_name: string;

    /**
     * Full URI describing the import source/destination. Required for data
     * provenance and audit.
     */
    source_uri: string & tags.MaxLength<80000>;

    /**
     * Timestamp the import actually occurred (should be set by system if
     * omitted). Sets the evidence anchor for audit and compliance
     * reporting.
     */
    imported_at?: string & tags.Format<"date-time">;
  };

