    /** Upper bound date/time for cart creation. */
    created_at_to?: (string & tags.Format<"date-time">) | null;

    /** Lower bound date/time for most recent update to cart. */
    updated_at_from?: (string & tags.Format<"date-time">) | null;

    /** Upper bound date/time for most recent update. */
