  };

  /**
   * Mutable fields for payment record updates.
   *
   * Limited only to correction/compliance flows. Maps to
   * payments.payment_method_id, completed_at, description. ID, transaction,
   * status, amount are not mutable except via specific admin logic.
   */
  export type IUpdate = {
    /**
