import { tags } from "typia";

/**
 * Atomic normalized record for a user payment method.
 *
 * References PaymentsDiscounts.payment_methods in Prisma; used in
 * wallet/account flows and admin registry.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IPaymentMethod = {
  /** Unique payment method ID (PK for payment_methods). */
  id: string & tags.Format<"uuid">;

  /** User's ID who owns this payment method. */
  user_id: string & tags.Format<"uuid">;

  /** Instrument type (VISA, wallet, crypto, etc). */
  type: string;

  /**
   * Display/proofable summary of payment details (last4, masked address,
   * etc).
   */
  masked_detail: string;

  /** Payment provider/platform ('Toss', 'Stripe', etc). */
  provider?: string | null;

  /** Indicates if this method is currently active/usable. */
  active: boolean;

  /** Timestamp when the payment method was created. */
  created_at: string & tags.Format<"date-time">;
};
export namespace IPaymentMethod {
  /**
   * Filter, search, and pagination payload for payment methods list
   * operation.
   *
   * Maps to key columns in PaymentsDiscounts.payment_methods. Used to drive
   * user wallet views, admin registry, or analytics.
   */
  export type IRequest = {
    /**
     * Filter payment methods by owner user ID. Used for user/my account
     * views and admin lookups.
     */
    user_id?: (string & tags.Format<"uuid">) | null;

    /** Filter by payment method type (e.g. VISA, PayPal, Wallet, etc). */
    type?: string | null;

    /**
     * Filter by activation status: true for only active (usable); false for
     * only disabled/revoked methods.
     */
    active?: boolean | null;

    /** Filter for source/payment provider (e.g., Toss, Stripe, Binance). */
    provider?: string | null;

    /** Start timestamp for filtering creation dates. */
    created_from?: (string & tags.Format<"date-time">) | null;

    /** End timestamp for filtering creation dates. */
    created_to?: (string & tags.Format<"date-time">) | null;

    /** Sort string, e.g. 'created_at:asc', 'type:desc'. */
    sort?: string | null;

    /** Page number for pagination (starting from 1). */
    page?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "int32";
          }>)
      | null;

    /** Number of payment methods per page to return (pagination). */
    limit?:
      | (number &
          tags.Type<"int32"> &
          tags.JsonSchemaPlugin<{
            format: "int32";
          }>)
      | null;
  };

  /**
   * Payload for payment method registration.
   *
   * All credentials must be PCI-compliant/masked; provider field is for
   * analytics or external registry only.
   */
  export type ICreate = {
    /**
     * User ID for whom method is registered. Required, must match existing
     * users.id.
     */
    user_id: string & tags.Format<"uuid">;

    /** Instrument type to register (e.g., VISA, wallet, crypto). */
    type: string;

    /** Masked/partial ref for PCI/privacy-safe identification; required. */
    masked_detail: string;

    /** Payment provider/string reference to source. */
    provider?: string | null;

    /** Registration status. Usually true on create. */
    active: boolean;
  };

  /**
   * Fields updatable in payment method records (ICreate, active, provider,
   * masked_detail).
   *
   * Name/type/user_id are immutable post-creation for compliance/audit.
   */
  export type IUpdate = {
    /**
     * Updated PCI-compliant detail for display/reference. E.g.: last4, new
     * wallet address. Null means unchanged.
     */
    masked_detail?: string | null;

    /** New provider string, if provider changes/correction required. */
    provider?: string | null;

    /**
     * Change registration to active/inactive (deactivate/re-enable), for
     * operational or compliance purposes.
     */
    active?: boolean | null;
  };
}

