    sort_field?: "created_at" | "updated_at" | "subject";

    /** Sort direction (ascending or descending). */
    sort_order?: "asc" | "desc";
  };

  /**
   * Payload for creating new conversation thread. Must include subject,
   * created_by_user_id (if system/admin), and may set archived flag for admin
   * flows.
   */
  export type ICreate = {
    /**
     * The creating user's UUID. Required only for system/admin
     * audits—otherwise set from authentication context.
     */
