    /**
     * 변경할 메시지 유형 (user/system 등).
     * CommunicationReview.messages.message_type.
     */
    message_type?: string;

    /** 읽음 시간 업데이트. 읽은 경우 클라이언트에서 타임스탬프를 기록. */
