    "/apiOmnichannel/webhookEvents/{id}": {
      "get": {
        "summary": "Get details of a single webhook event (API Omnichannel - webhook_events) by ID.",
        "description": "This operation retrieves all available data for a single webhook event record specified by its unique ID. Includes delivery target, attempt/delivery status, timestamps, integration channel, and evidence metadata (payload hash, delivery history). Used in compliance audits, delivery diagnostics, and AI-driven/event replay use-cases in omnichannel commerce. Only authorized actors (system, admin, compliance modules) may access these details. All request and response actions are logged for evidence preservation and audit trail compliance.",
