test/features/api/refund/test_update_ref:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * Test suite for updating an existing refund record by ID, validation and error scenarios.
 *
 * This test covers the following flows in order:
 * 1. Create a valid refund event record via POST (dependency for ID).
 * 2. Update the refund record with modified fields (e.g., amount, reason, status).
 * 3. Fetch the record and verify that all updated fields have been saved correctly (audit).
 * 4. Attempt to update a non-existent refund ID (expect 404 error).
 * 5. Attempt to update a refund with invalid/forbidden field values (e.g., negative amount) and expect validation errors.
 *
 * This scenario ensures:
 * - Updates are reflected correctly for valid data and ID
 * - Proper error handling for missing refund or invalid schema
 * - Business/data integrity for financial compliance
 */
export async function test_api_refund_update_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid refund record (dependency)
  const createBody: IRefund.ICreate = {
    payment_id: typia.random<string & tags.Format<"uuid">>(),
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 100.0,
    currency: "USD",
    status: "requested",
    reason: "Initial refund - test",
  };
  const created: IRefund = await api.functional.paymentsDiscounts.refunds.post(connection, {
    body: createBody,
  });
  typia.assert(created);

  // 2. Update the refund record (e.g., increase amount, change status, update reason)
  const updateBody: IRefund.IUpdate = {
    amount: 120.0,
    status: "processed",
    reason: "Updated for further review",
    currency: "USD",
  };
  const updated: IRefund = await api.functional.paymentsDiscounts.refunds.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  // 3. Verify updated fields
  TestValidator.equals("refund id")(created.id)(updated.id);
  TestValidator.equals("refund amount")(updateBody.amount)(updated.amount);
  TestValidator.equals("refund status")(updateBody.status)(updated.status);
  TestValidator.equals("refund reason")(updateBody.reason)(updated.reason);
  TestValidator.equals("refund currency")(updateBody.currency)(updated.currency);

  // 4. Attempt to update a non-existent refund - expect 404
  await TestValidator.httpError("update non-existent refund should 404")(404)(async () =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // new random UUID
      body: updateBody,
    })
  );

  // 5. Attempt to update with invalid data (e.g., negative amount) - expect validation error (likely 400)
  const invalidUpdate: IRefund.IUpdate = {
    amount: -50.0, // invalid negative
    currency: "USD",
    status: "completed",
    reason: "Bogus"
  };
  await TestValidator.httpError("negative refund amount should fail")(400)(async () =>
    api.functional.paymentsDiscounts.refunds.putById(connection, {
      id: created.id,
      body: invalidUpdate,
    })
  );
}

test/features/api/refund/test_soft_delet:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * Validate the soft-deletion (logical deletion) of a refund record by ID, evidence/audit logic, and edge cases.
 *
 * 1. Create a refund event (for deletion test setup)
 * 2. Soft-delete (logically delete) the created refund by its valid ID
 * 3. Attempt to re-fetch the deleted refund from the standard (active) list if such functionality exists (simulate: should not retrieve), and verify via audit/evidence flow that it remains available for compliance
 * 4. Attempt to soft-delete a non-existent refund (random UUID) and expect a 404 error
 * 5. Attempt to soft-delete an already deleted refund again, confirming idempotency or error response per business logic
 *
 * This test ensures: all delete operations preserve regulatory-compliant evidence, no undeleted refunds remain in standard queries, and all error/idempotency semantics are correct.
 */
export async function test_api_refund_soft_delete_with_audit_and_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a refund event (for deletion test setup)
  const created: IRefund = await api.functional.paymentsDiscounts.refunds.post(connection, {
    body: {
      payment_id: typia.random<string & tags.Format<"uuid">>(),
      transaction_id: typia.random<string & tags.Format<"uuid">>(),
      order_id: null,
      amount: 1000,
      currency: "USD",
      status: "requested",
      reason: "Test refund request",
    } satisfies IRefund.ICreate,
  });
  typia.assert(created);

  // 2. Soft-delete (logically delete) the created refund by its valid ID
  const deleted: IRefund.IDeleteResult = await api.functional.paymentsDiscounts.refunds.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("deleted-refund-id")(created.id)(deleted.id);
  TestValidator.equals("deleted-result-success")(true)(deleted.success);
  // `deleted_at` should be an ISO string
  TestValidator.equals("deleted_at-isostring")("string")(typeof deleted.deleted_at);

  // 3. Try to retrieve the deleted refund via active/standard flow (assume "list" functionality, skipped if unavailable)
  // -- This step would need active list query (not provided in the mock); here we only assert business trace.

  // 4. Try to soft-delete a non-existent refund (random UUID): expect 404 error
  await TestValidator.httpError("delete-nonexistent-refund-404")(404)(() =>
    api.functional.paymentsDiscounts.refunds.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. Try to delete the already deleted refund again; should be idempotent or error per business
  // (simulate as error here unless endpoint documents otherwise)
  await TestValidator.error("double-delete-already-deleted-refund")(async () => {
    await api.functional.paymentsDiscounts.refunds.eraseById(connection, {
      id: created.id,
    });
  });
}

test/features/api/payment-audit/test_lis:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentAudit";
import { IPageIPaymentAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPaymentAudit";
import typia from "typia";

/**
 * List payment audit events with advanced filters and pagination, and verify error handling.
 *
 * Validates retrieval and searching of audit events by different filters and pagination via
 * /paymentsDiscounts/paymentAudits (PATCH). Ensures all filter combinations and boundary
 * conditions including invalid/malformed input yield the correct data or errors.
 *
 * Steps:
 * 1. Create several audit records (at least 3) with varied user_id, entity_type, entity_id,
 *    action, and timestamps (some with null values). At least one record for each filterable field.
 * 2. List all audit records using patch with no filters to confirm all created ones appear.
 * 3. Filter by entity_type, confirm only matching records appear.
 * 4. Filter by action, confirm only proper action matches returned.
 * 5. Filter by user_id, confirm only records for that user_id returned.
 * 6. Filter by timestamp window (from/to).
 * 7. Use paginated queries (limit/page) and confirm correct subset/total returned.
 * 8. Try invalid filters (e.g., junk user_id/entity_type)—confirm empty or error.
 * 9. Try malformed filters (e.g., non-date string in timestamp_from)—expect validation error.
 */
export async function test_api_payment_audit_list_with_filtering_and_error_handling(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create diverse audit records
  const nowISO = new Date().toISOString();
  const otherDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // Yesterday

  const auditA: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(
    connection,
    {
      body: {
        entity_type: "payment",
        entity_id: typia.random<string>(),
        action: "create",
        user_id: typia.random<string>(),
        old_value: null,
        new_value: JSON.stringify({ amount: 100 }),
        timestamp: nowISO,
      } satisfies IPaymentAudit.ICreate,
    },
  );
  typia.assert(auditA);

  const auditB: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(
    connection,
    {
      body: {
        entity_type: "discount",
        entity_id: typia.random<string>(),
        action: "apply",
        user_id: null,
        old_value: null,
        new_value: JSON.stringify({ percent: 15 }),
        timestamp: otherDate,
      } satisfies IPaymentAudit.ICreate,
    },
  );
  typia.assert(auditB);

  const auditC: IPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.post(
    connection,
    {
      body: {
        entity_type: "refund",
        entity_id: typia.random<string>(),
        action: "refund",
        user_id: typia.random<string>(),
        old_value: JSON.stringify({ status: "pending" }),
        new_value: JSON.stringify({ status: "approved" }),
        timestamp: nowISO,
      } satisfies IPaymentAudit.ICreate,
    },
  );
  typia.assert(auditC);

  // Step 2: List all audit records (no filter)
  const allAudits: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: {} satisfies IPaymentAudit.IRequest },
  );
  typia.assert(allAudits);
  // Confirm the three new audits appear (may have pre-existing data, so search by id)
  const auditIds = allAudits.data.map((a) => a.id);
  TestValidator.equals("find auditA")(true)(auditIds.includes(auditA.id));
  TestValidator.equals("find auditB")(true)(auditIds.includes(auditB.id));
  TestValidator.equals("find auditC")(true)(auditIds.includes(auditC.id));

  // Step 3: Filter by entity_type
  const paymentOnly: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: { entity_type: "payment" } satisfies IPaymentAudit.IRequest },
  );
  typia.assert(paymentOnly);
  TestValidator.equals("only payment entity_type")(
    true,
  )(
    paymentOnly.data.every((d) => d.entity_type === "payment")
  );

  // Step 4: Filter by action
  const applyAction: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: { action: "apply" } satisfies IPaymentAudit.IRequest },
  );
  typia.assert(applyAction);
  TestValidator.equals("only apply action")(
    true,
  )(
    applyAction.data.every((d) => d.action === "apply")
  );

  // Step 5: Filter by user_id
  if (auditA.user_id) {
    const userFilter: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
      connection,
      { body: { user_id: auditA.user_id } satisfies IPaymentAudit.IRequest },
    );
    typia.assert(userFilter);
    TestValidator.equals("only user_id matches")(
      true,
    )(
      userFilter.data.every((d) => d.user_id === auditA.user_id)
    );
  }

  // Step 6: Filter by timestamp window
  const fromDate = new Date(Date.now() - 2 * 24 * 60 * 60 * 1000).toISOString();
  const toDate = new Date(Date.now() + 60 * 1000).toISOString();
  const timestampWindow: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: { timestamp_from: fromDate, timestamp_to: toDate } satisfies IPaymentAudit.IRequest },
  );
  typia.assert(timestampWindow);
  TestValidator.equals("all in range")(
    true,
  )(
    timestampWindow.data.every(
      (a) =>
        new Date(a.timestamp) >= new Date(fromDate) &&
        new Date(a.timestamp) <= new Date(toDate),
    )
  );

  // Step 7: Pagination
  {
    const paged: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
      connection,
      { body: { limit: 2, page: 1 } satisfies IPaymentAudit.IRequest },
    );
    typia.assert(paged);
    TestValidator.equals("limit=2")(
      2,
    )(paged.data.length <= 2 ? paged.data.length : 2);
    TestValidator.equals("pagination meta")(
      true,
    )(
      paged.pagination.current === 1 && paged.pagination.limit === 2
    );
  }

  // Step 8: Invalid filters (should yield empty result or error)
  const junkType: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: { entity_type: "no-such-entity-type" } satisfies IPaymentAudit.IRequest },
  );
  typia.assert(junkType);
  TestValidator.equals("junk entity_type empty")(
    0,
  )(junkType.data.length);

  const junkUser: IPageIPaymentAudit = await api.functional.paymentsDiscounts.paymentAudits.patch(
    connection,
    { body: { user_id: "11112222-3333-4444-5555-666677778888" } satisfies IPaymentAudit.IRequest },
  );
  typia.assert(junkUser);
  TestValidator.equals("junk user_id empty")(
    0,
  )(junkUser.data.length);

  // Step 9: Malformed filter (validation error)
  await TestValidator.error("malformed timestamp_from")(() =>
    api.functional.paymentsDiscounts.paymentAudits.patch(connection, {
      body: { timestamp_from: "not-a-date" } as any,
    }),
  );
}

