 * 2. Retrieve the created audit event by valid ID and verify that returned data exactly matches the original record.
 * 3. Attempt to fetch a non-existent audit event and confirm a 404 Not Found error is thrown.
 * 4. Attempt to fetch using an invalidly formatted ID and verify that a validation error is triggered.
 */
export async function test_api_payment_audit_get_by_id_with_success_and_failure_scenarios(
  connection: api.IConnection,
): Promise<void> {
