  const now = new Date().toISOString();
  const payload: IPaymentAudit.ICreate = {
    user_id: null,
    entity_type: "payment",
    entity_id: "11111111-1111-4111-8111-111111111111",
    action: "create",
    old_value: null,
    new_value: "{\"approved\":true}",
    timestamp: now,
  };
  const output = await api.functional.paymentsDiscounts.paymentAudits.post(connection, {
    body: payload satisfies IPaymentAudit.ICreate,
