import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import typia, { tags } from "typia";

/**
 * E2E test for modifying API client metadata and negative case for non-existing ID.
 *
 * 1. Create an API client (POST /apiOmnichannel/apiClients)
 * 2. Update the API client's mutable metadata fields (PUT /apiOmnichannel/apiClients/{id})
 *    - Fields to update: description, contact_email, public_key, is_active
 *    - Confirm updated fields changed as requested
 *    - Confirm immutable fields (id, client_name, created_at) are not changed
 * 3. Attempt to update a non-existent API client (random UUID)
 *    - Verify 404 Not Found error returned
 */
export async function test_api_apiClients_update_by_id_with_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an API client
  const createBody: IApiClients.ICreate = {
    client_name: `test-e2e-client_${Date.now()}`,
    contact_email: `e2e_${Date.now()}@test.com`,
    public_key: "test-public-key",
    description: "E2E test initial client",
  };
  const original: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: createBody,
  });
  typia.assert(original);

  // 2. Update the API client's metadata (only mutable fields)
  const updateBody: IApiClients.IUpdate = {
    description: "E2E updated description",
    contact_email: `updated_${Date.now()}@test.com`,
    public_key: "updated-public-key",
    is_active: !original.is_active,
  };
  const updated: IApiClients = await api.functional.apiOmnichannel.apiClients.putById(connection, {
    id: original.id,
    body: updateBody,
  });
  typia.assert(updated);

  // Validate mutable fields updated
  if (updateBody.description !== undefined)
    TestValidator.equals("description was updated")(updateBody.description)(updated.description!);
  if (updateBody.contact_email !== undefined)
    TestValidator.equals("contact_email was updated")(updateBody.contact_email)(updated.contact_email!);
  if (updateBody.public_key !== undefined)
    TestValidator.equals("public_key was updated")(updateBody.public_key)(updated.public_key!);
  if (updateBody.is_active !== undefined)
    TestValidator.equals("is_active was updated")(updateBody.is_active)(updated.is_active);

  // Validate immutable fields are not changed
  TestValidator.equals("id unchanged")(original.id)(updated.id);
  TestValidator.equals("client_name unchanged")(original.client_name)(updated.client_name);
  TestValidator.equals("created_at unchanged")(original.created_at)(updated.created_at);

  // 3. Attempt update with non-existent ID
  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("not found")
    (404)
    (() => api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: randomId,
      body: updateBody,
    }));
}

/**
 * Validate that updating an API client with invalid data types or missing required fields returns validation errors.
 *
 * Business context:
 * Robust input validation is required to prevent corrupt or malformed data. This test ensures the API rejects invalid update attempts for API clients.
 *
 * Scenario steps:
 * 1. Create a valid API client to set up the test precondition.
 * 2. Attempt to update the client by:
 *    a. Using a field (is_active) with an invalid data type (string instead of boolean)
 *    b. Omitting all fields (empty object)
 *    c. Using an invalid field name (e.g., typo: contact_emal)
 *    d. Supplying a wrong value in an optional field (public_key as a number)
 * 3. For each update attempt, verify the API returns a validation or error response, and does not update the record.
 * 4. Optionally, confirm the final client state is unchanged if a GET endpoint is available.
 */
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { TestValidator } from "@nestia/e2e";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";

export async function test_update_api_client_by_id_with_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a valid API client
  const validClient: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `client-invalid-e2e-${Date.now()}`,
      contact_email: `test-e2e-${Date.now()}@test.com`,
      public_key: "-----BEGIN PUBLIC KEY-----test-invalid-key-----END PUBLIC KEY-----",
      description: "E2E client for invalid update edge cases"
    } satisfies IApiClients.ICreate
  });
  typia.assert(validClient);

  // 2a. Update with invalid data type for is_active
  await TestValidator.httpError("invalid is_active type (string)")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: validClient.id,
      body: {
        is_active: "yes"
      } as any // intentionally bypass type for the test
    })
  );

  // 2b. Update with completely empty payload (should be invalid)
  await TestValidator.httpError("empty update body")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: validClient.id,
      body: {} as any
    })
  );

  // 2c. Update with typo field name (should fail validation)
  await TestValidator.httpError("invalid field name")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: validClient.id,
      body: { contact_emal: "bad@test.com" } as any
    })
  );

  // 2d. Update with wrong type in optional field (public_key as number)
  await TestValidator.httpError("invalid public_key type")(400)(() =>
    api.functional.apiOmnichannel.apiClients.putById(connection, {
      id: validClient.id,
      body: { public_key: 12345 } as any
    })
  );
}

