test/features/api/api-token/test_list_an:
import typia from "typia";
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";
import { IPageIApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIApiTokens";
import { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";

/**
 * Retrieve a filtered and paginated list of API access tokens, verifying filtering, search, and pagination logic.
 * Includes a test with filters that yield no results to ensure the API handles empty responses gracefully.
 *
 * Steps:
 * 1. Create an API client (for which tokens can be issued and searched).
 * 2. Issue at least one token for this specific client.
 * 3. Retrieve API tokens by filtering with the client ID and/or token scope. Verify response data/pagination.
 * 4. Paginate or apply different search parameters (active, scope) to ensure relevant filtering and pages.
 * 5. Fetch using a deliberately invalid filter (nonexistent api_client_id or random scope) and confirm the response contains an empty data array.
 * 6. Assert all returned types match expected DTOs and pagination meta.
 */
export async function test_api_token_list_and_search_api_tokens_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `Test Client ${Date.now()}`,
      contact_email: `test${Date.now()}@testdomain.com`,
      description: "E2E test client for token listing",
      public_key: "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQE...", // Dummy key
    } satisfies IApiClients.ICreate,
  });
  typia.assert(client);

  // 2. Issue at least one token for this client
  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:all",
      issued_at: new Date(Date.now()).toISOString(),
      expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(), // 24 hours later
    } satisfies IApiToken.ICreate,
  });
  typia.assert(token);

  // 3. Retrieve API tokens for this client by filtering with api_client_id
  const page1: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: {
      api_client_id: client.id,
      page: 1,
      limit: 10,
    } satisfies IApiTokens.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("Pagination is page 1")(1)(page1.pagination.current);
  TestValidator.equals("Page contains at least one token")(true)(page1.data.length > 0);
  TestValidator.equals("Token belongs to created client")(client.id)(page1.data[0].api_client_id);

  // 4. Search by scope (should find our token)
  const byScope: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: {
      scope: "read:all",
      limit: 10,
      page: 1,
    } satisfies IApiTokens.IRequest,
  });
  typia.assert(byScope);
  TestValidator.equals("At least one token with scope read:all")(true)(byScope.data.some((t) => t.scope === "read:all"));

  // 5. Fetch tokens with a deliberately invalid filter (unmatched api_client_id)
  const emptyPage: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: {
      api_client_id: "00000000-0000-4000-8000-000000000000", // random UUID unlikely to exist
      page: 1,
      limit: 10,
    } satisfies IApiTokens.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("Response should contain empty token data")([] as IApiToken[])(emptyPage.data);

  // 6. Fetch with an unknown scope (should also yield no results)
  const emptyScope: IPageIApiTokens = await api.functional.apiOmnichannel.apiTokens.patch(connection, {
    body: {
      scope: "nonexistent:scope",
      page: 1,
      limit: 5,
    } satisfies IApiTokens.IRequest,
  });
  typia.assert(emptyScope);
  TestValidator.equals("Empty result for random scope")([] as IApiToken[])(emptyScope.data);
}

