import { IApiTokens } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiTokens";

/**
 * Fetch an API access token by valid ID and assert correct metadata is returned.
 * Attempt to fetch with an invalid or revoked token ID and expect a 404 error response.
 *
 * Scenario:
 * 1. Create a new API client to establish a context for token issuance.
 * 2. Issue a new API token for the created API client.
 * 3. Fetch the API token by its valid ID; verify the metadata matches and is correct.
 * 4. Attempt to fetch an API token by a random (non-existent) UUID and expect a 404 error.
 * 5. (Optional for completeness) Revoke the created API token, then attempt to fetch it again and expect a 404 error response (if revocation deletes or disables fetch).
 */
export async function test_api_token_get_by_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(
    connection,
    {
      body: {
        client_name: `Test Suite Client ${Date.now()}`,
        contact_email: `client${Date.now()}@test.com`,
        public_key: "-----BEGIN PUBLIC KEY-----\nTESTKEY\n-----END PUBLIC KEY-----",
        description: "E2E test API client for token tests."
      } satisfies IApiClients.ICreate,
    }
  );
  typia.assert(client);

  // 2. Issue a new API token
  const now = new Date();
  const issued_at = now.toISOString();
  const expires_at = new Date(now.getTime() + 1000 * 3600 * 24 * 7).toISOString(); // +1 week
  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(
    connection,
    {
      body: {
        api_client_id: client.id,
        scope: "*", // full scope for test
        issued_at,
        expires_at
      } satisfies IApiToken.ICreate,
    }
  );
  typia.assert(token);

  // 3. Fetch token by valid ID
  const fetched: IApiTokens = await api.functional.apiOmnichannel.apiTokens.getById(
    connection,
    {
      id: token.id
    }
  );
  typia.assert(fetched);
  // ID and api_client_id, etc, must match
  TestValidator.equals("token.id")(token.id)(fetched.id);
  TestValidator.equals("api_client_id")(token.api_client_id)(fetched.api_client_id);
  // Optional/nullable fields checked for presence/absense, and client name
  TestValidator.equals("scope")(token.scope)(fetched.scope);

  // 4. Attempt to fetch non-existent token ID
  await TestValidator.httpError("fetch non-existent API token")(404)(() =>
    api.functional.apiOmnichannel.apiTokens.getById(
      connection,
      { id: typia.random<string & tags.Format<"uuid">>() }
    )
  );

  // (OPTIONAL) If system supports explicit revoke-and-hide:
  // - You may implement a revoke/delete API call, then assert subsequent GET fails with 404
}

