test/features/api/api-token/test_update_:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";

/**
 * Update allowed fields of an existing API token and verify that only mutable fields can be changed.
 * Also attempt to update a non-existent or revoked token and ensure proper error responses.
 *
 * Scenario steps:
 * 1. Create a new API client (to associate tokens)
 * 2. Issue a new API token for that client
 * 3. Update the scope of the API token and verify changes were applied
 * 4. Update the expiration date (expires_at) of the token and verify the update
 * 5. Revoke the token by setting revoked_at
 * 6. Attempt to update a non-existent token (random UUID), expect 404
 * 7. Attempt to update a revoked token, expect error (since it is revoked)
 *
 * This verifies both success and failure mutation paths for API tokens.
 */
export async function test_api_token_update_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an API client
  const client: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `test-client-${Date.now()}`,
      contact_email: `client${Date.now()}@test.com`,
      description: "E2E test client",
      public_key: "dummy-public-key"
    } satisfies IApiClients.ICreate
  });
  typia.assert(client);

  // 2. Issue a new API token for that client
  const issuedAt = new Date().toISOString();
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(); // +1 day
  const token: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: client.id,
      scope: "read:all",
      issued_at: issuedAt,
      expires_at: expiresAt
    } satisfies IApiToken.ICreate
  });
  typia.assert(token);

  // 3. Update the scope of the API token
  const updateScope = "write:all";
  const updated1: IApiToken = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      scope: updateScope
    } satisfies IApiToken.IUpdate
  });
  typia.assert(updated1);
  TestValidator.equals("scope updated")(updateScope)(updated1.scope);

  // 4. Update the expiration date
  const newExpiresAt = new Date(Date.now() + 1000 * 60 * 60 * 48).toISOString(); // +2 days
  const updated2: IApiToken = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      expires_at: newExpiresAt
    } satisfies IApiToken.IUpdate
  });
  typia.assert(updated2);
  TestValidator.equals("expires_at updated")(newExpiresAt)(updated2.expires_at);

  // 5. Revoke the token by setting revoked_at
  const revokeAt = new Date().toISOString();
  const revoked: IApiToken = await api.functional.apiOmnichannel.apiTokens.putById(connection, {
    id: token.id,
    body: {
      revoked_at: revokeAt
    } satisfies IApiToken.IUpdate
  });
  typia.assert(revoked);
  TestValidator.equals("revoked_at updated")(revokeAt)(revoked.revoked_at!);

  // 6. Attempt to update a non-existent token
  await TestValidator.httpError("update non-existent token, should get 404")(404)(() =>
    api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: "00000000-0000-4000-8000-000000000000" as string & tags.Format<"uuid">,
      body: { scope: "fail-scope" } satisfies IApiToken.IUpdate
    })
  );

  // 7. Attempt to update a revoked token (should be rejected)
  await TestValidator.httpError("update revoked token")(400)(() =>
    api.functional.apiOmnichannel.apiTokens.putById(connection, {
      id: revoked.id,
      body: { scope: "should-not-apply" } satisfies IApiToken.IUpdate
    })
  );
}

