import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiClients } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiClients";
import { IApiToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiToken";
import typia, { tags } from "typia";

/**
 * Revoke (soft-delete) an API token and confirm it can no longer be used for authentication.
 *
 * This E2E test covers the revoke workflow for API tokens:
 *   1. Create a new API client (integration partner/client/app).
 *   2. Issue a new API token for this client.
 *   3. Revoke (DELETE) the API token by ID and check revoked_at is set.
 *   4. Attempt to revoke this already-revoked token again; expect error.
 *   5. Attempt to revoke a non-existent token ID; expect error.
 *
 * Ensures proper auditability and denial of API usage by revoked/invalid tokens.
 */
export async function test_api_token_revoke_and_double_delete(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new API client for context
  const apiClient: IApiClients = await api.functional.apiOmnichannel.apiClients.post(connection, {
    body: {
      client_name: `test-client-${Date.now()}`,
      contact_email: `owner-${Date.now()}@example.com`,
      public_key: undefined,
      description: "Test client for token revoke E2E scenario",
    } satisfies IApiClients.ICreate,
  });
  typia.assert(apiClient);

  // 2. Issue a new API token for this client
  const now = new Date();
  const expires = new Date(now.getTime() + 1000 * 60 * 60 * 24); // 1 day later
  const apiToken: IApiToken = await api.functional.apiOmnichannel.apiTokens.post(connection, {
    body: {
      api_client_id: apiClient.id,
      scope: "test:all",
      issued_at: now.toISOString(),
      expires_at: expires.toISOString(),
    } satisfies IApiToken.ICreate,
  });
  typia.assert(apiToken);

