import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";
import { IPageIApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIApiAudit";

/**
 * List and search API audit entries with various filters and paginated results.
 *
 * Pre-condition: Insert a variety of audit records with diverse properties to exercise filter and pagination logic.
 *
 * 1. Insert several API audit entries with controlled, distinct properties (different endpoints, actors, status codes, timestamps, etc).
 * 2. List all audit entries with no filters. Verify all inserted records appear and check result includes pagination metadata.
 * 3. Search audits by a specific endpoint. Confirm only those entries are returned.
 * 4. Filter audits by is_success=true, status_code=200. Assert only those entries and count is as expected.
 * 5. Filter with created_from and created_to: restrict audits to a focused date range, verify match result.
 * 6. Paginate: limit=2 & page=2, verify returned entries slice matches the expected chunk, and pagination works as intended.
 * 7. Use a filter (e.g. status_code=999) that matches NOTHING; result data should be empty, but pagination sane.
 * 8. Optionally, try edge filters (actor_id, http_method, api_token_id) for completeness.
 */
export async function test_api_audit_list_and_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Insert several distinct audit logs for searchability
  const baseTime = new Date();
  const audits: IApiAudit[] = [];
  for (let i = 0; i < 5; ++i) {
    const audit: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(
      connection,
      {
        body: {
          api_client_id: typia.random<string & typia.tags.Format<"uuid">>(),
          api_token_id: typia.random<string & typia.tags.Format<"uuid">>(),
          integration_channel_id: i % 2 === 0 ? typia.random<string & typia.tags.Format<"uuid">>() : undefined,
          endpoint: `/api/test/${i % 2}`,
          http_method: i % 2 === 0 ? "POST" : "GET",
          actor_id: `actor-id-${i}` as string & typia.tags.Format<"uuid">,
          is_success: i % 2 === 0,
          status_code: i % 2 === 0 ? 200 : 500,
          created_at: new Date(baseTime.getTime() + i * 1000).toISOString(),
          decision_log_id: `log-${i}`,
          request_hash: `req-hash-${i}`,
          response_hash: `res-hash-${i}`,
        } satisfies IApiAudit.ICreate,
      },
    );
    typia.assert(audit);
    audits.push(audit);
  }
  // Sort audits by time ascending for easier assertion
  audits.sort((a, b) => a.created_at.localeCompare(b.created_at));

  // 2. List all audits without filter
  const resultAll: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: {},
  });
  typia.assert(resultAll);
  for (const a of audits) TestValidator.predicate(`audit in list: ${a.id}`)(resultAll.data.some(x => x.id === a.id));

  // 3. Filter by endpoint
  const endpointFilter = audits[0].endpoint;
  const resultEndpoint: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { endpoint: endpointFilter },
  });
  typia.assert(resultEndpoint);
  for (const entry of resultEndpoint.data) TestValidator.equals("filtered endpoint")(endpointFilter)(entry.endpoint);

  // 4. Filter by is_success=true and status_code=200
  const resultSuccess200: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { is_success: true, status_code: 200 },
  });
  typia.assert(resultSuccess200);
  const expectedSuccess = audits.filter(x => x.is_success && x.status_code === 200);
  TestValidator.equals("success+200 count")(expectedSuccess.length)(resultSuccess200.data.length);
  for (const entry of resultSuccess200.data) {
    TestValidator.equals("is_success")(true)(entry.is_success);
    TestValidator.equals("status_code")(200)(entry.status_code);
  }

  // 5. Filter by created_at range
  const start = audits[1].created_at;
  const end = audits[3].created_at;
  const resultRange: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { created_from: start, created_to: end },
  });
  typia.assert(resultRange);
  for (const entry of resultRange.data) {
    TestValidator.predicate("within range")(entry.created_at >= start && entry.created_at <= end);
  }

  // 6. Pagination: limit=2, page=2
  const resultPage2: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(resultPage2);
  TestValidator.equals("page2.limit")(2)(resultPage2.pagination.limit);
  TestValidator.equals("page2.current")(2)(resultPage2.pagination.current);
  const expectedSlice = resultAll.data.slice(2, 4);
  for (let i = 0; i < resultPage2.data.length; ++i) {
    if (expectedSlice[i]) TestValidator.equals("paging: id")(expectedSlice[i].id)(resultPage2.data[i].id);
  }

  // 7. Empty filter e.g. status_code=999
  const resultNone: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { status_code: 999 },
  });
  typia.assert(resultNone);
  TestValidator.equals("empty data")(0)(resultNone.data.length);
  // pagination structure always present

  // 8. Edge filters
  // actor_id
  const actorIdFilter = audits[2].actor_id;
  const resultActor: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { actor_id: actorIdFilter },
  });
  typia.assert(resultActor);
  for (const entry of resultActor.data) TestValidator.equals("actor_id eq")(actorIdFilter)(entry.actor_id);
  // http_method
  const httpMethod = audits[0].http_method;
  const resultMethod: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { http_method: httpMethod },
  });
  typia.assert(resultMethod);
  for (const entry of resultMethod.data) TestValidator.equals("http_method eq")(httpMethod)(entry.http_method);
  // api_token_id
  const tokenId = audits[1].api_token_id;
  const resultToken: IPageIApiAudit = await api.functional.apiOmnichannel.apiAudits.patch(connection, {
    body: { api_token_id: tokenId },
  });
  typia.assert(resultToken);
  for (const entry of resultToken.data) TestValidator.equals("token_id eq")(tokenId)(entry.api_token_id);
}

