import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IApiAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IApiAudit";
import typia, { tags } from "typia";

/**
 * E2E: API audit record retrieval and not-found scenario validation.
 *
 * This test validates the full lifecycle of creating and retrieving audit entries from the omnichannel audit log.
 * Steps:
 * 1. Create an API audit log entry (via POST /apiOmnichannel/apiAudits) to generate a known entry for lookup.
 * 2. Retrieve the audit record by its valid ID (GET /apiOmnichannel/apiAudits/{id}), and assert that all fields match.
 * 3. Attempt to retrieve an audit record using a random (likely non-existent) UUID and expect a 404 Not Found error.
 *
 * This ensures compliant storage, retrieval accuracy, and error handling for missing records.
 */
export async function test_api_audit_get_detail_and_notfound(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new audit record for lookup
  const createBody: IApiAudit.ICreate = {
    api_client_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    endpoint: "/some/path",
    http_method: "POST",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    is_success: true,
    status_code: 200,
    created_at: new Date().toISOString(),
  };
  const created: IApiAudit = await api.functional.apiOmnichannel.apiAudits.post(connection, { body: createBody });
  typia.assert(created);

  // 2. Retrieve the created entry by ID and verify details
  const fetched: IApiAudit = await api.functional.apiOmnichannel.apiAudits.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("api_client_id")(createBody.api_client_id)(fetched.api_client_id);
  TestValidator.equals("api_token_id")(createBody.api_token_id)(fetched.api_token_id);
  TestValidator.equals("endpoint")(createBody.endpoint)(fetched.endpoint);
  TestValidator.equals("http_method")(createBody.http_method)(fetched.http_method);
  TestValidator.equals("actor_id")(createBody.actor_id)(fetched.actor_id);
  TestValidator.equals("is_success")(createBody.is_success)(fetched.is_success);
  TestValidator.equals("status_code")(createBody.status_code)(fetched.status_code);

  // 3. Attempt to fetch with a non-existent ID and expect a 404
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("not found")(404)(() =>
    api.functional.apiOmnichannel.apiAudits.getById(connection, { id: fakeId }),
  );
}

