test/features/api/integration-channel/te:
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { TestValidator } from "@nestia/e2e";
import { IIntegrationChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IIntegrationChannel";
import { IPageIIntegrationChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIIntegrationChannel";

/**
 * Validate listing and searching integration channels with flexible filters and pagination.
 *
 * This test assures that various filtering, sorting, and pagination options yield expected results when retrieving integration channels,
 * and confirms proper handling of cases with no matching records.
 *
 * 1. Create several integration channels with distinct channel_code, channel_name, and is_active
 * 2. List all (no filter) – verify all created channels appear
 * 3. Search by exact channel_code
 * 4. Search by partial channel_name
 * 5. Filter by is_active (true/false)
 * 6. Filter by created_at period (from/to)
 * 7. Sort by different fields/directions
 * 8. Apply pagination (page/limit)
 * 9. Filter that matches no record (empty response)
 */
export async function test_api_integration_channel_list_and_search_with_filters_and_pagination(connection: api.IConnection): Promise<void> {
  // 1. Create test data: multiple integration channels
  const now = new Date();
  const channelInputs: IIntegrationChannel.ICreate[] = [
    { channel_code: "web",      channel_name: "Web Store" },
    { channel_code: "mobile",   channel_name: "Mobile App" },
    { channel_code: "partner_1", channel_name: "Partner Alpha" },
    { channel_code: "erp_sync", channel_name: "ERP Synchronizer" },
  ];
  const createdChannels: IIntegrationChannel[] = [];
  for (const [, input] of channelInputs.entries()) {
    const ch = await api.functional.apiOmnichannel.integrationChannels.post(connection, { body: input });
    typia.assert(ch);
    createdChannels.push(ch);
  }

  // 2. List all (no filters)
  {
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: {} });
    typia.assert(res);
    TestValidator.equals("all channels count")(createdChannels.length)(res.data.length);
    // All channels returned must match what we created
    for (const c of createdChannels) {
      const found = res.data.find(rc => rc.id === c.id);
      TestValidator.equals(`channel: ${c.channel_code}`)(!!c)(!!found);
    }
  }

  // 3. Exact channel_code filter
  {
    const sel = createdChannels[2];
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { channel_code: sel.channel_code }}});
    typia.assert(res);
    TestValidator.equals("exact channel_code count")(1)(res.data.length);
    TestValidator.equals("channel_code")(sel.channel_code)(res.data[0].channel_code);
  }

  // 4. Partial channel_name match
  {
    const partial = "Web";
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { channel_name: partial }}});
    typia.assert(res);
    TestValidator.equals("partial channel_name count")(1)(res.data.length);
    TestValidator.equals("partial channel_name")("Web Store")(res.data[0].channel_name);
  }

  // 5. Filter by is_active (default true on creation)
  {
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { is_active: true }}});
    typia.assert(res);
    TestValidator.equals("active channels count")(createdChannels.length)(res.data.length);
  }
  // (Simulate inactive/deleted by searching for is_active: false – should be 0)
  {
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { is_active: false }}});
    typia.assert(res);
    TestValidator.equals("inactive channels count")(0)(res.data.length);
  }

  // 6. Filter by created_at range
  {
    const from = new Date(now.getTime() - 5 * 60000).toISOString();
    const to = new Date(now.getTime() + 5 * 60000).toISOString();
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { created_at: { from, to }}}});
    typia.assert(res);
    // All should be in the range just created
    TestValidator.equals("created_at range count")(createdChannels.length)(res.data.length);
  }
  // Out-of-range (should match no records)
  {
    const from = new Date(now.getTime() - 60 * 60000).toISOString();
    const to = new Date(now.getTime() - 55 * 60000).toISOString();
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { created_at: { from, to }}}});
    typia.assert(res);
    TestValidator.equals("created_at out-of-range count")(0)(res.data.length);
  }

  // 7. Sort by various fields and orders
  {
    // By channel_name ascending
    const resAsc = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { sort: { by: "channel_name", order: "asc" }}});
    typia.assert(resAsc);
    const sorted = [...createdChannels].sort((a, b) => a.channel_name.localeCompare(b.channel_name));
    TestValidator.equals("sort asc 0")(sorted[0].channel_name)(resAsc.data[0].channel_name);
    TestValidator.equals("sort asc n-1")(sorted[sorted.length-1].channel_name)(resAsc.data[resAsc.data.length-1].channel_name);

    // By channel_name descending
    const resDesc = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { sort: { by: "channel_name", order: "desc" }}});
    typia.assert(resDesc);
    const sortedDesc = [...createdChannels].sort((a, b) => b.channel_name.localeCompare(a.channel_name));
    TestValidator.equals("sort desc 0")(sortedDesc[0].channel_name)(resDesc.data[0].channel_name);
    TestValidator.equals("sort desc n-1")(sortedDesc[sortedDesc.length-1].channel_name)(resDesc.data[resDesc.data.length-1].channel_name);
  }

  // 8. Pagination: limit to 2 per page, walk through pages
  {
    const limit = 2;
    let collected: string[] = [];
    let page = 1;
    while (collected.length < createdChannels.length) {
      const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { pagination: { page, limit }}});
      typia.assert(res);
      for (const c of res.data) collected.push(c.id);
      // Check pagination props
      TestValidator.equals("pagination page")(page)(res.pagination.current);
      TestValidator.equals("pagination limit")(limit)(res.pagination.limit);
      if (page < res.pagination.pages) ++page; else break;
    }
    // Should collect all unique IDs exactly
    TestValidator.equals("all paginated ids unique")([...createdChannels].map(c => c.id).sort())([...collected].sort());
  }

  // 9. No-match filter (non-existent channel)
  {
    const res = await api.functional.apiOmnichannel.integrationChannels.patch(connection, { body: { filters: { channel_code: "never-will-match" }}});
    typia.assert(res);
    TestValidator.equals("no match empty array")(0)(res.data.length);
    TestValidator.equals("no match pages")(1)(res.pagination.pages);
    TestValidator.equals("no match records")(0)(res.pagination.records);
  }
}

