import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";
import { IPageIChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIChannelSession";

/**
 * Retrieve a filtered and paginated list of channel sessions with different criteria.
 *
 * This test validates the filtering, sorting, pagination, and empty results handling
 * for listing channel sessions using the PATCH /apiOmnichannel/channelSessions API.
 *
 * 1. Create a new channel session (POST /apiOmnichannel/channelSessions)
 * 2. Retrieve channel sessions with various filter params (by integration_channel_id, api_token_id, user_id, session_key)
 * 3. For each filter, verify that only correct records are returned or results are empty
 * 4. Validate pagination mechanics with custom limit/page
 * 5. Issue a filter that should yield no results and confirm empty data
 * 6. Validate response types, structure, and detailed test assertions
 */
export async function test_api_channel_session_list_with_filters_and_handle_empty_results(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a baseline channel session
  const created: IChannelSession = await api.functional.apiOmnichannel.channelSessions.post(
    connection,
    {
      body: {
        integration_channel_id: typia.random<string>(),
        api_token_id: typia.random<string>(),
        user_id: typia.random<string>(),
        session_key: `test-session-key-${Date.now()}`,
        started_at: new Date().toISOString(),
      } satisfies IChannelSession.ICreate,
    },
  );
  typia.assert(created);

  // 2. Retrieve channel sessions by integration_channel_id
  const resByChannel: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: {
        filters: { integration_channel_id: created.integration_channel_id },
      },
    },
  );
  typia.assert(resByChannel);
  TestValidator.equals("integration_channel_id filter count")(1)(resByChannel.data.length);
  TestValidator.equals("integration_channel_id match")(created.integration_channel_id)(resByChannel.data[0]?.integration_channel_id);

  // 3. Retrieve by api_token_id
  const resByToken: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { filters: { api_token_id: created.api_token_id } },
    },
  );
  typia.assert(resByToken);
  TestValidator.equals("api_token_id filter count")(1)(resByToken.data.length);
  TestValidator.equals("api_token_id match")(created.api_token_id)(resByToken.data[0]?.api_token_id);

  // 4. Retrieve by user_id
  const resByUser: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { filters: { user_id: created.user_id ?? undefined } },
    },
  );
  typia.assert(resByUser);
  TestValidator.equals("user_id filter count")(1)(resByUser.data.length);
  TestValidator.equals("user_id match")(created.user_id)(resByUser.data[0]?.user_id);

  // 5. Retrieve by session_key
  const resBySessionKey: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { filters: { session_key: created.session_key } },
    },
  );
  typia.assert(resBySessionKey);
  TestValidator.equals("session_key filter count")(1)(resBySessionKey.data.length);
  TestValidator.equals("session_key match")(created.session_key)(resBySessionKey.data[0]?.session_key);

  // 6. Test sorting desc/asc by started_at
  // Ideally, insert multiple sessions to fully test order; here we just check call does not throw
  await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { sort: { by: "started_at", order: "desc" } },
    },
  );
  await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { sort: { by: "started_at", order: "asc" } },
    },
  );

  // 7. Test pagination: set a tight limit (1)
  const pagedRes: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { pagination: { limit: 1, page: 1 } },
    },
  );
  typia.assert(pagedRes);
  TestValidator.equals("pagination limit")(1)(pagedRes.data.length);
  TestValidator.equals("pagination limit meta")(1)(pagedRes.pagination.limit);

  // 8. Use impossible filter to produce empty results
  const emptyRes: IPageIChannelSession = await api.functional.apiOmnichannel.channelSessions.patch(
    connection,
    {
      body: { filters: { session_key: "nonexistent-session-key-xyz" } },
    },
  );
  typia.assert(emptyRes);
  TestValidator.equals("empty filter produces empty data")(0)(emptyRes.data.length);
  TestValidator.equals("empty result page meta should still exist")(1)(emptyRes.pagination.current);
}

