import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IChannelSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IChannelSession";
import typia, { tags } from "typia";

/**
 * 테스트 목적: 채널 세션을 ID로 조회하는 기능의 정상 동작 및 예외 상황(404 Not Found) 검증.
 *
 * 본 테스트는 아래 두 가지 시나리오를 차례로 검증한다.
 * 1. 유효한 ID로 세션을 생성 후, 해당 ID로 상세정보를 정상 조회 (성공 케이스)
 * 2. 무작위/존재하지 않는 UUID로 요청 시 404 Not Found 반환 확인 (실패 케이스)
 *
 * 테스트 프로세스:
 * 1. 세션 생성을 위해 IChannelSession.ICreate 타입의 데이터로 POST /apiOmnichannel/channelSessions 호출
 * 2. 정상 생성된 세션의 id 값을 보관
 * 3. 해당 id로 GET /apiOmnichannel/channelSessions/{id} 호출해서 세션 상세 정보를 검증
 * 4. typia.assert로 응답 타입 확인 및 id/세션 속성 등 주요 값 일치 여부 검증
 * 5. 임의의 UUID(존재하지 않는 값)로 GET 요청 시 404 반환 및 에러 발생 검증
 */
export async function test_api_channel_session_get_by_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. 세션 생성
  const now = new Date();
  const createBody: IChannelSession.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    api_token_id: typia.random<string & tags.Format<"uuid">>(),
    session_key: "integration-key-" + Math.random().toString(36).slice(2, 10),
    started_at: now.toISOString(),
  };
  const created: IChannelSession = await api.functional.apiOmnichannel.channelSessions.post(connection, {
    body: createBody,
  });
  typia.assert(created);

  // 2. 생성된 세션을 정상 ID로 조회
  const found: IChannelSession = await api.functional.apiOmnichannel.channelSessions.getById(connection, {
    id: created.id,
  });
  typia.assert(found);

  // 3. 생성시 전달 값과 조회 결과 매칭 검증
  TestValidator.equals("integration_channel_id")(createBody.integration_channel_id)(found.integration_channel_id);
  TestValidator.equals("api_token_id")(createBody.api_token_id)(found.api_token_id);
  TestValidator.equals("session_key")(createBody.session_key)(found.session_key);
  TestValidator.equals("started_at")(createBody.started_at)(found.started_at);
  // (user_id와 ended_at은 optional, 기본 미검증)

  // 4. 존재하지 않는 random UUID로 404 에러 검증
  const neverExistsId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("session not found")(404)(() =>
    api.functional.apiOmnichannel.channelSessions.getById(connection, {
      id: neverExistsId,
    }),
  );
}

