  const event_types = ["order.updated", "payment.completed", "shipment.dispatched"];
  const delivery_statuses: IWebhookEvent["delivery_status"][] = ["pending", "success", "failed"];
  const testEvents: IWebhookEvent[] = [];
  for (let i = 0; i < 9; ++i) {
    const event: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: {
        integration_channel_id,
        event_type: event_types[i % event_types.length],
        destination_url: `https://webhook${i}.example.com/notify`,
        event_hash: `testhash${i}`,
      } satisfies IWebhookEvent.ICreate
    });
    // Patch status via mock (staging only) if desired
    testEvents.push({
      ...event,
      delivery_status: delivery_statuses[i % delivery_statuses.length],
      created_at: new Date(now.getTime() - i * 86400000).toISOString(), // Last 9 days
    });
  }

  // 2. List all webhook events
  const listResponse: IPageIWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: {
      integration_channel_id,
      limit: 20
    } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(listResponse);
  // Confirm all created events are included
  const ids = new Set(testEvents.map(e => e.id));
  const found = listResponse.data.filter(ev => ids.has(ev.id));
  TestValidator.equals("all events included")(testEvents.length)(found.length);

  // 3. Search by event_type
  for (const type of event_types) {
    const res = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { integration_channel_id, event_type: type } satisfies IWebhookEvent.IRequest,
    });
    typia.assert(res);
    for (const ev of res.data) TestValidator.equals("event_type matches")(type)(ev.event_type);
  }

  // 4. Search by delivery_status
  for (const status of delivery_statuses) {
    const res = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
      body: { integration_channel_id, delivery_status: status } satisfies IWebhookEvent.IRequest,
    });
    typia.assert(res);
    for (const ev of res.data) TestValidator.equals("delivery_status matches")(status)(ev.delivery_status);
  }

  // 5. Search by date range
  const from = new Date(now.getTime() - 3 * 86400000).toISOString();
  const to = now.toISOString();
  const windowRes = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, created_from: from, created_to: to } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(windowRes);
  for (const ev of windowRes.data) {
    TestValidator.equals("within window")(
      true
    )(
      ev.created_at >= from && ev.created_at <= to
    );
  }

  // 6. Filter for non-existent event_type/status → expect empty result
  const noneRes1 = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, event_type: "nonexistent.event" } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(noneRes1);
  TestValidator.equals("empty for invalid event_type")(0)(noneRes1.data.length);
  const noneRes2 = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, delivery_status: "failed", event_type: "nonexistent.event" } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(noneRes2);
  TestValidator.equals("empty for invalid event_type+status")(0)(noneRes2.data.length);

  // 7. Pagination logic
  const page1 = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, limit: 3, page: 1 } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page 1 count")(3)(page1.data.length);
  const page2 = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, limit: 3, page: 2 } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("page 2 count")(3)(page2.data.length);
  const page3 = await api.functional.apiOmnichannel.webhookEvents.patch(connection, {
    body: { integration_channel_id, limit: 3, page: 3 } satisfies IWebhookEvent.IRequest,
  });
  typia.assert(page3);
  TestValidator.equals("page 3 count")(3)(page3.data.length);
  // Optionally check correct unique ids (if order is deterministic)
}

