import typia, { tags } from "typia";

/**
 * Retrieve a single webhook event by a valid and an invalid ID.
 *
 * Ensures that webhook events can be reliably retrieved by their ID, and that the system responds with a 404 error for non-existent IDs.
 *
 * 1. Create a webhook event using POST /apiOmnichannel/webhookEvents.
 * 2. Retrieve the created webhook event by its ID using GET /apiOmnichannel/webhookEvents/{id}. Assert the returned object matches.
 * 3. Attempt to retrieve a non-existent webhook event using a random UUID. Assert that a 404 error is returned.
 */
export async function test_api_webhook_event_get_by_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a webhook event
  const eventInput: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.updated",
    destination_url: "https://example-webhook.destination/test",
    event_hash: "abcdef1234567890dummyhash",
  };
  const created: IWebhookEvent = 
    await api.functional.apiOmnichannel.webhookEvents.post(connection, {
      body: eventInput,
    });
  typia.assert(created);

  // 2. Retrieve the webhook event with valid ID
  const found: IWebhookEvent = 
    await api.functional.apiOmnichannel.webhookEvents.getById(connection, {
      id: created.id,
    });
  typia.assert(found);
  TestValidator.equals("id should match")(created.id)(found.id);
  TestValidator.equals("integration_channel_id")(created.integration_channel_id)(found.integration_channel_id);
  TestValidator.equals("event_type")(created.event_type)(found.event_type);
  TestValidator.equals("destination_url")(created.destination_url)(found.destination_url);
  TestValidator.equals("event_hash")(created.event_hash)(found.event_hash);

  // 3. Attempt to retrieve a webhook event with a non-existent valid UUID
  const randomId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  if (randomId !== created.id) {
    await TestValidator.httpError("404 for non-existent webhook event")(404)(() =>
      api.functional.apiOmnichannel.webhookEvents.getById(connection, {
        id: randomId,
      }),
    );
  }
}

