/**
 * Validate updating the delivery/audit state of a webhook event and 404 handling for missing event.
 *
 * 1. Create a webhook event (to be updated)
 * 2. Update certain metadata fields (delivery status, attempt_count, timestamps)
 * 3. Read response and verify changes are reflected
 * 4. Try to update a non-existent webhook event (random UUID)
 * 5. Ensure 404 error is returned on missing event update
 */
export async function test_api_webhook_event_update_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a webhook event
  const created: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, {
    body: {
      integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "order.updated",
      destination_url: "https://webhook.destination/notify",
      event_hash: "abcdef1234567890",
    } satisfies IWebhookEvent.ICreate,
  });
  typia.assert(created);

  // 2. Update delivery state/meta of the webhook event
  const patch: IWebhookEvent.IUpdate = {
    attempt_count: (created.attempt_count ?? 0) + 1,
    last_attempted_at: new Date().toISOString(),
    delivery_status: "success",
    delivered_at: new Date().toISOString(),
  };
  const updated: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.putById(connection, {
    id: created.id,
    body: patch,
  });
  typia.assert(updated);
  // 3. Check that important fields are updated
  TestValidator.equals("attempt_count updated")(patch.attempt_count)(updated.attempt_count);
  TestValidator.equals("delivery_status updated")(patch.delivery_status)(updated.delivery_status);
  TestValidator.equals("delivered_at updated")(patch.delivered_at)(updated.delivered_at);

  // 4. Attempt to update a non-existent webhook event, expect 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>()
  await TestValidator.httpError("webhook event not found update")(404)(() =>
    api.functional.apiOmnichannel.webhookEvents.putById(connection, {
      id: nonExistentId,
      body: { delivery_status: "failed" },
    })
  );
}

