import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IWebhookEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IWebhookEvent";

/**
 * Validate deletion (soft-delete) of a webhook event and error handling for non-existent/already deleted events.
 *
 * This test ensures compliance, traceability, and regulatory evidence preservation by verifying that webhook events
 * can be soft-deleted, are retained for compliance (not physically purged), and that appropriate error responses
 * are returned when attempting invalid or repeated deletions.
 *
 * 1. Create a webhook event to guarantee a deletable entity exists
 * 2. Delete (soft-delete) the webhook event
 * 3. Validate the deletion response structure (archived evidence & status)
 * 4. Attempt to delete the same webhook event again — expect error
 * 5. Attempt to delete a non-existent webhook event id — expect error
 */
export async function test_api_webhook_event_softdelete_and_idempotent_error(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a webhook event
  const createBody: IWebhookEvent.ICreate = {
    integration_channel_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "order.updated",
    destination_url: "https://partner.example.com/webhook/xxx",
    event_hash: "sha256:b1c2d2d34b...",
  };
  const created: IWebhookEvent = await api.functional.apiOmnichannel.webhookEvents.post(connection, { body: createBody });
  typia.assert(created);

  // 2. Delete (soft-delete) the webhook event
  const deleted: IWebhookEvent.IDelete = await api.functional.apiOmnichannel.webhookEvents.eraseById(connection, { id: created.id });
  typia.assert(deleted);
  TestValidator.equals("deleted id matches")(created.id)(deleted.id);
  TestValidator.equals("status is archived")("archived")(deleted.status);

  // 3. Attempt to delete the same event again — should fail (already deleted)
  await TestValidator.httpError("deletion of already-deleted event")(404)(() =>
    api.functional.apiOmnichannel.webhookEvents.eraseById(connection, { id: created.id }),
  );

  // 4. Attempt to delete a non-existent webhook event id
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("deletion of non-existent event")(404)(() =>
    api.functional.apiOmnichannel.webhookEvents.eraseById(connection, { id: fakeId }),
  );
}

