test/features/api/consent/test_list_cons:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreConsent";
import { IPageICoreConsent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreConsent";
import typia from "typia";

/**
 * Test paginated and filtered consent record retrieval.
 *
 * Validates pagination, filtering by user/status/date, and edge case (no records) behaviors:
 *
 * 1. Create multiple users' consents with variety in type, grant status, and timestamps
 * 2. Retrieve first page with a small limit; check correct page size and pagination meta
 * 3. Filter by specific user_id and verify only their consents
 * 4. Filter by is_granted false (revoked consents) and check correctness
 * 5. Filter by date range (grant time window)
 * 6. Filter for non-existent values — must return zero records cleanly
 */
export async function test_api_core_consents_list_pagination_and_filter(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create diverse consents
  const userA = typia.random<string & typia.tags.Format<"uuid">>();
  const userB = typia.random<string & typia.tags.Format<"uuid">>();
  const grantedAt = new Date().toISOString();

  const records: ICoreConsent[] = [];
  // Create 5 consents for userA
  for (let i = 0; i < 5; ++i) {
    const consent = await api.functional.core.consents.post(connection, {
      body: {
        user_id: userA,
        type: `ai_training_${i}`,
        is_granted: true,
        granted_at: grantedAt,
      } satisfies ICoreConsent.ICreate,
    });
    typia.assert(consent);
    records.push(consent);
  }
  // Create 3 revoked consents for userB
  for (let i = 0; i < 3; ++i) {
    const consent = await api.functional.core.consents.post(connection, {
      body: {
        user_id: userB,
        type: `marketing_${i}`,
        is_granted: false,
        granted_at: grantedAt,
        revoked_at: new Date(Date.now() + 1000 * i).toISOString(),
      } satisfies ICoreConsent.ICreate,
    });
    typia.assert(consent);
    records.push(consent);
  }

  // Step 2: Retrieve first page (limit 4)
  let output: IPageICoreConsent = await api.functional.core.consents.patch(
    connection,
    {
      body: {
        page: 1,
        limit: 4,
      },
    },
  );
  typia.assert(output);
  TestValidator.equals("page size 4")(4)(output.data.length);
  TestValidator.equals("total records")(records.length)(output.pagination.records);
  TestValidator.equals("current page")(1)(output.pagination.current);

  // Step 3: Filter by exact user_id (userA)
  output = await api.functional.core.consents.patch(
    connection,
    {
      body: {
        filter: { user_id: userA },
      },
    },
  );
  typia.assert(output);
  for (const rec of output.data) TestValidator.equals("user_id")(userA)(rec.user_id);
  TestValidator.equals("userA consent count")(5)(output.data.length);

  // Step 4: Filter by revoked/is_granted = false
  output = await api.functional.core.consents.patch(
    connection,
    {
      body: {
        filter: { user_id: userB, is_granted: false },
      },
    },
  );
  typia.assert(output);
  for (const rec of output.data) {
    TestValidator.equals("user_id")(userB)(rec.user_id);
    TestValidator.equals("is_granted")(false)(rec.is_granted);
  }
  TestValidator.equals("userB revoked count")(3)(output.data.length);

  // Step 5: Filter by grant date (window includes both sets)
  output = await api.functional.core.consents.patch(
    connection,
    {
      body: {
        filter: { granted_at: grantedAt },
      },
    },
  );
  typia.assert(output);
  // At least all consents created above should match
  TestValidator.equals("all with set grant date")(8)(output.data.length);

  // Step 6: Non-existent user filter
  const dummy = typia.random<string & typia.tags.Format<"uuid">>();
  output = await api.functional.core.consents.patch(
    connection,
    {
      body: { filter: { user_id: dummy } },
    },
  );
  typia.assert(output);
  TestValidator.equals("no match for dummy user")(0)(output.data.length);
}

