test/features/api/core-accesslog/test_li:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreAccessLog";
import { IPageICoreAccessLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreAccessLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import typia from "typia";

/**
 * Retrieve access logs with pagination and advanced filters, and validate result accuracy.
 *
 * Scenario Overview:
 * This test validates the paginated retrieval and advanced filtering of access logs via the /core/accessLogs PATCH API.
 * It checks that:
 * - Inserting multiple access log entries allows their correct retrieval by various filters (user_id, event, date range, etc)
 * - Pagination is honored (results per page, page number, total counts)
 * - Edge cases with no matching results return an empty page and correct metadata
 *
 * Steps:
 * 1. Insert several access log entries with distinct user IDs, events, times, and agents.
 * 2. Query all logs with no filters, verify all inserted are returned (may span multiple pages)
 * 3. Query for specific user_id, check only those logs returned
 * 4. Query for event_type (e.g., 'login'), check correct subset
 * 5. Query with date/time range, confirm only expected logs within the range are returned
 * 6. Verify pagination: request partial pages, check page info and per-page results
 * 7. Edge case: filter by non-existent user/session/etc., expect empty result set with valid metadata
 * 8. Validate total record/pagination metadata matches expectations at each stage
 */
export async function test_api_core_accesslog_list_and_filter_with_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Insert test access log entries
  const now = new Date();
  const users = [
    typia.random<string & typia.tags.Format<"uuid">>(),
    typia.random<string & typia.tags.Format<"uuid">>(),
  ];
  const events = ["login", "logout", "api_call"];
  const logs: ICoreAccessLog[] = [];
  for (let i = 0; i < 6; ++i) {
    const log: ICoreAccessLog = await api.functional.core.accessLogs.post(connection, {
      body: {
        user_id: users[i % users.length],
        event_type: events[i % events.length],
        ip: `192.168.0.${i}`,
        agent: `agent-${i}`,
        success: i % 2 === 0,
        occurred_at: new Date(now.getTime() - i * 1000 * 60).toISOString(),
      } satisfies ICoreAccessLog.ICreate,
    });
    typia.assert(log);
    logs.push(log);
  }

  // 2. Query all logs without filters
  const allPage: IPageICoreAccessLog = await api.functional.core.accessLogs.patch(connection, {
    body: { page: 1, limit: 100 },
  });
  typia.assert(allPage);
  // Should include all inserted logs above
  for (const inserted of logs) {
    const found = allPage.data.find(r => r.id === inserted.id);
    if (!found) {
      TestValidator.error(`log exists: ${inserted.id}`)(() => {
        throw new Error(`Inserted log with id ${inserted.id} not found in results`);
      });
    } else {
      TestValidator.equals(`log exists: ${inserted.id}`)(inserted.id)(found.id);
    }
  }
  TestValidator.equals("total record count")(logs.length)(allPage.pagination.records);

  // 3. Query by specific user_id
  const userId = users[0];
  const userPage: IPageICoreAccessLog = await api.functional.core.accessLogs.patch(connection, {
    body: { user_id: userId, page: 1, limit: 100 },
  });
  typia.assert(userPage);
  for (const log of userPage.data) {
    TestValidator.equals("filtered user")(userId)(log.user_id);
  }
  // Check count matches reality
  const expectUserLogs = logs.filter(l => l.user_id === userId);
  TestValidator.equals("user logs count")(expectUserLogs.length)(userPage.pagination.records);

  // 4. Query by event_type
  const event = "login";
  const eventPage: IPageICoreAccessLog = await api.functional.core.accessLogs.patch(connection, {
    body: { event_type: event, page: 1, limit: 100 },
  });
  typia.assert(eventPage);
  for (const log of eventPage.data) {
    TestValidator.equals("filtered event")(event)(log.event_type);
  }
  const expectEventLogs = logs.filter(l => l.event_type === event);
  TestValidator.equals("event logs count")(expectEventLogs.length)(eventPage.pagination.records);

  // 5. Query by date range (include last 3 of 6 logs, e.g. most recent from 'now-2m')
  const since = new Date(now.getTime() - 2 * 1000 * 60).toISOString();
  const datePage: IPageICoreAccessLog = await api.functional.core.accessLogs.patch(connection, {
    body: { occurred_at_from: since, page: 1, limit: 100 },
  });
  typia.assert(datePage);
  const expectDateLogs = logs.filter(l => l.occurred_at >= since);
  for (const log of datePage.data) {
    TestValidator.equals("date filter")(true)(log.occurred_at >= since);
  }
  TestValidator.equals("date logs count")(expectDateLogs.length)(datePage.pagination.records);

  // 6. Pagination: get only 2 logs per page
  const paged1 = await api.functional.core.accessLogs.patch(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(paged1);
  TestValidator.equals("page size")(2)(paged1.data.length);
  TestValidator.equals("current page")(1)(paged1.pagination.current);
  TestValidator.equals("limit")(2)(paged1.pagination.limit);
  // Do page 2 as well
  const paged2 = await api.functional.core.accessLogs.patch(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(paged2);
  TestValidator.equals("page 2 size")(2)(paged2.data.length);
  TestValidator.equals("page 2 current")(2)(paged2.pagination.current);

  // 7. Edge case: filter by non-existent user_id
  const nonePage = await api.functional.core.accessLogs.patch(connection, {
    body: { user_id: typia.random<string & typia.tags.Format<"uuid">>(), page: 1, limit: 10 },
  });
  typia.assert(nonePage);
  TestValidator.equals("no logs found")(0)(nonePage.data.length);
  TestValidator.equals("no logs record count")(0)(nonePage.pagination.records);

  // 8. Validate audit meta: pages/records
  const totalPages = Math.ceil(logs.length / 2);
  TestValidator.equals("total pages")(totalPages)(paged1.pagination.pages);
}

