import api from "@ORGANIZATION/PROJECT-api";
import { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import { IPageIProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCatalogProduct";
import typia from "typia";

/**
 * Validate product list retrieval with various filters, pagination, and metadata.
 *
 * This test ensures that querying the product catalog endpoint (/productCatalog/products)
 * supports robust search features (by category, name, status), enforces pagination
 * correctness, and returns accurate evidence/audit traces for regulatory requirements.
 *
 * 1. Create several products with diverse categories, statuses, and names.
 * 2. Retrieve paginated product lists and verify results by category, name, and status filters.
 * 3. Test an empty result case using a filter that matches nothing.
 * 4. Confirm page metadata reflects true pagination state.
 * 5. Cross-validate all results match their search criteria (category, etc).
 * 6. Assert the evidence/audit fields (created_by_user_id, updated_by_user_id) are present in all records.
 */
export async function test_api_product_list_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create products with different categories and statuses
  const user_id = typia.random<string & typia.tags.Format<"uuid">>();
  const timestamp = new Date().toISOString();
  const products: IProductCatalogProduct[] = [];

  // e.g., 3 products in 'electronics', 2 in 'books', status 'active' and 'draft'
  const testData = [
    { name: "Phone", category: "electronics", status: "active" },
    { name: "Tablet", category: "electronics", status: "draft" },
    { name: "Camera", category: "electronics", status: "active" },
    { name: "Novel", category: "books", status: "active" },
    { name: "Comics", category: "books", status: "draft" },
  ];
  for (const d of testData) {
    const created = await api.functional.productCatalog.products.post(connection, {
      body: {
        name: d.name,
        description: d.name + " desc",
        internal_code: d.name + Math.floor(Math.random() * 100000),
        status: d.status,
        created_by_user_id: user_id,
        updated_by_user_id: user_id,
      } satisfies IProductCatalogProduct.ICreate,
    });
    typia.assert(created);
    products.push(created);
  }

  // 2. Retrieve only electronics
  const listElectronics: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: {
      category: "electronics",
      page: 1,
      limit: 10,
    } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(listElectronics);
  // No category property to check, so do not validate p.category here

  // 3. Retrieve only books, status active
  const listBooksActive: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: {
      category: "books",
      status: "active",
      page: 1,
      limit: 10,
    } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(listBooksActive);
  // Do not check p.category, only status
  for (const p of listBooksActive.data) {
    TestValidator.equals("status")("active")(p.status);
  }
  // 4. Retrieve by a name search
  const listByName: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: {
      name: "Phone",
      page: 1,
      limit: 10,
    } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(listByName);
  for (const p of listByName.data) {
    TestValidator.equals("name")("Phone")(p.name);
  }
  // 5. Page out to only one result per page (pagination)
  const paged: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { page: 2, limit: 1 } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("limit")(1)(paged.pagination.limit);
  TestValidator.equals("current")(2)(paged.pagination.current);
  // 6. Edge case: No result (impossible filter)
  const empty: IPageIProductCatalogProduct = await api.functional.productCatalog.products.patch(connection, {
    body: { name: "DefinitelyNoSuchName", page: 1, limit: 10 } satisfies IProductCatalogProduct.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("empty result")(0)(empty.data.length);
  // 7. Evidence/audit validation for all results
  for (const results of [listElectronics, listBooksActive, listByName, paged]) {
    for (const p of results.data) {
      typia.assert(p.created_by_user_id);
      typia.assert(p.updated_by_user_id);
    }
  }
  // 8. Page metadata cross-check
  for (const results of [listElectronics, listBooksActive, listByName, paged, empty]) {
    const meta = results.pagination;
    typia.assert(meta.current);
    typia.assert(meta.limit);
    typia.assert(meta.records);
    typia.assert(meta.pages);
  }
}

