import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";

/**
 * Validate retrieval of full product details by ID, and error handling for non-existent product scenario.
 *
 * This test verifies two cases:
 * 1. Retrieval of a real (existing) product by its unique ID, confirming response matches all catalog and audit requirements.
 * 2. Attempt to fetch using a non-existent random UUID, ensuring proper error is returned and no product data is leaked.
 *
 * Steps:
 * 1. Create a new product in the catalog for controlled retrieval.
 * 2. Retrieve the product details by the valid ID, checking all fields for correctness and audit compliance.
 * 3. Attempt to retrieve a product by a made-up UUID and expect/validate an error (e.g., 404 not found).
 *
 * This ensures catalog integrity, correct audit evidence return, and absence of data leakage in error case.
 */
export async function test_api_productCatalog_product_detail_and_notfound(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a product to ensure we have a known product to retrieve
  const createBody: IProductCatalogProduct.ICreate = {
    created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    name: `Test Product - ${Date.now()}`,
    description: "E2E test product description.",
    internal_code: `E2E-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    status: "active"  // Typical valid status
  };
  const created: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, { body: createBody });
  typia.assert(created);

  // 2. Retrieve product by valid ID and validate all expected fields
  const gotten: IProductCatalogProduct = await api.functional.productCatalog.products.getById(connection, { id: created.id });
  typia.assert(gotten);
  TestValidator.equals("product.id")(created.id)(gotten.id);
  TestValidator.equals("created_by_user_id")(createBody.created_by_user_id)(gotten.created_by_user_id);
  TestValidator.equals("updated_by_user_id")(createBody.updated_by_user_id)(gotten.updated_by_user_id);
  TestValidator.equals("name")(createBody.name)(gotten.name);
  TestValidator.equals("description")(createBody.description)(gotten.description);
  TestValidator.equals("internal_code")(createBody.internal_code)(gotten.internal_code);
  TestValidator.equals("status")(createBody.status)(gotten.status);
  // Timestamps and id formats validated by typia.assert()

  // 3. Attempt fetch with non-existent product ID and confirm error.
  await TestValidator.httpError("product not found")(404)(() =>
    api.functional.productCatalog.products.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()  // Assumed to not exist
    })
  );
}

