import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * Validate updating an existing product's permitted fields and evidence/audit persistence.
 *
 * Steps:
 * 1. Create a product category for the product.
 * 2. Create a product in the category.
 * 3. Update the product's permitted fields (name, internal_code, status) using user's ID.
 * 4. Verify that changes persisted and updated_at is refreshed.
 * 5. (Simulate audit/evidence via change in updated_by_user_id and updated_at.)
 * 6. Attempt to update a non-existing product (random UUID), expecting 404 error.
 *
 * This test ensures business edits reflect in server/store, and that audit/evidence (updated_by and updated_at) are accurate.
 */
export async function test_api_product_update_success_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a product category
  const category: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: {
      name: `TestCategory_${Date.now()}`,
    } satisfies IProductCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a product (simulate linkage via internal_code/category name in description)
  const creatorId = typia.random<string & tags.Format<"uuid">>();
  const product: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, {
    body: {
      created_by_user_id: creatorId,
      updated_by_user_id: creatorId,
      name: `Original Product Name - ${Date.now()}`,
      description: `Category: ${category.name}`,
      internal_code: `CODE_${Date.now()}`,
      status: "draft",
    } satisfies IProductCatalogProduct.ICreate,
  });
  typia.assert(product);

  // 3. Prepare update payload (change name, internal_code, status)
  const updateId = typia.random<string & tags.Format<"uuid">>();
  const updatedFields = {
    updated_by_user_id: updateId,
    name: "Updated Product Name",
    internal_code: `CODE_UPDATED_${Date.now()}`,
    status: "active",
  } satisfies IProductCatalogProduct.IUpdate;
  const updated: IProductCatalogProduct = await api.functional.productCatalog.products.putById(connection, {
    id: product.id,
    body: updatedFields,
  });
  typia.assert(updated);
  // 4. Validate changes
  TestValidator.equals("name updated")(updatedFields.name)(updated.name);
  TestValidator.equals("internal_code updated")(updatedFields.internal_code)(updated.internal_code);
  TestValidator.equals("status updated")(updatedFields.status)(updated.status);
  TestValidator.equals("updated_by_user_id updated")(updatedFields.updated_by_user_id)(updated.updated_by_user_id);
  TestValidator.equals("id stable")(product.id)(updated.id);
  TestValidator.predicate("updated_at must be more recent")(
    () => (new Date(updated.updated_at)).getTime() > (new Date(product.updated_at)).getTime()
  );

  // 5. Attempt to update a non-existent product (should 404)
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("update non-existing product should 404")(404)(() =>
    api.functional.productCatalog.products.putById(connection, {
      id: nonExistId,
      body: updatedFields,
    })
  );
}

