import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductCatalogProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProduct";
import typia, { tags } from "typia";

/**
 * Soft-delete an existing product and ensure it is excluded from listings and search.
 * Attempt to delete a non-existing product and confirm a not found error.
 * Confirm audit/compliance evidence is maintained.
 *
 * 1. Create a new product (for delete).
 * 2. Soft-delete the created product.
 * 3. Attempt to fetch or search for the deleted product (should be excluded from listing).
 * 4. Attempt to delete a non-existing product and expect a not found error.
 * 5. Confirm audit trail fields in the delete response.
 * 6. Validate all type assertions and business responses.
 */
export async function test_api_product_delete_success_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new product.
  const createInput: IProductCatalogProduct.ICreate = {
    created_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    updated_by_user_id: typia.random<string & tags.Format<"uuid">>(),
    name: "Test Product for Deletion",
    description: "This is a test product to verify deletion.",
    internal_code: `TEST-DELETE-${Date.now()}`,
    status: "active",
  };

  const product: IProductCatalogProduct = await api.functional.productCatalog.products.post(connection, { body: createInput });
  typia.assert(product);

  // 2. Soft-delete the created product.
  const deleteResult: IProductCatalogProduct.IDeleteResult = await api.functional.productCatalog.products.eraseById(connection, { id: product.id });
  typia.assert(deleteResult);
  TestValidator.equals("deleted id")(product.id)(deleteResult.id);
  TestValidator.equals("status after delete")("archived")(deleteResult.status);
  TestValidator.predicate("deleted_at present")(deleteResult.deleted_at !== undefined);
  TestValidator.predicate("deleted_at non-empty")(!!deleteResult.deleted_at);

  // 3. Attempt to fetch/search the deleted product - SKIPPED due to missing SDK functions.
  // 4. Attempt to delete a non-existent product.
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("delete non-existent product")(404)(() =>
    api.functional.productCatalog.products.eraseById(connection, { id: randomId }),
  );

  // 5. Audit trail compliance check is in deleteResult as above.
}

