 * - 이미 삭제되었거나 존재하지 않는 ID로 삭제 시 적절한 에러와 감사 내역이 유지되는지 검증해야 함
 *
 * 1. 상품 변형을 신규로 생성한다
 * 2. 생성된 변형의 ID로 삭제(소프트 삭제) 요청을 수행한다
 *    - 정상적으로 삭제됨을 응답으로 확인한다 (ID, 삭제상태, 삭제시각)
 * 3. 이미 삭제된 변형 ID로 다시 삭제 시도시 NotFound(404) 등 적절한 에러 코드와 감사증적이 보존되는지 검증
 * 4. 존재하지 않는 변형 ID로 삭제 요청시에도 적절한 에러 반환을 검증
 */
export async function test_api_product_variant_delete_and_error(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Variant 생성
  const variantInput: IProductCatalogProductVariant.ICreate = {
    product_id: typia.random<string>(),
    sku: `sku-${Date.now()}`,
    price: 2000,
    barcode: `barcode-${Date.now()}`,
    available: true,
  };
  const created: IProductCatalogProductVariant = await api.functional.productCatalog.productVariants.post(connection, {
    body: variantInput,
  });
  typia.assert(created);

  // Step 2: 변형 삭제
  const deletedResult: IProductVariant.IDeleteResult = await api.functional.productCatalog.productVariants.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deletedResult);
  TestValidator.equals("id is matched")(created.id)(deletedResult.id);
  TestValidator.equals("status is deleted")("deleted")(deletedResult.status.toLowerCase());

  // Step 3: 이미 삭제된 ID 다시 삭제 시도
  await TestValidator.httpError("delete already-deleted variant")(404)(() =>
    api.functional.productCatalog.productVariants.eraseById(connection, {
      id: created.id,
    }),
  );

  // Step 4: 존재하지 않는 ID로 삭제 시도
  const nonExistId = typia.random<string>();
  await TestValidator.httpError("delete non-existent variant")(404)(() =>
    api.functional.productCatalog.productVariants.eraseById(connection, {
      id: nonExistId,
    }),
  );
}

