import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";
import { IPageIProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductCategory";

/**
 * List/search product categories with filtering, pagination, and metadata validation.
 *
 * This test validates the product category listing endpoint, ensuring categories can be listed,
 * searched by name, filtered by parent/child hierarchy, and paginated correctly. It also checks
 * that all returned metadata fields and audit evidence traces (timestamps, parent_id, etc.) are present
 * and correctly typed. Edge cases such as no-results searches are also exercised.
 *
 * 1. Create a root category and a multi-level hierarchy (Apparel > Shoes > Men's Running)
 * 2. List all categories, verify presence and correct pagination metadata
 * 3. List subcategories by parent_id (should return children of Apparel)
 * 4. Search by partial name (e.g., 'Appar' for 'Apparel')
 * 5. Search that returns no results (e.g., gibberish)
 * 6. In each list/search, validate all fields: id, name, parent_id, created_at, updated_at
 * 7. Check audit fields (created_at/updated_at are ISO strings, non-empty, present)
 * 8. Paginate with offset/limit to verify paging response
 */
export async function test_api_product_category_list_and_search(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create root and hierarchy chain
  const root: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "Apparel" } satisfies IProductCategory.ICreate,
  });
  typia.assert(root);

  const shoes: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "Shoes", parent_id: root.id } satisfies IProductCategory.ICreate,
  });
  typia.assert(shoes);

  const mensRunning: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: { name: "Men's Running", parent_id: shoes.id } satisfies IProductCategory.ICreate,
  });
  typia.assert(mensRunning);

  // 2. List all categories (no filters)
  const allList: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: {} satisfies IProductCategory.IRequest,
  });
  typia.assert(allList);
  const allCatNames = allList.data.map((c) => c.name);
  const allPresent = ["Apparel", "Shoes", "Men's Running"].every((name) => allCatNames.includes(name));
  TestValidator.predicate("all categories present")(allPresent);

  // Validate presence of all fields/metadata & audit evidence
  for (const cat of allList.data) {
    typia.assert(cat);
    TestValidator.predicate("id present")(!!cat.id);
    TestValidator.predicate("name present")(!!cat.name);
    TestValidator.predicate("created_at present")(!!cat.created_at);
    TestValidator.predicate("updated_at present")(!!cat.updated_at);
    // ISO 8601
    TestValidator.predicate("valid created_at ISO")(!!cat.created_at && /^\d{4}-\d{2}-\d{2}T/.test(cat.created_at));
    TestValidator.predicate("valid updated_at ISO")(!!cat.updated_at && /^\d{4}-\d{2}-\d{2}T/.test(cat.updated_at));
    // parent_id can be null or a uuid string
    if (cat.parent_id !== null && cat.parent_id !== undefined) {
      TestValidator.predicate("valid parent_id uuid")(!!cat.parent_id && /^[0-9a-fA-F\-]{36}$/.test(cat.parent_id));
    }
  }

  // Pagination meta check
  TestValidator.equals("pages nonzero")(true)(allList.pagination.pages >= 1);
  TestValidator.equals("records count")(true)(allList.pagination.records >= 3);

  // 3. List subcategories using parent_id (children of root)
  const subcatList: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { parent_id: root.id } satisfies IProductCategory.IRequest,
  });
  typia.assert(subcatList);
  const subcatNames = subcatList.data.map((c) => c.name);
  TestValidator.equals("Apparel children")(["Shoes"])(subcatNames);

  // 4. Partial name search: should match 'Apparel' only
  const nameList: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { name: "Appar" } satisfies IProductCategory.IRequest,
  });
  typia.assert(nameList);
  const nameMatches = nameList.data.map((c) => c.name);
  const partialMatch = ["Apparel"].every((name) => nameMatches.includes(name));
  TestValidator.predicate("partial name matches")(partialMatch);

  // 5. Search that produces no results (unlikely/invalid string)
  const emptyList: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { name: "!!!gibberish!!!" } satisfies IProductCategory.IRequest,
  });
  typia.assert(emptyList);
  TestValidator.equals("no matches")(0)(emptyList.data.length);

  // 6. Validate metadata and audit evidence for each response above (done inline)

  // 7. Pagination window: ask for first 2, offset=0, limit=2
  const paged: IPageIProductCategory = await api.functional.productCatalog.productCategories.patch(connection, {
    body: { offset: 0, limit: 2 } satisfies IProductCategory.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("limit == 2")(2)(paged.pagination.limit);
  TestValidator.equals("paged window length")(2)(paged.data.length);
}

