import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCategory";

/**
 * Validate creating new product categories, including flat (root) and hierarchical (child/parent) cases.
 * 
 * - Ensures correct behavior for both atomic (no parent) categories and hierarchical (with parent) categories
 * - Validates constraint enforcement for duplicates, missing/invalid parent references, and schema requirements
 * - Confirms parent linkage for hierarchical child category
 * 
 * ## Steps
 * 1. Create a root category (no parent_id, flat case)
 * 2. Create a child category using the root's id as parent_id
 * 3. Attempt to create a category with a missing/non-existent parent_id (should error: invalid parent)
 * 4. Attempt to create a category with duplicate name as existing (should error: duplicate)
 * 5. Attempt invalid request: empty name (should error: constraint violation)
 * 6. Verify category data and parent linkage (parent_id for child equals root id)
 */
export async function test_api_product_category_flat_hierarchical_and_constraint_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a flat (atomic) root category
  const rootName = `RootCategory_${Date.now()}`;
  const rootCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: {
      name: rootName,
    } satisfies IProductCategory.ICreate,
  });
  typia.assert(rootCategory);
  TestValidator.equals("Root category name")(rootName)(rootCategory.name);
  const parentId: null = rootCategory.parent_id ?? null;
  TestValidator.equals("Root category parent_id")(null)(parentId);

  // 2. Create a hierarchical child category referencing the root
  const childName = `ChildCategory_${Date.now()}`;
  const childCategory: IProductCategory = await api.functional.productCatalog.productCategories.post(connection, {
    body: {
      name: childName,
      parent_id: rootCategory.id,
    } satisfies IProductCategory.ICreate,
  });
  typia.assert(childCategory);
  TestValidator.equals("Child category name")(childName)(childCategory.name);
  TestValidator.equals("Child category parent_id")(rootCategory.id)(childCategory.parent_id!);

  // 3. Attempt category creation with missing/non-existent parent
  await TestValidator.httpError("Invalid parent_id")(400)(() =>
    api.functional.productCatalog.productCategories.post(connection, {
      body: {
        name: `InvalidParent_${Date.now()}`,
        parent_id: "00000000-0000-4000-8000-000000000000", // Fake UUID, invalid
      } satisfies IProductCategory.ICreate,
    })
  );

  // 4. Attempt to create category with duplicate name as existing
  await TestValidator.httpError("Duplicate category name")(409)(() =>
    api.functional.productCatalog.productCategories.post(connection, {
      body: {
        name: rootName,
      } satisfies IProductCategory.ICreate,
    })
  );

  // 5. Attempt to create an invalid category (empty name)
  await TestValidator.httpError("Empty name constraint violation")(400)(() =>
    api.functional.productCatalog.productCategories.post(connection, {
      body: {
        name: "",
      } satisfies IProductCategory.ICreate,
    })
  );

  // 6. Final verification: linkage and types
  TestValidator.equals("Child's parent_id linkage")(rootCategory.id)(childCategory.parent_id!);
  typia.assert<IProductCategory>(rootCategory);
  typia.assert<IProductCategory>(childCategory);
}

