import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolicy";
import { IPageIPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolicy";
import typia from "typia";

/**
 * Test retrieving a paginated, filtered list of permission policies.
 *
 * Validate that the endpoint returns correct results for various filter and pagination scenarios:
 *
 * 1. No filter: Retrieve all policies in the first page (default page & limit).
 * 2. Single field filter: List policies filtered by exact `name`.
 * 3. Multi-field filter: List policies with filters for both `name` and partial `conditions`.
 * 4. Malformed query: Provide an invalid (non-integer or negative) page or limit; expect error.
 * 5. Pagination size exceeding maximum: Use an excessively large `limit`; expect cap or error.
 *
 * Ensures:
 * - Correct pagination metadata
 * - Fuzzy/exact filters work independently and jointly
 * - Robust handling of bad/malformed client input
 */
export async function test_api_policy_list_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. No filter: should list all, default page/limit
  const all: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.equals("page 1")(
    1
  )(all.pagination.current);

  // 2. Single field filter: by name (if data exists)
  if (all.data.length) {
    const filterName = all.data[0].name;
    const nameFiltered: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { name: filterName },
    });
    typia.assert(nameFiltered);
    for (const policy of nameFiltered.data)
      TestValidator.equals("filter by name")(filterName)(policy.name);
  }

  // 3. Multi-field filter: name + partial conditions (if data exists)
  if (all.data.length) {
    const filterName = all.data[0].name;
    const anyCond: string = all.data[0].conditions?.substring(0, 5) || "{";
    const filtered: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
      body: { name: filterName, conditions: anyCond },
    });
    typia.assert(filtered);
    for (const policy of filtered.data) {
      TestValidator.equals("multi-field filter: name")(filterName)(policy.name);
      TestValidator.equals("multi-field filter: conditions")(true)(policy.conditions.includes(anyCond));
    }
  }

  // 4. Malformed query: negative page, non-integer page, invalid limit
  await TestValidator.error("negative page")(() =>
    api.functional.securityCompliance.policy.patch(connection, {
      body: { page: -1 as any },
    })
  );
  await TestValidator.error("non-integer page")(() =>
    api.functional.securityCompliance.policy.patch(connection, {
      body: { page: "one" as any },
    })
  );
  await TestValidator.error("negative limit")(() =>
    api.functional.securityCompliance.policy.patch(connection, {
      body: { limit: -25 as any },
    })
  );

  // 5. Pagination size exceeding maximum (e.g., limit way above config)
  const hugeLimit = 10000;
  const capped: IPageIPolicy = await api.functional.securityCompliance.policy.patch(connection, {
    body: { limit: hugeLimit },
  });
  typia.assert(capped);
  TestValidator.equals("limit not exceeded")(
    true
  )(capped.pagination.limit <= hugeLimit);
}

