/**
 * Test fetching a single permission policy by valid ID and by invalid/nonexistent ID.
 *
 * This test validates retrieval functions of the policy registry, confirming both success and error flows.
 *
 * Steps:
 * 1. Create a permission policy via POST /securityCompliance/policy.
 * 2. Fetch the policy using GET /securityCompliance/policy/{id} with the valid ID.
 *    - Assert returned policy matches what was created (id, name, conditions, created_at).
 *    - Type assertion on output.
 * 3. Attempt to fetch a random/nonexistent policy ID.
 *    - Validate expected 404 or error response returned.
 */
export async function test_api_policy_get_by_id_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a policy
  const createInput: IPolicy.ICreate = {
    name: `policy_test_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
    conditions: JSON.stringify({ allow: ["admin"], hours: [9, 18] }),
  };
  const created: IPolicy = await api.functional.securityCompliance.policy.post(connection, {
    body: createInput,
  });
  typia.assert(created);

  // 2. Fetch the created policy by valid ID
