/**
 * Validate updating a permission policy with various conditions.
 *
 * This test covers:
 * - Updating an existing policy with valid data and verifying persistence
 * - Attempting to update a nonexistent policy and expecting a 404 error or failure
 * - Supplying invalid data and expecting validation errors
 *
 * Steps:
 * 1. Create a new permission policy via POST
 * 2. Update the created policy with new valid data; verify the result
 * 3. Attempt to update a policy using a random/nonexistent UUID and expect 404
 * 4. Try updating with invalid payloads (e.g., empty name, empty conditions) and ensure error is returned
 */
export async function test_api_policy_update_with_various_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new permission policy
  const created: IPolicy = await api.functional.securityCompliance.policy.post(connection, {
    body: {
      name: `E2E_Policy_${Date.now()}`,
      conditions: '{"allow":true}',
    } satisfies IPolicy.ICreate,
  });
  typia.assert(created);

  // 2. Update the created policy with new valid data
  const updated: IPolicy = await api.functional.securityCompliance.policy.putById(connection, {
    id: created.id,
    body: {
      name: created.name + "_updated",
      conditions: '{"allow":false}',
    } satisfies IPolicy.IUpdate,
  });
