  await TestValidator.error("update with empty conditions should fail")(() =>
    api.functional.securityCompliance.policy.putById(connection, {
      id: created.id,
      body: {
        name: created.name + "_invalid2",
        conditions: "",
      } satisfies IPolicy.IUpdate,
    }),
  );
}

