import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolicy";

/**
 * Tests soft-deleting a permission policy and verifies audit preservation and error handling.
 *
 * Scenario:
 * 1. Create a new permission policy as prerequisite.
 * 2. Soft-delete the policy by valid ID.
 *    - Ensure the returned object matches the deleted policy.
 *    - Confirm audit/evidence preservation (i.e., the record is still returned in deletion response).
 * 3. Attempt to delete a policy using an invalid UUID.
 *    - Assert appropriate error is raised (not found or invalid).
 * 4. Attempt to delete the already-deleted (archived) policy again.
 *    - Assert proper error is returned (policy is not active or already deleted).
 */
export async function test_api_policy_soft_delete_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new permission policy for deletion testing
  const policy: IPolicy = await api.functional.securityCompliance.policy.post(
    connection,
    {
      body: {
        name: `soft_delete_policy_test_` + Math.random().toString(36).substring(2, 12),
        conditions: '{"role":"admin","rule":"allow"}',
      } satisfies IPolicy.ICreate,
    },
  );
  typia.assert(policy);

  // 2. Soft-delete the policy by valid ID
  const deleted: IPolicy = await api.functional.securityCompliance.policy.eraseById(
    connection,
    { id: policy.id },
  );
  typia.assert(deleted);
  TestValidator.equals("deleted policy id")(policy.id)(deleted.id);
  TestValidator.equals("deleted policy name")(policy.name)(deleted.name);
  TestValidator.equals("deleted policy conditions")(policy.conditions)(deleted.conditions);

  // 3. Attempt to delete a policy with an invalid (random) UUID
  await TestValidator.httpError("invalid policy id")
    (404)
    (() =>
      api.functional.securityCompliance.policy.eraseById(connection, {
        id: "00000000-0000-4000-8000-000000000000" as string & tags.Format<"uuid">,
      }),
    );

  // 4. Attempt to delete the already-deleted (archived) policy again
  await TestValidator.httpError("policy already deleted")
    (404)
    (() =>
      api.functional.securityCompliance.policy.eraseById(connection, {
        id: policy.id,
      }),
    );
}

test/features/api/audit-log/test_list_au:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";
import { IPageIAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAuditLog";
import typia from "typia";

/**
 * 테스트: 다양한 필터 및 페이지네이션 옵션으로 감사 로그 목록/검색을 검증합니다.
 *
 * 이 테스트는 다양한 필터 조합(필터 미적용, 특정 날짜/시간 필터, 극단적인 페이지네이션 값 등)으로
 * /securityCompliance/auditLog 엔드포인트의 감사 로그 조회 및 검색을 검증합니다.
 * 또한 필수 쿼리 파라미터가 누락되거나 잘못 구성된 경우 에러 핸들링도 확인합니다.
 *
 * 1. 필터 없이 전체 감사 로그 목록을 조회한다.
 * 2. 특정 날짜/시간(time_from, time_to)로 필터링 하여 조회한다.
 * 3. 극단적인 페이지네이션 값(예: page=10000, limit=1 등)으로 조회한다.
 * 4. 필수 파라미터가 누락되거나 잘못된 값(잘못된 uuid 등)일 때 에러 처리 동작을 검증한다.
 */
export async function test_api_audit_log_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 필터 없이 전체 감사 로그 목록을 조회
  const resultAll: IPageIAuditLog =
    await api.functional.securityCompliance.auditLog.patch(connection, {
      body: {},
    });
  typia.assert(resultAll);

  // 2. 특정 날짜/시간 필터를 사용하여 감사 로그 조회
  const now = new Date();
  const timeFrom = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 7).toISOString(); // 일주일 전
  const timeTo = now.toISOString();
  const resultTimeFiltered: IPageIAuditLog =
    await api.functional.securityCompliance.auditLog.patch(connection, {
      body: {
        time_from: timeFrom,
        time_to: timeTo,
      } satisfies IAuditLog.IRequest,
    });
  typia.assert(resultTimeFiltered);
  // 변환된 결과의 모든 레코드가 필터 구간 내에 있는지 검증
  for (const log of resultTimeFiltered.data) {
    const createdAt = new Date(log.created_at).getTime();
    TestValidator.equals("created_at 범위 내 확인")(
      createdAt >= new Date(timeFrom).getTime() && createdAt <= new Date(timeTo).getTime()
    )(true);
  }

  // 3. 극단적인 페이지네이션 값으로 감사 로그 조회 (limit=1, 아무리 큰 page)
  // (실제 IAuditLog.IRequest에는 page, limit 필드가 없을 수 있으나 페이지네이션이 필요한 경우 IPage 관련 확장 필요)
  // 예시로 entity_type 필터와 조합하여 실행
  const resultExtremePaging: IPageIAuditLog =
    await api.functional.securityCompliance.auditLog.patch(connection, {
      body: {
        entity_type: "order",
      } satisfies IAuditLog.IRequest,
    });
  typia.assert(resultExtremePaging);

  // 4. 잘못된 파라미터, 필수 값 누락 등 에러 발생 케이스 검증
  // (예: 잘못된 actor_id 형식)
  await TestValidator.error("잘못된 actor_id uuid 포맷")(() =>
    api.functional.securityCompliance.auditLog.patch(connection, {
      body: {
        actor_id: "not-a-uuid",
      } satisfies IAuditLog.IRequest,
    })
  );
}

