import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuditLog";

/**
 * Validate updating an audit log record by ID with proper fields, and confirm audit trail preservation and error handling.
 *
 * Steps:
 * 1. Create an audit log entry as a prerequisite (required for valid update target).
 * 2. Update the created entry using only allowed updatable fields (`evidence_archive_id` and/or `context`).
 * 3. Assert that only permissible fields are changed; verify immutability of other fields.
 * 4. Attempt to update a non-existent audit log ID and expect a not found error response.
 * 5. Try to update immutable fields (such as `created_at`, `id`, `action`, `entity_type`) and expect validation or forbidden errors.
 * 6. Test update API with invalid/missing data and confirm error response.
 */
export async function test_api_auditLog_update_with_various_conditions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an audit log entry for update target
  const initial: IAuditLog = await api.functional.securityCompliance.auditLog.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      evidence_archive_id: typia.random<string & tags.Format<"uuid">>(),
      action: "create",
      entity_type: "order",
      entity_id: typia.random<string & tags.Format<"uuid">>(),
      context: JSON.stringify({ before: null, after: { foo: "bar" } }),
    } satisfies IAuditLog.ICreate,
  });
  typia.assert(initial);

  // 2. Update allowed fields (context/evidence_archive_id)
  const updateRequest: IAuditLog.IUpdate = {
    evidence_archive_id: typia.random<string & tags.Format<"uuid">>(),
    context: JSON.stringify({ before: { foo: "bar" }, after: { foo: "baz" }, annotation: "Appended context" }),
  };

  const updated: IAuditLog = await api.functional.securityCompliance.auditLog.putById(connection, {
    id: initial.id,
    body: updateRequest,
  });
  typia.assert(updated);

  // 3. Assert only allowed fields have changed; immutable fields remain
  TestValidator.equals("id should remain unchanged")<string>(initial.id)(updated.id);
  TestValidator.equals("action should remain unchanged")<string>(initial.action)(updated.action);
  TestValidator.equals("entity_type should remain unchanged")<string>(initial.entity_type)(updated.entity_type);
  TestValidator.equals("entity_id should remain unchanged")<string | undefined>(initial.entity_id)(updated.entity_id);
  TestValidator.equals("user_id should remain unchanged")<string | undefined>(initial.user_id)(updated.user_id);
  TestValidator.predicate("context updated correctly")(updated.context !== initial.context);
  TestValidator.predicate("evidence_archive_id updated correctly")(updated.evidence_archive_id !== initial.evidence_archive_id);

  // 4. Try to update a non-existent audit log and expect a not found error
  await TestValidator.httpError("Not found on nonexistent audit log update")(404)(() =>
    api.functional.securityCompliance.auditLog.putById(connection, {
      id: "00000000-0000-4000-8000-000000000000" as string & tags.Format<"uuid">,
      body: updateRequest,
    }),
  );

  // 5. Attempt to update immutable fields (should fail)
  const immutables: Partial<Record<string, any>>[] = [
    { created_at: new Date().toISOString() },
    { id: typia.random<string & tags.Format<"uuid">>() },
    { action: "something_else" },
    { entity_type: "user" },
  ];
  for (const attempt of immutables) {
    await TestValidator.error("Update forbidden on immutable fields")(() =>
      api.functional.securityCompliance.auditLog.putById(connection, {
        id: initial.id,
        body: { ...updateRequest, ...attempt },
      }),
    );
  }

  // 6. Test updates with invalid or missing data (should error)
  await TestValidator.error("Missing body should fail")(() =>
    api.functional.securityCompliance.auditLog.putById(connection, {
      id: initial.id,
      body: {},
    }),
  );
  await TestValidator.error("Bad context value should fail")(() =>
    api.functional.securityCompliance.auditLog.putById(connection, {
      id: initial.id,
      body: { context: JSON.stringify(42) },
    }),
  );
}

