/**
 * Test listing and searching compliance reports with advanced filters, searching, and pagination options.
 *
 * This scenario validates the compliance report listing endpoint by exercising extensive variations in the request body, including correct, empty, and malformed parameter sets as well as edge pagination behaviors. Confirm that valid filters return the expected set, improper or missing fields are robustly handled, and pagination information always remains consistent.
 *
 * 1. List compliance reports with no filters (default request).
 * 2. List compliance reports filtering by a single known (random/mock) user_id.
 * 3. List compliance reports filtered by organization_id and report_type, also varying status and generated_from/to date values.
 * 4. Provide intentionally malformed values (invalid UUID, date format) to verify validation or error handling response.
 * 5. Issue a search with an empty object to exercise endpoint defaults.
 * 6. Test pagination: request the first page, last page, and a page number beyond last. Confirm that pagination and data structure match expectations (empty or correct bounds).
 */
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IComplianceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IComplianceReport";
import { IPageIComplianceReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComplianceReport";

export async function test_api_compliance_report_query_pagination_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. List with default (no filters)
  const result1: IPageIComplianceReport.ISummary = await api.functional.securityCompliance.complianceReport.patch(connection, {
    body: {},
  });
  typia.assert(result1);
  TestValidator.equals("type: array")(true)(Array.isArray(result1.data));

  // Assume at least one compliance report is present for further filter tests
  const sample = result1.data[0];
  if (sample) {
    // 2. Filter by user_id
    const list2: IPageIComplianceReport.ISummary = await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: { user_id: sample.id } as any, // purposely plausible but maybe not correct type
    });
    typia.assert(list2);

    // 3. Filter by organization_id, report_type, status, and date range
    const now = new Date().toISOString();
    const list3: IPageIComplianceReport.ISummary = await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: {
        organization_id: "00000000-0000-4000-0000-000000000000",
        report_type: sample.report_type,
        status: sample.status,
        generated_from: sample.generated_at,
        generated_to: now,
      },
    });
    typia.assert(list3);
  }

  // 4. Malformed values: invalid uuid/date (should be robustly rejected or safely ignored)
  await TestValidator.error("invalid UUID in user_id")(() =>
    api.functional.securityCompliance.complianceReport.patch(connection, {
      body: { user_id: "not-a-uuid" },
    }),
  );
  await TestValidator.error("invalid date in generated_from")(() =>
    api.functional.securityCompliance.complianceReport.patch(connection, {
      body: { generated_from: "12345" },
    }),
  );

  // 5. Search with completely empty object
  const result5: IPageIComplianceReport.ISummary = await api.functional.securityCompliance.complianceReport.patch(connection, {
    body: {},
  });
  typia.assert(result5);

  // 6. Pagination check: get first, last and out-of-bounds page
  const totalPages = result5.pagination.pages;
  if (totalPages > 0) {
    // First page (should match default)
    const firstPage = await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: {},
    });
    typia.assert(firstPage);
    TestValidator.equals("pagination.current=1")(1)(firstPage.pagination.current);

    // Last valid page
    const lastPage = await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: { ...(result5 as any), pagination: { ...result5.pagination, current: totalPages } },
    });
    typia.assert(lastPage);
    TestValidator.equals("pagination.current=last")(totalPages)(lastPage.pagination.current);

    // Out-of-bounds (should be empty data or handled gracefully)
    const beyond = await api.functional.securityCompliance.complianceReport.patch(connection, {
      body: { ...(result5 as any), pagination: { ...result5.pagination, current: totalPages + 1 } },
    });
    typia.assert(beyond);
    TestValidator.equals("empty data array on out-of-bounds")(true)(beyond.data.length === 0);
  }
}

