/**
 * Validate listing and searching data retention policies with filters and pagination.
 *
 * This scenario tests the listing endpoint for data retention policies under various conditions, ensuring correct handling of:
 * - No filters: Retrieve all data retention policies with default pagination.
 * - Single filter: Retrieve policies filtered by a specific entity type (e.g., 'user').
 * - Multiple filters: Retrieve policies filtered by both organization and legal hold state.
 * - Pagination: Test proper paging by setting small limits and requesting non-first pages, including out-of-range.
 * - Edge/boundary pagination: Use limits of 0, negative, or excessively large values to test system robustness.
 * - No results: Provide impossible filter criteria and confirm empty result lists are handled gracefully.
 *
 * Steps:
 * 1. List all data retention policies without filters (default pagination).
 * 2. List data retention policies with entity_type filter.
 * 3. List data retention policies with organization_id and is_legal_hold filters.
 * 4. Paginate through the policy list (set limit=1 or 2, test page 2).
 * 5. Request a page well beyond existing records (e.g., current + 1000).
 * 6. Attempt listing with boundary/invalid pagination values (limit=0, -1, very large).
 * 7. Attempt a query guaranteed to return zero records (nonsense entity_type).
 * 8. Validate all responses for type and data contract with typia.assert().
 */
export async function test_api_data_retention_list_with_various_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. List all data retention policies without filters (default pagination)
  const all: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: {},
    });
  typia.assert(all);
  TestValidator.equals("pagination is present")(true)(!!all.pagination);

  // 2. List data retention policies with entity_type filter
  const filterEntity: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { entity_type: "user" },
    });
  typia.assert(filterEntity);
  if (filterEntity.data.length > 0)
    for (const rec of filterEntity.data)
      TestValidator.equals("entity_type == 'user'")("user")(rec.entity_type);

  // 3. List data retention policies with organization_id and is_legal_hold filters
  // Use a valid organization_id if possible from previous data
  let orgId: string | undefined;
  if (all.data.length > 0) {
    orgId = all.data.find(x => x.organization_id)?.organization_id || undefined;
  }
  const filterMultiple: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: orgId
        ? { organization_id: orgId, is_legal_hold: true }
        : { is_legal_hold: true },
    });
  typia.assert(filterMultiple);
  if (filterMultiple.data.length > 0) {
    if (orgId)
      for (const rec of filterMultiple.data)
        TestValidator.equals("organization_id matches")(orgId ?? "")(rec.organization_id ?? "");
    for (const rec of filterMultiple.data)
      TestValidator.equals("is_legal_hold == true")(true)(rec.is_legal_hold);
  }

  // 4. Paginate through the policy list (limit=1, page 2)
  const filterPaginated: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { ...(orgId ? { organization_id: orgId } : {}), limit: 1, current: 2 },
    } as any); // Allow extra properties for pagination even if not in IRequest strictly
  typia.assert(filterPaginated);
  TestValidator.equals("limit is 1")(1)(filterPaginated.pagination.limit);
  TestValidator.equals("current is 2")(2)(filterPaginated.pagination.current);

  // 5. Request a page well beyond existing records
  const beyondPage: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { ...(orgId ? { organization_id: orgId } : {}), limit: 1, current: (all.pagination?.pages || 1) + 1000 },
    } as any);
  typia.assert(beyondPage);
  TestValidator.equals("no records on page out of range")(0)(beyondPage.data.length);

  // 6. Attempt listing with boundary/invalid pagination values
  const zeroLimit: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { limit: 0 } as any,
    });
  typia.assert(zeroLimit);
  const negLimit: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { limit: -1 } as any,
    });
  typia.assert(negLimit);
  const largeLimit: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { limit: 100_000 } as any,
    });
  typia.assert(largeLimit);

  // 7. Query guaranteed to return zero records
  const zeroResult: IPageIDataRetention.ISummary =
    await api.functional.securityCompliance.dataRetention.patch(connection, {
      body: { entity_type: "no-such-entity-type-surely" },
    });
  typia.assert(zeroResult);
  TestValidator.equals("zero results when entity_type does not exist")(0)(zeroResult.data.length);
}

