import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IDataRetention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDataRetention";

/**
 * Test updating a data retention policy via valid and invalid inputs.
 *
 * This E2E test covers the following scenarios for the data retention policy update endpoint:
 * 1. Create a new data retention policy for testing.
 * 2. Update the policy by valid ID, changing allowed fields (retention_period_days, is_legal_hold).
 * 3. Attempt to update immutable/disallowed fields and expect the failure.
 * 4. Attempt update with invalid/bad data and expect a validation error.
 * 5. Attempt update with a nonexistent ID and expect a not-found or error response.
 * 6. Verify the updated policy accurately reflects permitted mutations.
 */
export async function test_api_dataRetention_update_variants(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new data retention policy
  const createBody: IDataRetention.ICreate = {
    entity_type: "user",
    retention_period_days: 365,
    is_legal_hold: false,
    organization_id: null,
  };
  const created: IDataRetention = await api.functional.securityCompliance.dataRetention.post(connection, {
    body: createBody,
  });
  typia.assert(created);

  // 2. Update by valid ID: allowed fields
  const updateBody: IDataRetention.IUpdate = {
    retention_period_days: 730,
    is_legal_hold: true,
  };
  const updated: IDataRetention = await api.functional.securityCompliance.dataRetention.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("retention_period_days updated")(730)(updated.retention_period_days);
  TestValidator.equals("is_legal_hold updated")(true)(updated.is_legal_hold);
  TestValidator.equals("entity_type immutable")(created.entity_type)(updated.entity_type);
  TestValidator.equals("organization_id immutable")(created.organization_id)(updated.organization_id);
  TestValidator.equals("created_at immutable")(created.created_at)(updated.created_at);

  // 3. Attempt to update immutable/disallowed fields (should ignore or error)
  const badUpdate: any = {
    entity_type: "order", // immutable
    organization_id: "00000000-0000-0000-0000-000000000000", // immutable
    created_at: new Date().toISOString(), // immutable
    retention_period_days: 90,
  };
  await TestValidator.error("should not allow changing immutable fields")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: created.id,
      body: badUpdate,
    }),
  );

  // 4. Attempt update with invalid/bad data
  await TestValidator.error("should fail on invalid data")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: created.id,
      // invalid value: negative retention days
      body: {
        retention_period_days: -100,
      },
    }),
  );

  // 5. Attempt update with a nonexistent ID
  await TestValidator.error("should fail with nonexistent ID")(() =>
    api.functional.securityCompliance.dataRetention.putById(connection, {
      id: "00000000-1111-2222-3333-444444444444" as string & tags.Format<"uuid">,
      body: updateBody,
    }),
  );

  // 6. Final read: confirm persisted changes
  const after: IDataRetention = await api.functional.securityCompliance.dataRetention.putById(connection, {
    id: created.id,
    body: {}, // no changes
  });
  typia.assert(after);
  TestValidator.equals("final retention_period_days")(730)(after.retention_period_days);
  TestValidator.equals("final is_legal_hold")(true)(after.is_legal_hold);
}

