/**
 * Test soft deleting a data retention policy by ID, ensuring compliance evidence is retained.
 *
 * Steps:
 * 1. Create a data retention policy for test.
 * 2. Soft delete the created policy by its ID and validate that evidence of policy remains.
 * 3. Attempt to delete the already soft-deleted policy again, validate correct error handling (e.g. not found or forbidden).
 * 4. Attempt to delete using a completely invalid/non-existent policy ID, confirm that the correct error is raised.
 *
 * This ensures deletion follows compliance (evidence/audit not physically erased), prevents duplicate deletion, and guards against invalid IDs.
 */
export async function test_api_dataRetention_soft_delete_and_error_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a data retention policy for testing
  const createBody: IDataRetention.ICreate = {
    entity_type: "user",
    retention_period_days: 365,
    is_legal_hold: false,
    organization_id: null,
  };
  const policy: IDataRetention = await api.functional.securityCompliance.dataRetention.post(connection, { body: createBody });
