import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IEvidenceArchive";
import { IPageIEvidenceArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEvidenceArchive";
import typia from "typia";

/**
 * Test listing and searching evidence archive records with different filters and pagination.
 *
 * Verifies listing and accurate search for evidence archive records via the /securityCompliance/evidenceArchive PATCH API.
 * Includes tests for unfiltered, filtered, paginated, empty, over-limit, and malformed requests.
 *
 * 1. Query all evidence archives, no filters (default pagination)
 * 2. Filter by evidence_type: verify all returned respect filter
 * 3. Filter by checksum: ensure only matching record(s) returned
 * 4. Filter by created_at_from and/or created_at_to: correct date-filtered window
 * 5. Pagination: request page/limit, check correct subset of results
 * 6. Edge: limit=max allowed and limit above max
 * 7. Malformed input: negative page/limit, invalid date
 * 8. Empty result: filters that guarantee no match
 */
export async function test_api_evidence_archive_list_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Unfiltered (default) query
  const page1: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: {},
  });
  typia.assert(page1);

  // early exist check: if no data, skip further filters
  if (!page1.data.length) return;
  const sample = page1.data[0];

  // 2. Filter by evidence_type
  const byType: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { evidence_type: sample.evidence_type },
  });
  typia.assert(byType);
  for (const rec of byType.data) TestValidator.equals("evidence_type")(sample.evidence_type)(rec.evidence_type);

  // 3. Filter by checksum
  const byChecksum: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { checksum: sample.checksum },
  });
  typia.assert(byChecksum);
  for (const rec of byChecksum.data) TestValidator.equals("checksum")(sample.checksum)(rec.checksum);

  // 4. Filter by date window (tight window guaranteed to include sample)
  const byDate: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: {
      created_at_from: sample.created_at,
      created_at_to: sample.created_at,
    },
  });
  typia.assert(byDate);
  for (const rec of byDate.data) {
    TestValidator.equals("created_at_from")(sample.created_at <= rec.created_at)(true);
    TestValidator.equals("created_at_to")(sample.created_at >= rec.created_at)(true);
  }

  // 5. Pagination
  const paginated: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { page: 2, limit: 1 },
  });
  typia.assert(paginated);
  TestValidator.equals("page index")(paginated.pagination.current)(2);
  TestValidator.equals("page limit")(paginated.pagination.limit)(1);
  TestValidator.equals("page data size")(paginated.data.length <= 1)(true);

  // 6. Edge: max limit (assuming 100), and over-limit (expect clamp or error)
  const maxLimit = 100;
  const paginatedMax: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { limit: maxLimit },
  });
  typia.assert(paginatedMax);
  TestValidator.equals("limit=max")(paginatedMax.pagination.limit)(maxLimit);

  const overMaxLimit = maxLimit + 1;
  await TestValidator.error("limit above max")(() => api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { limit: overMaxLimit },
  }));

  // 7. Malformed inputs
  await TestValidator.error("negative page")(() => api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { page: -1 },
  }));
  await TestValidator.error("negative limit")(() => api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { limit: -10 },
  }));
  await TestValidator.error("bad date format")(() => api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { created_at_from: "bad-date" as any },
  }));

  // 8. Empty result
  const empty: IPageIEvidenceArchive = await api.functional.securityCompliance.evidenceArchive.patch(connection, {
    body: { evidence_type: "totally-unlikely-fake-type-cb529d6c0" },
  });
  typia.assert(empty);
  TestValidator.equals("empty result")(empty.data.length)(0);
}

