 *
 * Validates the correct behavior of API client listing endpoint,
 * including:
 *  1. Query with empty filter for listing all (default pagination)
 *  2. Filter by a single field (e.g., client_name or is_active)
 *  3. Complex filter with multiple fields at once
 *  4. Pagination controls: limit and offset (page)
 *  5. Invalid/malformed query parameters (error handling)
 */
export async function test_apiClients_list_with_various_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Basic: List all (no filter, default pagination)
  const resultAll: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(connection, {
    body: {},
  });
  typia.assert(resultAll);

  // 2. Filter: By single field (client_name)
  if (resultAll.data.length > 0) {
    const targetClient = resultAll.data[0];
    const resultByName: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(connection, {
      body: { client_name: targetClient.client_name },
    });
    typia.assert(resultByName);
    for (const client of resultByName.data) {
      TestValidator.equals("client_name matches")(targetClient.client_name)(client.client_name);
    }
  }

  // 3. Complex filter: client_name + is_active + contact_email
  if (resultAll.data.length > 0) {
    const targetClient = resultAll.data[0];
    const resultComplex: IPageIApiClients = await api.functional.apiOmnichannel.apiClients.patch(connection, {
      body: {
        client_name: targetClient.client_name,
        is_active: targetClient.is_active,
