import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IPageIUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIUser";
import { IUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IUser";

/**
 * Validate paginated and filtered user list retrieval.
 *
 * This test checks that the user listing API supports filtering, pagination, and correct edge-case handling as per requirements. Core steps:
 *
 * 1. Request users list (default page/limit), ensure pagination metadata and data presence.
 * 2. Apply username/email filters and confirm only correct users are included.
 * 3. Use is_active and organization_id filters to check RBAC/active state filtering.
 * 4. Request a high, out-of-bounds page (e.g., page=9999), expect empty data array or appropriate error handling.
 * 5. Ensure response meta (current, limit, records, pages) matches data length and filter state.
 */
export async function test_api_user_list_users_with_pagination_and_filtering(connection: api.IConnection): Promise<void> {
  // 1. Fetch first page with default params
  const page1: IPageIUser = await api.functional.core.users.patch(connection, { body: {} });
  typia.assert(page1);

  TestValidator.equals("First page current page")(1)(page1.pagination.current);
  TestValidator.equals("First page page size")(page1.data.length)(Math.min(page1.pagination.limit, page1.pagination.records));
  TestValidator.equals("Records nonnegative")(true)(page1.pagination.records >= 0);

  // 2. If data exists, filter by username/email of first user
  if (page1.data.length > 0) {
    const firstUser = page1.data[0];

    // Filter by username
    const pageByUsername: IPageIUser = await api.functional.core.users.patch(connection, { body: { username: firstUser.username } });
    typia.assert(pageByUsername);
    expectUserListSubset([firstUser], pageByUsername.data, "username filter");

    // Filter by email
    const pageByEmail: IPageIUser = await api.functional.core.users.patch(connection, { body: { email: firstUser.email } });
    typia.assert(pageByEmail);
    expectUserListSubset([firstUser], pageByEmail.data, "email filter");

    // Filter by organization_id
    const pageByOrg: IPageIUser = await api.functional.core.users.patch(connection, { body: { organization_id: firstUser.organization_id } });
    typia.assert(pageByOrg);
    TestValidator.equals("All users belong to organization")(true)(pageByOrg.data.every(u => u.organization_id === firstUser.organization_id));

    // Filter by is_active
    const pageByActive: IPageIUser = await api.functional.core.users.patch(connection, { body: { is_active: firstUser.is_active } });
    typia.assert(pageByActive);
    TestValidator.equals("All users active flag")(true)(pageByActive.data.every(u => u.is_active === firstUser.is_active));
  }

  // 3. Query high page expected to be empty (pagination beyond actual pages)
  const emptyPage: IPageIUser = await api.functional.core.users.patch(connection, { body: { page: 9999, limit: 10 } });
  typia.assert(emptyPage);
  TestValidator.equals("Empty page data")(0)(emptyPage.data.length);
  TestValidator.equals("Pagination beyond pages")(emptyPage.pagination.pages)(emptyPage.pagination.pages);
}

function expectUserListSubset(expected: IUser[], actual: IUser[], description: string) {
  const expectedSet = new Set(expected.map(u => u.id));
  for (const u of actual) {
    TestValidator.equals(`User from result [${description}]`)(true)(expectedSet.has(u.id));
  }
}

