 *
 * Test Steps:
 * 1. Create a new user to acquire a fresh user ID
 * 2. Soft-delete this user (DELETE /core/users/:id)
 * 3. Assert returned structure contains the correct user id and deleted_at timestamp
 * 4. (Optional: Listing API not present, skip listing check)
 * 5. Attempt to repeat deletion for the same user, expecting error or idempotent confirmation
 * 6. Attempt to delete a non-existent user, expecting proper error handling
 *
 * Background:
 * - The test follows audit, compliance, and evidence preservation requirements for soft deletion.
 * - Ensures permanently deleted flag (deleted_at) is set, and operation is logged.
 * - Verifies correct error signals for double-deletion/idempotency and missing resources.
 */
export async function test_delete_user_soft_delete_and_idempotency(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new user
  const uniqueSeed = Date.now();
  const userCreate: IUser.ICreate = {
    username: `testuser_${uniqueSeed}`,
    email: `testuser_${uniqueSeed}@test.com`,
