 *
 * The test ensures the profile search API and pagination behaves as expected for all core scenarios.
 */
export async function test_api_userprofile_list_with_pagination_and_filters(connection: api.IConnection): Promise<void> {
  // 1. Create user profiles with various attributes
  const baseUserId = crypto.randomUUID();
  const profiles: IUserProfile[] = [];
  for (let i = 0; i < 5; ++i) {
    const profile: IUserProfile = await api.functional.core.userProfiles.post(connection, {
      body: {
        user_id: crypto.randomUUID(),
        locale_id: i % 2 === 0 ? "11111111-1111-1111-1111-111111111111" : "22222222-2222-2222-2222-222222222222",
        full_name: `Test User ${i}`,
