 * This test seeds multiple organizations and verifies the correct working of
 * organization list/search endpoint, including:
 * - Pagination (page/limit)
 * - Filtering by name and code
 * - Edge cases: empty filter results, pagination out-of-bounds
 *
 * 1. Create several organizations with distinct names/codes to serve as search and pagination data
 * 2. List organizations without any filter, ensure all exist, test basic paging
 * 3. List organizations by a specific name filter, expect correct only-result
 * 4. List organizations by a code filter, expect only matching entity
 * 5. Query a non-existent name filter and assert zero results
 * 6. Query a non-existent code filter and assert zero results
 * 7. Provide page number exceeding total, expect empty data but valid pagination meta
 */
export async function test_list_organizations_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seed organizations with unique names/codes
  const organizations: IOrganization[] = [];
  for (let i = 0; i < 5; ++i) {
    const org = await api.functional.core.organizations.post(connection, {
      body: {
        name: `Test Organization ${i}_${Date.now()}`,
        code: `test-org-code-${i}-${Math.random().toString(36).slice(2, 10)}`,
      } satisfies IOrganization.ICreate,
    });
    typia.assert(org);
    organizations.push(org);
  }

  // 2. List all organizations - basic (limit covers just seeded)
  const allPage: IPageIOrganization = await api.functional.core.organizations.patch(connection, {
    body: {
      limit: organizations.length,
      page: 1,
    } satisfies IOrganization.IRequest,
  });
  typia.assert(allPage);
  for (const org of organizations)
    TestValidator.equals(`org by id (${org.id})`)(
      true,
    )(
      allPage.data.some((x) => x.id === org.id),
    );

  // 3. Filter by one seeded name
  const filterName = organizations[2].name;
  const pageName = await api.functional.core.organizations.patch(connection, {
    body: { name: filterName } satisfies IOrganization.IRequest,
  });
  typia.assert(pageName);
  TestValidator.equals("filter by name count")(1)(pageName.data.length);
  TestValidator.equals("filter by name id")(organizations[2].id)(pageName.data[0].id);

  // 4. Filter by code
  const filterCode = organizations[3].code;
  const pageCode = await api.functional.core.organizations.patch(connection, {
    body: { code: filterCode } satisfies IOrganization.IRequest,
  });
  typia.assert(pageCode);
  TestValidator.equals("filter by code count")(1)(pageCode.data.length);
  TestValidator.equals("filter by code id")(organizations[3].id)(pageCode.data[0].id);

  // 5. Non-existent name returns empty
