  // 6. Non-existent code returns empty
  const nonePageCode = await api.functional.core.organizations.patch(connection, {
    body: { code: "no-such-test-org-code-never-exists" } satisfies IOrganization.IRequest,
  });
  typia.assert(nonePageCode);
  TestValidator.equals("empty by non-existent code")(0)(nonePageCode.data.length);

  // 7. High page number returns empty, valid meta
  const bigPage = await api.functional.core.organizations.patch(connection, {
    body: {
      limit: organizations.length,
      page: 9999,
    } satisfies IOrganization.IRequest,
  });
  typia.assert(bigPage);
  TestValidator.equals("big page empty")(0)(bigPage.data.length);
  TestValidator.equals("big page meta page")(9999)(bigPage.pagination.current);
