import { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";
import typia from "typia";

/**
 * Validate creation of a new organization and related constraints.
 *
 * Scenario background: Organizations are the core business entity—crucial for multi-tenant, B2B, and compliance management. Each organization requires unique name and code. Field validations, error handling, and uniqueness must be strictly enforced to satisfy operational, audit, and compliance requirements.
 *
 * Step-by-step process:
 * 1. Create organization with valid data. Ensure all details are persisted and response matches input (plus server fields).
 * 2. Attempt creation with missing "name". Should receive validation error.
 * 3. Attempt creation with missing "code". Should receive validation error.
 * 4. Attempt creation with empty strings for required fields. Should receive validation error.
 * 5. Attempt creation with duplicate "name". Should receive uniqueness/duplicate error.
 * 6. Attempt creation with duplicate "code". Should receive uniqueness/duplicate error.
 */
export async function test_api_organization_create_and_validation(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create with valid data
  const orgInput: IOrganization.ICreate = {
    name: `WrtnTestOrg_${Date.now()}`,
    code: `wrtn_test_code_${Date.now()}`,
  };
  const organization: IOrganization = await api.functional.core.organizations.post(
    connection,
    {
      body: orgInput satisfies IOrganization.ICreate,
    },
  );
  typia.assert(organization);
  TestValidator.equals("organization.name")(orgInput.name)(organization.name);
  TestValidator.equals("organization.code")(orgInput.code)(organization.code);

  // Step 2: Missing name
  await TestValidator.httpError("missing name - validation")(400)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        // name is missing
        code: `test_missing_name_${Date.now()}`,
      } as any,
    }),
  );

  // Step 3: Missing code
  await TestValidator.httpError("missing code - validation")(400)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: "Test Missing Code",
        // code is missing
      } as any,
    }),
  );

  // Step 4: Empty required fields
  await TestValidator.httpError("empty name - validation")(400)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: "",
        code: `emptynm_code_${Date.now()}`,
      } as IOrganization.ICreate,
    }),
  );
  await TestValidator.httpError("empty code - validation")(400)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: `EmptCdName_${Date.now()}`,
        code: "",
      } as IOrganization.ICreate,
    }),
  );

  // Step 5: Duplicate name
  await TestValidator.httpError("duplicate name - uniqueness")(409)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: orgInput.name,
        code: `unique_code_${Date.now()}`,
      } satisfies IOrganization.ICreate,
    }),
  );

  // Step 6: Duplicate code
  await TestValidator.httpError("duplicate code - uniqueness")(409)(() =>
    api.functional.core.organizations.post(connection, {
      body: {
        name: `unique_name_${Date.now()}`,
        code: orgInput.code,
      } satisfies IOrganization.ICreate,
    }),
  );
}

