import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";

/**
 * Validate organization update (PUT /core/organizations/:id).
 *
 * 1. Create a new organization (POST /core/organizations).
 * 2. Update organization details with valid values; verify updates reflected.
 * 3. Attempt to update with invalid payload (e.g. empty name/code); expect validation error.
 * 4. Attempt to update a non-existent organization ID; expect 404 error.
 */
export async function test_api_organization_update_valid_invalid_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create organization.
  const orgCreate: IOrganization.ICreate = {
    name: `Test Org ${Date.now()}`,
    code: `test-org-${Math.floor(Math.random() * 100000)}`,
  };
  const organization: IOrganization = await api.functional.core.organizations.post(connection, { body: orgCreate });
  typia.assert(organization);

  // 2. Update organization with valid data.
  const updatePayload: IOrganization.IUpdate = {
    name: `Updated Org ${Date.now()}`,
    code: `updated-org-${Math.floor(Math.random() * 100000)}`,
  };
  const updated: IOrganization = await api.functional.core.organizations.putById(connection, {
    id: organization.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("updated id")(organization.id)(updated.id);
  TestValidator.equals("updated name")(updatePayload.name)(updated.name);
  TestValidator.equals("updated code")(updatePayload.code)(updated.code);

  // 3. Update with invalid data (empty name) - expect validation error (400 or 422).
  await TestValidator.error("invalid update payload")(async () =>
    api.functional.core.organizations.putById(connection, {
      id: organization.id,
      body: { name: "" },
    })
  );

  // 4. Update with non-existent ID - expect not found error (404).
  const nonExistentId: string & tags.Format<"uuid"> =
    "00000000-0000-4000-8000-000000000000";
  await TestValidator.httpError("not found on update")(404)(() =>
    api.functional.core.organizations.putById(connection, {
      id: nonExistentId,
      body: {
        name: "Should Not Work",
      },
    })
  );
}

