import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrganization } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrganization";
import typia, { tags } from "typia";

/**
 * Soft-delete an existing organization and validate idempotency and error handling.
 *
 * This test simulates the soft-deletion of an organization and ensures correct audit and idempotent behaviors as per system compliance:
 *
 * 1. Create (seed) a new organization for testing.
 * 2. Soft-delete the organization and validate response.
 * 3. Attempt to re-delete the same organization; verify idempotency or error.
 * 4. Attempt to delete a non-existent (random UUID) organization and expect appropriate handling.
 *
 * This ensures organizations are only soft-deleted for audit, cannot be "hard" removed, and handles edge cases as required.
 */
export async function test_api_organization_soft_delete_and_idempotency(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seed: Create a new organization to delete
  const orgCreatePayload = {
    name: `Test Org ${Date.now()}`,
    code: `test-org-${Date.now()}`,
  } satisfies IOrganization.ICreate;
  const org: IOrganization = await api.functional.core.organizations.post(connection, { body: orgCreatePayload });
  typia.assert(org);

  // 2. Soft-delete the organization
  const deleted: IOrganization = await api.functional.core.organizations.eraseById(connection, { id: org.id });
  typia.assert(deleted);
  TestValidator.equals("deleted organization id should match")(org.id)(deleted.id);
  // (If there exists a field like deleted_at or similar, assert its presence here)

  // 3. Attempt to delete already deleted org again
  try {
    const deletedAgain: IOrganization = await api.functional.core.organizations.eraseById(connection, { id: org.id });
    typia.assert(deletedAgain);
    TestValidator.equals("re-deleting already deleted org should remain idempotent")(org.id)(deletedAgain.id);
  } catch (err) {
    // Acceptable alternative: system may return 404 or specific error, validate error condition
    TestValidator.error("re-deleting already deleted org should error or be idempotent")(() => { throw err; });
  }

  // 4. Attempt to delete a non-existent organization
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("deleting non-existent org should error")(
    () => api.functional.core.organizations.eraseById(connection, { id: randomId })
  );
}

test/features/api/role/test_list_roles_w:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IRole";
import { IPageIRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRole";
import typia from "typia";

/**
 * List roles with various filters, search and pagination settings.
 *
 * Validate that role listing works correctly with different filters, search terms,
 * and pagination options. The test also verifies that the pagination
 * logic functions as expected, including empty or error cases for excessive page numbers.
 *
 * This test seeds sufficient roles to allow meaningful testing of filters and pagination.
 *
 * 1. Seed multiple role records with various names, codes, and organization_ids for comprehensive query scenarios.
 * 2. Query roles using no filter (default—should return all roles paginated).
 * 3. Query roles filtered by organization_id and validate that only roles of that org are returned.
 * 4. Query roles filtered by name and validate that only matching roles are returned.
 * 5. Query roles filtered by code and validate correct entries are returned.
 * 6. Query roles using a specific page/limit and check pagination metadata and returned data match expectations.
 * 7. Attempt to query with an excessive page number (beyond last page) and confirm response is empty or returns appropriate error/empty state.
 */
export async function test_api_role_list_roles_with_search_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seed roles into multiple organizations with various names and codes
  const orgA = typia.random<string & typia.tags.Format<"uuid">>();
  const orgB = typia.random<string & typia.tags.Format<"uuid">>();

  // Seed roles in orgA
  const adminA = await api.functional.core.roles.post(connection, {
    body: {
      organization_id: orgA,
      name: "admin",
      code: "ADMIN",
      description: "Administrator role for orgA",
    } satisfies IRole.ICreate,
  });
  typia.assert(adminA);

  const managerA = await api.functional.core.roles.post(connection, {
    body: {
      organization_id: orgA,
      name: "manager",
      code: "MANAGER",
      description: "Manager role for orgA",
    } satisfies IRole.ICreate,
  });
  typia.assert(managerA);

  // Seed roles in orgB
  const adminB = await api.functional.core.roles.post(connection, {
    body: {
      organization_id: orgB,
      name: "admin",
      code: "ADMIN",
      description: "Administrator role for orgB",
    } satisfies IRole.ICreate,
  });
  typia.assert(adminB);

  const staffB = await api.functional.core.roles.post(connection, {
    body: {
      organization_id: orgB,
      name: "staff",
      code: "STAFF",
      description: "Staff role for orgB",
    } satisfies IRole.ICreate,
  });
  typia.assert(staffB);

  // 2. Query all roles with no filter (defaults/pagination)
  const allRoles: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {},
  });
  typia.assert(allRoles);
  TestValidator.equals("all seeded roles returned")(
    4,
  )(allRoles.data.length);
  const allIds = allRoles.data.map((r) => r.id).sort();
  TestValidator.equals("all seeded role ids present")(
    [adminA.id, managerA.id, adminB.id, staffB.id].sort(),
  )(allIds);

  // 3. Query with organization_id filter for orgA
  const orgARoles: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {
      organization_id: orgA,
    },
  });
  typia.assert(orgARoles);
  TestValidator.equals("only orgA roles")(
    [adminA.id, managerA.id].sort(),
  )(orgARoles.data.map((r) => r.id).sort());
  orgARoles.data.forEach((r) =>
    TestValidator.equals("organization_id matches orgA")(orgA)(r.organization_id),
  );

  // 4. Query with name filter for "admin"
  const adminRoles: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {
      name: "admin",
    },
  });
  typia.assert(adminRoles);
  // Both adminA and adminB should be returned, possibly with pagination
  const adminReturnedIds = adminRoles.data.map((r) => r.id).sort();
  TestValidator.equals("only admin name roles")(
    [adminA.id, adminB.id].sort(),
  )(adminReturnedIds);
  adminRoles.data.forEach((r) =>
    TestValidator.equals("role name is admin")("admin")(r.name),
  );

  // 5. Query with code filter for "STAFF"
  const staffRoles: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {
      code: "STAFF",
    },
  });
  typia.assert(staffRoles);
  TestValidator.equals("only staffB found")([staffB.id])(staffRoles.data.map((r) => r.id));
  staffRoles.data.forEach((r) =>
    TestValidator.equals("role code is STAFF")("STAFF")(r.code),
  );

  // 6. Query with specific page and limit (pagination logic)
  // Let's ask for limit=2, check page 1 and page 2 contain expected data
  const page1: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(page1);
  TestValidator.equals("page 1, limit 2 has 2 records or less")(
    true,
  )(page1.data.length <= 2);
  TestValidator.equals("pagination current page")(
    1,
  )(page1.pagination.current);
  TestValidator.equals("pagination limit")(
    2,
  )(page1.pagination.limit);

  const page2: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: {
      page: 2,
      limit: 2,
    },
  });
  typia.assert(page2);
  TestValidator.equals("page 2, limit 2 has 2 records or less")(
    true,
  )(page2.data.length <= 2);
  TestValidator.equals("pagination current page")(
    2,
  )(page2.pagination.current);

  // Combined data from both pages (should contain all four roles w/o duplication)
  const pagedIds = [...page1.data, ...page2.data].map((r) => r.id).sort();
  TestValidator.equals("all expected IDs present after pagination")(
    [adminA.id, managerA.id, adminB.id, staffB.id].sort(),
  )(pagedIds);

  // 7. Query with excessive page number (should be empty)
  const excessivePage: IPageIRole = await api.functional.core.roles.patch(connection, {
    body: { page: 100, limit: 2 },
  });
  typia.assert(excessivePage);
  TestValidator.equals("excessive page is empty")(
    0,
  )(excessivePage.data.length);
}

