import typia from "typia";

/**
 * Test session listing/search API with pagination and advanced filters.
 *
 * To verify robust pagination, filtering, and error handling:
 * 1. Seed at least 3 sessions with diverse user_id, expires_at, device_fingerprint, and ip.
 * 2. List all sessions with no filter; assert seeded sessions are present and types are correct.
 * 3. Filter by user_id; results must only include that user's sessions.
 * 4. Filter by device_fingerprint/ip; check filtering logic.
 * 5. Filter by expires_before and expires_after for time range.
 * 6. Paginate (limit=1); verify correct session and pagination metadata per page.
 * 7. Query page far out of range (e.g. 1000); expect empty result.
 * 8. Combine non-matching filters (ip+user_id); expect empty result, no error.
 * 9. Send invalid filter values (e.g. bad UUID); expect a validation error response.
 *
 * Validates API structure, filter logic accuracy, proper empty result for no matches, and proper error for invalid input.
 */
export async function test_api_session_list_sessions_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create diverse sessions
  const users = [typia.random<string>(), typia.random<string>(), typia.random<string>()];
  const now = new Date();
  const future = new Date(now.getTime() + 86400000);

  const sessionA: ISession = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: users[0],
      token: typia.random<string>(),
      expires_at: future.toISOString(),
      device_fingerprint: "alpha-fingerprint",
      ip: "1.2.3.4",
    } satisfies ISession.ICreate,
  });
  typia.assert(sessionA);

  const sessionB: ISession = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: users[1],
      token: typia.random<string>(),
      expires_at: now.toISOString(),
      device_fingerprint: "beta-fingerprint",
      ip: "5.6.7.8",
    } satisfies ISession.ICreate,
  });
  typia.assert(sessionB);

  const sessionC: ISession = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: users[2],
      token: typia.random<string>(),
      expires_at: new Date(now.getTime() + 43200000).toISOString(),
      device_fingerprint: "charlie-fingerprint",
      ip: "9.10.11.12",
    } satisfies ISession.ICreate,
  });
  typia.assert(sessionC);

  // 2. List all sessions (no filters)
  const allSessions: IPageISession = await api.functional.core.sessions.patch(connection,{
    body: {},
  });
  typia.assert(allSessions);
  // Assert created session IDs returned in data
  TestValidator.predicate("all sessions contain seeded", () => [sessionA.id, sessionB.id, sessionC.id].every(id => allSessions.data.map(s => s.id).includes(id)));

  // 3. Filter by user_id
  const byUser: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { user_id: users[0] },
  });
  typia.assert(byUser);
  TestValidator.equals("user filter session count")(
    byUser.data.length
  )(1);
  TestValidator.equals("user filter ID match")(byUser.data[0].user_id)(users[0]);

  // 4. Filter by device_fingerprint
  const byFingerprint: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { device_fingerprint: "beta-fingerprint" },
  });
  typia.assert(byFingerprint);
  TestValidator.equals("fingerprint count")(byFingerprint.data.length)(1);
  TestValidator.equals("fingerprint match")(byFingerprint.data[0].device_fingerprint)("beta-fingerprint");

  // 4b. Filter by ip
  const byIp: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: { ip: "9.10.11.12" },
  });
  typia.assert(byIp);
  TestValidator.equals("ip count")(byIp.data.length)(1);
  TestValidator.equals("ip match")(byIp.data[0].ip)("9.10.11.12");

  // 5. Filter by expires_before and expires_after
  const expiresBefore = new Date(now.getTime() + 50000).toISOString();
  const byExpires: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: {
      expires_before: expiresBefore,
    },
  });
  typia.assert(byExpires);
  TestValidator.equals("expires_before")(byExpires.data.length)(1);
  TestValidator.equals("expires_before ID")(byExpires.data[0].id)(sessionB.id);

  const expiresAfter = new Date(now.getTime() + 5000).toISOString();
  const byExpiresAfter: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: {
      expires_after: expiresAfter,
    },
  });
  typia.assert(byExpiresAfter);
  // sessionA and sessionC should match
  const expectedIds = [sessionA.id, sessionC.id].sort();
  const actualIds = byExpiresAfter.data.map(s => s.id).sort();
  TestValidator.equals("expires_after IDs")(actualIds)(expectedIds);

  // 6. Pagination: limit = 1, get page 1/2/3, check each session & meta
  for (let i = 1; i <= 3; ++i) {
    const paged: IPageISession = await api.functional.core.sessions.patch(connection, {
      body: {
        page: i,
        limit: 1,
      },
    });
    typia.assert(paged);
    TestValidator.equals("pagination current page")(paged.pagination.current)(i);
    TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
    TestValidator.equals("records")(paged.pagination.records)(allSessions.pagination.records);
    TestValidator.equals("pages")(paged.pagination.pages)(3);
    // session id on page matches one of seeded sessions
    TestValidator.predicate(`session page ${i}`, () => [sessionA.id, sessionB.id, sessionC.id].includes(paged.data[0].id));
  }

  // 7. Out-of-bounds page (empty dataset)
  const outOfRange: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: {
      page: 1000,
      limit: 1,
    },
  });
  typia.assert(outOfRange);
  TestValidator.equals("oob page empty")(outOfRange.data.length)(0);

  // 8. Non-matching multi-filters (ip+user_id)
  const impossible: IPageISession = await api.functional.core.sessions.patch(connection, {
    body: {
      ip: "not-an-ip",
      user_id: users[0],
    },
  });
  typia.assert(impossible);
  TestValidator.equals("no result combo filters")(impossible.data.length)(0);

  // 9. Invalid values: user_id not a uuid
  await TestValidator.httpError("invalid user_id fails")(400)(() =>
    api.functional.core.sessions.patch(connection, {
      body: {
        user_id: "bad-uuid",
      },
    })
  );
}

