import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import typia, { tags } from "typia";

/**
 * Validate retrieval of session by ID and correct error handling for unknown IDs.
 *
 * This scenario ensures that the session API can:
 * 1. Correctly create a user session.
 * 2. Retrieve an existing session by a valid session ID with full details.
 * 3. Properly respond with an error when a request is made for a non-existent session ID.
 *
 * [Scenario steps]
 * 1. Create a new session (POST /core/sessions)
 * 2. Retrieve the created session by ID (GET /core/sessions/{id})
 * 3. Attempt to retrieve with a non-existent random UUID and verify correct error response.
 */
export async function test_api_session_get_by_id_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new session
  const sessionCreate: ISession.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    token: "token-" + Math.random().toString(36).substring(2),
    expires_at: new Date(Date.now() + 3600 * 1000).toISOString(),
    device_fingerprint: null,
    ip: "127.0.0.1",
  };
  const created: ISession = await api.functional.core.sessions.post(connection, {
    body: sessionCreate,
  });
  typia.assert(created);

  // 2. Retrieve the created session by its ID
  const found: ISession = await api.functional.core.sessions.getById(connection, {
    id: created.id,
  });
  typia.assert(found);
  TestValidator.equals("session.id")(created.id)(found.id);
  TestValidator.equals("session.user_id")(created.user_id)(found.user_id);
  TestValidator.equals("session.token")(created.token)(found.token);
  TestValidator.equals("session.expires_at")(created.expires_at)(found.expires_at);
  TestValidator.equals("session.device_fingerprint")(created.device_fingerprint)(found.device_fingerprint);
  TestValidator.equals("session.ip")(created.ip)(found.ip);
  TestValidator.equals("session.created_at")(created.created_at)(found.created_at);
  TestValidator.equals("session.revoked_at")(created.revoked_at ?? null)(found.revoked_at ?? null);

  // 3. Attempt to retrieve with a non-existent session ID
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("session not found")(404)(() =>
    api.functional.core.sessions.getById(connection, {
      id: nonExistentId,
    })
  );
}

test/features/api/session/test_create_se:
/**
 * Validate session creation logic, including successful creation, validation failure, and duplicate session behavior.
 *
 * This test confirms that session records are only created when valid data is provided, invalid data triggers proper error responses, and business constraints (such as double-creation with same token or user_id if not allowed) are properly enforced.
 *
 * 1. Attempt to create a valid session (expect success)
 * 2. Attempt to create a session with invalid data (e.g., missing user_id/token/expiry) (expect error)
 * 3. Attempt to create a second session with either identical (token, user_id), or as per logic constraint to trigger duplication error (expect error)
 */
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import typia from "typia";

export async function test_api_session_create_success_invalid_and_duplicate(connection: api.IConnection): Promise<void> {
  // 1. Create a valid session
  const createBody: ISession.ICreate = {
    user_id: typia.random<string & typia.tags.Format<"uuid">>(),
    token: `tok-${Math.random().toString(36).slice(2, 15)}`,
    expires_at: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
    device_fingerprint: `dev-${Math.random().toString(36).slice(2, 8)}`,
    ip: "192.168.1.200"
  };
  const session: ISession = await api.functional.core.sessions.post(connection, {
    body: createBody,
  });
  typia.assert(session);
  TestValidator.equals("user_id should match")(createBody.user_id)(session.user_id);
  TestValidator.equals("token should match")(createBody.token)(session.token);
  TestValidator.equals("expires_at")(createBody.expires_at)(session.expires_at);

  // 2. Attempt to create a session with invalid data (missing user_id, token, expires_at)
  await TestValidator.httpError("missing required fields")(400)(() =>
    api.functional.core.sessions.post(connection, {
      body: {
        // user_id is missing
        token: "",
        expires_at: "",
        device_fingerprint: null,
        ip: null
      } as any,
    })
  );

  // 3. Attempt to create a duplicate session for same user and token (should fail by logic constraint)
  await TestValidator.httpError("duplicate session")(409)(() =>
    api.functional.core.sessions.post(connection, {
      body: createBody,
    })
  );
}

test/features/api/session/test_update_se:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import typia from "typia";

/**
 * Validate updating session details and handling errors.
 *
 * This test ensures that session updates can only affect allowed fields and proper error handling occurs for invalid input or a non-existent session.
 *
 * 1. Create a session to use as update basis.
 * 2. Update session with valid mutable fields (expires_at, device_fingerprint, ip, revoked_at).
 *    - Check the response reflects the update.
 * 3. Attempt to update with invalid data (malformed date, invalid IP); ensure validation errors occur.
 * 4. Attempt to update a non-existent session ID; expect 404 or not-found error.
 */
export async function test_api_session_update_valid_invalid_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create session as update basis
  const session: ISession = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: typia.random<string & typia.tags.Format<"uuid">>(),
      token: "tok_test_validsessionupdate",
      expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(),
      device_fingerprint: "browser-chrome-2025062408",
      ip: "203.0.113.123",
    } satisfies ISession.ICreate,
  });
  typia.assert(session);

  // 2. Update with valid fields only
  const newExpiry = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString();
  const updated: ISession = await api.functional.core.sessions.putById(connection, {
    id: session.id,
    body: {
      expires_at: newExpiry,
      device_fingerprint: "browser-firefox-20250624",
      ip: "198.51.100.77",
      revoked_at: null,
    } satisfies ISession.IUpdate,
  });
  typia.assert(updated);
  // Validate that updates are reflected
  TestValidator.equals("session.id")(session.id)(updated.id);
  TestValidator.equals("expires_at")(newExpiry)(updated.expires_at);
  TestValidator.equals("device_fingerprint")("browser-firefox-20250624")(updated.device_fingerprint!);
  TestValidator.equals("ip")("198.51.100.77")(updated.ip!);

  // 3. Attempt to update with invalid data - malformed date
  await TestValidator.httpError("invalid expires_at format")(400)(() =>
    api.functional.core.sessions.putById(connection, {
      id: session.id,
      body: {
        expires_at: "notadate",
      } satisfies ISession.IUpdate,
    }),
  );

  // 3b. Attempt invalid IP
  await TestValidator.httpError("invalid IP address")(400)(() =>
    api.functional.core.sessions.putById(connection, {
      id: session.id,
      body: {
        ip: "999.999.999.999",
      } satisfies ISession.IUpdate,
    }),
  );

  // 4. Attempt to update non-existent session
  await TestValidator.httpError("not found session")(404)(() =>
    api.functional.core.sessions.putById(connection, {
      id: "650e751d-c962-46c0-8119-eeee1111dead",
      body: {
        expires_at: new Date(Date.now() + 4000).toISOString(),
      } satisfies ISession.IUpdate,
    }),
  );
}

test/features/api/session/test_delete_se:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { ISession } from "@ORGANIZATION/PROJECT-api/lib/structures/ISession";
import { ICoreSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreSession";

/**
 * 테스트 목적: 세션을 소프트 삭제(즉, revoke)하여 활성 세션에서 사라지고, 감사를 위해 기록이 보존되는지 확인합니다. 또한 이미 삭제된 세션이나 존재하지 않는 세션을 삭제하는 경우에도 idempotency(멱등성)을 보장하는지 검증합니다.
 * 
 * 시나리오 개요 및 사유: 세션 삭제 API는 실질적으로 "revoked_at" 타임스탬프를 기록해 소프트 삭제가 이뤄집니다. 사용자의 로그아웃, 세션 만료, 권한 회수, 관리자의 강제 세션 만료 등에 사용됩니다. 즉시 접근이 차단되어야 하며, 감사/증거 목적상 DB에서 완전히 삭제되지 않아야 합니다. 삭제 요청이 여러 번 들어왔을 때 멱등성을 보장해야 하며(여러 번 삭제해도 결과가 안전하게 반환), 존재하지 않는 세션에 대해서도 예외가 없거나 적절한 에러 응답이 나와야 합니다.
 *
 * [진행 순서]
 * 1. 새로운 세션을 생성합니다.
 * 2. 세션 삭제(소프트 딜리트) API를 호출하여 정상적으로 revoke 및 감사 정보가 남는지 확인합니다.
 * 3. 이미 삭제(revoked)된 세션에 대해 다시 삭제 요청을 보내고 결과를 확인합니다(멱등성 검증).
 * 4. 아예 존재하지 않는(임의의 uuid) 세션에 대해서도 삭제 요청을 보내고 결과/에러 응답을 확인합니다.
 */
export async function test_api_session_soft_delete_and_idempotency(connection: api.IConnection): Promise<void> {
  // 1. 새로운 세션 생성
  const session: ISession = await api.functional.core.sessions.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      token: `test-token-${Date.now()}-${Math.random()}`,
      expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1시간 뒤
      device_fingerprint: null,
      ip: "127.0.0.1",
    } satisfies ISession.ICreate,
  });
  typia.assert(session);

  // 2. 세션 삭제: 정상적으로 성공
  const delete1: ICoreSession.IDeleteResult = await api.functional.core.sessions.eraseById(connection, {
    id: session.id,
  });
  typia.assert(delete1);
  TestValidator.equals("session_id 반환 확인")(session.id)(delete1.session_id);
  TestValidator.equals("성공 여부 success")(true)(delete1.success);
  // 삭제 타임스탬프가 있다
  TestValidator.predicate("deleted_at 생성됨")(() => typeof delete1.deleted_at === "string" && !isNaN(Date.parse(delete1.deleted_at)));

  // 3. 이미 삭제된 세션에 대해 재삭제(멱등성): 정상 응답 또는 idempotent 보장
  const delete2: ICoreSession.IDeleteResult = await api.functional.core.sessions.eraseById(connection, {
    id: session.id,
  });
  typia.assert(delete2);
  TestValidator.equals("idempotency: session_id 동일함")(session.id)(delete2.session_id);
  TestValidator.equals("idempotency: success true")(true)(delete2.success);

  // 4. 존재하지 않는 uuid로 삭제 시도 - 에러 발생(404) 또는 일관된 response
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 세션 삭제")(() =>
    api.functional.core.sessions.eraseById(connection, { id: nonExistId }),
  );
}

test/features/api/core/test_list_locales:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { ICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/ICoreLocale";
import { IPageICoreLocale } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICoreLocale";

/**
 * Validate paginated and filtered listing of Core locales.
 *
 * This test covers the ability to list and search locale entries with
 * paginate/filter options, confirm total size, validate page and search results,
 * and check error handling for out-of-bounds or invalid filters.
 *
 * Background:
 * The /core/locales PATCH API allows querying the list of locales, with
 * pagination, search, and advanced filter options (by code/name, etc).
 * To verify correct behavior, we first seed the locale store with known
 * entries, then exercise the listing endpoint using various queries.
 *
 * Steps:
 * 1. Seed multiple unique locale entries via POST /core/locales.
 * 2. Retrieve full list with pagination (page, limit), confirm correct page size and data.
 * 3. Search by part of code or name using 'search', confirm only correct results returned.
 * 4. Apply filter (e.g., { code: ... }), confirm precise filtering.
 * 5. Request a non-existing page (e.g., very high page number), expect empty data.
 * 6. Try invalid filter, confirm API handles gracefully (no crash, returns empty or error as appropriate).
 */
export async function test_api_core_locales_list_with_pagination_and_filters(
  connection: api.IConnection
): Promise<void> {
  // 1. Seed unique locales
  const localeSeeds: ICoreLocale.ICreate[] = [
    { code: "en-US", name: "English (United States)" },
    { code: "ko-KR", name: "Korean (Republic of Korea)" },
    { code: "ja-JP", name: "Japanese (Japan)" },
    { code: "fr-FR", name: "French (France)" },
    { code: "de-DE", name: "German (Germany)" },
  ];
  const created: ICoreLocale[] = [];
  for (const seed of localeSeeds) {
    const output: ICoreLocale = await api.functional.core.locales.post(
      connection,
      { body: seed satisfies ICoreLocale.ICreate }
    );
    typia.assert(output);
    created.push(output);
  }

  // 2. Retrieve list page 1, limit 3
  const page1: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { page: 1, limit: 3 } satisfies ICoreLocale.IRequest }
  );
  typia.assert(page1);
  TestValidator.equals("should have 3 items on page 1")(3)(page1.data.length);
  TestValidator.equals("should report correct total size")(localeSeeds.length)(page1.pagination.records);
  TestValidator.equals("should report correct page number")(1)(page1.pagination.current);

  // 3. Retrieve page 2, limit 3 (should have remainder)
  const page2: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { page: 2, limit: 3 } satisfies ICoreLocale.IRequest }
  );
  typia.assert(page2);
  TestValidator.equals("should have remaining items")(
    localeSeeds.length - 3
  )(page2.data.length);

  // 4. Search by partial name
  const searchName: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { search: "English" } satisfies ICoreLocale.IRequest }
  );
  typia.assert(searchName);
  TestValidator.equals("search English matches only one")(
    1
  )(searchName.data.length);
  TestValidator.equals("first result is English")(
    "en-US"
  )(searchName.data[0].code);

  // 5. Filter by code
  const filterCode: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { filter: { code: "ko-KR" } } satisfies ICoreLocale.IRequest }
  );
  typia.assert(filterCode);
  TestValidator.equals("filter by code returns 1")(
    1
  )(filterCode.data.length);
  TestValidator.equals("Korean code")("ko-KR")(filterCode.data[0].code);

  // 6. Out-of-bounds page (page too high)
  const outOfBounds: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { page: 999, limit: 10 } satisfies ICoreLocale.IRequest }
  );
  typia.assert(outOfBounds);
  TestValidator.equals("out-of-bounds page returns empty")(
    0
  )(outOfBounds.data.length);

  // 7. Invalid filter (field does not exist)
  const invalidFilter: IPageICoreLocale = await api.functional.core.locales.patch(
    connection,
    { body: { filter: { nonexistent: "foobar" } } satisfies ICoreLocale.IRequest }
  );
  typia.assert(invalidFilter);
  TestValidator.equals("invalid filter returns empty")(
    0
  )(invalidFilter.data.length);
}

test/features/api/locale/test_get_locale:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
