import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductTag";
import { IPageIProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductTag";
import typia from "typia";

/**
 * List and search product tags using pagination and filtering.
 *
 * This test validates that searching the product tag list by tag value,
 * boundary pagination, and empty results works correctly. It creates multiple tags, lists all, searches by value (both with
 * results and with no matches), and checks pagination edge cases (e.g., extra large page size beyond available tags).
 *
 * 1. Create several product tags for testing (with distinct and common patterns in value).
 * 2. List all product tags without filters. Assert all created tags are present in results.
 * 3. Search by tag value substring/pattern. Assert expected filtered tags are included.
 * 4. Search with a value that matches no tags. Assert empty results.
 * 5. Use excessive page size to fetch all tags at once; test pagination data.
 */
export async function test_api_product_tag_list_and_search_paginated_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create product tags for test - three with unique values, two with common prefix 'trend-'
  const createdTags: IProductTag[] = [];
  const tagValues = [
    "trend-popular",
    "trend-winter",
    "eco-friendly",
    "limited-edition",
    "holiday-sale",
  ];
  for (const value of tagValues) {
    const tag = await api.functional.productCatalog.productTags.post(connection, {
      body: { value } satisfies IProductTag.ICreate,
    });
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 2. List all tags, no filter
  const allTagsPage: IPageIProductTag = await api.functional.productCatalog.productTags.patch(connection, {
    body: {} satisfies IProductTag.IRequest,
  });
  typia.assert(allTagsPage);
  for (const tag of createdTags) {
    TestValidator.equals(`all-tag-exists-${tag.value}`)(
      true
    )(
      allTagsPage.data.some((x) => x.id === tag.id && x.value === tag.value)
    );
  }

  // 3. Filter by substring 'trend-': should match two tags
  const trendTagsPage: IPageIProductTag = await api.functional.productCatalog.productTags.patch(connection, {
    body: { value: "trend-" } satisfies IProductTag.IRequest,
  });
  typia.assert(trendTagsPage);
  TestValidator.equals("trend-tags-len")(2)(trendTagsPage.data.length);
  for (const val of ["trend-popular", "trend-winter"]) {
    TestValidator.equals(`trend-tag-exists-${val}`)(
      true
    )(
      trendTagsPage.data.some((x) => x.value === val)
    );
  }

  // 4. Filter with non-matching substring (e.g. 'zzz')
  const noneTagsPage: IPageIProductTag = await api.functional.productCatalog.productTags.patch(connection, {
    body: { value: "zzz" } satisfies IProductTag.IRequest,
  });
  typia.assert(noneTagsPage);
  TestValidator.equals("no-results")(0)(noneTagsPage.data.length);

  // 5. Pagination: use extremely large limit
  const largePage: IPageIProductTag = await api.functional.productCatalog.productTags.patch(connection, {
    body: { limit: 1000 } satisfies IProductTag.IRequest,
  });
  typia.assert(largePage);
  // All created tags present
  for (const tag of createdTags) {
    TestValidator.equals(`large-limit-all-tag-exists-${tag.value}`)(
      true
    )(
      largePage.data.some((x) => x.id === tag.id)
    );
  }
  // Pagination object is correct
  TestValidator.equals("pagination.limit")(1000)(largePage.pagination.limit);
}

