import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";
import { IPageIProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIProductMedia";

/**
 * Paginate and filter product media records by various criteria (type, product id, locale, alt_text, date range), ensuring correct results are returned.
 *
 * Steps:
 * 1. Create several product media records with different media_type, product_id, locale, and alt_text.
 * 2. Call the productCatalog.productMedia.patch API to paginate and filter records by:
 *    - media_type
 *    - product_id
 *    - locale
 *    - alt_text
 *    - date range (created_from, created_to)
 *    - pagination (offset, limit)
 * 3. Validate returned results precisely match the filter criteria.
 * 4. Test edge case: filtering that should return no results (e.g., non-existent type).
 * 5. Test edge case: out-of-range pagination (offset beyond total records).
 * 6. Ensure pagination meta is correctly reported in responses.
 * 7. Assert all records are type-valid and fields are correct.
 */
export async function test_api_product_media_list_and_filter(
  connection: api.IConnection,
) {
  // 1. Create test media records with distinct fields
  const records: IProductMedia[] = [];
  const testFixtures = [
    {
      media_type: "image",
      locale: "en-US",
      alt_text: "Running shoes",
      uri: "https://cdn.example.com/asset1.png",
    },
    {
      media_type: "video",
      locale: "ko-KR",
      alt_text: "운동화 리뷰",
      uri: "https://cdn.example.com/asset2.mp4",
    },
    {
      media_type: "image",
      locale: "ko-KR",
      alt_text: "메인 썸네일",
      uri: "https://cdn.example.com/asset3.png",
    },
    {
      media_type: "pdf",
      locale: "en-US",
      alt_text: "Product manual",
      uri: "https://cdn.example.com/manual.pdf",
    },
  ];
  const now = new Date();
  for (const f of testFixtures) {
    const result = await api.functional.productCatalog.productMedia.post(connection, {
      body: {
        ...f,
        // Assign random UUID for product_id to enable product-level filter
        product_id: typia.random<string & typia.tags.Format<"uuid">>(),
      } satisfies IProductMedia.ICreate,
    });
    typia.assert(result);
    records.push(result);
    // Force a small delay to ensure created_at difference if needed
    await new Promise(r => setTimeout(r, 20));
  }
  // 2. Filter by media_type
  const filterImage: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { media_type: "image", limit: 10 },
  });
  typia.assert(filterImage);
  for (const item of filterImage.data) {
    TestValidator.equals("media_type")(item.media_type)("image");
    typia.assert(item);
  }

  // 3. Filter by product_id of the second record
  const byProductId: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { product_id: records[1].product_id, limit: 10 },
  });
  typia.assert(byProductId);
  for (const item of byProductId.data) {
    TestValidator.equals("product_id")(item.product_id)(records[1].product_id);
    typia.assert(item);
  }

  // 4. Filter by locale
  const filterLocale: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { locale: "ko-KR", limit: 10 },
  });
  typia.assert(filterLocale);
  for (const item of filterLocale.data) {
    TestValidator.equals("locale")(item.locale)("ko-KR");
    typia.assert(item);
  }

  // 5. Filter by alt_text substring (simulate partial search)
  const filterAlt: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { alt_text: "운동화", limit: 10 },
  });
  typia.assert(filterAlt);
  for (const item of filterAlt.data) {
    TestValidator.predicate("alt_text")(() => item.alt_text.includes("운동화"));
    typia.assert(item);
  }

  // 6. Filter by created_from and created_to (should catch all, since created just now)
  const createdFrom = new Date(now.getTime() - 500).toISOString();
  const createdTo = new Date(Date.now() + 500).toISOString();
  const byDate: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { created_from: createdFrom, created_to: createdTo, limit: 10 },
  });
  typia.assert(byDate);
  TestValidator.equals("count in range")(records.length)(byDate.data.length);

  // 7. Pagination: offset=2, limit=1 → the 3rd item
  const paged: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { limit: 1, offset: 2, sort: "created_at asc" },
  });
  typia.assert(paged);
  if (paged.data.length) {
    TestValidator.equals("offset-paged[0]")(paged.data[0].id)(records[2].id);
  }

  // 8. Edge case: type that does not exist
  const none: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { media_type: "unknown-type-that-does-not-exist", limit: 5 },
  });
  typia.assert(none);
  TestValidator.equals("none found")(none.data.length)(0);
  TestValidator.equals("pagination none records")(none.pagination.records)(0);

  // 9. Edge case: offset beyond data
  const outOfRange: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { limit: 2, offset: 50 },
  });
  typia.assert(outOfRange);
  TestValidator.equals("out of range")(outOfRange.data.length)(0);

  // 10. Validate pagination meta
  const pagedAll: IPageIProductMedia = await api.functional.productCatalog.productMedia.patch(connection, {
    body: { limit: 2, offset: 0 },
  });
  typia.assert(pagedAll);
  TestValidator.equals("limit")(pagedAll.pagination.limit)(2);
  TestValidator.equals("current")(pagedAll.pagination.current)(0);
}

