import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";
import typia from "typia";

/**
 * Validate product media creation and data validation logic.
 *
 * This test confirms successful creation of a product media record with valid data,
 * and ensures that required field/format validations and referential integrity checks
 * correctly trigger errors in the following cases:
 *
 * 1. Create a product media record with all valid fields and check correct full record is returned.
 * 2. Attempt creation with missing required fields (e.g., missing uri, media_type, locale, alt_text).
 * 3. Attempt creation with invalid uri (malformed URI string).
 * 4. Attempt creation referencing a non-existent product_id (should fail).
 */
export async function test_api_product_media_create_with_various_data_validations(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create with all valid fields
  const validCreate: IProductMedia.ICreate = {
    uri: "https://example-cdn.com/assets/valid-image.jpg",
    media_type: "image",
    locale: "en-US",
    alt_text: "Front view of product.",
    product_id: "52bc8225-bdec-4e83-9918-7f72076d1045",
  };
  const created: IProductMedia = await api.functional.productCatalog.productMedia.post(connection, {
    body: validCreate,
  });
  typia.assert(created);
  TestValidator.equals("uri")(validCreate.uri)(created.uri);
  TestValidator.equals("media_type")(validCreate.media_type)(created.media_type);
  TestValidator.equals("locale")(validCreate.locale)(created.locale);
  TestValidator.equals("alt_text")(validCreate.alt_text)(created.alt_text);
  TestValidator.equals("product_id")(validCreate.product_id)(created.product_id!);

  // 2. Required field validation (missing uri)
  await TestValidator.httpError("missing uri")(422)(() =>
    api.functional.productCatalog.productMedia.post(connection, {
      // @ts-expect-error
      body: {
        media_type: "image",
        locale: "en-US",
        alt_text: "Should fail: missing uri",
        product_id: "52bc8225-bdec-4e83-9918-7f72076d1045",
      } satisfies Partial<IProductMedia.ICreate>,
    }),
  );

  // 3. Invalid uri format
  await TestValidator.httpError("invalid uri")(422)(() =>
    api.functional.productCatalog.productMedia.post(connection, {
      body: {
        uri: "ht!tp:::/bad-uri!!@#",
        media_type: "image",
        locale: "en-US",
        alt_text: "Bad URI format",
        product_id: "52bc8225-bdec-4e83-9918-7f72076d1045",
      } satisfies IProductMedia.ICreate,
    }),
  );

  // 4. Referential integrity - non-existent product_id
  await TestValidator.httpError("non-existent product_id")(404)(() =>
    api.functional.productCatalog.productMedia.post(connection, {
      body: {
        uri: "https://example-cdn.com/assets/unused.jpg",
        media_type: "image",
        locale: "en-US",
        alt_text: "Nonexistent product id",
        product_id: "00000000-0000-0000-0000-000000000000", // unrealistic UUID
      } satisfies IProductMedia.ICreate,
    }),
  );
}

