import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IProductMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductMedia";

/**
 * 제품 미디어(product media) 레코드 업데이트의 성공, 유효성 오류 및 존재하지 않는 id 처리 검증.
 *
 * 1. 테스트용 제품 미디어 레코드 등록(POST /productCatalog/productMedia)
 * 2. 생성된 id에 대해 PUT /productCatalog/productMedia/{id}로 일부 필드 수정 → 정상 반영 여부 검증
 * 3. 존재하지 않는 UUID로 업데이트 시도 시 404 반환 검증
 * 4. invalid(필수값 누락 혹은 잘못된 포맷)로 업데이트 시도 시 validation 에러(400 등) 검증
 */
export async function test_api_product_media_update_scenarios(
  connection: api.IConnection,
): Promise<void> {
  // 1. 정상적인 ProductMedia 생성
  const original: IProductMedia = await api.functional.productCatalog.productMedia.post(connection, {
    body: {
      uri: "https://cdn.example.com/image/original.jpg",
      media_type: "image",
      locale: "ko-KR",
      alt_text: "상품 대표 이미지 (Original)",
      product_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IProductMedia.ICreate,
  });
  typia.assert(original);

  // 2. 생성된 id로 일부 필드 업데이트
  const updated: IProductMedia = await api.functional.productCatalog.productMedia.putById(connection, {
    id: original.id,
    body: {
      uri: "https://cdn.example.com/image/updated.jpg",
      alt_text: "수정된 상품 대표 이미지"
    } satisfies IProductMedia.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("update uri applied")(updated.uri)("https://cdn.example.com/image/updated.jpg");
  TestValidator.equals("update alt_text applied")(updated.alt_text)("수정된 상품 대표 이미지");
  // 불변 필드는 불변인지 검증
  TestValidator.equals("product_id should not change")(original.product_id)(updated.product_id);
  TestValidator.equals("id should not change")(original.id)(updated.id);

  // 3. 존재하지 않는 id(UUID)로 업데이트 시도 → 404
  await TestValidator.httpError("not found update")(404)(() =>
    api.functional.productCatalog.productMedia.putById(connection, {
      id: "b91a2f03-88c5-4d83-8e33-b4ea50a802b9", // 무작위로 존재하지 않는 값
      body: { alt_text: "존재하지 않는 것" } satisfies IProductMedia.IUpdate,
    })
  );

  // 4. 유효하지 않은 데이터(alt_text 미입력 등)로 업데이트 시도 → 400
  await TestValidator.httpError("invalid update missing alt_text")(400)(() =>
    api.functional.productCatalog.productMedia.putById(connection, {
      id: original.id,
      body: { alt_text: "" } satisfies IProductMedia.IUpdate, // 비어 있음 (실제로 필수 여부 정책에 맞게 에러 처리해야 함)
    })
  );

  await TestValidator.httpError("invalid update bad locale")(400)(() =>
    api.functional.productCatalog.productMedia.putById(connection, {
      id: original.id,
      body: { locale: "INVALID_LOCALE", alt_text: "잘못된 로케일" } satisfies IProductMedia.IUpdate,
    })
  );
}

