test/features/api/inventory/test_list_se:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPageIInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIInventory";
import { IInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IInventory";
import { IProductCatalogProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IProductCatalogProductVariant";
import typia from "typia";

/**
 * End-to-end test for inventory listing with comprehensive pagination and filter checks.
 *
 * This function validates the correct operation of inventory search/listing endpoint:
 *  - By product_variant_id
 *  - By stock_count (range inclusions, exclusions)
 *  - Pagination behavior (first/last pages, meta data)
 *  - Handling of empty/no-result scenarios
 *
 * Scenario steps:
 * 1. Create a product variant (for inventory association)
 * 2. Create multiple inventory records for this variant (vary stock_count, timestamps)
 * 3. List inventory with no filters (should return all, check total)
 * 4. Filter by product_variant_id
 * 5. Filter by partial stock_count range
 * 6. Filter with non-existent range (expect 0 results)
 * 7. Paginate: first, middle, last page (check meta)
 * 8. Search on invalid product_variant_id (should return empty)
 */
export async function test_api_inventory_list_search_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create product variant
  const variant: IProductCatalogProductVariant = await api.functional.productCatalog.productVariants.post(connection, {
    body: {
      product_id: typia.random<string>(),
      sku: `SKU-${Math.random().toString(36).substring(7)}`,
      price: Math.floor(Math.random() * 10000) + 100,
      barcode: `BAR-${Math.random().toString(36).substring(7)}`,
      available: true,
    } satisfies IProductCatalogProductVariant.ICreate,
  });
  typia.assert(variant);

  // Step 2: Create 7 inventory records (different stock_count)
  const inventoryInputs: IInventory.ICreate[] = Array.from({ length: 7 }, (_, i) => ({
    product_variant_id: variant.id,
    stock_count: i * 10 + 5, // 5, 15, ..., 65
  }));
  const inventories: IInventory[] = [];
  for (const createInput of inventoryInputs) {
    const inv = await api.functional.productCatalog.inventory.post(connection, { body: createInput });
    typia.assert(inv);
    inventories.push(inv);
  }

  // Step 3: List all inventories (no filter)
  const allResult: IPageIInventory = await api.functional.productCatalog.inventory.patch(connection, { body: {} });
  typia.assert(allResult);
  TestValidator.equals("inventory total count")(inventories.length)(allResult.data.filter(r => r.product_variant_id === variant.id).length);

  // Step 4: Filter by variant id
  const filteredByVariant = await api.functional.productCatalog.inventory.patch(connection, { body: { product_variant_id: variant.id } });
  typia.assert(filteredByVariant);
  TestValidator.equals("filtered correct variant count")(inventories.length)(filteredByVariant.data.length);
  for (const rec of filteredByVariant.data) {
    TestValidator.equals("matched variant id")(variant.id)(rec.product_variant_id);
  }

  // Step 5: Filter by stock_count (15-45 inclusive); should match i=1,2,3,4 (stock_count: 15,25,35,45)
  const min = 15, max = 45;
  const filteredStock = await api.functional.productCatalog.inventory.patch(connection, { body: { stock_from: min, stock_to: max, product_variant_id: variant.id } });
  const expectedCount = inventories.filter(i => i.stock_count >= min && i.stock_count <= max).length;
  TestValidator.equals("stock range count")(expectedCount)(filteredStock.data.length);
  for (const r of filteredStock.data) {
    if (!(r.stock_count >= min && r.stock_count <= max)) throw new Error(`Stock out of range: ${r.stock_count}`);
  }

  // Step 6: Stock_count range that matches none
  const nullResult = await api.functional.productCatalog.inventory.patch(connection, {
    body: { stock_from: 999, stock_to: 1999, product_variant_id: variant.id },
  });
  typia.assert(nullResult);
  TestValidator.equals("empty result")(0)(nullResult.data.length);

  // Step 7: Pagination edge (limit 3)
  const totalRec = inventories.length;
  const limit = 3;
  // first page (offset 0)
  const page1 = await api.functional.productCatalog.inventory.patch(connection, { body: { offset: 0, limit, product_variant_id: variant.id } });
  typia.assert(page1);
  TestValidator.equals("page 1 record count")(
    Math.min(limit, totalRec),
  )(page1.data.length);
  // middle page (offset 3)
  const page2 = await api.functional.productCatalog.inventory.patch(connection, { body: { offset: 3, limit, product_variant_id: variant.id } });
  TestValidator.equals("page 2 record count")(
    Math.min(limit, totalRec - 3),
  )(page2.data.length);
  // last page (offset 6)
  const lastPage = await api.functional.productCatalog.inventory.patch(connection, { body: { offset: 6, limit, product_variant_id: variant.id } });
  TestValidator.equals("page last record count")(totalRec - 6)(lastPage.data.length);
  // check meta
  TestValidator.equals("meta total records")(totalRec)(page1.pagination.records);

  // Step 8: Non-existent variant id
  const notFound = await api.functional.productCatalog.inventory.patch(connection, {
    body: { product_variant_id: "11111111-2222-3333-4444-555555555555" },
  });
  typia.assert(notFound);
  TestValidator.equals("non-existent variant empty")(0)(notFound.data.length);
