test/features/api/import-feed/test_list_:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IImportFeed";
import { IPageIImportFeed } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIImportFeed";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * List and search import feed records paginated and with filters.
 *
 * This test validates listing and searching import feed records using the PATCH /productCatalog/importFeeds endpoint,
 * verifying proper support for filters, pagination, search, and correct result metadata. It ensures records are listed,
 * filters such as source_name and imported_at work as expected, search supports fuzzy match, pagination boundaries are respected, and empty/result edge-cases are handled cleanly.
 *
 * 1. Create several import feed records with varying source_name, source_uri, and imported_at.
 * 2. List import feeds without filters, verify all created records appear.
 * 3. Filter by source_name and check only relevant records are returned.
 * 4. Filter by imported_at date range.
 * 5. Search by a general string match.
 * 6. Test pagination and page boundaries.
 * 7. Test for empty result set.
 * 8. Confirm pagination metadata correctness at each step.
 */
export async function test_api_import_feed_list_and_search_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create import feeds with varied fields
  const now = new Date();
  const feeds: IImportFeed[] = [];
  const scenarios = [
    { source_name: "Google Shopping", source_uri: "https://partner-a/feeds/1001", offsetDays: -1 },
    { source_name: "Facebook Catalog", source_uri: "https://partner-b/feeds/2034", offsetDays: -2 },
    { source_name: "Custom ERP", source_uri: "ftp://erp.feeds.local/789", offsetDays: -3 },
    { source_name: "Google Shopping", source_uri: "https://another-feed/9002", offsetDays: -7 },
  ];
  for (const s of scenarios) {
    const imported_at = new Date(now.getTime() + s.offsetDays * 24 * 60 * 60 * 1000).toISOString();
    const feed = await api.functional.productCatalog.importFeeds.post(connection, {
      body: {
        source_name: s.source_name,
        source_uri: s.source_uri,
        imported_at,
      } satisfies IImportFeed.ICreate,
    });
    typia.assert(feed);
    feeds.push(feed);
  }

  // 2. List all feeds: no filter
  const listRes: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: {} });
  typia.assert(listRes);
  TestValidator.equals("all feeds appear")(
    feeds.map(f => f.id).sort()
  )((listRes.data ?? []).map(f => f.id).filter(id => feeds.map(r => r.id).includes(id)).sort());

  // 3. Filter by source_name
  const srcName = "Google Shopping";
  const listByName: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { source_name: srcName } });
  typia.assert(listByName);
  for (const feed of listByName.data ?? []) TestValidator.equals("source_name filter")(srcName)(feed.source_name);
  TestValidator.equals("Google Shopping count")(
    feeds.filter(f => f.source_name === srcName).length
  )((listByName.data ?? []).length);

  // 4. Filter by imported_at date range
  const from = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString();
  const to = now.toISOString();
  const listDate: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { imported_from: from, imported_to: to } });
  typia.assert(listDate);
  for (const feed of listDate.data ?? []) {
    TestValidator.equals("imported_from subset")(true)(feed.imported_at >= from && feed.imported_at <= to);
  }

  // 5. General search string
  const searchText = "partner";
  const listSearch: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { search: searchText } });
  typia.assert(listSearch);
  for (const feed of listSearch.data ?? []) {
    TestValidator.equals(
      "search match"
    )(
      true
    )(
      feed.source_name.toLowerCase().includes(searchText) ||
      feed.source_uri.toLowerCase().includes(searchText)
    );
  }

  // 6. Pagination
  const limit = 2;
  const firstPage: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { limit, sort: "imported_at-desc" } });
  typia.assert(firstPage);
  TestValidator.equals("first page length")(limit)((firstPage.data ?? []).length);
  TestValidator.equals("pagination - current")(1)(firstPage.pagination!.current!);
  TestValidator.equals("pagination - limit")(limit)(firstPage.pagination!.limit!);
  // Next page if there are more
  if ((firstPage.pagination?.pages ?? 1) > 1) {
    const secondPage: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { limit, page: 2, sort: "imported_at-desc" } });
    typia.assert(secondPage);
    TestValidator.equals("second page length")(
      Math.max(0, feeds.length - limit)
    )((secondPage.data ?? []).length);
    TestValidator.equals("pagination - page2")(2)(secondPage.pagination!.current!);
  }

  // 7. Empty result: nonexistent source_name
  const notExistName = "Does Not Exist Catalog";
  const emptyResult: IPageIImportFeed = await api.functional.productCatalog.importFeeds.patch(connection, { body: { source_name: notExistName } });
  typia.assert(emptyResult);
  TestValidator.equals("empty array for nonexistent name")(0)((emptyResult.data ?? []).length);

  // 8. Pagination metadata correctness
  for (const response of [listRes, listByName, listDate, listSearch, firstPage]) {
    if (!response.pagination) continue;
    const count = (response.data ?? []).length;
    TestValidator.equals("pagination count matches data array length")(count)(response.pagination.current <= response.pagination.pages ? count : 0);
    TestValidator.equals("limit respected")(
      response.pagination.limit <= feeds.length || response.pagination.limit === limit
    )(
      true
    );
  }
}

