test/features/api/catalog-event/test_lis:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvent";
import { IPageICatalogEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICatalogEvent";
import typia from "typia";

/**
 * Paginate, list, and filter catalog event records by type, date, or product association.
 * Ensures catalog event search matches filters, supports empty/large result edge-cases, and validates pagination.
 *
 * Steps:
 * 1. Create catalog event records with various event_type, product_id, user_id, product_variant_id, and occurred_at values (including edge and normal cases).
 * 2. List all events with no filters/pagination. Assert all events returned.
 * 3. List events paginated with a limit (e.g., 2 per page), fetch page 1 and page 2, and confirm event count and contents.
 * 4. Filter by event_type, user_id, product_id, product_variant_id, and by occurred_at window. Assert only matching events are returned.
 * 5. Search with a non-existent filter to confirm empty data result returns.
 * 6. Create more events for a large dataset test (15+ records), then test multi-page navigation and edge-case final page.
 * 7. Assert pagination metadata and response correctness throughout.
 *
 * All responses are validated with typia.assert and TestValidator logic. Coverage includes both coverage and edge-case scenarios.
 */
export async function test_api_catalog_event_list_and_search_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // --- Setup: Test Data Preparation ---
  // Create 5 distinct catalog events (different event_types, users, products, variants, date ranges)
  const userIds = [
    "4fb9b4e4-3cde-417c-94f3-f87e707f381a",
    "aafb2b7e-da2f-45c9-85c9-5c8b0543a7e2"
  ];
  const productIds = [
    "ecfa82da-a85b-4dcf-8fe6-ea3702074db4",
    "e4b41f49-cf11-42fe-92ab-9e4d7f039ec6"
  ];
  const variantIds = [
    "7582001f-804c-4ac4-bbf1-2c8d8cfc57ca",
    "f303be61-508a-4f0f-bee3-06e0cfb3e0e1"
  ];
  const now = new Date();
  const baseDate = new Date("2023-01-01T00:00:00Z");

  // Diverse test event data for realistic coverage
  const eventsData: ICatalogEvent.ICreate[] = [
    {
      event_type: "create",
      description: "Product created",
      product_id: productIds[0],
      product_variant_id: variantIds[0],
      user_id: userIds[0],
      occurred_at: baseDate.toISOString(),
    },
    {
      event_type: "update",
      description: "Product updated",
      product_id: productIds[0],
      product_variant_id: variantIds[1],
      user_id: userIds[1],
      occurred_at: new Date(baseDate.getTime() + 1 * 60 * 1000).toISOString(),
    },
    {
      event_type: "import",
      description: "Imported from feed",
      product_id: productIds[1],
      product_variant_id: variantIds[0],
      user_id: userIds[1],
      occurred_at: new Date(baseDate.getTime() + 2 * 60 * 1000).toISOString(),
    },
    {
      event_type: "status_change",
      description: "Product status changed",
      product_id: productIds[1],
      product_variant_id: variantIds[1],
      user_id: userIds[0],
      occurred_at: new Date(baseDate.getTime() + 3 * 60 * 1000).toISOString(),
    },
    {
      event_type: "delete",
      description: "Product deleted",
      product_id: productIds[0],
      product_variant_id: variantIds[1],
      user_id: userIds[1],
      occurred_at: new Date(baseDate.getTime() + 4 * 60 * 1000).toISOString(),
    },
  ];

  // 1. Create them via the API
  const createdEvents: ICatalogEvent[] = [];
  for (const data of eventsData) {
    const event = await api.functional.productCatalog.catalogEvents.post(connection, { body: data });
    typia.assert(event);
    createdEvents.push(event);
  }

  // 2. List all events, no filters
  {
    const output = await api.functional.productCatalog.catalogEvents.patch(connection, {
      body: {} // No filters/pagination
    });
    typia.assert(output);
    const resultIds = (output.data ?? []).map(r => r.id);
    for (const e of createdEvents) {
      TestValidator.equals("created listed")(true)(resultIds.includes(e.id));
    }
    // Also check pagination metadata
    TestValidator.equals("pagination:records")(createdEvents.length)((output.pagination?.records) ?? (output.data?.length ?? 0));
  }

  // 3. Paginated listing (limit=2)
  {
    // Page 1
    const page1 = await api.functional.productCatalog.catalogEvents.patch(connection, {
      body: { limit: 2, page: 1 },
    });
    typia.assert(page1);
    TestValidator.equals("page 1 count")(2)(page1.data?.length ?? 0);
    TestValidator.equals("page 1 current")(1)(page1.pagination?.current ?? 0);
    // Page 2
    const page2 = await api.functional.productCatalog.catalogEvents.patch(connection, {
      body: { limit: 2, page: 2 },
    });
    typia.assert(page2);
    // Ensure remaining events in page 2
    TestValidator.equals("page 2 count")(createdEvents.length - 2)(page2.data?.length ?? 0);
    TestValidator.equals("page 2 current")(2)(page2.pagination?.current ?? 0);
  }

  // 4. Filter by event_type, user_id, product_id, product_variant_id, occurred_at
  // Filter by event_type = 'import'
  {
    const resp = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { event_type: "import" } });
    typia.assert(resp);
    for (const ev of resp.data ?? []) {
      TestValidator.equals("filter event_type")(ev.event_type)("import");
    }
  }
  // Filter by user_id
  {
    const filterUser = userIds[0];
    const resp = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { user_id: filterUser } });
    typia.assert(resp);
    for (const ev of resp.data ?? []) {
      TestValidator.equals("filter user_id")(ev.user_id)(filterUser);
    }
  }
  // Filter by product_id
  {
    const filterProduct = productIds[1];
    const resp = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { product_id: filterProduct } });
    typia.assert(resp);
    for (const ev of resp.data ?? []) {
      TestValidator.equals("filter product_id")(ev.product_id)(filterProduct);
    }
  }
  // Filter by variant_id
  {
    const filterVariant = variantIds[1];
    const resp = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { product_variant_id: filterVariant } });
    typia.assert(resp);
    for (const ev of resp.data ?? []) {
      TestValidator.equals("filter variant_id")(ev.product_variant_id)(filterVariant);
    }
  }
  // Filter by occurred_at window
  {
    const from = new Date(baseDate.getTime() + 60 * 1000).toISOString();
    const to = new Date(baseDate.getTime() + 3 * 60 * 1000).toISOString();
    const resp = await api.functional.productCatalog.catalogEvents.patch(connection, {
      body: { from, to },
    });
    typia.assert(resp);
    for (const ev of resp.data ?? []) {
      TestValidator.equals("occurred_at range")(true)(
        ev.occurred_at >= from && ev.occurred_at <= to
      );
    }
  }

  // 5. Search for non-existent combo: e.g. wrong event_type
  {
    const output = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { event_type: "non-existent-type" } });
    typia.assert(output);
    TestValidator.equals("empty edge")(0)(output.data?.length ?? 0);
  }

  // 6. Large result set test - create 15+ more events
  const moreEvents: ICatalogEvent.ICreate[] = [];
  for (let i = 0; i < 15; ++i) {
    moreEvents.push({
      event_type: "mass_import",
      description: `Bulk event #${i}`,
      product_id: productIds[i % productIds.length],
      product_variant_id: variantIds[i % variantIds.length],
      user_id: userIds[i % userIds.length],
      occurred_at: new Date(baseDate.getTime() + 600000 + i * 60000).toISOString(),
    });
  }
  for (const data of moreEvents) {
    const event = await api.functional.productCatalog.catalogEvents.post(connection, { body: data });
    typia.assert(event);
    createdEvents.push(event);
  }

  // Page size 5, get 4th and last page
  {
    const size = 5;
    const page4 = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { limit: size, page: 4 } });
    typia.assert(page4);
    // Final page should have remaining events
    const expected = createdEvents.length - size * 3;
    TestValidator.equals("page 4 count")(expected)(page4.data?.length ?? 0);
    TestValidator.equals("current page")(4)(page4.pagination?.current ?? 0);
    TestValidator.equals("total records")(createdEvents.length)(page4.pagination?.records ?? 0);
    // All events sum to total records
    let allIds: string[] = [];
    for (let p = 1; p <= (page4.pagination?.pages ?? 0); ++p) {
      const resp = await api.functional.productCatalog.catalogEvents.patch(connection, { body: { limit: size, page: p } });
      typia.assert(resp);
      allIds = allIds.concat((resp.data ?? []).map(e => e.id));
    }
    TestValidator.equals("unique ids count")(createdEvents.length)([...new Set(allIds)].length);
  }
}

