import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ISentimentAnalysisLog";
import { IPageISentimentAnalysisLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISentimentAnalysisLog";
import typia from "typia";

/**
 * Retrieve a paginated, filtered list of sentiment analysis logs.
 *
 * This test function ensures that the paginated and filtered retrieval of sentiment analysis logs works correctly.
 * It first creates a log entry to guarantee there is at least one entry for subsequent filter and pagination queries.
 * The test then fetches logs using various filters, validates proper results, and also checks for correct error handling with invalid values.
 *
 * 1. Create a sentiment analysis log entry to ensure data is available.
 * 2. Retrieve the log list with default pagination (no filters)
 * 3. Retrieve logs filtered by review_id (should include the entry created above)
 * 4. Retrieve logs with a date/time range that includes the created entry
 * 5. Supply invalid pagination/filter parameters, expect error handling
 */
export async function test_api_communicationReview_sentimentAnalysisLogs_list_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a sentiment analysis log entry
  const logCreate: ISentimentAnalysisLog.ICreate = {
    review_id: typia.random<string>(),
    ai_model_version_id: typia.random<string>(),
    raw_input: "hello world",
    output: '{"sentiment":"positive","score":0.98}',
    model_version: "v1.0.0",
    analyzed_at: new Date().toISOString(),
  };
  const log: ISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.post(
    connection,
    {
      body: logCreate,
    },
  );
  typia.assert(log);

  // 2. Retrieve the log list with default pagination (no filters)
  const resDefault: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resDefault);
  TestValidator.equals("default results has data")(
    true
  )(resDefault.data.length > 0);

  // 3. Retrieve logs filtered by review_id (should include the entry created above)
  const resByReview: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: { review_id: logCreate.review_id },
    },
  );
  typia.assert(resByReview);
  TestValidator.equals("should find log by review_id")(
    1
  )(resByReview.data.filter((l) => l.id === log.id).length);

  // 4. Retrieve logs with a date/time range that includes the created entry
  const resByTime: IPageISentimentAnalysisLog = await api.functional.communicationReview.sentimentAnalysisLogs.patch(
    connection,
    {
      body: {
        time_from: new Date(Date.now() - 10 * 1000).toISOString(),
        time_to: new Date(Date.now() + 10 * 1000).toISOString(),
      },
    },
  );
  typia.assert(resByTime);
  TestValidator.equals("should find log in time range")(
    true
  )(resByTime.data.some((l) => l.id === log.id));

  // 5. Supply invalid pagination parameter (negative page number), expect error
  await TestValidator.httpError("invalid page number")(400)(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.patch(
      connection,
      {
        body: {
          page: -1,
        },
      },
    )
  );

  // 6. Supply invalid date filter (malformed)
  await TestValidator.httpError("malformed time_from")(400)(() =>
    api.functional.communicationReview.sentimentAnalysisLogs.patch(
      connection,
      {
        body: {
          time_from: "not-a-date",
        },
      },
    )
  );
}

