import { TestValidator } from "@nestia/e2e";
import typia from "typia";
import api from "@ORGANIZATION/PROJECT-api";
import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import { IFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavorite";
import { IPageIFavorite } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIFavorite";

/**
 * Retrieve a paginated and filterable list of favorite records.
 *
 * - Covers filters by user, product, and date range, and pagination correctness.
 * - Ensures soft-deleted favorites are excluded unless explicitly requested.
 * - Checks for error handling on invalid filters and excessive pagination.
 *
 * 1. Create multiple favorite records using distinct users/products.
 * 2. Soft-delete some created favorites (by direct API or simulated if unavailable).
 * 3. Query favorites without filters (default pagination) and ensure soft-deleted are absent.
 * 4. Perform queries by:
 *     a. user_id
 *     b. product_id
 *     c. creation date range
 *     d. deleted=true (should show only soft-deleted)
 * 5. Paginate through favorites using various limits and pages. Check error on out-of-bounds pagination.
 * 6. Submit invalid filter (malformed uuid) and confirm error raised.
 * 7. For each response, validate list content and pagination metadata.
 */
export async function test_api_favoritesPersonalization_favorites_list_with_advanced_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple favorite records
  const users = [typia.random<string>(), typia.random<string>()].map(u => typia.random<string & typia.tags.Format<"uuid">>());
  const products = [typia.random<string>(), typia.random<string>()].map(p => typia.random<string & typia.tags.Format<"uuid">>());
  const created: IFavoritesPersonalization.IFavorite[] = [];

  for (const user_id of users) {
    for (const product_id of products) {
      const favorite = await api.functional.favoritesPersonalization.favorites.post(connection, {
        body: { user_id, product_id } satisfies IFavoritesPersonalization.IFavoriteCreate,
      });
      typia.assert(favorite);
      created.push(favorite);
    }
  }

  // 2. Soft-delete half the created favorites (simulate by setting deleted_at if no direct API is available)
  const now = new Date().toISOString();
  const softDeleted = new Set<string>();
  for (let i = 0; i < created.length; i += 2) {
    // If a real soft-delete API exists, call it here; for now, simulate in-memory:
    created[i].deleted_at = now;
    softDeleted.add(created[i].id);
  }

  // 3. Query: No filters, default pagination. Should only return non-deleted favorites.
  let output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: {} satisfies IFavorite.IRequest,
  });
  typia.assert<IPageIFavorite>(output);
  for (const fav of output.data) {
    TestValidator.equals("not soft-deleted")(undefined as (string & typia.tags.Format<"date-time">) | undefined)(fav.deleted_at);
    TestValidator.equals("active favorite present")(
      true,
    )(
      created.some((c) => c.id === fav.id && !softDeleted.has(fav.id))
    );
  }

  // 4a. Filter by user_id
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { user_id: users[0] } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  for (const fav of output.data) {
    TestValidator.equals("user matches")(users[0])(fav.user_id);
  }

  // 4b. Filter by product_id
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { product_id: products[1] } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  for (const fav of output.data) {
    TestValidator.equals("product matches")(products[1])(fav.product_id);
  }

  // 4c. Filter by created_at_from and created_at_to
  const earliest = created.map((c) => c.created_at).sort()[0];
  const latest = created.map((c) => c.created_at).sort().slice(-1)[0];
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { created_at_from: earliest, created_at_to: latest } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  for (const fav of output.data) {
    TestValidator.equals("within range")(
      fav.created_at >= earliest && fav.created_at <= latest,
    )(true);
  }

  // 4d. Query with deleted=true should return soft-deleted
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { deleted: true } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  for (const fav of output.data) {
    TestValidator.equals("soft-deleted present")(true)(softDeleted.has(fav.id));
  }

  // 5. Pagination tests
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 1, page: 1 } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  TestValidator.equals("limit 1")(1)(output.data.length);

  // Request a page past the end
  const bigPage = 1000;
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 1, page: bigPage } satisfies IFavorite.IRequest,
  });
  typia.assert(output);
  TestValidator.equals("empty page")([] as IFavorite[])(output.data);

  // 6. Invalid filter format (malformed uuid)
  await TestValidator.httpError("Invalid filter uuid")(400)(() =>
    api.functional.favoritesPersonalization.favorites.patch(connection, {
      body: { user_id: "not-a-uuid" as any } satisfies IFavorite.IRequest,
    })
  );

  // 7. Validate pagination metadata for normal result
  output = await api.functional.favoritesPersonalization.favorites.patch(connection, {
    body: { limit: 2, page: 1 } satisfies IFavorite.IRequest,
  });
  typia.assert(output.pagination);
  TestValidator.equals("current page")(1)(output.pagination.current);
  TestValidator.equals("limit")(2)(output.pagination.limit);
  TestValidator.equals("page length")(output.pagination.limit)(output.data.length <= output.pagination.limit ? output.data.length : output.pagination.limit);
