 *
 * Steps:
 * 1. Create a favorite.
 * 2. Soft delete the favorite via valid update.
 * 3. Attempt update with invalid UUID (expect error).
 * 4. Attempt update with nonexistent UUID (expect 404).
 * 5. Attempt update for a deleted favorite (should be idempotent or return error).
 * 6. Attempt invalid update payload (should result in validation error).
 */
export async function test_api_favorite_update_various_cases(
  connection: api.IConnection,
): Promise<void> {
