import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * Validate listing, searching, filtering, and paginating bookmarks with robust validation and correct omission of soft-deleted records.
 *
 * 1. Create several bookmarks for a single user with different categories, tags, products, and notes.
 * 2. List bookmarks filtered by user_id and check all bookmarks created in step 1 are present (excluding any soft-deleted ones).
 * 3. Add a soft-deleted bookmark and verify it does not appear in active queries.
 * 4. List bookmarks filtered by product_id, custom_folder, and tag—validate results match appropriate bookmarks.
 * 5. Test pagination logic by limiting and incrementally paging through results, confirming page and total counts.
 * 6. Pass an invalid filter (such as non-existent user_id or negative page/limit). Confirm that validation fails or returns empty set as appropriate.
 * 7. Request a page number past maximum. Confirm that an empty page or logical handling is returned.
 */
export async function test_api_favoritesPersonalization_bookmarks_list_search_filters_pagination_validation(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create several bookmarks
  const user_id = typia.random<string & typia.tags.Format<"uuid">>();
  const product_id_1 = typia.random<string & typia.tags.Format<"uuid">>();
  const product_id_2 = typia.random<string & typia.tags.Format<"uuid">>();
  const product_id_3 = typia.random<string & typia.tags.Format<"uuid">>();

  const createdBookmarks: IFavoritesPersonalization.IBookmark[] = [];
  for (const [product_id, custom_folder, tag, note] of [
    [product_id_1, "favorites", "tag1", "my first bookmark"],
    [product_id_2, "work", "urgent", "work bookmark"],
    [product_id_3, "leisure", "fun", "fun stuff"],
  ]) {
    const bookmark = await api.functional.favoritesPersonalization.bookmarks.post(
      connection,
      {
        body: {
          user_id,
          product_id,
          custom_folder,
          tag,
          note,
        } satisfies IFavoritesPersonalization.IBookmarkCreate,
      },
    );
    typia.assert(bookmark);
    createdBookmarks.push(bookmark);
  }

  // Step 2: List bookmarks filtered by user_id (active only)
  let page = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: {
      user_id: user_id,
      deleted: false,
    } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
  });
  typia.assert(page);
  TestValidator.equals("All active bookmarks returned")(3)(page.data.length);

  // Step 3: Add a soft-deleted bookmark
  const deletedBookmark = await api.functional.favoritesPersonalization.bookmarks.post(
    connection,
    {
      body: {
        user_id,
        product_id: typia.random<string & typia.tags.Format<"uuid">>(),
        custom_folder: "archive",
        tag: "archived",
        note: "should not show",
      } satisfies IFavoritesPersonalization.IBookmarkCreate,
    },
  );
  typia.assert(deletedBookmark);

  // Simulate soft-delete by manipulating deleted_at
  deletedBookmark.deleted_at = new Date().toISOString();

  // Step 4: Filter by product_id, custom_folder, or tag
  for (const filter of [
    { product_id: product_id_1 },
    { custom_folder: "work" },
    { tag: "fun" }
  ]) {
    const filtered = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
      body: {
        ...filter,
        user_id,
        deleted: false,
      } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
    });
    typia.assert(filtered);
    for (const bm of filtered.data) {
      if (filter.product_id)
        TestValidator.equals("product_id filtered")(filter.product_id)(bm.product_id);
      if (filter.custom_folder)
        TestValidator.equals("custom_folder filtered")(filter.custom_folder)(bm.custom_folder ?? "");
      if (filter.tag)
        TestValidator.equals("tag filtered")(filter.tag)(bm.tag ?? "");
    }
  }

  // Step 5: Pagination logic
  let paged = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: {
      user_id,
      limit: 2,
      page: 1,
      deleted: false,
    } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination page 1 count")(2)(paged.data.length);
  if (paged.pagination.pages > 1) {
    let paged2 = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
      body: {
        user_id,
        limit: 2,
        page: 2,
        deleted: false,
      } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
    });
    typia.assert(paged2);
    TestValidator.equals("pagination page 2 correct count")(1)(paged2.data.length);
  }

  // Step 6: Invalid queries
  // a) Nonexistent user
  const invalidUserResult = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: {
      user_id: typia.random<string & typia.tags.Format<"uuid">>(),
      deleted: false,
    } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
  });
  typia.assert(invalidUserResult);
  TestValidator.equals("nonexistent user yields empty")(0)(invalidUserResult.data.length);

  // b) Invalid limit/page
  for (const bad of [
    { limit: -1 },
    { page: -2 },
    { limit: 9999 },
  ]) {
    await TestValidator.error("invalid pagination params")(() =>
      api.functional.favoritesPersonalization.bookmarks.patch(connection, {
        body: {
          user_id,
          ...bad,
        } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
      }),
    );
  }

  // Step 7: Excessive page number
  const largePageResult = await api.functional.favoritesPersonalization.bookmarks.patch(connection, {
    body: {
      user_id,
      page: 1000,
      limit: 10,
      deleted: false,
    } satisfies IFavoritesPersonalization.IBookmarkSearchRequest,
  });
  typia.assert(largePageResult);
  TestValidator.equals("empty on large page")(0)(largePageResult.data.length);
}

