 * 2. Persisted changes are reflected.
 * 3. Updating with invalid field values triggers appropriate error responses.
 * 4. Attempting to update a non-existent ID results in error handling as expected.
 *
 * Steps:
 * 1. Create a new discount rule for testing.
 * 2. Update the created discount rule using valid modifications (value, active flag, campaign, ai_model_version_id).
 * 3. Validate that the updated fields are changed as expected and unchangeable fields remain stable.
 * 4. Try to update with invalid field values (e.g., negative value if disallowed, bad types).
 * 5. Attempt to update a non-existent discount rule UUID and check for not found error.
 */
export async function test_api_discount_rule_update_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a discount rule to update
  const createInput: IDiscountRule.ICreate = {
    type: "percentage",
    value: 10,
    active: true,
    campaign_id: null,
    ai_model_version_id: null,
