import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";
import { IPageIDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscountCampaign";
import typia from "typia";

export async function test_api_payments_discount_campaign_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create campaigns
  const now = new Date();
  const campaigns: IDiscountCampaign[] = [];

  // Active campaign
  campaigns.push(
    await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: "Summer Festival 2025",
        description: "Active campaign for summer.",
        start_at: new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(),
        end_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(),
        active: true,
      } satisfies IDiscountCampaign.ICreate,
    })
  );

  // Inactive/past campaign
  campaigns.push(
    await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: "Black Friday 2024",
        description: "Past campaign.",
        start_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 30).toISOString(),
        end_at: new Date(now.getTime() - 1000 * 60 * 60 * 24 * 20).toISOString(),
        active: false,
      } satisfies IDiscountCampaign.ICreate,
    })
  );

  // Future campaign
  campaigns.push(
    await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
      body: {
        name: "Winter Preview 2025",
        description: "Upcoming campaign.",
        start_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 10).toISOString(),
        end_at: new Date(now.getTime() + 1000 * 60 * 60 * 24 * 20).toISOString(),
        active: true,
      } satisfies IDiscountCampaign.ICreate,
    })
  );

  for (const c of campaigns) typia.assert(c);

  // Step 2: List all campaigns
  const all: IPageIDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.patch(
    connection,
    {
      body: {}, // no filters
    }
  );
  typia.assert(all);

  // Should at least include all the created campaigns by name
  for (const c of campaigns) {
    TestValidator.predicate(`all/search includes "${c.name}", all.data`)
      ((arr: IDiscountCampaign[]) => arr.find((x: IDiscountCampaign) => x.id === c.id) !== undefined)
      (all.data);
  }

  // Step 3: Filter by name (partial)
  {
    const byName = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { name: "Festival" },
    });
    typia.assert(byName);
    TestValidator.predicate("at least one with 'Festival'")
      ((arr: IDiscountCampaign[]) => arr.some((x: IDiscountCampaign) => x.name.includes("Festival")))
      (byName.data);
  }

  // Step 4: Filter by 'active' status
  {
    const byActive = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { active: true },
    });
    typia.assert(byActive);
    TestValidator.predicate("all active are active")
      ((arr: IDiscountCampaign[]) => arr.every((x: IDiscountCampaign) => x.active === true))
      (byActive.data);
    // Pair: inactive
    const byInactive = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { active: false },
    });
    typia.assert(byInactive);
    TestValidator.predicate("all inactive are inactive")
      ((arr: IDiscountCampaign[]) => arr.every((x: IDiscountCampaign) => x.active === false))
      (byInactive.data);
  }

  // Step 5: Filter by 'start_at_range'
  {
    const startRange = [
      new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString(),
      new Date(now.getTime() + 1000 * 60 * 60 * 24 * 5).toISOString(),
    ];
    const byStart = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { start_at_range: startRange as [string, string] },
    });
    typia.assert(byStart);
    for (const camp of byStart.data)
      TestValidator.predicate("start_at >= range[0]")
        ((v: string) => v >= startRange[0])
        (camp.start_at);
    for (const camp of byStart.data)
      TestValidator.predicate("start_at <= range[1]")
        ((v: string) => v <= startRange[1])
        (camp.start_at);
  }

  // Step 6: Filter by 'created_at_range'
  {
    const minCreated = campaigns[0].created_at;
    const maxCreated = campaigns[1].created_at > campaigns[2].created_at ? campaigns[1].created_at : campaigns[2].created_at;
    const byCreated = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { created_at_range: [minCreated, maxCreated] as [string, string] },
    });
    typia.assert(byCreated);
    TestValidator.predicate("created_at in correct range")
      ((arr: IDiscountCampaign[]) => arr.every((x: IDiscountCampaign) => x.created_at >= minCreated && x.created_at <= maxCreated))
      (byCreated.data);
  }

  // Step 7: (No explicit limit/page in DTO, so skip if not supported)
  // (If pagination params supported by extension, place tests here.)

  // Step 8: Invalid filter query (date range wrong size)
  await TestValidator.error("date range size error")(() =>
    api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { start_at_range: [now.toISOString()] as any },
    })
  );

  // Step 9: Empty filter result (no name matches)
  {
    const empty = await api.functional.paymentsDiscounts.discountCampaigns.patch(connection, {
      body: { name: "CampaignThatDoesNotExist" },
    });
    typia.assert(empty);
    TestValidator.equals("should return empty array")([] as IDiscountCampaign[])(empty.data);
  }
}

