import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IDiscountCampaign } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscountCampaign";

/**
 * 할인 캠페인 수정 기능 검증
 *
 * 본 테스트는 기존 할인 캠페인(Discount Campaign)의 업데이트(수정) 기능이 올바르게 동작하는지 검증합니다. 실제 비즈니스 환경에서 캠페인 업데이트 시 주로 발생하는 유효한/유효하지 않은 입력, 존재하지 않는 캠페인 ID를 모두 시나리오에 포함합니다.
 *
 * [테스트 단계]
 * 1. 정상 입력값으로 캠페인을 생성한다
 * 2. 해당 캠페인에 대해 유효한 값으로 수정(put) 요청을 보낸다
 * 3. 수정 결과가 적절히 반영되어 반환되는지 검증한다
 * 4. 캠페인 기간(end_at < start_at) 등 비정상 데이터로 수정 요청을 보냈을 때 에러가 발생하는지 검증한다
 * 5. 존재하지 않는 campaignId로 수정 요청을 할 때 적절한 에러가 발생하는지 검증한다
 */
export async function test_api_discount_campaign_update_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. 할인 캠페인 생성 (의존성 API)
  const campaign: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.post(connection, {
    body: {
      name: `K-Summer Sale ${Date.now()}`,
      description: "여름 한정 마케팅 프로모션 할인 캠페인",
      start_at: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
      end_at: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
      active: true,
    } satisfies IDiscountCampaign.ICreate,
  });
  typia.assert(campaign);

  // 2. 캠페인 이름 등 정상값으로 변경
  const updatedName = `${campaign.name}-MODIFIED`;
  const updated: IDiscountCampaign = await api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
    id: campaign.id,
    body: {
      name: updatedName,
      description: campaign.description ? campaign.description + "(수정됨)" : "설명 추가",
      active: false,
    } satisfies IDiscountCampaign.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("할인캠페인명 수정 확인")(updatedName)(updated.name);
  TestValidator.equals("활성상태 플래그 수정")(false)(updated.active);

  // 3. end_at이 start_at보다 과거(비정상)인 데이터 입력 → 400/422 등 오류 반환 기대
  const invalidEndAt = new Date(Date.parse(campaign.start_at) - 1000).toISOString();
  await TestValidator.error("end_at이 start_at보다 이전이면 400/422 에러")(async () =>
    api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: campaign.id,
      body: {
        end_at: invalidEndAt,
      } satisfies IDiscountCampaign.IUpdate,
    })
  );

  // 4. 존재하지 않는 campaignId로 수정 시도 → 404 not found 에러 기대
  const nonExistentId: string =
    "d24c66b2-cf1b-4abc-b769-8599999af000";
  await TestValidator.httpError("존재하지 않는 캠페인ID 수정 404")(404)(async () =>
    api.functional.paymentsDiscounts.discountCampaigns.putById(connection, {
      id: nonExistentId as any,
      body: {
        name: "ImpossibleCampaign",
        active: false,
      } satisfies IDiscountCampaign.IUpdate,
    })
  );
}

