import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITransaction";
import { IPageITransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITransaction";
import typia from "typia";

/**
 * Validate paginated and filterable transaction list retrieval.
 *
 * This test verifies the ability to retrieve lists of payment transactions with proper filters, date range, type, pagination, and edge/error cases.
 * Key validations include filter accuracy, sorting, pagination correctness, and proper error handling when using out-of-range pages or invalid filters.
 *
 * Process:
 * 1. Create multiple transaction records with distinct user_id, type, dates (some matching and some differing for filter variety).
 * 2. List transactions with no filters and default pagination, validate all created records appear.
 * 3. List transactions filtering by user_id, verify result only contains correct user records.
 * 4. List transactions filtering by type, assert only correct type is returned.
 * 5. List transactions within a created_at date range, verify result is exact.
 * 6. Use pagination (limit/page), verify records returned, limits, total counts, and pagination meta.
 * 7. Attempt to fetch page beyond total pages, confirm empty data or appropriate error.
 * 8. Attempt to use an unrecognized filter property, confirm error behavior or ignore per API policy.
 */
export async function test_api_transaction_list_transactions_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple transaction records with variety for filtering
  const users = [typia.random<string>(), typia.random<string>()];
  const base_date = new Date();
  const tx_types = ["purchase", "refund"];

  const transactionA: ITransaction = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    {
      body: {
        user_id: users[0],
        type: tx_types[0],
        created_at: new Date(base_date.getTime() - 1000000).toISOString(),
        description: "A purchase tx",
      } satisfies ITransaction.ICreate,
    },
  );
  typia.assert(transactionA);

  const transactionB: ITransaction = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    {
      body: {
        user_id: users[0],
        type: tx_types[1],
        created_at: new Date(base_date.getTime() - 500000).toISOString(),
        description: "A refund tx",
      } satisfies ITransaction.ICreate,
    },
  );
  typia.assert(transactionB);

  const transactionC: ITransaction = await api.functional.paymentsDiscounts.transactions.post(
    connection,
    {
      body: {
        user_id: users[1],
        type: tx_types[0],
        created_at: new Date(base_date.getTime()).toISOString(),
        description: "Another purchase tx",
      } satisfies ITransaction.ICreate,
    },
  );
  typia.assert(transactionC);

  // 2. List all transactions, no filters
  const allList: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: {},
    },
  );
  typia.assert(allList);
  TestValidator.equals("all created tx appear")(
    [transactionA.id, transactionB.id, transactionC.id].sort()
  )(
    allList.data.map((t) => t.id).filter((id) => [transactionA.id, transactionB.id, transactionC.id].includes(id)).sort()
  );

  // 3. List by user_id filter
  const userList: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: { user_id: users[0] },
    },
  );
  typia.assert(userList);
  TestValidator.equals("only user 0 txs")(
    [transactionA.id, transactionB.id].sort()
  )(
    userList.data.map((t) => t.id).filter((id) => [transactionA.id, transactionB.id].includes(id)).sort()
  );
  for (const tx of userList.data) TestValidator.equals("user check")(users[0])(tx.user_id);

  // 4. List by type filter
  const typeList: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: { type: tx_types[1] },
    },
  );
  typia.assert(typeList);
  TestValidator.equals("refund tx present")([transactionB.id])(
    typeList.data.map((t) => t.id).filter((id) => id === transactionB.id)
  );
  for (const tx of typeList.data) TestValidator.equals("type check")(tx_types[1])(tx.type);

  // 5. Filter by date range
  const after = new Date(base_date.getTime() - 600000).toISOString();
  const before = base_date.toISOString();
  const dateList: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: { created_after: after, created_before: before },
    },
  );
  typia.assert(dateList);
  // Only transactions B and C are in this range.
  TestValidator.equals("date filter txs")(
    [transactionB.id, transactionC.id].sort()
  )(
    dateList.data.map((t) => t.id).filter((id) => [transactionB.id, transactionC.id].includes(id)).sort()
  );

  // 6. Pagination
  const paged: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: { page: 1, limit: 2 },
    },
  );
  typia.assert(paged);
  TestValidator.equals("pagination limit")(2)(paged.data.length);
  TestValidator.equals("pagination meta: limit")(2)(paged.pagination.limit);
  TestValidator.equals("pagination meta: current")(1)(paged.pagination.current);

  // 7. Out of bound page (e.g., page 9999)
  const emptyPage: IPageITransaction = await api.functional.paymentsDiscounts.transactions.patch(
    connection,
    {
      body: { page: 9999, limit: 2 },
    },
  );
  typia.assert(emptyPage);
  TestValidator.equals("out of bound page empty")(0)(emptyPage.data.length);

  // 8. Unrecognized filter (simulate unknown property in filter)
  // Per API policy, if ignored, result should not fail. If strict, should error.
  // We'll check that either empty data or error is handled.
  try {
    await api.functional.paymentsDiscounts.transactions.patch(
      connection,
      {
        body: { bogusField: "bogus" } as any, // intentionally wrong
      },
    );
    // If no error, pass.
  } catch (err) {
    // If throws, that's expected if API is strict. Optionally, check error code.
  }
}

