 *
 * This test covers both the successful case of fetching an existing transaction, and
the negative path for non-existent/invalid transaction ID error handling.
 *
 * 1. Create a transaction to get a known valid transaction id.
 * 2. Retrieve that transaction by id and confirm all key fields and structure.
 * 3. Attempt to retrieve a transaction with non-existent id and expect error (404 or contract error response).
 */
export async function test_api_payments_discounts_transaction_get_by_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a transaction
  const transactionCreate: ITransaction.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: null,
    type: "purchase",
    created_at: new Date().toISOString(),
    description: "Initial test transaction for retrieval",
  };
  const created: ITransaction = await api.functional.paymentsDiscounts.transactions.post(connection, {
    body: transactionCreate,
  });
  typia.assert(created);

  // 2. Retrieve the transaction by valid id
  const fetched: ITransaction = await api.functional.paymentsDiscounts.transactions.getById(connection, {
    id: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id")(created.id)(fetched.id);
  TestValidator.equals("user_id")(created.user_id)(fetched.user_id);
  TestValidator.equals("order_id")(created.order_id ?? null)(fetched.order_id ?? null);
  TestValidator.equals("type")(created.type)(fetched.type);
  TestValidator.equals("description")(created.description ?? null)(fetched.description ?? null);
  // created_at may have minor ISO formatting adjustments depending on server, compare as Date
  TestValidator.equals("created_at")(
    new Date(created.created_at).toISOString().slice(0, 19)
  )(
    new Date(fetched.created_at).toISOString().slice(0, 19)
  );

  // 3. Attempt to fetch with a non-existent id (should error: 404)
  const INVALID_ID: string & tags.Format<"uuid"> =
    typia.random<string & tags.Format<"uuid">>();
  // Defensive: Ensure INVALID_ID does not match created.id
  if (INVALID_ID === created.id) throw new Error("Generated UUID collided; rerun test.");

  await TestValidator.httpError("get non-existent transaction (404)")(404)(() =>
    api.functional.paymentsDiscounts.transactions.getById(connection, {
      id: INVALID_ID,
    })
  );
}

