  typia.assert(tx);

  // 2. Update all mutable fields (order_id, type, description)
  const updateInput: ITransaction.IUpdate = {
    order_id: typia.random<string & tags.Format<"uuid">>(),
    type: "refund",
    description: "Transaction description updated.",
  };
  const updated: ITransaction = await api.functional.paymentsDiscounts.transactions.putById(connection, {
    id: tx.id,
    body: updateInput,
  });
