  TestValidator.equals("user_id (immutable)")(tx.user_id)(updated.user_id);
  TestValidator.equals("created_at (immutable)")(tx.created_at)(updated.created_at);

  // 3. Retrieve updated transaction and confirm mutations (if GET endpoint available)
