test/features/api/voucher/test_list_vouc:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";
import { IPageIVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIVoucher";
import typia from "typia";

/**
 * List and search vouchers using flexible queries.
 *
 * This test covers the voucher listing/search endpoint by:
 * - Creating several vouchers with different filterable attributes
 * - Retrieving vouchers filtered by user, code, campaign, payment method, expiry, and currency
 * - Verifying pagination (multiple pages, limits, boundaries)
 * - Testing for zero-match/no result and unsupported filters (error handling)
 *
 * Steps:
 * 1. Create 6+ vouchers with varied users, campaigns, payment methods, expiry, currency, and codes
 * 2. List vouchers by user to verify correct filtering
 * 3. List vouchers by specific codes for individual match
 * 4. List by campaign_id/payment_method_id to verify filter logic
 * 5. List expiring before/after certain dates
 * 6. List by redeemed status (both redeemed and not)
 * 7. List by currency codes
 * 8. Paginate with page/limit combinations, asserting correct boundaries and data integrity
 * 9. Issue a search that should return zero results (verifying edge/no-match)
 * 10. Try an unsupported filter key and check error is thrown/handled
 */
export async function test_api_voucher_list_with_various_filters_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create several vouchers for test variety
  const users = Array.from({ length: 2 }, () => typia.random<string & typia.tags.Format<"uuid">>());
  const campaigns = [typia.random<string & typia.tags.Format<"uuid">>(), null];
  const paymentMethods = [typia.random<string & typia.tags.Format<"uuid">>(), null];
  const codes = ["VCHR-A", "VCHR-B", "VCHR-C", "VCHR-D", "VCHR-E", "VCHR-F"];
  const currencies = ["KRW", "USD"];
  const expires = [
    new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // +1 day
    new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(), // +2 days
    null,
  ];
  // Mix up combinations
  const vouchers: IVoucher[] = [];
  for (let i = 0; i < 6; ++i) {
    const res: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: {
        user_id: users[i % users.length],
        campaign_id: campaigns[i % campaigns.length],
        payment_method_id: paymentMethods[i % paymentMethods.length],
        code: codes[i],
        balance: Math.floor(Math.random() * 10000) + 100,
        currency: currencies[i % currencies.length],
        expires_at: expires[i % expires.length],
      } satisfies IVoucher.ICreate,
    });
    typia.assert(res);
    vouchers.push(res);
  }
  // 2. Filter by user_id
  const user0Vouchers = vouchers.filter(v => v.user_id === users[0]);
  const listByUser = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      user_id: users[0],
    } satisfies IVoucher.IRequest,
  });
  typia.assert(listByUser);
  TestValidator.equals("user_id filter count")(user0Vouchers.length)(listByUser.data.length);
  for (const v of listByUser.data) TestValidator.equals("user_id match")(users[0])(v.user_id);

  // 3. Filter by code
  const byCode = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      code: codes[0],
    } satisfies IVoucher.IRequest,
  });
  typia.assert(byCode);
  TestValidator.equals("code filter count")(1)(byCode.data.length);
  for (const v of byCode.data) TestValidator.equals("code match")(codes[0])(v.code);

  // 4. Filter by campaign_id and payment_method_id (compound filters)
  const filtered = vouchers.filter(
    v => (v.campaign_id ?? null) === campaigns[0] && (v.payment_method_id ?? null) === paymentMethods[0],
  );
  const byCampaignAndPayment = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      campaign_id: campaigns[0],
      payment_method_id: paymentMethods[0],
    } satisfies IVoucher.IRequest,
  });
  typia.assert(byCampaignAndPayment);
  TestValidator.equals("campaign+payment-method filter")(filtered.length)(byCampaignAndPayment.data.length);
  for (const v of byCampaignAndPayment.data) {
    TestValidator.equals("campaign_id match")(campaigns[0])((v.campaign_id ?? null));
    TestValidator.equals("payment_method_id match")(paymentMethods[0])((v.payment_method_id ?? null));
  }

  // 5. Expiry date range queries
  const expiresBefore = expires[1]!;
  const beforeList = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      expires_before: expiresBefore,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(beforeList);
  for (const v of beforeList.data)
    if (v.expires_at)
      TestValidator.equals("expires before check")(
        true,
      )(new Date(v.expires_at).getTime() < new Date(expiresBefore).getTime());

  // 6. Redeemed (none redeemed, so all false)
  const byNotRedeemed = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      redeemed: false,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(byNotRedeemed);
  for (const v of byNotRedeemed.data)
    TestValidator.equals("not redeemed")(null)(v.redeemed_at);

  // 7. Filter by currency
  const byKRW = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      currency: "KRW",
    } satisfies IVoucher.IRequest,
  });
  typia.assert(byKRW);
  for (const v of byKRW.data) TestValidator.equals("currency match")("KRW")(v.currency);

  // 8. Pagination test (page=1,2 with small limit)
  const limit = 2;
  const page1 = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      limit,
      page: 1,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page1 current")(1)(page1.pagination.current);
  TestValidator.equals("page1 limit")(limit)(page1.pagination.limit);
  TestValidator.equals("page1 length")(limit)(page1.data.length);

  const page2 = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      limit,
      page: 2,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("page2 current")(2)(page2.pagination.current);
  TestValidator.equals("page2 limit")(limit)(page2.pagination.limit);

  // Page overflow
  const pageOverflow = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      limit,
      page: 100,
    } satisfies IVoucher.IRequest,
  });
  typia.assert(pageOverflow);
  TestValidator.equals("overflow empty")(0)(pageOverflow.data.length);

  // 9. No match search
  const noResult = await api.functional.paymentsDiscounts.vouchers.patch(connection, {
    body: {
      code: "NON_EXISTENT_CODE",
    } satisfies IVoucher.IRequest,
  });
  typia.assert(noResult);
  TestValidator.equals("no match")(0)(noResult.data.length);

  // 10. Unsupported filter key: should throw or ignore; expect error or 0 result
  await TestValidator.error("unsupported filter should throw")(()
    => api.functional.paymentsDiscounts.vouchers.patch(connection, {
      body: {
        invalid_key: "foo",
      } as any,
    }),
  );
}

