/**
 * Retrieve detailed information for a voucher using a valid ID and verify the returned fields.
 * Attempt to fetch a voucher with an invalid/non-existent ID and check for the expected error.
 *
 * Prerequisite:
 * 1. Issue a voucher so there is a known ID to retrieve.
 *
 * Steps:
 * 1. Issue (create) a new voucher via the POST /paymentsDiscounts/vouchers endpoint.
 * 2. Retrieve this voucher using its valid ID via GET /paymentsDiscounts/vouchers/{id}.
 * 3. Validate that all important fields are returned and correct (by comparing to created values).
 * 4. Attempt to retrieve a voucher with a random/non-existent ID and verify the API returns the expected error (e.g., 404).
 */
export async function test_api_voucher_get_by_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Issue (create) a new voucher
  const voucherCreate: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: `TEST-CODE-${Math.random().toString(36).slice(2, 10)}`,
    balance: 10000,
    currency: "USD",
    // Optionally set campaign_id, payment_method_id, expires_at
  };
  const created: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(connection, {
    body: voucherCreate,
  });
