import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";
import typia from "typia";

/**
 * Validate the voucher creation endpoint with both valid and invalid scenarios.
 *
 * This test covers these cases:
 * 1. Successfully issue a new voucher with valid required/optional fields.
 * 2. Attempt to create a voucher with missing required data (e.g., no amount/balance, no code, no expiry where required) and expect a validation error.
 * 3. Attempt to create a voucher reusing an already existing code and expect a duplicate code error.
 *
 * Business context:
 * Voucher issuance requires compliance — user, code, currency, and balance are mandatory, and code uniqueness is enforced. This test both validates correct flow and guards against common error scenarios for admin or automated workflows.
 */
export async function test_api_voucher_issue_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Successfully issue a valid voucher
  const validVoucherInput: IVoucher.ICreate = {
    user_id: typia.random<string>(),
    code: `VOUCHER-${Date.now()}`,
    balance: 10000,
    currency: "KRW",
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24 * 30).toISOString(),
  };
  const issued: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(
    connection,
    { body: validVoucherInput },
  );
  typia.assert(issued);
  TestValidator.equals("issued code")(validVoucherInput.code)(issued.code);
  TestValidator.equals("user id")(validVoucherInput.user_id)(issued.user_id);
  TestValidator.equals("currency")(validVoucherInput.currency)(issued.currency);
  TestValidator.equals("balance")(validVoucherInput.balance)(issued.balance);

  // 2. Validation error: missing required data (code)
  await TestValidator.httpError("missing code")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, code: undefined as any },
    }),
  );

  // 2-2. Validation error: missing balance
  await TestValidator.httpError("missing balance")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, balance: undefined as any },
    }),
  );

  // 2-3. Validation error: invalid currency
  await TestValidator.httpError("invalid currency")(400)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: { ...validVoucherInput, currency: "XXX" },
    }),
  );

  // 3. Duplicate code error: reuse same code
  await TestValidator.httpError("duplicate code")(409)(() =>
    api.functional.paymentsDiscounts.vouchers.post(connection, {
      body: validVoucherInput,
    }),
  );
}

test/features/api/voucher/test_update_vo:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * E2E test: voucher update scenario covers both valid and invalid update operations, as well as enforcement of immutable fields.
 *
 * Scenario steps:
 * 1. Issue a new voucher with valid creation data.
 * 2. Update mutable fields (like expiry, balance) on the voucher using valid data.
 * 3. Attempt to update the voucher with an invalid balance (negative or zero), expect error.
 * 4. Attempt to update a voucher using a non-existent ID, expect error.
 * 5. Attempt to update an immutable field (code, user_id) and confirm the mutation is rejected or ignores in response.
 * 6. For each valid mutation, assert correct persistence; for each invalid, assert expected error semantics.
 *
 * This test ensures compliance and audit constraints are enforced as per system policy.
 */
export async function test_api_voucher_update_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Issue a new voucher
  const init: IVoucher.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    code: `VCH-${Date.now()}-${Math.floor(Math.random()*10000)}`,
    balance: 1000.0,
    currency: "USD",
    expires_at: new Date(Date.now() + 10*24*60*60*1000).toISOString(), // expires in 10 days
  };
  const created: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(connection, { body: init });
  typia.assert(created);
  TestValidator.equals("voucher_code_persisted")(init.code)(created.code);

  // 2. Update with valid data (e.g., balance, currency, expires_at)
  const updatePayload: IVoucher.IUpdate = {
    balance: 500.5,
    expires_at: new Date(Date.now() + 5*24*60*60*1000).toISOString(), // new expiry (5 days from now)
    currency: "USD"
  };
  const updated: IVoucher = await api.functional.paymentsDiscounts.vouchers.putById(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("voucher_id_persisted")(created.id)(updated.id);
  TestValidator.equals("voucher_balance_updated")(updatePayload.balance)(updated.balance);
  TestValidator.equals("voucher_expiry_updated")(updatePayload.expires_at)(updated.expires_at);

  // 3. Attempt with invalid data (negative balance)
  await TestValidator.error("negative balance forbidden")(() =>
    api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: created.id,
      body: { balance: -100 } satisfies IVoucher.IUpdate,
    })
  );

  // 4. Attempt with non-existent voucher ID
  await TestValidator.httpError("update non-existent id")(404)(() =>
    api.functional.paymentsDiscounts.vouchers.putById(connection, {
      id: "47111111-1111-4111-8111-111111111111" as string & tags.Format<"uuid">,
      body: { expires_at: new Date(Date.now() + 1*24*60*60*1000).toISOString() } satisfies IVoucher.IUpdate,
    })
  );

  // 5. Attempt to update immutable fields (simulate code/user_id change)
  const immutTestPayload: IVoucher.IUpdate = {
    // These properties are not part of allowed update interface but for negative test we add by casting
    ...( {
      code: "DUMMY-CODE", user_id: typia.random<string & tags.Format<"uuid">>()
    } as any ),
    expires_at: new Date(Date.now() + 20*24*60*60*1000).toISOString()
  };
  const immutResult: IVoucher = await api.functional.paymentsDiscounts.vouchers.putById(connection, {
    id: created.id,
    body: immutTestPayload,
  });
  typia.assert(immutResult);
  // Code and user_id must NOT have changed
  TestValidator.equals("immutable_code_enforced")(created.code)(immutResult.code);
  TestValidator.equals("immutable_user_id_enforced")(created.user_id)(immutResult.user_id);
}

test/features/api/voucher/test_soft_dele:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IVoucher } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoucher";

/**
 * Soft-delete (revoke) an existing voucher by valid ID and confirm status update.
 *
 * Steps:
 * 1. Issue a new voucher to establish a valid test asset.
 * 2. Soft-delete (revoke) the issued voucher by ID.
 * 3. Confirm the voucher's response shows it is revoked (using `redeemed_at` as deletion mark or field behavior).
 * 4. Attempt to delete the revoked voucher a second time to check idempotency (should not error and maintains revoked state).
 * 5. Attempt to delete a non-existent (randomly generated) voucher ID and expect error response (e.g., 404).
 *
 * This test validates regulatory soft-deletion behavior and idempotency/error handling.
 */
export async function test_api_voucher_soft_delete_and_invalid_delete(
  connection: api.IConnection,
): Promise<void> {
  // 1. Issue a new voucher
  const voucher: IVoucher = await api.functional.paymentsDiscounts.vouchers.post(
    connection,
    {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        code: `TEST-${Math.random().toString(36).slice(2, 12).toUpperCase()}`,
        balance: 10000,
        currency: "KRW",
      } satisfies IVoucher.ICreate,
    },
  );
  typia.assert(voucher);

  // 2. Soft-delete (revoke) the issued voucher
  const revoked: IVoucher = await api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
    id: voucher.id,
  });
  typia.assert(revoked);
  // 3. Confirm voucher is revoked (redeemed_at should now be set)
  TestValidator.equals("redeemed_at set after revoke")(true)(typeof revoked.redeemed_at === "string" && revoked.redeemed_at.length > 0);

  // 4. Attempt to delete already revoked voucher for idempotency
  const repeat: IVoucher = await api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
    id: voucher.id,
  });
  typia.assert(repeat);
  TestValidator.equals("Same voucher remains revoked")(revoked.redeemed_at)(repeat.redeemed_at);

  // 5. Attempt to delete a non-existing voucher
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  // Ensure we don't collide with the issued voucher's ID
  if (fakeId === voucher.id) throw new Error("Random UUID collision");
  await TestValidator.httpError("Delete non-existent voucher should error")(404)(() =>
    api.functional.paymentsDiscounts.vouchers.eraseById(connection, {
      id: fakeId,
    }),
  );
}

