import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { ILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/ILoyaltyPoint";
import { IPageILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageILoyaltyPoint";

/**
 * List and search loyalty points records with combinations of filters, pagination, and sorting.
 *
 * This test ensures that:
 *  - Filtering by user ID, type, and date range works correctly.
 *  - Empty result sets are returned on missing data or unmatched filters.
 *  - Errors are raised on invalid filter parameters.
 *
 * Steps:
 * 1. Create several loyalty point events with diverse user_ids, types, and timestamps.
 * 2. Search using a specific user_id and get only that user's points.
 * 3. Search using type filter and validate only events of that type are returned.
 * 4. Search using a date range and check results fall within it.
 * 5. Search with filters that match nothing and confirm empty results.
 * 6. Pass an invalid filter (malformed date/type) and validate error response.
 */
export async function test_api_paymentsDiscounts_loyaltyPoints_list_with_filters_and_pagination(connection: api.IConnection): Promise<void> {
  // 1. Create diverse loyalty points data
  const now = new Date();
  const past = new Date(now.getTime() - 24 * 60 * 60 * 1000); // 1 day ago
  const userA = typia.random<string & typia.tags.Format<"uuid">>();
  const userB = typia.random<string & typia.tags.Format<"uuid">>();
  const earn1: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
    body: {
      user_id: userA,
      points: 100,
      type: "earn",
      transaction_id: undefined,
      campaign_id: undefined
    } satisfies ILoyaltyPoint.ICreate,
  });
  const earn2: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
    body: {
      user_id: userA,
      points: 50,
      type: "bonus",
      transaction_id: undefined,
      campaign_id: undefined
    } satisfies ILoyaltyPoint.ICreate,
  });
  const redeem1: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
    body: {
      user_id: userB,
      points: -40,
      type: "redeem",
      transaction_id: undefined,
      campaign_id: undefined
    } satisfies ILoyaltyPoint.ICreate,
  });
  // Backdate one point to test range filter
  const oldPoint: ILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
    body: {
      user_id: userA,
      points: 5,
      type: "expire",
      transaction_id: undefined,
      campaign_id: undefined
    } satisfies ILoyaltyPoint.ICreate,
  });
  // 2. Filter by user_id
  const userAList: IPageILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: userA } satisfies ILoyaltyPoint.IRequest,
  });
  typia.assert(userAList);
  for (const rec of userAList.data) {
    TestValidator.equals("user_id")(userA)(rec.user_id);
  }
  // 3. Filter by type (bonus)
  const bonusList: IPageILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { type: "bonus" } satisfies ILoyaltyPoint.IRequest,
  });
  typia.assert(bonusList);
  for (const rec of bonusList.data) {
    TestValidator.equals("type")("bonus")(rec.type);
  }
  // 4. Filter by date range (only recent)
  const dateList: IPageILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { created_from: now.toISOString() } satisfies ILoyaltyPoint.IRequest,
  });
  typia.assert(dateList);
  for (const rec of dateList.data) {
    if (rec.created_at < now.toISOString())
      throw new Error(`Found point before date range: ${rec.created_at}`);
  }
  // 5. Non-matching filters (should return empty list)
  const noneList: IPageILoyaltyPoint = await api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
    body: { user_id: typia.random<string & typia.tags.Format<"uuid">>() } satisfies ILoyaltyPoint.IRequest,
  });
  typia.assert(noneList);
  TestValidator.equals("should be empty set")(0)(noneList.data.length);
  // 6. Malformed filter error (invalid date string)
  await TestValidator.httpError("invalid date filter")(400)(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.patch(connection, {
      body: { created_from: "not-a-date" as any } satisfies ILoyaltyPoint.IRequest }));
}

