import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ILoyaltyPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/ILoyaltyPoint";
import typia, { tags } from "typia";

/**
 * Amend (mutate) permissible metadata fields on a loyalty point event and confirm the changes.
 * Also attempt to update immutable fields or use an invalid ID, ensuring proper system validation and error reporting.
 *
 * Scenario steps:
 * 1. Create a new loyalty point event via POST /paymentsDiscounts/loyaltyPoints.
 * 2. Amend mutable metadata fields on the loyalty point (such as campaign_id, transaction_id, points, or type) with PUT /paymentsDiscounts/loyaltyPoints/{id}, and confirm the update.
 * 3. Attempt to update an immutable field (id or user_id) and confirm the system rejects the change and returns a validation error.
 * 4. Attempt to update a non-existent (invalid) loyalty_point id and confirm the system returns an appropriate error (such as 404).
 */
export async function test_api_loyalty_point_update_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new loyalty point event
  const created: ILoyaltyPoint =
    await api.functional.paymentsDiscounts.loyaltyPoints.post(connection, {
      body: {
        user_id: typia.random<string & tags.Format<"uuid">>(),
        transaction_id: typia.random<string & tags.Format<"uuid">>(),
        campaign_id: typia.random<string & tags.Format<"uuid">>(),
        points: 50,
        type: "earn",
      } satisfies ILoyaltyPoint.ICreate,
    });
  typia.assert(created);

  // 2. Successfully update mutable metadata fields
  const updated: ILoyaltyPoint =
    await api.functional.paymentsDiscounts.loyaltyPoints.putById(connection, {
      id: created.id,
      body: {
        campaign_id: typia.random<string & tags.Format<"uuid">>(),
        points: 42,
        type: "bonus",
      } satisfies ILoyaltyPoint.IUpdate,
    });
  typia.assert(updated);
  TestValidator.equals("loyaltyPoint.id")(created.id)(updated.id);
  TestValidator.equals("loyaltyPoint.user_id")(created.user_id)(updated.user_id);
  TestValidator.equals("Updated campaign_id")(updated.campaign_id !== created.campaign_id ? updated.campaign_id : created.campaign_id)(updated.campaign_id);
  TestValidator.equals("Updated type")("bonus")(updated.type);
  TestValidator.equals("Updated points")(42)(updated.points);

  // 3. Attempt to update immutable field (id or user_id) - should not actually be allowed in DTO/patch, so try an unexpected key or wrong type
  await TestValidator.error("attempt to update immutable user_id should fail")(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.putById(connection, {
      id: created.id,
      body: {
        // @ts-expect-error - purposely insert immutable/user_id
        // Some servers may ignore, some may 400/422, test for either
        user_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 4. Attempt to update a non-existent (invalid) loyalty point ID
  await TestValidator.httpError("update on non-existent loyalty point id should 404")(404)(() =>
    api.functional.paymentsDiscounts.loyaltyPoints.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random, unlikely to exist
      body: {
        campaign_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );
}

