test/features/api/refund/test_list_refun:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";
import { IPageIRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIRefund";
import typia from "typia";

/**
 * List/search refund events with multiple filters, pagination, and error handling.
 *
 * This test covers the following:
 * 1. Creating payment records that will be potentially refunded
 * 2. Creating multiple refund events with diverse data (amount, status, etc)
 * 3. Fetching refund lists with filters by payment_id, transaction_id, amount ranges, date ranges, and status
 * 4. Verifying the result matches filters
 * 5. Testing pagination (page, limit) and empty result page
 * 6. Testing error handling (invalid filter values)
 */
export async function test_api_refund_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two payments to refund
  const payment1: IPayment = await api.functional.paymentsDiscounts.payments.post(
    connection,
    {
      body: {
        transaction_id: typia.random<string>(),
        payment_method_id: typia.random<string>(),
        amount: 20000.00,
        currency: "KRW",
        description: "Refundable payment 1",
      } satisfies IPayment.ICreate,
    },
  );
  typia.assert(payment1);

  const payment2: IPayment = await api.functional.paymentsDiscounts.payments.post(
    connection,
    {
      body: {
        transaction_id: typia.random<string>(),
        payment_method_id: typia.random<string>(),
        amount: 43000.00,
        currency: "KRW",
        description: "Refundable payment 2",
      } satisfies IPayment.ICreate,
    },
  );
  typia.assert(payment2);

  // 2. Create three refunds for the payments with varying status/amounts
  const refund1: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    {
      body: {
        payment_id: payment1.id,
        transaction_id: payment1.transaction_id,
        amount: 5000.00,
        currency: payment1.currency,
        status: "requested",
        reason: "Partial refund for payment 1",
      } satisfies IRefund.ICreate,
    },
  );
  typia.assert(refund1);

  const refund2: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    {
      body: {
        payment_id: payment2.id,
        transaction_id: payment2.transaction_id,
        amount: 10000.00,
        currency: payment2.currency,
        status: "completed",
        reason: "Refund complete for payment 2",
      } satisfies IRefund.ICreate,
    },
  );
  typia.assert(refund2);

  const refund3: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    {
      body: {
        payment_id: payment1.id,
        transaction_id: payment1.transaction_id,
        amount: 7500.00,
        currency: payment1.currency,
        status: "rejected",
        reason: "Rejected refund for payment 1",
      } satisfies IRefund.ICreate,
    },
  );
  typia.assert(refund3);

  // 3. Search refunds by payment_id
  const filteredByPayment: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        payment_id: payment1.id,
        limit: 10,
        page: 1,
      } satisfies IRefund.IRequest,
    },
  );
  typia.assert(filteredByPayment);
  for (const r of filteredByPayment.data) {
    TestValidator.equals("filter by payment_id")(payment1.id)(r.payment_id);
  }

  // 4. Search refunds by status
  const filteredByStatus: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        status: "completed",
        limit: 10,
        page: 1,
      } satisfies IRefund.IRequest,
    },
  );
  typia.assert(filteredByStatus);
  for (const r of filteredByStatus.data) {
    TestValidator.equals("filter by status")("completed")(r.status);
  }

  // 5. Search refunds by requested_from/requested_to
  const now = new Date();
  const from = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(); // 1 day ago
  const to = new Date(now.getTime() + 60 * 60 * 1000).toISOString();
  const filteredByDate: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        requested_from: from,
        requested_to: to,
        limit: 10,
        page: 1,
      } satisfies IRefund.IRequest,
    }
  );
  typia.assert(filteredByDate);
  for (const r of filteredByDate.data) {
    // The refunds must be created within [from, to]
    TestValidator.equals("refund date in range")(true)(
      new Date(r.requested_at) >= new Date(from) && new Date(r.requested_at) <= new Date(to),
    );
  }

  // 6. Test pagination (limit=1): Should get 1 result per page, next page fetches next
  const firstPage: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: { limit: 1, page: 1 } satisfies IRefund.IRequest,
    }
  );
  typia.assert(firstPage);
  TestValidator.equals("pagination: 1 result")(1)(firstPage.data.length);

  if (firstPage.pagination.pages > 1) {
    const secondPage: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
      connection,
      {
        body: { limit: 1, page: 2 } satisfies IRefund.IRequest,
      },
    );
    typia.assert(secondPage);
    TestValidator.equals("pagination: page 2")(2)(secondPage.pagination.current);
  }

  // 7. Empty result (set impossible filter)
  const emptyResult: IPageIRefund = await api.functional.paymentsDiscounts.refunds.patch(
    connection,
    {
      body: {
        status: "definitely-nonexistent-status-filter-zzz",
        limit: 5,
        page: 1,
      } satisfies IRefund.IRequest,
    },
  );
  typia.assert(emptyResult);
  TestValidator.equals("empty search")(0)(emptyResult.data.length);

  // 8. Error case: invalid values (invalid page/limit)
  await TestValidator.httpError("invalid limit")
    (400)(() =>
      api.functional.paymentsDiscounts.refunds.patch(connection, {
        body: {
          limit: -10, // negative not allowed
          page: 1,
        } satisfies IRefund.IRequest,
      }),
    );

  await TestValidator.httpError("invalid page")
    (400)(() =>
      api.functional.paymentsDiscounts.refunds.patch(connection, {
        body: {
          limit: 1,
          page: -2, // negative page not allowed
        } satisfies IRefund.IRequest,
      }),
    );
}

