import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import { IRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefund";

/**
 * Validate creation and error handling of refund events for payments.
 *
 * This scenario ensures that refund events can only be created for valid payment references and valid monetary amounts.
 * The test fully exercises refund creation, field validation, uniqueness, and error responses.
 *
 * Steps:
 * 1. Create a valid payment record using the payments API, to be eligible for refund.
 * 2. Create a proper refund for the above payment and assert result.
 * 3. Attempt refund creation with missing/invalid references and expect validation errors.
 * 4. Attempt refund creation with negative refund amount and expect validation error.
 * 5. Attempt duplicate refund for the same payment and expect error (no double-refund allowed).
 */
export async function test_api_refund_create_with_and_without_valid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create valid payment
  const paymentReq: IPayment.ICreate = {
    transaction_id: typia.random<string>(),
    payment_method_id: typia.random<string>(),
    amount: 100.0,
    currency: "USD",
    description: "Test payment for refund flow",
  };
  const payment: IPayment = await api.functional.paymentsDiscounts.payments.post(
    connection,
    { body: paymentReq }
  );
  typia.assert(payment);

  // 2. Create valid refund for above payment
  const refundReq: IRefund.ICreate = {
    payment_id: payment.id,
    transaction_id: payment.transaction_id,
    amount: 100.0,
    currency: payment.currency,
    status: "requested",
    reason: "Requested by customer",
    order_id: null,
  };
  const refund: IRefund = await api.functional.paymentsDiscounts.refunds.post(
    connection,
    { body: refundReq }
  );
  typia.assert(refund);
  TestValidator.equals("refund.payment_id")(refundReq.payment_id)(refund.payment_id);
  TestValidator.equals("refund.amount")(refundReq.amount)(refund.amount);
  TestValidator.equals("refund.currency")(refundReq.currency)(refund.currency);
  TestValidator.equals("refund.status")(refundReq.status)(refund.status);
  TestValidator.equals("refund.reason")(refundReq.reason)(refund.reason);

  // 3. Attempt refund with missing references (no payment_id, no transaction_id)
  await TestValidator.httpError("missing payment reference")(400)(() =>
    api.functional.paymentsDiscounts.refunds.post(
      connection,
      {
        body: {
          payment_id: undefined as any,
          transaction_id: undefined as any,
          amount: 100.0,
          currency: payment.currency,
          status: "requested",
        },
      })
  );

  // 4. Attempt refund with negative amount
  await TestValidator.httpError("negative refund amount")(400)(() =>
    api.functional.paymentsDiscounts.refunds.post(
      connection,
      {
        body: {
          payment_id: payment.id,
          transaction_id: payment.transaction_id,
          amount: -50.0,
          currency: payment.currency,
          status: "requested",
        } as any,
      })
  );

  // 5. Attempt duplicate refund
  await TestValidator.httpError("duplicate refund")(409)(() =>
    api.functional.paymentsDiscounts.refunds.post(
      connection,
      {
        body: refundReq,
      })
  );
}

