import { TestValidator } from "@nestia/e2e";
import typia, { tags } from "typia";
import api from "@ORGANIZATION/PROJECT-api";
import { IAITrainingData } from "@ORGANIZATION/PROJECT-api/lib/structures/IAITrainingData";

/**
 * E2E test: Update AI training data with various scenarios (valid ID, invalid ID, malformed data, uneditable fields, and concurrent updates).
 *
 * 1. Create a new AI training dataset (prerequisite for update tests).
 * 2. Update with valid ID and valid data fields. Assert result matches changes.
 * 3. Fetch after update: confirm change reflect.
 * 4. Attempt update with an invalid (random) ID: expect not found error (404).
 * 5. Attempt update with malformed/invalid data (missing required or invalid type): expect validation error (400).
 * 6. Attempt update changing uneditable fields (id, created_at): expect rejection.
 * 7. Attempt concurrent updates (simulate as possible): expect conflict or last-write-wins as defined by system.
 */
export async function test_api_ai_training_data_update_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new AI training dataset
  const created: IAITrainingData = await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      name: "Audit User Event Logs",
      version: "20240623",
      source_uri: "s3://datasets/events/20240623.csv",
      schema_hash: "abcd1234deadbeef9999",
      ai_model_id: null,
      record_count: 12345,
    } satisfies IAITrainingData.ICreate,
  });
  typia.assert(created);

  // 2. Update with valid ID and valid data
  const updateBody: IAITrainingData.IUpdate = {
    name: "Refined User Logs",
    version: "20240624",
    record_count: 12400,
  };
  const updated: IAITrainingData = await api.functional.advancedAI.aiTrainingData.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("Update name")(updateBody.name)(updated.name);
  TestValidator.equals("Update version")(updateBody.version)(updated.version);
  TestValidator.equals("Update record_count")(updateBody.record_count)(updated.record_count);
  TestValidator.equals("not changed source_uri")(created.source_uri)(updated.source_uri);

  // 3. Fetch after update: system may provide GET by ID; if not, check updated in update result.
  // If fetch API exists, fetch here and do similar asserts. (Omitted if not available)

  // 4. Update with invalid ID (random UUID)
  await TestValidator.httpError("update with invalid ID")(404)(() =>
    api.functional.advancedAI.aiTrainingData.putById(connection, {
      id: "1c061bad-d3ad-4122-a7c2-abcdefabcdef" as string & tags.Format<"uuid">,
      body: updateBody,
    })
  );

  // 5. Update with malformed/invalid data (invalid type: string for record_count)
  await TestValidator.httpError("invalid data: record_count string")(400)(() =>
    api.functional.advancedAI.aiTrainingData.putById(connection, {
      id: created.id,
      body: {
        record_count: "wrong-type" as any,
      },
    })
  );

  // 6. Attempt update on uneditable fields: id, created_at (should be ignored or cause error)
  await TestValidator.error("update on uneditable fields: id")(async () => {
    await api.functional.advancedAI.aiTrainingData.putById(connection, {
      id: created.id,
      body: {
        id: "should-not-be-allowed" as any,
        name: "Corrupted Name",
      } as any,
    });
  });

  await TestValidator.error("update on uneditable fields: created_at")(async () => {
    await api.functional.advancedAI.aiTrainingData.putById(connection, {
      id: created.id,
      body: {
        created_at: new Date().toISOString(),
        name: "Corrupted Name",
      } as any,
    });
  });

  // 7. Concurrent updates: race two updates, last-write-wins or conflict
  const concurrent1: Promise<IAITrainingData> = api.functional.advancedAI.aiTrainingData.putById(connection, {
    id: created.id,
    body: {
      version: "concurrent-1",
      name: "Concurrent 1 Updated",
    },
  });
  const concurrent2: Promise<IAITrainingData> = api.functional.advancedAI.aiTrainingData.putById(connection, {
    id: created.id,
    body: {
      version: "concurrent-2",
      name: "Concurrent 2 Updated",
    },
  });
  const results = await Promise.all([concurrent1, concurrent2]);
  typia.assert(results[0]);
  typia.assert(results[1]);
  // At least one update applies. Cannot guarantee which last, but both succeed.
  TestValidator.equals("concurrent names/versions")(
    ["Concurrent 1 Updated", "Concurrent 2 Updated"].includes(results[0].name) &&
      ["Concurrent 1 Updated", "Concurrent 2 Updated"].includes(results[1].name)
  )(true);
}

