import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IAIFeatureStore } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIFeatureStore";
import { IPageIAIFeatureStore } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAIFeatureStore";

/**
 * Test listing and searching AI feature store records using various filter, pagination, and sorting options.
 *
 * This test validates advanced list/search APIs in the AI feature store, focusing on filtering, pagination, and sorting.
 * Various searches (including for known records, non-existent, with partial/fuzzy terms, and pagination edge cases) are performed
 * to ensure only matching features are returned, pagination works as expected, and empty or error states are handled correctly.
 *
 * 1. List all feature store records without filters (basic listing, ensure data is returned)
 * 2. List with pagination (limit=2), check pagination data and results length
 * 3. Search for records by an existing name (exact match)
 * 4. Search for records by model version (ai_model_version_id)
 * 5. Search with both model version and name (AND filter)
 * 6. Use partial/fuzzy matching (e.g., partial name)
 * 7. Apply sorting (by name asc and created_at desc)
 * 8. Submit a query with non-existent filter values (should return empty array)
 * 9. Query a page number beyond the last page (should return empty array)
 */
export async function test_api_ai_feature_store_search_with_filter_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. List all records (no filters)
  const all: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: {},
  });
  typia.assert(all);
  TestValidator.equals("list: has at least one record")(true)(all.data.length > 0);

  // 2. Paginated fetch (limit = 2)
  const paged: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination: limit applies")(paged.data.length <= 2)(true);
  TestValidator.equals("pagination: correct page/limit")(1)(paged.pagination.current);
  TestValidator.equals("pagination: correct limit")(2)(paged.pagination.limit);

  // Use a record from the first page for filter-based searches
  const sample = all.data[0];

  // 3. Search by name (exact match)
  const byName: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { name: sample.name },
  });
  typia.assert(byName);
  TestValidator.equals("search by name: result not empty")(true)(byName.data.length > 0);
  TestValidator.equals("search by name: exact match")(sample.name)(byName.data[0].name);

  // 4. Search by model version
  const byVersion: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { ai_model_version_id: sample.ai_model_version_id },
  });
  typia.assert(byVersion);
  TestValidator.equals("search by version: has results")(true)(byVersion.data.length > 0);
  byVersion.data.forEach(row => TestValidator.equals("ai_model_version_id matches")(sample.ai_model_version_id)(row.ai_model_version_id));

  // 5. Search by (version AND name)
  const byBoth: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { ai_model_version_id: sample.ai_model_version_id, name: sample.name },
  });
  typia.assert(byBoth);
  byBoth.data.forEach(row => {
    TestValidator.equals("both: version matches")(sample.ai_model_version_id)(row.ai_model_version_id);
    TestValidator.equals("both: name matches")(sample.name)(row.name);
  });

  // 6. Partial/fuzzy name search (using prefix or partial string if possible)
  const partialTerm = sample.name.slice(0, Math.max(1, Math.floor(sample.name.length / 2)));
  const byPartial: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { name: partialTerm },
  });
  typia.assert(byPartial);
  TestValidator.equals("partial search: not empty")(true)(byPartial.data.length > 0);
  TestValidator.equals("partial search: contains matches")(true)(byPartial.data.some(f => f.name.includes(partialTerm)));

  // 7. Sorting by name ASC and created_at DESC
  const sortedByName: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { sort_by: "name", order: "asc" },
  });
  typia.assert(sortedByName);
  for (let i = 1; i < sortedByName.data.length; ++i) {
    TestValidator.equals("sorted by name ASC")(
      sortedByName.data[i - 1].name <= sortedByName.data[i].name
    )(true);
  }
  const sortedByCreatedAt: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { sort_by: "created_at", order: "desc" },
  });
  typia.assert(sortedByCreatedAt);
  for (let i = 1; i < sortedByCreatedAt.data.length; ++i) {
    TestValidator.equals("sorted by created_at DESC")(
      sortedByCreatedAt.data[i - 1].created_at >= sortedByCreatedAt.data[i].created_at
    )(true);
  }

  // 8. Non-existent filter values (should return empty array)
  const nonExistent: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { name: "__non_existent_feature_name__" },
  });
  typia.assert(nonExistent);
  TestValidator.equals("empty on non-existent filter")(0)(nonExistent.data.length);

  // 9. Query page number beyond last page
  const lastPage = Math.max(1, all.pagination.pages);
  const outOfBounds: IPageIAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.patch(connection, {
    body: { page: lastPage + 10, limit: 5 },
  });
  typia.assert(outOfBounds);
  TestValidator.equals("returns empty for out-of-bounds page")(0)(outOfBounds.data.length);
}

