 * 3. Retrieve and validate the updated data
 * 4. Attempt to update using a non-existent (random) ID and expect a not found error
 * 5. Try to update immutable fields (e.g., created_at, id) and validate that changes are either rejected or ignored
 */
export async function test_api_advancedAI_aiFeatureStore_update(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new feature store record
  const createData: IAIFeatureStore.ICreate = {
    ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
    name: "initial-featureset-name",
    description: "Initial creation description.",
    schema: JSON.stringify({ features: ["a", "b", "c"] }),
  };
  const featureStore: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.post(connection, { body: createData });
  typia.assert(featureStore);
  TestValidator.equals("featureStore.name")(createData.name)(featureStore.name);
  TestValidator.equals("featureStore.schema")(createData.schema)(featureStore.schema);

  // 2. Update the feature store's name and schema (valid update)
  const updateData: IAIFeatureStore.IUpdate = {
    name: "updated-featureset-name",
    schema: JSON.stringify({ features: ["x", "y", "z"] }),
    description: "Updated description for feature set.",
  };
  const updatedFeatureStore: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.putById(connection, {
    id: featureStore.id,
    body: updateData,
  });
  typia.assert(updatedFeatureStore);
  TestValidator.equals("updatedFeatureStore.id")(featureStore.id)(updatedFeatureStore.id);
  TestValidator.equals("updatedFeatureStore.name")(updateData.name)(updatedFeatureStore.name);
  TestValidator.equals("updatedFeatureStore.schema")(updateData.schema)(updatedFeatureStore.schema);
  TestValidator.equals("updatedFeatureStore.description")(updateData.description)(updatedFeatureStore.description);
  // created_at and ai_model_version_id should remain unchanged
  TestValidator.equals("updatedFeatureStore.ai_model_version_id")(featureStore.ai_model_version_id)(updatedFeatureStore.ai_model_version_id);
  TestValidator.equals("updatedFeatureStore.created_at")(featureStore.created_at)(updatedFeatureStore.created_at);

