    api.functional.advancedAI.aiFeatureStore.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateData,
    }),
  );

  // 4. Try to update immutable fields (id, created_at)
  // These fields are not accepted in the IUpdate type, but attempt to fake mutation (should be ignored if forced)
  const invalidUpdate: any = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString(),
    name: "should-not-apply",
  };
  const resultAfterInvalidAttempt: IAIFeatureStore = await api.functional.advancedAI.aiFeatureStore.putById(connection, {
    id: featureStore.id,
    body: invalidUpdate,
  });
  typia.assert(resultAfterInvalidAttempt);
  // Should not have changed id or created_at, name should not update either, or only name applies
  TestValidator.equals("id unchanged")(featureStore.id)(resultAfterInvalidAttempt.id);
  TestValidator.equals("created_at unchanged")(featureStore.created_at)(resultAfterInvalidAttempt.created_at);
}

