import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";
import { IPageIAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAIDecisionLog";

/**
 * 테스트: AI 의사결정 로그 필터, 페이지네이션, 정렬 기능의 검증
 *
 * 이 시나리오는 다양한 필터, 페이지네이션, 정렬 옵션을 통해 AI 의사결정 로그를 조회하고,
 * 결과가 지정된 조건과 일치하는지 확인합니다. 또한, 조건에 맞는 로그가 없는 경우 정상적으로 빈 결과가
 * 반환되는지, 페이지네이션 동작이 올바른지(예: 범위를 벗어난 페이지)까지 검증합니다.
 *
 * 1. 여러 개의 AI 의사결정 로그 더미 데이터 생성(사전 구축 필요)
 * 2. 특정 model_version, target_entity, decision 등으로 필터링하여 조회
 * 3. 결과 로그들의 각 필드가 지정한 조건과 정확히 일치하는지 검사
 * 4. rationale 등 텍스트 필드 부분 검색 - 일부 단어 포함시 결과 필터링 확인
 * 5. 없는 조건(존재하지 않는 ID 등)으로 조회시 빈 결과를 반환하는지 확인
 * 6. 페이지네이션: 1페이지, 중간, 마지막, 범위 초과 페이지 번호 모두 조회하여 결과 및 meta 정보
 *    (pagination) 검증
 * 7. 정렬(order_by + order) 옵션별(오름차순/내림차순) 정렬 정확성 확인
 */
export async function test_api_ai_decision_log_list_search_with_filters_pagination(
  connection: api.IConnection,
): Promise<void> {
  // [전제] 사전 fixture 또는 seed 시나리오에서 충분한 ai_decision_log 데이터가 구축되어 있다고 가정

  // 1. 기본 전체 목록 조회(기본 정렬, 첫 페이지)
  const allResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
    body: { page: 1, limit: 5 } satisfies IAIDecisionLog.IRequest,
  });
  typia.assert(allResult);
  TestValidator.equals("current page")(1)(allResult.pagination.current);
  TestValidator.equals("page limit")(5)(allResult.pagination.limit);
  // 실제 데이터가 5개 미만일 수도 있으므로 data의 총 개수 <= limit
  TestValidator.equals("data.length should be <= pagination.limit")(
    true
  )(allResult.data.length <= allResult.pagination.limit);

  if(allResult.data.length > 0) {
    const target = allResult.data[0];
    // 2. 특정 모델 버전 ID, entity로 조회
    const filteredResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: {
        ai_model_version_id: target.ai_model_version_id,
        target_entity: target.target_entity,
        page: 1,
        limit: 10,
      } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(filteredResult);
    // 결과 각각이 필터와 일치하는지 확인
    filteredResult.data.forEach((item) => {
      TestValidator.equals("ai_model_version_id match")(target.ai_model_version_id)(item.ai_model_version_id);
      TestValidator.equals("target_entity match")(target.target_entity)(item.target_entity);
    });

    // 3. 일부 rationale 텍스트 검색(부분 일치)
    if(target.rationale) {
      const keyword = target.rationale.slice(0, 2); // 일부 단어 추출
      const rationaleResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
        body: { rationale: keyword, limit: 10 } satisfies IAIDecisionLog.IRequest,
      });
      typia.assert(rationaleResult);
      rationaleResult.data.forEach((item) => {
        if (item.rationale)
          TestValidator.equals("rationale includes keyword")(
            true
          )(item.rationale.includes(keyword));
      });
    }

    // 4. decision 값 테스트
    const decisionVal = target.decision;
    const decisionResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { decision: decisionVal } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(decisionResult);
    decisionResult.data.forEach((item) => {
      TestValidator.equals("decision value match")(decisionVal)(item.decision);
    });

    // 5. created_at__gte, __lte 조합(날짜 범위 조건)
    const createdAt = target.created_at;
    const gteResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { created_at__gte: createdAt } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(gteResult);
    gteResult.data.forEach((item) => {
      TestValidator.equals("created_at >= gte")(
        true
      )(item.created_at >= createdAt);
    });
    const lteResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { created_at__lte: createdAt } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(lteResult);
    lteResult.data.forEach((item) => {
      TestValidator.equals("created_at <= lte")(
        true
      )(item.created_at <= createdAt);
    });

    // 6. 없는 값(존재하지 않는 ai_model_version_id)으로 필터
    const emptyResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: {
        ai_model_version_id: "00000000-0000-0000-0000-000000000000",
        page: 1,
        limit: 10,
      } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(emptyResult);
    TestValidator.equals("empty result on invalid id")(0)(emptyResult.data.length);

    // 7. 페이지네이션 여러 페이지 - 마지막 페이지, 범위 초과 페이지
    const nextPageNum = allResult.pagination.pages;
    const lastPageResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { page: nextPageNum, limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(lastPageResult);
    TestValidator.equals("last page num")(nextPageNum)(lastPageResult.pagination.current);
    // 존재하는 페이지 바로 다음(범위 초과)
    const outOfRangePageResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { page: nextPageNum + 1, limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(outOfRangePageResult);
    TestValidator.equals("out of range returns 0 data")(0)(outOfRangePageResult.data.length);

    // 8. 정렬: created_at asc/desc
    const ascResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { order_by: "created_at", order: "asc", limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(ascResult);
    for(let i=1;i<ascResult.data.length;++i) {
      TestValidator.equals("ascending order")(
        true
      )(ascResult.data[i-1].created_at <= ascResult.data[i].created_at);
    }
    const descResult: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { order_by: "created_at", order: "desc", limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(descResult);
    for(let i=1;i<descResult.data.length;++i) {
      TestValidator.equals("descending order")(
        true
      )(descResult.data[i-1].created_at >= descResult.data[i].created_at);
    }

    // 9. 정렬: decision asc/desc
    const decisionAsc: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { order_by: "decision", order: "asc", limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(decisionAsc);
    for(let i=1;i<decisionAsc.data.length;++i) {
      TestValidator.equals("decision asc")(
        true
      )(decisionAsc.data[i-1].decision <= decisionAsc.data[i].decision);
    }
    const decisionDesc: IPageIAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.patch(connection, {
      body: { order_by: "decision", order: "desc", limit: 5 } satisfies IAIDecisionLog.IRequest,
    });
    typia.assert(decisionDesc);
    for(let i=1;i<decisionDesc.data.length;++i) {
      TestValidator.equals("decision desc")(
        true
      )(decisionDesc.data[i-1].decision >= decisionDesc.data[i].decision);
    }
  }
}

