/**
 * Test fetching a single AI decision log by ID (valid and invalid cases).
 *
 * 1. Create a new AI decision log using POST /advancedAI/aiDecisionLogs. This returns a valid ID.
 * 2. Fetch the created decision log record by its valid ID using GET /advancedAI/aiDecisionLogs/{id}.
 *    - Validate all fields returned for schema completeness and type correctness.
 *    - Check key attributes: id, ai_model_version_id, target_user_id, target_entity, target_entity_id, decision, input_snapshot, rationale, created_at.
 * 3. Attempt to fetch a decision log using an obviously invalid/non-existent UUID.
 *    - Validate HTTP 404 (Not Found) error is returned.
 *
 * This test confirms correct behavior for both positive (existing log) and negative (nonexistent log) cases.
 */
export async function test_api_ai_decision_log_get_by_id_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new AI decision log
  const created: IAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.post(connection, {
    body: {
      ai_model_version_id: typia.random<string & tags.Format<"uuid">>(),
      target_user_id: typia.random<string & tags.Format<"uuid">>(),
      target_entity: "order",
      target_entity_id: typia.random<string & tags.Format<"uuid">>(),
      decision: "approve",
      input_snapshot: JSON.stringify({ example: "input" }),
      rationale: "Auto-approved by model for test.",
    } satisfies IAIDecisionLog.ICreate,
  });
  typia.assert(created);

  // 2. Fetch by valid ID
  const fetched: IAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.getById(connection, {
    id: created.id,
  });
