  TestValidator.equals("ai_model_version_id")(created.ai_model_version_id)(fetched.ai_model_version_id);
  TestValidator.equals("target_entity")(created.target_entity)(fetched.target_entity);
  TestValidator.equals("target_entity_id")(created.target_entity_id)(fetched.target_entity_id);
  TestValidator.equals("decision")(created.decision)(fetched.decision);
  TestValidator.equals("input_snapshot")(created.input_snapshot)(fetched.input_snapshot);
  TestValidator.equals("rationale")(created.rationale)(fetched.rationale);
  TestValidator.equals("created_at")(created.created_at)(fetched.created_at);

  // 3. Attempt to fetch with an invalid/non-existent ID
  await TestValidator.httpError("getById - non-existent id")(404)(() =>
    api.functional.advancedAI.aiDecisionLogs.getById(connection, {
      id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa" as string & tags.Format<"uuid">,
    })
  );
}

