import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAIDecisionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIDecisionLog";
import typia from "typia";

/**
 * Validate AI decision log update functionality and enforcement of field immutability.
 *
 * This test covers the following:
 * 1. Creation of a valid AI decision log (prep work for update).
 * 2. Update the rationale field (the only editable field) on the decision log.
 * 3. Fetch and verify the update was correctly saved (rationale changed, all other fields remain unchanged).
 * 4. Attempt to update a non-existing decision log (should result in not found / error response).
 * 5. Attempt to update immutable fields (should result in error / immutable fields not changing).
 *
 * Steps:
 * 1. Create a decision log.
 * 2. Update rationale via putById (should succeed).
 * 3. Fetch the updated log and check rationale has changed, other fields are the same.
 * 4. Attempt putById with a randomly generated invalid ID (expect error/404).
 * 5. Attempt to update both rationale and an immutable top-level field (e.g., decision, should be ignored or error); verify only rationale can be updated and evidence is preserved.
 */
export async function test_api_ai_decision_log_update_and_validation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a decision log
  const createBody: IAIDecisionLog.ICreate = {
    ai_model_version_id: typia.random<string>(),
    target_user_id: typia.random<string>(),
    target_entity: "order",
    target_entity_id: typia.random<string>(),
    decision: "approve",
    input_snapshot: "{\"foo\":\"bar\"}",
    rationale: "Initial AI rationale for testing.",
  };
  const log: IAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.post(connection, { body: createBody });
  typia.assert(log);

  // 2. Update rationale (editable field)
  const updatedRationale = "Updated rationale for compliance.";
  const updateResult: IAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.putById(connection, {
    id: log.id,
    body: { rationale: updatedRationale } satisfies IAIDecisionLog.IUpdate,
  });
  typia.assert(updateResult);

  // 3. Re-fetch the decision log and verify rationale is updated, other fields are not changed
  // (Assume fetch by ID endpoint is GET /advancedAI/aiDecisionLogs/:id)
  const fetched: IAIDecisionLog = await api.functional.advancedAI.aiDecisionLogs.getById(connection, { id: log.id });
  typia.assert(fetched);
  TestValidator.equals("Rationale updated")(updatedRationale)(fetched.rationale ?? "");
  // Check other top-level fields are unchanged
  TestValidator.equals("Fields unchanged")(log.ai_model_version_id ?? "")(fetched.ai_model_version_id ?? "");
  TestValidator.equals("Fields unchanged")(log.decision ?? "")(fetched.decision ?? "");
  TestValidator.equals("Fields unchanged")(log.input_snapshot ?? "")(fetched.input_snapshot ?? "");
  TestValidator.equals("Fields unchanged")(log.target_entity ?? "")(fetched.target_entity ?? "");
  TestValidator.equals("Fields unchanged")(log.target_entity_id ?? "")(fetched.target_entity_id ?? "");

  // 4. Attempt update with invalid (random) id
  await TestValidator.httpError("Not found")(404)(() =>
    api.functional.advancedAI.aiDecisionLogs.putById(connection, {
      id: typia.random<string>(),
      body: { rationale: "Should fail" },
    }),
  );

  // 5. Attempt to update immutable field (should either not change value, or return error)
  await TestValidator.error("Immutable field update rejected")(() =>
    api.functional.advancedAI.aiDecisionLogs.putById(connection, {
      id: log.id,
      // @ts-expect-error: testing mutation of non-editable field
      body: { decision: "reject", rationale: "Malicious mutation" },
    }),
  );
}

