 * 2. If records exist, pick a sample and search by user_id, decision_log_id, feedback_type.
 *    Confirm filter returns only proper matches.
 * 3. Search with a combination of filters (e.g., specific user_id + feedback_type). Validate results.
 * 4. Test pagination: request a small limit per page, walk through multiple pages; check that all returned records are unique and belong to total count.
 * 5. Test ascending sort order and validate order correctness.
 * 6. Test edge case: search with impossible filter (random UUID) and confirm that 0 results are returned.
 * 7. Optionally: If feasible, test response and paging with a very large number of records for performance/stability.
 */
export async function test_api_ai_feedback_search_list_pagination_sort(
  connection: api.IConnection,
): Promise<void> {
  // 1. Fetch all records, descending sort (default)
  const allResult: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { sort_order: "desc", page: 1, limit: 5 } satisfies IAiFeedback.IRequest,
  });
  typia.assert(allResult);
  TestValidator.equals("pagination.limit")(5)(allResult.pagination.limit);
  // Validate descending order by created_at
  const sortedDesc = [...allResult.data].sort((a, b) => b.created_at.localeCompare(a.created_at));
  TestValidator.equals("descending order")(sortedDesc.map(r => r.id))(allResult.data.map(r => r.id));

  if (allResult.data.length > 0) {
    const sample = allResult.data[0];

    // 2. Filter by user_id
    const byUserId: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
      body: { user_id: sample.user_id, limit: 100 } satisfies IAiFeedback.IRequest,
    });
    typia.assert(byUserId);
    if (sample.user_id) {
      for (const row of byUserId.data) {
        if (row.user_id != null) TestValidator.equals("user_id")(sample.user_id)(row.user_id);
      }
    }

    // 2. Filter by decision_log_id
    const byDecLog: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
      body: { decision_log_id: sample.decision_log_id } satisfies IAiFeedback.IRequest,
    });
    typia.assert(byDecLog);
    for (const row of byDecLog.data) {
      TestValidator.equals("decision_log_id")(sample.decision_log_id)(row.decision_log_id);
    }

    // 2. Filter by feedback_type
    const byType: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
      body: { feedback_type: sample.feedback_type } satisfies IAiFeedback.IRequest,
    });
    typia.assert(byType);
    for (const row of byType.data) {
      TestValidator.equals("feedback_type")(sample.feedback_type)(row.feedback_type);
    }

    // 3. Combination filter (user_id + feedback_type)
    if (sample.user_id) {
      const combo: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
        body: { user_id: sample.user_id, feedback_type: sample.feedback_type } satisfies IAiFeedback.IRequest,
      });
      typia.assert(combo);
      for (const row of combo.data) {
        if (row.user_id != null) TestValidator.equals("user_id")(sample.user_id)(row.user_id);
        TestValidator.equals("feedback_type")(sample.feedback_type)(row.feedback_type);
      }
    }
  }

  // 4. Pagination check: limit small, walk multiple pages
  const limit = 2;
  let pagedResult: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { page: 1, limit } });
  typia.assert(pagedResult);
  if (pagedResult.data.length > 0 && pagedResult.pagination.pages > 1) {
    let seen = new Set<string>();
    for (let page = 1; page <= Math.min(3, pagedResult.pagination.pages); ++page) {
      pagedResult = await api.functional.advancedAI.aiFeedback.patch(connection, { body: { page, limit } });
      typia.assert(pagedResult);
      for (const row of pagedResult.data) {
        TestValidator.equals("IAiFeedback")(true)(!!row.id);
        TestValidator.equals("unique record")(false)(seen.has(row.id));
        seen.add(row.id);
      }
    }
  }

  // 5. Ascending sort order check
  const ascResult: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { sort_order: "asc", limit: 5 } satisfies IAiFeedback.IRequest,
  });
  typia.assert(ascResult);
  const sortedAsc = [...ascResult.data].sort((a, b) => a.created_at.localeCompare(b.created_at));
  TestValidator.equals("ascending order")(sortedAsc.map(r => r.id))(ascResult.data.map(r => r.id));

  // 6. Edge case: impossible filter
  const empty: IPageIAiFeedback = await api.functional.advancedAI.aiFeedback.patch(connection, {
    body: { user_id: "ffffffff-ffff-ffff-ffff-ffffffffffff", feedback_type: "does-not-exist" } satisfies IAiFeedback.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("no result")(0)(empty.data.length);
}

