import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAiFeedback } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiFeedback";
import typia from "typia";

/**
 * 테스트 목적: AI 피드백 레코드의 생성 및 검증, 그리고 입력 검증/중복/불완전 입력에 대한 오류 처리를 검증한다.
 *
 * 시나리오 개요:
 * 1. 필수 메타데이터를 모두 포함하여 새로운 AI 피드백 레코드를 생성한다.
 * 2. 생성된 피드백 레코드가 정상적으로 저장되고, 반환 결과를 통해 올바르게 조회(반환)됨을 확인한다.
 * 3. 잘못된 데이터, 누락된 필수 필드, 또는 중복되는 데이터를 입력하여 적절한 검증 오류와 피드백이 반환되는지 확인한다.
 */
export async function test_api_ai_feedback_create_validate(
  connection: api.IConnection,
): Promise<void> {
  // 1. 올바른 피드백 레코드 생성
  const validPayload: IAiFeedback.ICreate = {
    decision_log_id: typia.random<string & typia.tags.Format<"uuid">>(),
    user_id: typia.random<string & typia.tags.Format<"uuid">>(),
    feedback_type: "accepted",
    feedback_value: "positive",
    metadata: JSON.stringify({ device: "web", rationale: "helpful suggestion" }),
  };
  const output: IAiFeedback = await api.functional.advancedAI.aiFeedback.post(
    connection,
    { body: validPayload },
  );
  typia.assert(output);
  TestValidator.equals("decision_log_id")(validPayload.decision_log_id)(output.decision_log_id);
  TestValidator.equals("feedback_type")(validPayload.feedback_type)(output.feedback_type);
  TestValidator.equals("feedback_value")(validPayload.feedback_value)(output.feedback_value);
  TestValidator.equals("metadata")(validPayload.metadata)(output.metadata);

  // 2. 일부 필수 필드 누락 (예: feedback_type 없음)
  await TestValidator.httpError("missing required field feedback_type")(400)(() =>
    api.functional.advancedAI.aiFeedback.post(connection, {
      body: {
        ...validPayload,
        feedback_type: undefined as any, // 일부러 누락 함
      } as any,
    })
  );

  // 3. 잘못된 UUID 입력
  await TestValidator.httpError("invalid uuid in decision_log_id")(400)(() =>
    api.functional.advancedAI.aiFeedback.post(connection, {
      body: {
        ...validPayload,
        decision_log_id: "not-a-uuid" as any,
      },
    })
  );

  // 4. 중복 데이터(동일 decision_log_id, user_id, feedback_type 3요소 조합이 고유하다 가정)
  // 실제 비즈니스 정책에 따라 중복 기준이 다를 수 있음. 여기서는 같은 데이터로 한 번 더 요청
  await TestValidator.httpError("duplicate ai feedback")(409)(() =>
    api.functional.advancedAI.aiFeedback.post(connection, {
      body: validPayload,
    })
  );
}

