 *
 * This test covers the full lifecycle and update policy for AI feedback records, ensuring that
 * all modifiable fields (feedback_type, feedback_value, metadata) can be amended as permitted,
 * and invalid operations are properly rejected. Feedback records serve as regulatory evidence,
 * so all updates must comply with audit and evidence chain requirements as described in the DTO.
 *
 * 1. Create an initial AI feedback record with required fields.
 * 2. Perform a valid update on all mutable fields. Confirm updated values in the returned response.
 * 3. Attempt to update using an invalid/nonexistent feedback ID. Verify error response.
 * 4. Attempt to update a record with an invalid payload (e.g., feedback_type missing/type error).
 *    Expect a validation error and no change to data.
 * 5. (If applicable by business) Attempt to update a locked/immutable feedback record (simulate or stub)
 *    and verify refusal.
 */
export async function test_api_ai_feedback_update_valid_and_invalid_cases(
  connection: api.IConnection,
): Promise<void> {
