  const createInput: IAiFeedback.ICreate = {
    decision_log_id: typia.random<string & tags.Format<"uuid">>(),
    user_id: typia.random<string & tags.Format<"uuid">>(),
    feedback_type: "accepted",
    feedback_value: "positive",
    metadata: JSON.stringify({ source: "unit-test", device: "web" }),
