    api.functional.advancedAI.aiFeedback.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // assume not existing
      body: updateInput,
    })
  );

  // 4. Invalid payload (missing feedback_type) should fail validation
  const badUpdate: IAiFeedback.IUpdate = {
    // feedback_type: intentionally omitted
    feedback_value: "invalid_case",
    metadata: null,
  };
  await TestValidator.error("invalid update payload validation error")(() =>
    api.functional.advancedAI.aiFeedback.putById(connection, {
      id: feedback.id,
      body: badUpdate,
    })
  );

  // 5. (Simulated) Update on a locked/immutable feedback record (If business rules supported)
  // Skipped: If no lock/immutable flag or deletion logic exposed by API, this test is a noop or placeholder.
}

