test/features/api/security-event/test_li:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";
import { IPageISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISecurityEvent";

/**
 * Validate paginated and filtered search of security event logs.
 *
 * This test covers the search, filter, and paging capabilities of the security event query endpoint.
 * It ensures that filters (by event type, user, session, time range, and status) work correctly, pagination is honored, and
 * error handling is robust when invalid queries or edge cases are encountered.
 *
 * 1. Query unfiltered event logs and validate overall pagination.
 * 2. Query with event_type filter and check presence of only matching event types.
 * 3. Query with user_id filter (assume known user_id exists in system).
 * 4. Query with date range (from_time, to_time) and assert returned events are within range.
 * 5. Query with combination of filters (event_type + user_id + time window).
 * 6. Test pagination: request a high page number and confirm it returns empty data (edge/past last page).
 * 7. Test invalid filter input (invalid UUID, negative page, nonsense event_type), expecting error or empty result.
 */
export async function test_api_security_event_log_filtered_and_paginated_search(
  connection: api.IConnection,
): Promise<void> {
  // 1. Query without filters to get a baseline and extract some event data to use as filter basis
  const base: IPageISecurityEvent = await api.functional.securityCompliance.securityEvent.patch(connection, {
    body: {}, // No filters
  });
  typia.assert(base);
  TestValidator.equals("pagination matches array length")(base.pagination.limit)(base.data.length <= base.pagination.limit ? base.data.length : base.pagination.limit);

  // Skip if there are no security events in the DB for convenience
  if (base.data.length === 0) return;

  const firstEvent = base.data[0];

  // 2. Filter by event_type
  if (firstEvent.event_type) {
    const byType = await api.functional.securityCompliance.securityEvent.patch(connection, {
      body: { event_type: firstEvent.event_type },
    });
    typia.assert(byType);
    for (const ev of byType.data)
      TestValidator.equals("event_type matches filter")(firstEvent.event_type)(ev.event_type);
  }

  // 3. Filter by user_id
  if (firstEvent.user_id) {
    const byUser = await api.functional.securityCompliance.securityEvent.patch(connection, {
      body: { user_id: firstEvent.user_id },
    });
    typia.assert(byUser);
    for (const ev of byUser.data) {
      if (ev.user_id != null)
        TestValidator.equals("user_id matches filter")(firstEvent.user_id!)(ev.user_id!);
    }
  }

  // 4. Filter by time range
  const firstTimestamp = new Date(firstEvent.created_at);
  const nextDay = new Date(firstTimestamp.getTime() + 24 * 60 * 60 * 1000);

  const byDate = await api.functional.securityCompliance.securityEvent.patch(connection, {
    body: {
      from_time: firstEvent.created_at,
      to_time: nextDay.toISOString(),
    },
  });
  typia.assert(byDate);
  for (const ev of byDate.data) {
    const t = new Date(ev.created_at);
    TestValidator.equals("created_at in range")(
      true,
    )(
      t >= firstTimestamp && t <= nextDay,
    );
  }

  // 5. Combination filter
  const comboFilter: ISecurityEvent.IRequest = {
    event_type: firstEvent.event_type,
    user_id: firstEvent.user_id,
    from_time: firstEvent.created_at,
    to_time: nextDay.toISOString(),
    status: undefined, // assuming status field present when meaningful
  };
  const byCombo = await api.functional.securityCompliance.securityEvent.patch(connection, {
    body: comboFilter,
  });
  typia.assert(byCombo);
  for (const ev of byCombo.data) {
    if (comboFilter.event_type)
      TestValidator.equals("event_type matches combo")(comboFilter.event_type)(ev.event_type);
    if (comboFilter.user_id && ev.user_id != null && ev.user_id !== undefined)
      TestValidator.equals("user_id matches combo")(comboFilter.user_id!)(ev.user_id!);
    const t = new Date(ev.created_at);
    TestValidator.equals("created_at in combo range")(true)(t >= firstTimestamp && t <= nextDay);
  }

  // 6. Pagination edge case: request a page past last page
  const lastPage = base.pagination.pages + 10;
  const pageEdge = await api.functional.securityCompliance.securityEvent.patch(connection, {
    body: { page: lastPage },
  });
  typia.assert(pageEdge);
  TestValidator.equals("empty results for high page")([] as ISecurityEvent[])(pageEdge.data);

  // 7. Invalid filter: event_type nonsense
  const nonsense = await api.functional.securityCompliance.securityEvent.patch(connection, {
    body: { event_type: "___nonsense_event_type___" },
  });
  typia.assert(nonsense);
  TestValidator.equals("no result for nonsense filter")([] as ISecurityEvent[])(nonsense.data);

  // 8. Invalid UUID, negative page: should result in error or empty safely
  await TestValidator.error("invalid UUID for user_id")(() =>
    api.functional.securityCompliance.securityEvent.patch(connection, {
      body: { user_id: "not-a-uuid" as any },
    })
  );
  await TestValidator.error("negative page error")(() =>
    api.functional.securityCompliance.securityEvent.patch(connection, {
      body: { page: -1 as any },
    })
  );
}

