 * 3. Check for the presence of all evidence-related fields (id, event_details, created_at, etc.).
 * 4. Attempt to retrieve a security event using an invalid (random) ID and expect a not found (404) error response.
 */
export async function test_api_security_event_get_by_id_valid_and_invalid(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new security event
  const created: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(
    connection,
    {
      body: {
        event_type: "login_attempt",
        event_details: JSON.stringify({ attempt: 1, status: "success" }),
        user_id: null,
        session_id: null,
        api_client_id: null,
      } satisfies ISecurityEvent.ICreate,
    },
  );
  typia.assert(created);

  // 2. Retrieve the event by its valid ID
