import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";
import typia from "typia";

/**
 * 테스트: 보안 이벤트 로그 생성과 검증
 * 
 * 1. 필수 필드를 모두 포함한 보안 이벤트 생성 요청으로 실제 보안 이벤트를 생성한다.
 * 2. 이벤트가 잘 생성되었는지 응답 객체 구조와 타입을 검증한다.
 * 3. (구현 환경에 검색 API 있다면) 해당 이벤트를 검색하거나 조회하여 정상적으로 저장이 되었는지 확인한다.
 * 4. 일부 필수 필드(event_type, event_details 등)가 누락된 상태로 생성 요청 시, 유효성 검사 오류가 발생하는지 검증한다.
 * 5. event_type에 비문자열 혹은 event_details에 비문자열/너무 짧은 등 잘못된 데이터로 요청 시, 올바른 에러 처리(400 BadRequest 등)를 확인한다.
 * 6. 동일 event_details, event_type 등으로 중복 값 생성 시 중복 허용/제한 여부 및 정책을 검증한다.
 *
 * 해당 테스트는 이벤트 로그 증적·컴플라이언스 기능 신뢰성 보장을 위함이다.
 */
export async function test_api_security_event_create_validate(
  connection: api.IConnection,
): Promise<void> {
  // 1. 모든 필수 필드로 보안 이벤트 생성
  const now = new Date();
  const createBody: ISecurityEvent.ICreate = {
    event_type: "login_attempt",
    event_details: JSON.stringify({ result: "success", ip: "127.0.0.1" }),
    user_id: typia.random<string>(), // 실제 환경에서는 존재하는 UUID 필요
    session_id: typia.random<string>(),
    api_client_id: typia.random<string>(),
    created_at: now.toISOString(),
  };
  const event: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(
    connection,
    {
      body: createBody,
    }
  );
  typia.assert(event);
  TestValidator.equals("event_type 일치")(createBody.event_type)(event.event_type);
  TestValidator.equals("event_details 일치")(createBody.event_details)(event.event_details);

  // 2. 필수 필드 누락 시 에러 검증(event_type 없음)
  const bodyMissingType = { ...createBody };
  // @ts-expect-error 의도적 타입 오류 테스트
  delete bodyMissingType.event_type;
  await TestValidator.httpError("event_type missing")(400)(() =>
    api.functional.securityCompliance.securityEvent.post(connection, {
      // @ts-ignore: purposely removing required field
      body: bodyMissingType,
    })
  );

  // 3. 필수 필드 누락 시 에러 검증(event_details 없음)
  const bodyMissingDetails = { ...createBody };
  delete (bodyMissingDetails as any).event_details;
  await TestValidator.httpError("event_details missing")(400)(() =>
    api.functional.securityCompliance.securityEvent.post(connection, {
      // @ts-ignore
      body: bodyMissingDetails,
    })
  );

  // 4. 타입 불일치/비정상 값 처리(event_type이 숫자 등)
  const bodyWrongType = {
    ...createBody,
    event_type: 123,
  };
  await TestValidator.httpError("event_type 타입 오류")(400)(() =>
    api.functional.securityCompliance.securityEvent.post(connection, {
      // @ts-ignore
      body: bodyWrongType,
    })
  );

  // 5. 중복 케이스 (event_details, event_type 동일하게 두 번 생성)
  // 정책에 따라 에러 or 성공 (여기서는 정상 허용 가정)
  const event2: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(
    connection,
    { body: createBody }
  );
  typia.assert(event2);
  TestValidator.equals("중복 이벤트 생성 허용")(createBody.event_details)(event2.event_details);
}

