import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { ISecurityEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityEvent";

/**
 * Test updating a security event record by valid ID (modifying updatable metadata fields only).
 *
 * Scenario:
 * 1. Create a new security event through the POST endpoint to use as a test target.
 * 2. Update the event via PUT by ID, altering only the mutable metadata field (event_details).
 * 3. Confirm that the update succeeds and only the 'event_details' field is changed, while immutable fields (id, created_at, event_type, etc.) remain untouched.
 * 4. Attempt to update an immutable field via the update API (should result in error; the API only allows event_details to be updated).
 * 5. Attempt to update a non-existent event (invalid ID); verify not found or error response.
 */
export async function test_api_security_event_update_valid_and_invalid_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new security event to obtain a valid ID
  const createPayload: ISecurityEvent.ICreate = {
    event_type: "login_attempt",
    event_details: "Initial login attempt",
    user_id: null,
    session_id: null,
    api_client_id: null,
    // Typically created_at generated server-side, but can optionally provide
  };
  const created: ISecurityEvent = await api.functional.securityCompliance.securityEvent.post(connection, {
    body: createPayload,
  });
  typia.assert(created);

  // 2. Update only the mutable field (event_details)
  const updatePayload: ISecurityEvent.IUpdate = {
    event_details: "Evidence amended after review.",
  };
  const updated: ISecurityEvent = await api.functional.securityCompliance.securityEvent.putById(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);
  // Verify event_details changed, other fields retained
  TestValidator.equals("id")(created.id)(updated.id);
  TestValidator.equals("event_type")(created.event_type)(updated.event_type);
  TestValidator.equals("created_at")(created.created_at)(updated.created_at);
  TestValidator.equals("event_details should be updated")(
    false,
  )(created.event_details === updated.event_details);

  // 3. Attempt to update an immutable field (e.g. event_type) -- This should be rejected by the API, but since
  // the SDK only allows event_details in the update type, simulate forbidden logic by direct/invalid usage pattern.
  await TestValidator.error("attempt to update immutable event_type should fail")(
    async () => {
      await api.functional.securityCompliance.securityEvent.putById(connection, {
        id: created.id,
        body: {
          // @ts-ignore
          event_type: "privilege_escalation",
          event_details: "Tamper attempt",
        },
      });
    },
  );

  // 4. Attempt to update with a non-existent event ID
  await TestValidator.error("invalid event id should result in error")(
    async () => {
      await api.functional.securityCompliance.securityEvent.putById(connection, {
        id: "00000000-0000-4000-8000-000000000000" as string & tags.Format<"uuid">,
        body: {
          event_details: "Attempt for non-existent id",
        },
      });
    },
  );
}

