test/features/api/permission/test_list_a:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPermission";
import { IPageIPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPermission";
import typia from "typia";

/**
 * 테스트: 권한 레코드의 검색 및 리스트업 (필터, 정렬, 페이지네이션 조합)
 *
 * 이 테스트는 다양한 필터, 정렬, 페이지네이션 조합을 사용해 /securityCompliance/permission 엔드포인트를 테스트합니다.
 * - code, description, policy_id, 생성일 기반으로 권한이 정상적으로 필터링되는지 검증합니다.
 * - 페이징 동작 및 정렬(asc/desc)에 따른 반환값이 올바른지도 확인합니다.
 * - 매칭되는 레코드가 없는 경우, 빈 결과가 반환되는 에지 케이스도 검증합니다.
 * - 유효하지 않은 쿼리(잘못된 타입, 잘못된 범위 등)를 보낼 경우 적절한 에러가 반환되는지도 검증합니다.
 *
 * [테스트 단계]
 * 1. 임의/존재하는 code, description, policy_id 값을 바탕으로 정상/부분일치/불일치 검색 요청
 * 2. created_from, created_to를 조합해 날짜 기준 필터 동작 확인
 * 3. sort_field/sort_direction에 따라 결과 순서 오름/내림차 순 체크
 * 4. page, limit으로 페이징 정상 동작 확인 (데이터 수, 전체 pages 체크)
 * 5. 실존하지 않는 값으로 검색해 빈 배열 반환 검증
 * 6. 잘못된 타입, 비정상 조합 등 유효하지 않은 쿼리를 보내고 에러 응답 검증
 */
export async function test_api_permission_list_and_filter_permissions_with_search_and_pagination(connection: api.IConnection): Promise<void> {
  // 1. code exact/partial match (assuming at least one permission exists)
  const initial: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { limit: 10 } satisfies IPermission.IRequest,
  });
  typia.assert(initial);
  const { data } = initial;
  if (!data.length) throw new Error("테스트를 위한 권한 레코드가 없습니다.");
  const sample = data[0];

  // exact code match
  const byCode: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { code: sample.code } satisfies IPermission.IRequest,
  });
  typia.assert(byCode);
  TestValidator.equals("code exact match")(true)(byCode.data.every((x) => x.code === sample.code));

  // partial code match
  if (sample.code.length >= 3) {
    const part = sample.code.slice(0, 3);
    const byPartial: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
      body: { code: part } satisfies IPermission.IRequest,
    });
    typia.assert(byPartial);
    TestValidator.equals("code partial match")(true)(byPartial.data.every((x) => x.code.includes(part)));
  }

  // 2. description filter
  if (sample.description.length >= 3) {
    const partDesc = sample.description.slice(0, 3);
    const byDesc: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
      body: { description: partDesc } satisfies IPermission.IRequest,
    });
    typia.assert(byDesc);
    TestValidator.equals("description partial match")(true)(byDesc.data.every((x) => x.description.includes(partDesc)));
  }

  // 3. policy_id exact filter (when exists)
  if (sample.policy_id != null) {
    const byPolicy: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
      body: { policy_id: sample.policy_id } satisfies IPermission.IRequest,
    });
    typia.assert(byPolicy);
    TestValidator.equals("policy_id exact match")(true)(byPolicy.data.every(x => x.policy_id === sample.policy_id));
  }

  // 4. created_from, created_to range
  const byDate: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: {
      created_from: sample.created_at,
      created_to: new Date(new Date(sample.created_at).getTime() + 1000).toISOString(),
    } satisfies IPermission.IRequest,
  });
  typia.assert(byDate);
  TestValidator.equals("date range filter")(true)(byDate.data.every(x => x.created_at >= sample.created_at));

  // 5. sort_field/sort_direction order check
  const asc: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { sort_field: "created_at", sort_direction: "asc", limit: 3 } satisfies IPermission.IRequest,
  });
  typia.assert(asc);
  const desc: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { sort_field: "created_at", sort_direction: "desc", limit: 3 } satisfies IPermission.IRequest,
  });
  typia.assert(desc);
  const ascTimes = asc.data.map(x => x.created_at);
  const descTimes = desc.data.map(x => x.created_at);
  TestValidator.equals("sort asc/desc order")(
    JSON.stringify(ascTimes.slice().reverse())
  )(
    JSON.stringify(descTimes)
  );

  // 6. pagination (multi page fetch)
  const paged1: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { page: 1, limit: 1 } satisfies IPermission.IRequest,
  });
  typia.assert(paged1);
  if (paged1.pagination.pages > 1) {
    const paged2: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
      body: { page: 2, limit: 1 } satisfies IPermission.IRequest,
    });
    typia.assert(paged2);
    await TestValidator.predicate("pagination should not return duplicate")(
      () => paged1.data[0].id !== paged2.data[0]?.id
    );
  }

  // 7. no match (nonexistent code)
  const none: IPageIPermission = await api.functional.securityCompliance.permission.patch(connection, {
    body: { code: "never.matching.code.@@@@@" } satisfies IPermission.IRequest,
  });
  typia.assert(none);
  TestValidator.equals("no match should return empty array")(0)(none.data.length);

  // 8. invalid query: negative page, invalid sort direction
  await TestValidator.httpError("invalid negative page")(400)(() =>
    api.functional.securityCompliance.permission.patch(connection, {
      body: { page: -1 } as any,
    })
  );
  await TestValidator.httpError("invalid sort_direction")(400)(() =>
    api.functional.securityCompliance.permission.patch(connection, {
      body: { sort_direction: "zzz" as any },
    })
  );
}

