 *
 * Background:
 * The permission entity supports compliance, RBAC, and audit features. It is required that permission codes are unique and every permission has a description. All successful creations must return a normalized permission with a valid UUID and timestamps.
 *
 * Steps:
 * 1. Create a permission with unique, valid data and validate its properties and that it is returned in a successful creation response.
 * 2. Attempt to create a permission with missing 'code' (required field); expect validation error.
 * 3. Attempt to create a permission with missing 'description' (required field); expect validation error.
 * 4. Attempt to create a permission with a duplicate code and expect a uniqueness/duplicate error.
 */
export async function test_api_permission_create_success_and_failure_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create permission with valid, unique data
