import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { ICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/ICatalogEvidence";
import { IPageICatalogEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICatalogEvidence";

/**
 * Validate pagination, filtering, and error handling for catalog evidence listing.
 *
 * This scenario ensures the API correctly delivers evidence records in paginated form, supports filtering by timestamps and description, and respects edge-cases with empty/resultless input or invalid filter combinations.
 *
 * 1. Create multiple catalog evidence records (with varying created_at, reference_uri, and description values)
 * 2. Retrieve first N records (page 1, limit N) – Validate count and ordering
 * 3. Retrieve subsequent page (page 2, limit N) – Validate no records are repeated from first page
 * 4. Filter by specific description substring, validate matching results
 * 5. Filter by created_at window (from–to), ensure correct subset returned
 * 6. Filter by non-existent fields (out-of-bounds reference_uri, wrong date), expect empty result
 * 7. Stress with invalid filters or out-of-range pages, expect empty or error response per business logic
 */
export async function test_api_product_catalog_list_catalog_evidence_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create sample evidence records (diversity in description & created_at)
  const now = new Date();
  const records: ICatalogEvidence[] = [];
  for (let i = 0; i < 6; ++i) {
    const createdDate = new Date(now.getTime() - i * 24 * 60 * 60 * 1000).toISOString();
    const evidence: ICatalogEvidence = await api.functional.productCatalog.catalogEvidence.post(connection, {
      body: {
        reference_uri: `urn:test:catalog-evidence:${Date.now()}-${i}`,
        description: `Evidence record ${i} testing pagination` + (i % 2 === 0 ? " special" : " general"),
        catalog_event_id: null,
      } satisfies ICatalogEvidence.ICreate,
    });
    typia.assert(evidence);
    // Simulate evidence created_at window (patch not allowed, so rely on generated time ordering)
    records.push(evidence);
  }
  // Sort for deterministic order (API may order by created_at DESC)
  records.sort((a, b) => b.created_at.localeCompare(a.created_at));

  // 2. Retrieve first 3 records (page 1, limit 3)
  const page1: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      page: 1,
      limit: 3,
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("page 1 items count")(3)(page1.data?.length ?? 0);
  TestValidator.equals("pagination meta present")(1)(page1.pagination?.current ?? 1);
  // Each record in returned data must be among inserted
  for (const item of page1.data ?? []) {
    TestValidator.equals("record exists in created sample")(
      true,
    )(!!records.find(r => r.id === item.id));
  }

  // 3. Retrieve second page (page 2, limit 3), ensure non-overlap
  const page2: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      page: 2,
      limit: 3,
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("page 2 items count")(3)(page2.data?.length ?? 0);
  for (const item of page2.data ?? []) {
    // No item of page2 should duplicate page1 ids
    TestValidator.equals("records are not repeated between pages")(
      false,
    )((page1.data ?? []).some(x => x.id === item.id));
  }

  // 4. Filter by substring in description ("special")
  const filteredSpecial: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      description: "special",
      limit: 10,
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(filteredSpecial);
  for (const item of filteredSpecial.data ?? []) {
    TestValidator.equals("filter on 'special' present in description")(
      true,
    )(item.description.includes("special"));
  }

  // 5. Filter by created_at window (middle two records)
  const from = records[2].created_at;
  const to = records[3].created_at;
  const filteredByDate: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(filteredByDate);
  // Each must be in correct date window
  for (const item of filteredByDate.data ?? []) {
    TestValidator.equals("created_at after from")(
      true
    )(item.created_at >= from);
    TestValidator.equals("created_at before to")(
      true
    )(item.created_at <= to);
  }

  // 6. Filter by non-existent reference_uri, expect empty
  const nonExistentRef: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      reference_uri: "urn:non-existent:catalog-evidence",
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(nonExistentRef);
  TestValidator.equals("empty data for non-existent reference_uri")(
    0
  )(nonExistentRef.data?.length ?? 0);

  // 7. Stress out-of-range page
  const stressPage: IPageICatalogEvidence = await api.functional.productCatalog.catalogEvidence.patch(connection, {
    body: {
      page: 999,
      limit: 10,
    } satisfies ICatalogEvidence.IRequest,
  });
  typia.assert(stressPage);
  TestValidator.equals("empty data for out-of-range page")(0)(stressPage.data?.length ?? 0);
}

