import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import { IPageICart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICart";
import typia from "typia";

/**
 * Validate cart list pagination and filtering.
 *
 * This e2e test ensures that the cart listing endpoint supports full pagination and filtering as expected. Scenarios include multiple cart creation (across different users), paginated retrieval (fetching first page, subsequent pages), filtering by user, and handling requests out of result bounds (returns empty results).
 *
 * Steps:
 * 1. Create sample carts for multiple users.
 * 2. Fetch carts unfiltered (all records, page 1, small limit).
 * 3. Fetch next page (page 2) and validate correct pagination.
 * 4. Filter carts by one specific user (should receive only that user’s carts).
 * 5. Filter using non-existent user (should return empty results).
 * 6. Request page number beyond available data (should return empty page).
 */
export async function test_api_cart_list_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create sample carts for multiple users
  const userA = typia.random<string & typia.tags.Format<"uuid">>();
  const userB = typia.random<string & typia.tags.Format<"uuid">>();

  // Create 3 carts for userA
  const cartsA: ICart[] = [];
  for (let i = 0; i < 3; ++i) {
    const cart = await api.functional.cartOrder.cart.post(connection, {
      body: {
        user_id: userA,
        session_id: null,
      } satisfies ICart.ICreate,
    });
    typia.assert(cart);
    cartsA.push(cart);
  }

  // Create 2 carts for userB
  const cartsB: ICart[] = [];
  for (let i = 0; i < 2; ++i) {
    const cart = await api.functional.cartOrder.cart.post(connection, {
      body: {
        user_id: userB,
        session_id: null,
      } satisfies ICart.ICreate,
    });
    typia.assert(cart);
    cartsB.push(cart);
  }

  // Step 2: Fetch all carts, page 1, limit 3
  let res: IPageICart = await api.functional.cartOrder.cart.patch(connection, {
    body: { page: 1, limit: 3 },
  });
  typia.assert(res);
  TestValidator.equals("pagination.limit")(3)(res.pagination?.limit ?? 0);
  TestValidator.equals("pagination.current")(1)(res.pagination?.current ?? 0);
  TestValidator.equals("first page count")(3)(res.data?.length ?? 0);
  // The total count should match cartsA+cartsB in this test context
  TestValidator.equals("total records")(5)(res.pagination?.records ?? 0);

  // Step 3: Fetch second page (should have 2 carts left)
  res = await api.functional.cartOrder.cart.patch(connection, {
    body: { page: 2, limit: 3 },
  });
  typia.assert(res);
  TestValidator.equals("pagination.current")(2)(res.pagination?.current ?? 0);
  TestValidator.equals("second page count")(2)(res.data?.length ?? 0);

  // Step 4: Filter carts by userA
  res = await api.functional.cartOrder.cart.patch(connection, {
    body: { user_id: userA },
  });
  typia.assert(res);
  TestValidator.equals("userA carts")(3)(res.data?.filter(c => c.user_id === userA).length ?? 0);
  // All returned carts should match userA
  for (const cart of res.data ?? []) {
    TestValidator.equals("cart user match")(userA)(cart.user_id);
  }

  // Step 5: Filter carts by non-existent user
  const fakeUser = typia.random<string & typia.tags.Format<"uuid">>();
  res = await api.functional.cartOrder.cart.patch(connection, {
    body: { user_id: fakeUser },
  });
  typia.assert(res);
  TestValidator.equals("non-existent user empty")(0)(res.data?.length ?? 0);

  // Step 6: Fetch with page number out of range
  res = await api.functional.cartOrder.cart.patch(connection, {
    body: { page: 10, limit: 5 },
  });
  typia.assert(res);
  TestValidator.equals("out-of-range page")(0)(res.data?.length ?? 0);
}

