 * 3. Verify the changes persist via returned payload.
 * 4. Attempt update with an empty body, expect error (400 or 409).
 * 5. Attempt update of a non-existent cart ID, expect error (404).
 * 6. Soft-delete the cart.
 * 7. Attempt update on the deleted cart, expect error (404 or 409).
 * 8. [Optional] Attempt update with data that violates business rules (e.g., updated_at in the past), expect error if implemented.
 */
export async function test_api_cartOrder_cart_update_and_error_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new cart
  const createBody: ICart.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    session_id: null,
  };
  const cart: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: createBody,
  });
  typia.assert(cart);

  // 2. Update the cart's session_id and updated_at fields
  const newSessionId = typia.random<string & tags.Format<"uuid">>();
  const newUpdatedAt = new Date(Date.now() + 60000).toISOString();
  const updateBody: ICart.IUpdate = {
    session_id: newSessionId,
    updated_at: newUpdatedAt,
  };
  const updated: ICart = await api.functional.cartOrder.cart.putById(connection, {
    id: cart.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("id should be unchanged")(cart.id)(updated.id);
  TestValidator.equals("session_id should be updated")(newSessionId)(updated.session_id!);
  TestValidator.equals("updated_at should be updated")(newUpdatedAt)(updated.updated_at);

  // 3. Try updating with empty object (should fail, expecting error)
  await TestValidator.httpError("empty update body should fail")(400)(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: {},
    }),
