  // 4. Try updating with a random (non-existent) cart ID (should 404)
  await TestValidator.httpError("update non-existent cart should 404")(404)(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    }),
  );

  // 5. Soft-delete the cart
  const delResult: ICart.IDeleteResult = await api.functional.cartOrder.cart.eraseById(connection, { id: cart.id });
  typia.assert(delResult);
  TestValidator.equals("deleted id")(cart.id)(delResult.id);

  // 6. Update deleted cart (should fail - typically 404 or 409)
  await TestValidator.error("update deleted cart should fail")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: updateBody,
    }),
  );

  // 7. (Optional) Attempt update with a clearly invalid updated_at (i.e., in the past)
  const invalidUpdate: ICart.IUpdate = { updated_at: "2000-01-01T00:00:00.000Z" };
  await TestValidator.error("update with past updated_at should fail if rule enforced")(() =>
    api.functional.cartOrder.cart.putById(connection, {
      id: cart.id,
      body: invalidUpdate,
    }),
  );
}

