import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { ICart } from "@ORGANIZATION/PROJECT-api/lib/structures/ICart";
import { ICartOrderCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderCartItem";
import { IPageICartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICartItem";
import { ICartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartItem";

/**
 * Validate listing and searching cart items with pagination and filtering.
 *
 * This test ensures:
 * - Listing items by cart, user, or product filters returns correct records.
 * - Pagination fields (page, limit) function as intended.
 * - Out-of-range and invalid parameters result in empty sets or errors as designed.
 *
 * Step-by-step process:
 * 1. Create two distinct cart records (different user_ids).
 * 2. Add two unique cart items to the first cart (distinct product_variant_id, various quantities).
 * 3. Add one cart item to the second cart (unique product_variant_id).
 * 4. List all cart items (no filters): verify pagination and data correctness.
 * 5. Filter by cart_id and verify only items for that cart are returned.
 * 6. Filter by product_variant_id and verify correct item is returned.
 * 7. Filter by nonexistent cart_id: expect empty result.
 * 8. Use out-of-range pagination (e.g., page=10): expect empty or last page.
 * 9. Pass invalid parameter types: verify error or empty response as per API contract.
 */
export async function test_api_cart_item_list_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create carts for two different users
  const user1 = typia.random<string & typia.tags.Format<"uuid">>();
  const user2 = typia.random<string & typia.tags.Format<"uuid">>();
  const cart1: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: { user_id: user1 } satisfies ICart.ICreate,
  });
  typia.assert(cart1);
  const cart2: ICart = await api.functional.cartOrder.cart.post(connection, {
    body: { user_id: user2 } satisfies ICart.ICreate,
  });
  typia.assert(cart2);

  // 2 & 3. Add cart items to carts
  const pv1 = typia.random<string & typia.tags.Format<"uuid">>();
  const pv2 = typia.random<string & typia.tags.Format<"uuid">>();
  const pv3 = typia.random<string & typia.tags.Format<"uuid">>();
  const item1: ICartOrderCartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: { cart_id: cart1.id, product_variant_id: pv1, quantity: 2 } satisfies ICartOrderCartItem.ICreate,
  });
  typia.assert(item1);
  const item2: ICartOrderCartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: { cart_id: cart1.id, product_variant_id: pv2, quantity: 1 } satisfies ICartOrderCartItem.ICreate,
  });
  typia.assert(item2);
  const item3: ICartOrderCartItem = await api.functional.cartOrder.cartItem.post(connection, {
    body: { cart_id: cart2.id, product_variant_id: pv3, quantity: 1 } satisfies ICartOrderCartItem.ICreate,
  });
  typia.assert(item3);

  // 4. List all cart items (no filters)
  const allItems: IPageICartItem = await api.functional.cartOrder.cartItem.patch(connection, {
    body: {} satisfies ICartItem.IRequest,
  });
  typia.assert(allItems);
  TestValidator.equals("should contain at least our added items")(
    true
  )(
    allItems.data.some((x) => x.id === item1.id && x.cart_id === cart1.id)
  );
  TestValidator.equals("should have consistent structure")(
    true
  )(Array.isArray(allItems.data));

  // 5. Filter by cart_id
  const filteredByCart: IPageICartItem = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { cart_id: cart1.id } satisfies ICartItem.IRequest,
  });
  typia.assert(filteredByCart);
  TestValidator.equals("cart filter count")(2)(filteredByCart.data.length);
  TestValidator.equals("cart filter ids")(
    [item1.id, item2.id].sort()
  )(
    filteredByCart.data.map((x) => x.id).sort()
  );

  // 6. Filter by product_variant_id
  const byProdVariant: IPageICartItem = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { product_variant_id: pv2 } satisfies ICartItem.IRequest,
  });
  typia.assert(byProdVariant);
  TestValidator.equals("product_variant_id filter one")(
    1
  )(byProdVariant.data.length);
  TestValidator.equals("product_variant_id value")(
    pv2
  )(byProdVariant.data[0].product_variant_id);

  // 7. Filter by nonexistent cart_id
  const nonexist: IPageICartItem = await api.functional.cartOrder.cartItem.patch(connection, {
    body: {
      cart_id: typia.random<string & typia.tags.Format<"uuid">>(),
    } satisfies ICartItem.IRequest,
  });
  typia.assert(nonexist);
  TestValidator.equals("empty for nonexistent cart")(0)(nonexist.data.length);

  // 8. Out-of-range pagination (page=10)
  const paged: IPageICartItem = await api.functional.cartOrder.cartItem.patch(connection, {
    body: { page: 10, limit: 2 } satisfies ICartItem.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("page over-bound")(paged.data.length)(paged.pagination.current === 10 ? 0 : paged.data.length);

  // 9. Invalid parameter types (e.g., negative page)
  await TestValidator.error("invalid params - negative page")(() =>
    api.functional.cartOrder.cartItem.patch(connection, {
      body: { page: -1 } as any,
    }),
  );
}

