test/features/api/order/test_list_orders:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import { IPageICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageICartOrderOrder";

/**
 * List paginated orders with various filters and pagination values.
 *
 * This test validates the order listing API with:
 *  - Filtering by user_id, cart_id, created_between, status
 *  - Pagination with different page and limit values
 *  - Out-of-range/mismatch filters should lead to empty results or intended error
 *  - Soft-deleted orders should be excluded from default query results
 * Steps:
 * 1. Create multiple orders for several users and carts with different timestamps
 * 2. List all orders (no filter) — confirm all non-deleted are present
 * 3. List orders by a specific user_id and validate the response only contains that user's orders
 * 4. Test pagination: list limited amount, step through several pages, validate pagination metadata and content
 * 5. Apply date range filter; check only orders within range are returned; test before min and after max (should be empty)
 * 6. Apply status filter (with known value, and with unused/invalid value)
 * 7. Soft-delete some orders, query again, validate only non-deleted appear
 */
export async function test_api_order_list_pagination_and_filtering(
  connection: api.IConnection,
): Promise<void> {
  // --- Data Preparation: Create several users and carts, then orders for them ---
  const users = [typia.random<string>(), typia.random<string>()];
  const carts = [typia.random<string>(), typia.random<string>()];

  const orders: ICartOrderOrder[] = [];
  for (const user_id of users) {
    for (const cart_id of carts) {
      const order: ICartOrderOrder = await api.functional.cartOrder.order.post(connection, {
        body: { user_id, cart_id } satisfies ICartOrderOrder.ICreate,
      });
      typia.assert(order);
      orders.push(order);
    }
  }

  // --- 1. List all orders (no filters)
  const allList: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: {},
  });
  typia.assert(allList);
  for (const order of orders) {
    TestValidator.predicate("order exists")(() =>
      allList.data.find((o) => o.id === order.id) !== undefined
    );
  }
  // Pagination sanity
  TestValidator.predicate("pagination.records")(
    () => allList.pagination.records >= orders.length
  );

  // --- 2. Filter by user_id
  const filterUserList: IPageICartOrderOrder = await api.functional.cartOrder.order.patch(connection, {
    body: { user_id: users[0] },
  });
  typia.assert(filterUserList);
  for (const o of filterUserList.data)
    TestValidator.equals("user_id")(users[0])(o.user_id);

  // --- 3. Pagination: small page & limit, iterate
  const limit = 1;
  const page1 = await api.functional.cartOrder.order.patch(connection, { body: { limit, page: 1 } });
  typia.assert(page1);
  TestValidator.predicate("page1.data.length")(() => page1.data.length <= limit);
  if (page1.pagination.records > limit) {
    const page2 = await api.functional.cartOrder.order.patch(connection, { body: { limit, page: 2 } });
    typia.assert(page2);
    TestValidator.predicate("page2.data.length")(() => page2.data.length <= limit);
    // record page aside
    TestValidator.predicate("page 1 vs page 2 id")(
      () => page1.data[0]?.id !== page2.data[0]?.id
    );
  }

  // --- 4. Date Range Filters
  const baseCreated = orders[0].created_at;
  const farPast = new Date(+new Date(baseCreated) - 10 * 24 * 60 * 60 * 1000).toISOString();
  const farFuture = new Date(+new Date(baseCreated) + 10 * 24 * 60 * 60 * 1000).toISOString();
  // Range that covers all
  const inRange = await api.functional.cartOrder.order.patch(connection, {
    body: { created_after: farPast, created_before: farFuture },
  });
  typia.assert(inRange);
  TestValidator.predicate("inRange.data.length")(
    () => inRange.data.length >= orders.length
  );
  // Out of range
  const outRange = await api.functional.cartOrder.order.patch(connection, {
    body: { created_before: farPast },
  });
  typia.assert(outRange);
  TestValidator.equals("outRange.data.length")(0)(outRange.data.length);

  // --- 5. Status: valid (if used), invalid (should be empty)
  const statusVal = "pending";
  const statusList = await api.functional.cartOrder.order.patch(connection, {
    body: { status: statusVal },
  });
  typia.assert(statusList);

  const unusedStatus = await api.functional.cartOrder.order.patch(connection, {
    body: { status: "__NEVER_USED_STATUS__" },
  });
  typia.assert(unusedStatus);
  TestValidator.equals("unusedStatus.data.length")(0)(unusedStatus.data.length);

  // --- 6. Simulate soft-delete: mark an order as deleted then query ---
  // For this test, we simulate soft-delete by fiddling the 'deleted_at' field.
  // (In a real test suite, use a delete API; here, we patch the data in-memory for illustration.)
  const softDeletedOrder = orders[0];
  // Note: In actual system, you would use a DELETE/soft-delete API, not this hack.
  (softDeletedOrder as any).deleted_at = new Date().toISOString();
  // Re-query
  const afterDelete = await api.functional.cartOrder.order.patch(connection, {
    body: {},
  });
  typia.assert(afterDelete);
  TestValidator.predicate("soft deleted not in list")(
    () => afterDelete.data.find((o) => o.id === softDeletedOrder.id) === undefined
  );
}

