import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import { ICartOrderOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrderItem";
import { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * E2E test: Fetch details of a specific order item by ID, completeness check, and error cases after deletion.
 *
 * This test validates that order item details are correctly fetched by ID, and that deleted/non-existent item requests are properly handled with errors.
 *
 * Steps:
 * 1. Create a new order record.
 * 2. Add a new order item to the created order.
 * 3. Fetch the order item by its ID and validate all fields and data completeness.
 * 4. Delete the order item by its ID.
 * 5. Attempt to fetch the deleted order item - expect error/404.
 * 6. Attempt to fetch an order item with a non-existent/random UUID - expect error/404.
 */
export async function test_api_cartOrder_orderItem_getById_and_deleted_case(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new order record.
  const orderCreate: ICartOrderOrder.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    cart_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const order: ICartOrderOrder = await api.functional.cartOrder.order.post(connection, {
    body: orderCreate satisfies ICartOrderOrder.ICreate,
  });
  typia.assert(order);

  // 2. Add a new order item to the created order.
  const itemCreate: ICartOrderOrderItem.ICreate = {
    order_id: order.id,
    product_variant_id: typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
  };
  const item: ICartOrderOrderItem = await api.functional.cartOrder.orderItem.post(connection, {
    body: itemCreate satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item);

  // 3. Fetch the order item by its ID and validate fields.
  const fetched: ICartOrderOrderItem = await api.functional.cartOrder.orderItem.getById(connection, {
    id: item.id,
  });
  typia.assert(fetched);
  TestValidator.equals("order_item.id")(item.id)(fetched.id);
  TestValidator.equals("order_item.order_id")(item.order_id)(fetched.order_id);
  TestValidator.equals("order_item.product_variant_id")(item.product_variant_id)(fetched.product_variant_id);
  TestValidator.equals("order_item.quantity")(item.quantity)(fetched.quantity);

  // 4. Delete (soft delete) the order item by its ID.
  const eraseResp: IVoidResponse = await api.functional.cartOrder.orderItem.eraseById(connection, {
    id: item.id,
  });
  typia.assert(eraseResp);
  TestValidator.equals("delete ok")(true)(eraseResp.ok);

  // 5. Attempt to fetch the deleted order item - expect 404 error.
  await TestValidator.httpError("deleted order_item fetch should 404")(404)(() =>
    api.functional.cartOrder.orderItem.getById(connection, { id: item.id }),
  );

  // 6. Attempt to fetch a non-existent order item - expect 404 error.
  await TestValidator.httpError("non-existent order_item fetch should 404")(404)(() =>
    api.functional.cartOrder.orderItem.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

