import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { ICartOrderOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrder";
import { ICartOrderOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/ICartOrderOrderItem";
import { IOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderItem";
import { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * Validate updating an order item, error handling, and business rule enforcement.
 *
 * This test ensures:
 * 1. Updating a valid order item persists changes.
 * 2. Invalid updates (bad quantity) are rejected.
 * 3. Updates to nonexistent/deleted items are rejected.
 * 4. Business rules (e.g. unauthorized relationships) are enforced.
 *
 * Process:
 * 1. Create a new order (with valid cart/user).
 * 2. Add an order item to the order.
 * 3. Update the order item with valid quantity, verify change persists.
 * 4. Attempt to update with invalid data, expect error.
 * 5. Attempt to update a non-existent order item, expect error.
 * 6. Delete the order item.
 * 7. Attempt to update deleted order item, expect error.
 * 8. Attempt business rule violation (e.g. wrong order_id/product_variant_id), expect error.
 */
export async function test_api_order_item_update_scenario(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new order
  const order: ICartOrderOrder = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      cart_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ICartOrderOrder.ICreate,
  });
  typia.assert(order);

  // 2. Add an order item to the order
  const item: ICartOrderOrderItem = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: order.id,
      product_variant_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 2,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(item);

  // 3. Update the order item with valid change (increase quantity)
  const updated: IOrderItem = await api.functional.cartOrder.orderItem.putById(connection, {
    id: item.id,
    body: {
      quantity: 3,
    } satisfies IOrderItem.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("increased quantity")(3)(updated.quantity);

  // 4. Attempt invalid update (negative quantity)
  await TestValidator.httpError("invalid quantity")(400)(() =>
    api.functional.cartOrder.orderItem.putById(connection, {
      id: item.id,
      body: {
        quantity: -5,
      } satisfies IOrderItem.IUpdate,
    }),
  );

  // 5. Update non-existent order item
  await TestValidator.httpError("not found")(404)(() =>
    api.functional.cartOrder.orderItem.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        quantity: 2,
      } satisfies IOrderItem.IUpdate,
    }),
  );

  // 6. Delete the order item
  const voidResp: IVoidResponse = await api.functional.cartOrder.orderItem.eraseById(connection, {
    id: item.id,
  });
  typia.assert(voidResp);
  TestValidator.equals("delete ok")(true)(voidResp.ok);

  // 7. Attempt to update deleted order item
  await TestValidator.httpError("update deleted order item")(404)(() =>
    api.functional.cartOrder.orderItem.putById(connection, {
      id: item.id,
      body: {
        quantity: 4,
      } satisfies IOrderItem.IUpdate,
    }),
  );

  // 8. Attempt business rule violation (wrong order_id). Try to update another valid order_item to a quantity, but swap its order_id (which shouldn't be allowed if API doesn't permit changing these fields)
  const anotherOrder: ICartOrderOrder = await api.functional.cartOrder.order.post(connection, {
    body: {
      user_id: typia.random<string & tags.Format<"uuid">>(),
      cart_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies ICartOrderOrder.ICreate,
  });
  typia.assert(anotherOrder);

  const anotherItem: ICartOrderOrderItem = await api.functional.cartOrder.orderItem.post(connection, {
    body: {
      order_id: anotherOrder.id,
      product_variant_id: typia.random<string & tags.Format<"uuid">>(),
      quantity: 1,
    } satisfies ICartOrderOrderItem.ICreate,
  });
  typia.assert(anotherItem);

  // Try to update referencing a different product_variant_id (simulate business rule violation, if applicable)
  await TestValidator.httpError("business rule violation")(400)(() =>
    api.functional.cartOrder.orderItem.putById(connection, {
      id: anotherItem.id,
      body: {
        quantity: 1,
        // product_variant_id or order_id cannot be set in update; so only quantity allowed; if API actually allowed patching forbidden fields, this would fail.
        // This scenario is for if the system mistakenly allows mutating forbidden fields—guard rails for API enforcement.
      } as any,
    }),
  );
}

