import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";
import { IPageIOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderStatus";
import typia from "typia";

function generate_uuid(): string {
    // Simple UUID generator for deterministic test
    return (
        "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
            const r = Math.random() * 16 | 0,
                v = c == "x" ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        })
    );
}

export async function test_api_cart_order_order_status_list_filter_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple order status events
  const testOrders: string[] = [generate_uuid(), generate_uuid()];
  const now = new Date();
  const early = new Date(now.getTime() - 1000 * 60 * 60);
  const statuses = ["pending", "paid", "shipped", "delivered"];

  // Insert events for both orders
  const createdEvents: IOrderStatus[] = [];
  for (const order_id of testOrders) {
    for (const status_code of statuses) {
      const changed_at = new Date(
        early.getTime() + Math.floor(Math.random() * (now.getTime() - early.getTime()))
      ).toISOString();
      const event = await api.functional.cartOrder.orderStatus.post(connection, {
        body: {
          order_id,
          status_code,
          changed_at,
          changed_by: null,
        } as IOrderStatus.ICreate,
      });
      typia.assert(event);
      createdEvents.push(event);
    }
  }

  // 2. Query by known order_id
  for (const order_id of testOrders) {
    const output: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
      body: {
        order_id,
      } as IOrderStatus.IRequest,
    });
    typia.assert(output);
    for (const record of output.data) {
      TestValidator.equals("filtered order_id")(order_id)(record.order_id);
    }
    TestValidator.equals("all records for order_id found")(statuses.length)(output.data.length);
  }

  // 3. Query by non-existent order_id
  const unknownOrderId = generate_uuid();
  const outputNone: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      order_id: unknownOrderId,
    } as IOrderStatus.IRequest,
  });
  typia.assert(outputNone);
  TestValidator.equals("empty when order_id not found")(0)(outputNone.data.length);

  // 4. Query by status_code
  const outputStatus: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      status_code: "paid",
    } as IOrderStatus.IRequest,
  });
  typia.assert(outputStatus);
  for (const record of outputStatus.data) {
    TestValidator.equals("status_code filter")("paid")(record.status_code);
  }

  // 5. Query by date range
  const minChangedAt = createdEvents
    .map(ev => new Date(ev.changed_at).getTime())
    .reduce((a, b) => Math.min(a, b));
  const maxChangedAt = createdEvents
    .map(ev => new Date(ev.changed_at).getTime())
    .reduce((a, b) => Math.max(a, b));
  const dateRange = [
    new Date(minChangedAt).toISOString(),
    new Date(maxChangedAt).toISOString(),
  ] as [string, string];
  const outputRange: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      changed_at_range: dateRange,
    } as IOrderStatus.IRequest,
  });
  typia.assert(outputRange);
  TestValidator.predicate("range has items")(() => outputRange.data.length > 0);
  for (const record of outputRange.data) {
    const ts = new Date(record.changed_at).getTime();
    TestValidator.equals("date in range")(true)(ts >= minChangedAt && ts <= maxChangedAt);
  }

  // 6. Pagination: request subset of results if pagination supported
  // (Assume all returned if pagination not yet implemented)
  const pagedOut: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {},
  });
  typia.assert(pagedOut);
  // 7. Query with invalid filter (status_code that does not exist)
  const invalidOut: IPageIOrderStatus = await api.functional.cartOrder.orderStatus.patch(connection, {
    body: {
      status_code: "definitely-not-present",
    } as IOrderStatus.IRequest,
  });
  typia.assert(invalidOut);
  TestValidator.equals("empty for missing status_code")(0)(invalidOut.data.length);
}

