/**
 * E2E test: Validate updating an order status (CartOrder.order_status) record, including audit/compliance edge cases.
 *
 * Scenario:
 * 1. Create an initial order_status record via POST (to ensure a record exists for updating)
 * 2. Update existing order_status: Modify permitted fields (status_code, changed_at, changed_by) and verify update is persisted
 * 3. Attempt to update a non-existent order_status by using a random UUID and confirm 404/not-found error is returned
 * 4. Attempt to update prohibited/read-only fields (e.g., provide an "id" or "order_id" in update body) and verify rejection/error handling
 *
 * This ensures strict audit compliance, immutability constraints and error paths are validated for order_status updating.
 */
export async function test_api_order_status_update_with_valid_and_invalid_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create initial order_status
  const created: IOrderStatus = await api.functional.cartOrder.orderStatus.post(connection, {
    body: {
      order_id: typia.random<string & tags.Format<"uuid">>(),
      status_code: "pending",
      changed_at: new Date().toISOString(),
      changed_by: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IOrderStatus.ICreate,
  });
  typia.assert(created);

  // 2. Update existing order_status: permitted fields (status_code, changed_at, changed_by)
  const updated: IOrderStatus = await api.functional.cartOrder.orderStatus.putById(connection, {
    id: created.id,
    body: {
      status_code: "paid",
      changed_at: new Date(Date.now() + 1000).toISOString(),
      changed_by: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IOrderStatus.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("id")(created.id)(updated.id);
  TestValidator.equals("order_id")(created.order_id)(updated.order_id);
  TestValidator.equals("status_code")("paid")(updated.status_code);
  // changed_at and changed_by may be audited; verify are present
  TestValidator.equals("changed_by")(true)(updated.changed_by != null);

  // 3. Attempt to update a non-existent order_status
  await TestValidator.httpError("order_status not found")(404)(() =>
    api.functional.cartOrder.orderStatus.putById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // random, unlikely to match
      body: {
        status_code: "shipped",
        changed_at: new Date().toISOString(),
      } satisfies IOrderStatus.IUpdate,
    }),
  );

  // 4. Attempt to update prohibited/read-only fields (simulate by including read-only fields in body)
  await TestValidator.error("should reject extra/prohibited fields")(() =>
    api.functional.cartOrder.orderStatus.putById(connection, {
      id: created.id,
      body: {
        status_code: "delivered",
        id: typia.random<string & tags.Format<"uuid">>(), // not allowed
        order_id: typia.random<string & tags.Format<"uuid">>(), // not allowed
      } as any,
    }),
  );
}

