import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IOrderStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderStatus";
import { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * E2E test for soft-deleting an order_status event.
 *
 * This test covers full compliance and audit needs as follows:
 * 1. Create a new order_status event for a parent order.
 * 2. Soft-delete the specific order_status event by ID.
 *    - Ensure response confirms success (IVoidResponse.ok === true).
 * 3. (If list endpoint available) Check that the deleted status is not present in active order_status list/API.
 * 4. Attempt to delete the same order_status again, confirm idempotency (ok: true) or appropriate error (e.g., 404/410).
 * 5. Attempt to delete a non-existent order_status by a random uuid, expect error or safe idempotent response.
 */
export async function test_api_order_status_soft_delete(connection: api.IConnection): Promise<void> {
  // 1. Create an order_status record
  const createInput: IOrderStatus.ICreate = {
    order_id: typia.random<string & tags.Format<"uuid">>(),
    status_code: "pending",
    changed_at: new Date().toISOString(),
    changed_by: typia.random<string & tags.Format<"uuid">>(),
  };
  const status: IOrderStatus = await api.functional.cartOrder.orderStatus.post(connection, {
    body: createInput,
  });
  typia.assert(status);

  // 2. Soft-delete it by ID
  const delResp: IVoidResponse = await api.functional.cartOrder.orderStatus.eraseById(connection, {
    id: status.id,
  });
  typia.assert(delResp);
  TestValidator.equals("delete success")(true)(delResp.ok);

  // 3. Attempt to delete again (should be idempotent or error)
  try {
    const secondResp: IVoidResponse = await api.functional.cartOrder.orderStatus.eraseById(connection, {
      id: status.id,
    });
    typia.assert(secondResp);
    // Accept both idempotent ok: true or backend-specific safe error codes
    TestValidator.equals("idempotent delete ok")(true)(secondResp.ok);
  } catch (error) {
    // Accept HTTP 404/410 as valid (already deleted)
    TestValidator.error("2nd delete should throw only if already gone")(() => { throw error; });
  }

  // 4. Delete a non-existent id
  const randomId = typia.random<string & tags.Format<"uuid">>();
  try {
    const nonExistResp: IVoidResponse = await api.functional.cartOrder.orderStatus.eraseById(connection, {
      id: randomId,
    });
    typia.assert(nonExistResp);
    // Again, idempotency or error acceptable
    TestValidator.equals("delete non-existent, maybe idempotent ok")(true)(nonExistResp.ok);
  } catch (error) {
    // Accept HTTP 404/410 etc for non-existent
    TestValidator.error("delete non-existent throws")(() => { throw error; });
  }
}

