import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderLog";
import { IPageIOrderLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderLog";
import typia from "typia";

/**
 * Test listing and searching CartOrder order_log records with advanced filter and pagination
 *
 * Scenario: Query the list of order_log records using various filters and pagination, ensuring that only matching records are returned and paging works as expected. Attempt to search with filters that yield no result and verify graceful handling of empty sets.
 *
 * 1. Create at least two order_log records with distinct event_type/order_id/actor_id
 * 2. Query order_log list with filter for first order_id: should return the corresponding record
 * 3. Query by event_type for second record: validate correct result
 * 4. Paginate with limit=1 and verify structure of results (pages, records, etc)
 * 5. Query with filter that does not match any logs: should return empty array
 */
export async function test_api_order_log_list_and_search_with_filter_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two distinct order_log records
  const order_id1 = typia.random<string & typia.tags.Format<"uuid">>();
  const order_id2 = typia.random<string & typia.tags.Format<"uuid">>();
  const actor_id = typia.random<string & typia.tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const log1: IOrderLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: {
      order_id: order_id1,
      event_type: "create",
      event_description: "Order created",
      event_time: now,
      actor_id,
    } satisfies IOrderLog.ICreate,
  });
  typia.assert(log1);
  const log2: IOrderLog = await api.functional.cartOrder.orderLog.post(connection, {
    body: {
      order_id: order_id2,
      event_type: "status_change",
      event_description: "Status updated",
      event_time: now,
      actor_id,
    } satisfies IOrderLog.ICreate,
  });
  typia.assert(log2);

  // 2. Query logs for first order_id
  const resultByOrder: IPageIOrderLog = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      order_id: order_id1,
    },
  });
  typia.assert(resultByOrder);
  TestValidator.equals("resultByOrder should contain only the log for order_id1")(
    [log1.id]
  )(resultByOrder.data.map(d => d.id));

  // 3. Query logs by event_type
  const resultByType: IPageIOrderLog = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      event_type: "status_change",
    },
  });
  typia.assert(resultByType);
  TestValidator.equals("resultByType should have only log2")(
    [log2.id]
  )(resultByType.data.map(d => d.id));

  // 4. Paginate with limit=1; should return at least one page if logs exist
  const paged: IPageIOrderLog = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(paged);
  TestValidator.equals("pagination.limit")(1)(paged.pagination.limit);
  TestValidator.equals("pagination.current")(1)(paged.pagination.current);
  // Should have at least one IOrderLog and correct type
  TestValidator.predicate("paged.data should be array")(Array.isArray(paged.data));
  paged.data.forEach((rec) => typia.assert(rec));

  // 5. Query by random actor_id to force empty result set
  const resultEmpty: IPageIOrderLog = await api.functional.cartOrder.orderLog.patch(connection, {
    body: {
      actor_id: typia.random<string & typia.tags.Format<"uuid">>(),
    },
  });
  typia.assert(resultEmpty);
  TestValidator.equals("Empty result")(0)(resultEmpty.data.length);
}

