export async function test_api_order_log_update_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an order_log record
  const created: IOrderLog = await api.functional.cartOrder.orderLog.post(
    connection,
    {
      body: {
        order_id: typia.random<string & tags.Format<"uuid">>(),
        event_type: "create",
        event_description: "Initial event for order audit log.",
        event_time: new Date().toISOString(),
        actor_id: null,
      } satisfies IOrderLog.ICreate,
    },
  );
  typia.assert(created);

  // 2. Update editable metadata fields
  const updatePayload: IOrderLog.IUpdate = {
    event_description: "Amended description for compliance.",
  };
  const updated: IOrderLog = await api.functional.cartOrder.orderLog.putById(
    connection,
    {
      id: created.id,
      body: updatePayload,
    },
  );
  typia.assert(updated);
  TestValidator.equals("id unchanged after update")(created.id)(updated.id);
  TestValidator.equals("order_id unchanged after update")(created.order_id)(updated.order_id);
  TestValidator.equals("event_description updated")(updatePayload.event_description)(updated.event_description);

