import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence";
import { IPageIOrderEvidence } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIOrderEvidence";
import typia from "typia";

/**
 * E2E test for searching and paginating order evidence records.
 *
 * This test validates the search and listing (with pagination and filters) of order_evidence records.
 *
 * Scenario:
 * 1. Create two order_evidence records with different evidence_type and order_id.
 * 2. List all order_evidence with pagination. Make sure records are returned and validate structure.
 * 3. Search only for entries matching a single order_id and verify only intended record is returned.
 * 4. Search only for entries matching a single evidence_type and verify only intended record is returned.
 * 5. Perform a search with filters that do not match any record and verify the empty result set (data array empty).
 */
export async function test_api_order_evidence_search_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two distinct order evidence records
  const now = new Date();
  const orderId1 = typia.random<string & typia.tags.Format<"uuid">>();
  const orderId2 = typia.random<string & typia.tags.Format<"uuid">>();
  const provider = typia.random<string & typia.tags.Format<"uuid">>();

  const evidence1: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: {
      order_id: orderId1,
      evidence_type: "invoice",
      evidence_uri: `https://files.example.com/${orderId1}/invoice.pdf`,
      provided_at: now.toISOString(),
      provided_by: provider,
    } satisfies IOrderEvidence.ICreate,
  });
  typia.assert(evidence1);

  const evidence2: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, {
    body: {
      order_id: orderId2,
      evidence_type: "photo",
      evidence_uri: `https://files.example.com/${orderId2}/photo.jpg`,
      provided_at: now.toISOString(),
      provided_by: provider,
    } satisfies IOrderEvidence.ICreate,
  });
  typia.assert(evidence2);

  // 2. List ALL order_evidence, check both come back (page 1, large limit)
  const allResult: IPageIOrderEvidence = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      page: 1,
      limit: 10,
    },
  });
  typia.assert(allResult);
  TestValidator.equals("should include created evidence1")(true)(
    allResult.data.some(x => x.id === evidence1.id)
  );
  TestValidator.equals("should include created evidence2")(true)(
    allResult.data.some(x => x.id === evidence2.id)
  );

  // 3. Search by order_id for evidence1
  const orderIdResult: IPageIOrderEvidence = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id: orderId1,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(orderIdResult);
  TestValidator.equals("filtered by order_id -- only evidence1")(
    [evidence1.id]
  )(
    orderIdResult.data.map(x => x.id)
  );

  // 4. Search by evidence_type for 'photo' (should only return evidence2)
  const typeResult: IPageIOrderEvidence = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      evidence_type: "photo",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(typeResult);
  TestValidator.equals("filtered by type -- only evidence2")(
    [evidence2.id]
  )(
    typeResult.data.map(x => x.id)
  );

  // 5. Search for non-existent combination (wrong order_id + wrong type)
  const emptyResult: IPageIOrderEvidence = await api.functional.cartOrder.orderEvidence.patch(connection, {
    body: {
      order_id: typia.random<string & typia.tags.Format<"uuid">>(),
      evidence_type: "does_not_exist_type",
      page: 1,
      limit: 10,
    },
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty search returns empty data set")(0)(emptyResult.data.length);
}

