import { TestValidator } from '@nestia/e2e';
import api from '@ORGANIZATION/PROJECT-api';
import { IOrderEvidence } from '@ORGANIZATION/PROJECT-api/lib/structures/IOrderEvidence';
import typia from 'typia';

/**
 * Update metadata on an order_evidence record and validate not-found & validation error handling.
 *
 * Scenario:
 * 1. Create an order_evidence record via POST to serve as the target for update.
 * 2. Update one or more metadata fields (evidence_type, evidence_uri, provided_by) by PUT /cartOrder/orderEvidence/{id}, and ensure returned result matches updates and type.
 * 3. Attempt to perform PUT with a non-existent id, expecting HTTP 404 (not found) error.
 * 4. Attempt to update with prohibited/invalid fields or payload (e.g., missing evidence_type), expecting a validation error (400 series).
 * 5. All success responses are type-asserted. All errors use TestValidator.httpError.
 */
export async function test_api_order_evidence_update_and_negative(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an order_evidence record
  const evidenceCreate: IOrderEvidence.ICreate = {
    order_id: typia.random<string>(),
    evidence_type: 'invoice',
    evidence_uri: 'https://evidence.example.com/doc1.pdf',
    provided_at: new Date().toISOString(),
    provided_by: null,
  };
  const created: IOrderEvidence = await api.functional.cartOrder.orderEvidence.post(connection, { body: evidenceCreate });
  typia.assert(created);

  // 2. Update evidence_type, evidence_uri, provided_by via PUT
  const updatePayload: IOrderEvidence.IUpdate = {
    evidence_type: 'signature',
    evidence_uri: 'https://evidence.example.com/signed2.pdf',
    provided_by: typia.random<string>(),
  };
  const updated: IOrderEvidence = await api.functional.cartOrder.orderEvidence.putById(connection, {
    id: created.id,
    body: updatePayload,
  });
  typia.assert(updated);
  // Business: IDs must match, fields must be updated
  TestValidator.equals('evidence_type')(updatePayload.evidence_type)(updated.evidence_type);
  TestValidator.equals('evidence_uri')(updatePayload.evidence_uri)(updated.evidence_uri);
  TestValidator.equals('provided_by')(updatePayload.provided_by)(updated.provided_by);
  TestValidator.equals('id')(created.id)(updated.id);

  // 3. Negative: updating a non-existent record (should 404)
  const nonExistingId = typia.random<string>();
  await TestValidator.httpError('not found')(404)(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: nonExistingId,
      body: updatePayload,
    })
  );

  // 4. Negative: Update with invalid/missing required fields (should 400)
  const invalidPayload = { evidence_uri: null } as any;
  await TestValidator.httpError('bad request')(400)(() =>
    api.functional.cartOrder.orderEvidence.putById(connection, {
      id: created.id,
      body: invalidPayload,
    })
  );
}

