import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import { IPageIPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPayment";

/**
 * List and search payment records with a variety of filter criteria (date ranges, amount, status, method), verifying correct result sets and pagination.
 * Also test filtering that matches no record.
 *
 * Scenario:
 * 1. Create at least three payment records, each with distinct transaction_id, payment_method_id, amounts, currency, and status (one 'completed', one 'pending', one 'failed').
 *    Use varying timestamps for initiated_at and completed_at.
 * 2. For each payment, test searching by status, payment_method_id, transaction_id, and currency.
 * 3. Test date range filtering (initiated_at, completed_at), including exact edge, outside, and inside range cases.
 * 4. Test combined filter scenario (status + payment_method_id).
 * 5. Test pagination (split results by limit = 1, fetch multiple pages).
 * 6. Issue a filter query that matches no records (e.g., status + currency not used).
 * 7. Assert all response records always match the filter criteria used. Pagination is always structurally correct.
 */
export async function test_api_payment_list_and_search_payments_with_comprehensive_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create 3 payments with diverse attributes
  const now = new Date();
  const threeMinutesAgo = new Date(now.getTime() - 180000);
  const sixMinutesAgo = new Date(now.getTime() - 360000);
  // Unique ids for transaction and payment method purposes
  const tx1 = typia.random<string>();
  const tx2 = typia.random<string>();
  const tx3 = typia.random<string>();
  const pm1 = typia.random<string>();
  const pm2 = typia.random<string>();
  const pm3 = typia.random<string>();

  const createInput = [
    {
      transaction_id: tx1,
      payment_method_id: pm1,
      amount: 88.50,
      currency: "USD",
      description: "Completed sample",
    } satisfies IPayment.ICreate,
    {
      transaction_id: tx2,
      payment_method_id: pm2,
      amount: 12.25,
      currency: "EUR",
      description: "Pending sample",
    } satisfies IPayment.ICreate,
    {
      transaction_id: tx3,
      payment_method_id: pm3,
      amount: 33.00,
      currency: "KRW",
      description: "Failed sample",
    } satisfies IPayment.ICreate,
  ];

  // We will simulate different statuses and timestamps after creation (mock/patch as needed for filtering)
  // But for purposes of the test, we will call create and expect: 3 distinct payment objects are retrievable.
  const payments: IPayment[] = [];
  for (let i = 0; i < createInput.length; ++i) {
    const payment: IPayment = await api.functional.paymentsDiscounts.payments.post(connection, { body: createInput[i] });
    typia.assert(payment);
    payments.push(payment);
  }

  // Patch statuses as test precondition to enable status-based searching: this is generally not possible via exposed API, so
  // if not possible, the test can only use what was returned.
  // For testing, we will assume the resulting records received have a status property we can use for filtering, and initiated_at, etc. are set to now.

  // Manually arrange mock statuses and times for testing (in real e2e, have to setup this via admin or fixtures)
  payments[0].status = "completed";
  payments[1].status = "pending";
  payments[2].status = "failed";
  payments[0].initiated_at = sixMinutesAgo.toISOString();
  payments[0].completed_at = sixMinutesAgo.toISOString();
  payments[1].initiated_at = threeMinutesAgo.toISOString();
  payments[1].completed_at = null;
  payments[2].initiated_at = now.toISOString();
  payments[2].completed_at = null;

  // 2. Search each by status, payment method, transaction id, currency
  for (let i = 0; i < payments.length; ++i) {
    const payment = payments[i];
    // By status
    let result: IPageIPayment = await api.functional.paymentsDiscounts.payments.patch(connection, { body: { status: payment.status } });
    typia.assert(result);
    for (const record of result.data)
      TestValidator.equals("status")(payment.status)(record.status);
    // Each result must include the payment in question.
    TestValidator.equals("includes desired payment")(true)(result.data.some((x) => x.id === payment.id));

    // By payment_method_id
    result = await api.functional.paymentsDiscounts.payments.patch(connection, { body: { payment_method_id: payment.payment_method_id } });
    typia.assert(result);
    for (const record of result.data)
      TestValidator.equals("payment_method_id")(payment.payment_method_id)(record.payment_method_id);
    TestValidator.equals("includes desired payment")(true)(result.data.some((x) => x.id === payment.id));

    // By transaction_id
    result = await api.functional.paymentsDiscounts.payments.patch(connection, { body: { transaction_id: payment.transaction_id } });
    typia.assert(result);
    for (const record of result.data)
      TestValidator.equals("transaction_id")(payment.transaction_id)(record.transaction_id);
    TestValidator.equals("includes desired payment")(true)(result.data.some((x) => x.id === payment.id));

    // By currency
    result = await api.functional.paymentsDiscounts.payments.patch(connection, { body: { currency: payment.currency } });
    typia.assert(result);
    for (const record of result.data)
      TestValidator.equals("currency")(payment.currency)(record.currency);
    TestValidator.equals("includes desired payment")(true)(result.data.some((x) => x.id === payment.id));
  }

  // 3. Date range filter (initiated_at & completed_at)
  // Range that includes only first record (completed, sixMinutesAgo)
  let result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: { initiated_from: sixMinutesAgo.toISOString(), initiated_to: threeMinutesAgo.toISOString() },
  });
  typia.assert(result);
  for (const record of result.data) {
    TestValidator.equals("init range record")("completed")(record.status);
    TestValidator.equals("initiated_at")(
      true,
    )(
      record.initiated_at >= sixMinutesAgo.toISOString() &&
        record.initiated_at < threeMinutesAgo.toISOString()
    );
  }

  // Range that includes only second record (pending, threeMinutesAgo)
  result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: { initiated_from: threeMinutesAgo.toISOString(), initiated_to: now.toISOString() },
  });
  typia.assert(result);
  for (const record of result.data) {
    TestValidator.equals("init range record")("pending")(record.status);
    TestValidator.equals("initiated_at")(
      true,
    )(
      record.initiated_at >= threeMinutesAgo.toISOString() &&
        record.initiated_at < now.toISOString()
    );
  }

  // Range that includes only last record (failed, now)
  result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: { initiated_from: now.toISOString(), initiated_to: new Date(now.getTime() + 1000).toISOString() },
  });
  typia.assert(result);
  for (const record of result.data) {
    TestValidator.equals("init range record")("failed")(record.status);
    TestValidator.equals("initiated_at")(
      true,
    )(record.initiated_at >= now.toISOString());
  }

  // 4. Combined search (e.g., status + payment_method_id)
  result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: {
      status: payments[0].status,
      payment_method_id: payments[0].payment_method_id,
    },
  });
  typia.assert(result);
  for (const record of result.data) {
    TestValidator.equals("both status")(payments[0].status)(record.status);
    TestValidator.equals("both pmid")(payments[0].payment_method_id)(record.payment_method_id);
  }
  TestValidator.equals("includes specific payment")(true)(result.data.some((x) => x.id === payments[0].id));

  // 5. Pagination test (limit = 1, fetch pages)
  result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(result);
  TestValidator.equals("limit 1")(1)(result.data.length);
  const totalRecords = result.pagination.records;
  let seenIds = new Set<string>();
  for (let page = 1; page <= Math.min(3, result.pagination.pages); ++page) {
    const paged = await api.functional.paymentsDiscounts.payments.patch(connection, {
      body: { limit: 1, page },
    });
    typia.assert(paged);
    TestValidator.equals("pagination page num")(page)(paged.pagination.current);
    TestValidator.equals("at most 1 result")(true)(paged.data.length <= 1);
    paged.data.forEach((x) => seenIds.add(x.id));
  }
  // Make sure at least created records are part of the paginated set
  for (const pmt of payments) {
    TestValidator.equals("paginated included")(true)(seenIds.has(pmt.id));
  }

  // 6. Negative filter: no record matches (we use a status/currency that doesn't exist)
  result = await api.functional.paymentsDiscounts.payments.patch(connection, {
    body: { status: "nonexistentstatus", currency: "ZXC" },
  });
  typia.assert(result);
