  connection: api.IConnection,
): Promise<void> {
  // Step 1. Valid payment creation
  const create: IPayment.ICreate = {
    transaction_id: "00000000-0000-4000-a000-000000000011",
    payment_method_id: "00000000-0000-4000-b000-000000000022",
