import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";

import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";

/**
 * Validate update of permitted metadata fields of a payment record.
 *
 * This scenario verifies that only allowed fields (such as description, payment_method_id, or completed_at) can be updated for a payment, and that attempts to update non-existent payments or mutate forbidden fields (such as amount, transaction_id, status, currency, or id) are properly rejected.
 *
 * Steps:
 * 1. Create a payment record for manipulation.
 * 2. Update permitted metadata (description and completed_at) of the payment, verifying changes are saved.
 * 3. Attempt update using an invalid (non-existent) payment id, expecting not-found error (404).
 * 4. Attempt to update forbidden fields (amount, status), verifying the request is rejected (400 or 422).
 */
export async function test_api_payment_update_metadata_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a payment record
  const payment: IPayment = await api.functional.paymentsDiscounts.payments.post(connection, {
    body: {
      transaction_id: typia.random<string & tags.Format<"uuid">>(),
      payment_method_id: typia.random<string & tags.Format<"uuid">>(),
      amount: 1000,
      currency: "USD",
      description: "Initial payment",
    } satisfies IPayment.ICreate,
  });
  typia.assert(payment);

  // 2. Update permitted metadata fields
  const updatePayload: IPayment.IUpdate = {
    description: "Reconciled in admin interface",
    completed_at: new Date().toISOString(),
  };
  const updated: IPayment = await api.functional.paymentsDiscounts.payments.putById(connection, {
    id: payment.id,
    body: updatePayload,
  });
  typia.assert(updated);
  TestValidator.equals("updated description")(updatePayload.description)(updated.description);
  TestValidator.equals("updated completed_at")(updatePayload.completed_at)(updated.completed_at);

  // 3. Attempt update with an invalid/non-existent payment id
  await TestValidator.httpError("update non-existent payment")(404)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: "00000000-0000-0000-0000-000000000000",
      body: { description: "Should not succeed" },
    })
  );

  // 4. Attempt update with forbidden field(s)
  await TestValidator.httpError("update forbidden field: amount")(400)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: payment.id,
      // @ts-ignore
      body: { amount: 123.45 },
    })
  );

  await TestValidator.httpError("update forbidden field: status")(400)(() =>
    api.functional.paymentsDiscounts.payments.putById(connection, {
      id: payment.id,
      // @ts-ignore
      body: { status: "completed" },
    })
  );
}

