import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPayment";
import typia, { tags } from "typia";

/**
 * Soft-delete a payment record by ID and validate compliance/audit preservation.
 *
 * This test ensures that when a payment is soft-deleted, the record is excluded
 * from regular/active payment lists but is still preserved internally for legal
 * or compliance reasons. It also tests idempotency and error response by
 * attempting to delete a non-existent or already soft-deleted payment.
 *
 * 1. Create a new payment record.
 * 2. Soft-delete the payment record by its ID.
 * 3. Attempt to soft-delete the same payment record again (should be idempotent or error).
 * 4. Attempt to soft-delete a random/non-existent payment ID (should error properly).
 */
export async function test_api_payment_soft_delete_record_by_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new payment record
  const paymentCreateInput: IPayment.ICreate = {
    transaction_id: typia.random<string & tags.Format<"uuid">>(),
