  );
}

test/features/api/payment-method/test_li:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";
import { IPageIPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPaymentMethod";
import typia from "typia";

/**
 * Paginate and filter payment_method records by type, status, or creation date, checking correctness and completeness.
 *
 * Steps:
 * 1. Create multiple payment method records with different types (e.g., VISA, Wallet, PayPal), status (active/inactive), and creation dates for the same user.
 * 2. List all payment methods (no filter) and verify all created are returned.
 * 3. Filter by type and verify only matching are returned.
 * 4. Filter by activation status and check correct filtering.
 * 5. Filter by creation date range — confirm inclusion/exclusion.
 * 6. Test pagination (multiple pages, different limits, and edge cases).
 * 7. Combine filters (e.g., VISA+active) and validate result.
 * 8. For every response, check pagination metadata is correct and response structure is asserted.
 */
export async function test_api_payment_method_list_and_filter_with_pagination(connection: api.IConnection) {
  // 1. Create several payment methods for a single user
  const userId = "11111111-1111-1111-1111-111111111111";
  const PM_TYPES = ["VISA", "Wallet", "PayPal"];
  const methods: IPaymentMethod[] = [];

  // Create 7 payment methods: 3x VISA (2 active, 1 inactive), 2x Wallet (act+inact), 2x PayPal (act+inact)
  const baseDate = new Date();

  for (let i = 0; i < 7; ++i) {
    const type = PM_TYPES[Math.floor(i / 2)];
    const active = (i % 2 === 0);
    const created_at = new Date(baseDate.getTime() - i * 3600*1000).toISOString();
    const pm = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
      body: {
        user_id: userId,
        type,
        masked_detail: `${type}-last4-${i}${active?"A":"I"}`,
        provider: i < 4 ? "Stripe" : "Toss",
        active,
      } satisfies IPaymentMethod.ICreate
    });
    // Patch created_at for controlled test date range if supported (if not, skip step for system auto now)
    methods.push({ ...pm, created_at });
  }

  // 2. List all - no filters
  let resp: IPageIPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
    body: {
      user_id: userId,
    } satisfies IPaymentMethod.IRequest
  });
  typia.assert(resp);
  TestValidator.equals("all methods count")(methods.length)(resp.data.length);

  // 3. Filter by type
  for (const type of PM_TYPES) {
    const byType = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
      body: { user_id: userId, type } satisfies IPaymentMethod.IRequest
    });
    typia.assert(byType);
    const expected = methods.filter(m => m.type === type);
    TestValidator.equals(`${type} count`)(expected.length)(byType.data.length);
    for (const pm of byType.data) {
      TestValidator.equals(`type match ${type}`)(type)(pm.type)
    }
  }

  // 4. Filter by activation status
  for (const active of [true, false]) {
    const byActive = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
      body: { user_id: userId, active } satisfies IPaymentMethod.IRequest
    });
    typia.assert(byActive);
    const expected = methods.filter(m => m.active === active);
    TestValidator.equals(`active=${active} count`)(expected.length)(byActive.data.length);
    for (const pm of byActive.data) {
      TestValidator.equals(`active field ${active}`)(active)(pm.active);
    }
  }

  // 5. Filter by creation date range
  {
    // oldest 2
    const fromDate = methods[5].created_at;
    const toDate = methods[6].created_at;
    const expected = methods.filter(m => m.created_at >= fromDate && m.created_at <= toDate);
    const byDate = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
      body: { user_id: userId, created_from: fromDate, created_to: toDate } satisfies IPaymentMethod.IRequest
    });
    typia.assert(byDate);
    TestValidator.equals("filter by date count")(expected.length)(byDate.data.length);
  }

  // 6. Pagination: set limit=2, page=2
  {
    const paged = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
      body: { user_id: userId, limit: 2, page: 2 } satisfies IPaymentMethod.IRequest
    });
    typia.assert(paged);
    TestValidator.equals("page limit")(2)(paged.pagination.limit);
    TestValidator.equals("current page")(2)(paged.pagination.current);
    TestValidator.equals("pages meta")(
      Math.ceil(methods.length / 2)
    )(paged.pagination.pages);
    TestValidator.equals("records meta")(methods.length)(paged.pagination.records);
    TestValidator.equals("data length (page 2)")(
      Math.min(2, methods.length - 2)
    )(paged.data.length);
  }
  // 7. Combined filter (e.g., VISA + active=true)
  {
    const visAct = await api.functional.paymentsDiscounts.paymentMethods.patch(connection, {
      body: { user_id: userId, type: "VISA", active: true } satisfies IPaymentMethod.IRequest
    });
    typia.assert(visAct);
    const expected = methods.filter(m => m.type === "VISA" && m.active === true);
    TestValidator.equals("VISA+active count")(expected.length)(visAct.data.length);
    for (const pm of visAct.data) {
      TestValidator.equals("type VISA")(pm.type)("VISA");
      TestValidator.equals("active true")(pm.active)(true);
    }
  }
  // 8. Meta/data checks: already embedded in asserts above for all responses.
}

