import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPaymentMethod";

/**
 * End-to-end test for updating a payment method with compliance and error checks.
 *
 * Scenario:
 * 1. Register a new payment method for a user.
 * 2. Update mutable fields (masked_detail, provider, active) and verify update.
 * 3. Attempt update with a non-existent payment_method ID → expect not-found error.
 * 4. Try updating restricted fields (user_id, type) → ensure update is not allowed.
 */
export async function test_api_payment_method_update_and_invalid_or_sensitive_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register payment method
  const createInput: IPaymentMethod.ICreate = {
    user_id: typia.random<string>(),
    type: "VISA",
    masked_detail: "**** 4242",
    provider: "Stripe",
    active: true,
  };
  const method: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(connection, {
    body: createInput,
  });
  typia.assert(method);

  // 2. Update fields that are allowed:
  const updateInput: IPaymentMethod.IUpdate = {
    masked_detail: "**** 9472",
    provider: "StripeX",
    active: false,
  };
  const updated: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
    id: method.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("masked_detail updated")("**** 9472")(updated.masked_detail);
  TestValidator.equals("provider updated")("StripeX")(updated.provider ?? "");
  TestValidator.equals("active updated")(false)(updated.active);

  // 3. Try updating a non-existent payment_method (random uuid)
  const fakeId = typia.random<string & typia.tags.Format<"uuid">>();
  await TestValidator.httpError("not-found error when updating bad id")(404)(() =>
    api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
      id: fakeId,
      body: updateInput,
    })
  );

  // 4. Try illegal attempts to change immutable fields (ignored by API)
  // Actually, the API does not accept these fields in update body,
  // so they should be ignored. But try to add them forcibly and ensure response did not change them.
  const illegalUpdate: any = {
    masked_detail: "**** 7777",
    type: "CRYPTO", // illegal field for update
    user_id: typia.random<string>(), // illegal field for update
  };
  const result = await api.functional.paymentsDiscounts.paymentMethods.putById(connection, {
    id: method.id,
    body: illegalUpdate,
  });
  typia.assert(result);
  // type/user_id should NOT have changed
  TestValidator.equals("type is not updated")("VISA")(result.type);
  TestValidator.equals("user_id is not updated")(createInput.user_id)(result.user_id);
  TestValidator.equals("masked_detail updated again")("**** 7777")(result.masked_detail);
}

