 *
 * This test validates that soft-deleting (deactivating) a payment method via its id:
 * - Removes it from the "active" list (active: true)
 * - Preserves the record for compliance/audit (active:false still exists in DB)
 * - Returns idempotent or correct error for already deactivated or non-existing records
 *
 * Steps:
 * 1. Register a new payment method (active:true)
 * 2. Soft-delete (deactivate) the payment method and check the response (active:false)
 * 3. Attempt to delete again (should be idempotent or return proper error, e.g., 404/409)
 * 4. Attempt to delete a non-existent payment_method id (should error)
 * 5. [If there were a list endpoint] Verify that deactivated methods are not listed among active but are preserved in the DB for audit/compliance
 */
export async function test_api_payment_method_soft_delete_and_idempotency(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a payment method
  const methodInput: IPaymentMethod.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    type: "VISA",
    masked_detail: "**** **** **** 1234",
    provider: "Stripe",
    active: true,
  };
  const created: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.post(connection, { body: methodInput });
  typia.assert(created);
  TestValidator.equals("should be active")(true)(created.active);

  // 2. Soft-delete (deactivate)
  const erased: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.eraseById(connection, { id: created.id });
  typia.assert(erased);
  TestValidator.equals("should be deactivated")(false)(erased.active);
  TestValidator.equals("same id after deactivation")(created.id)(erased.id);

  // 3. Try to deactivate again (should be idempotent or error)
  try {
    const again: IPaymentMethod = await api.functional.paymentsDiscounts.paymentMethods.eraseById(connection, { id: created.id });
    typia.assert(again);
    TestValidator.equals("should remain deactivated")(false)(again.active);
  } catch (err: any) {
    // Acceptable: proper HTTP error, e.g., 404 Not Found or 409 Conflict
    if (!(err instanceof Error) || (!/404|409/.test((err as any).status?.toString() || ""))) throw err;
  }

  // 4. Try to delete a non-existent id
  await TestValidator.httpError("delete non-existent method should fail")(404)(() =>
    api.functional.paymentsDiscounts.paymentMethods.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // highly likely not exist
    })
  );

  // 5. [Optionally: If active-list endpoint:]
  // This would query all active payment_methods for the user
  // and verify the deactivated one does not appear, but is present in DB.
}

test/features/api/discount/test_list_and:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import { IPageIDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscount";
import typia from "typia";

/**
 * Search, filter, and paginate discounts using various parameters (amount, date, status, assigned rule/order), and confirm correct results and empty set logic.
 *
 * 1. Create several discount records with differing rule IDs, order IDs, amounts, dates, and notes (or status if relevant)
 * 2. Search using /paymentsDiscounts/discounts PATCH with parameters:
 *    a. Filter by order_id
 *    b. Filter by discount_rule_id
 *    c. Filter by applied_at from/to range
 *    d. Filter by amount_from/amount_to (min/max amount)
 *    e. Pagination/limit (including page with no results)
 *    f. Combined multi-field filters
 * 3. Validate that the returned data sets and pagination metadata are correct and expected
 * 4. Validate that when no records match, the data set is empty and correct pagination is returned
 */
export async function test_api_discount_list_and_search_discounts_with_multiple_criteria(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create diverse discount records
  const now = new Date();
  const ruleA = typia.random<string & typia.tags.Format<"uuid">>();
  const ruleB = typia.random<string & typia.tags.Format<"uuid">>();
  const orderA = typia.random<string & typia.tags.Format<"uuid">>();
  const orderB = typia.random<string & typia.tags.Format<"uuid">>();

  // Discount 1: ruleA/orderA/-1000
  const discount1: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: ruleA,
      order_id: orderA,
      amount: -1000,
      notes: "bulk test 1",
    },
  });
  typia.assert(discount1);

  // Discount 2: ruleB/orderA/-2000, applied_at = now - 2 days
  const discount2: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: ruleB,
      order_id: orderA,
      amount: -2000,
      notes: "bulk test 2",
    },
  });
  typia.assert(discount2);

  // Discount 3: ruleA/orderB/-3000, applied_at = now - 1 day
  const discount3: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: ruleA,
      order_id: orderB,
      amount: -3000,
      notes: "bulk test 3",
    },
  });
  typia.assert(discount3);

  // Discount 4: ruleB/orderB/-3000, applied_at = now
  const discount4: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: ruleB,
      order_id: orderB,
      amount: -3000,
      notes: "bulk test 4",
    },
  });
  typia.assert(discount4);

  // To enable filtering by applied_at, use actual applied_at property after creation
  // Reload discount list for metadata
  const allResult: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  const all = allResult.data.filter(
    d => [discount1.id, discount2.id, discount3.id, discount4.id].includes(d.id),
  );

  // 2a. Filter by order_id (should return discounts 1 and 2 for orderA)
  const byOrderA: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { order_id: orderA },
  });
  typia.assert(byOrderA);
  const idsByOrderA = byOrderA.data.map(d => d.id);
  TestValidator.equals("order_id filter")(
    [discount1.id, discount2.id].sort(),
  )(idsByOrderA.sort());

  // 2b. Filter by discount_rule_id (ruleB – should return discounts 2 and 4)
  const byRuleB: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { discount_rule_id: ruleB },
  });
  typia.assert(byRuleB);
  const idsByRuleB = byRuleB.data.map(d => d.id);
  TestValidator.equals("rule_id filter")(
    [discount2.id, discount4.id].sort(),
  )(idsByRuleB.sort());

  // 2c. applied_at from/to (between discount2/3/4)
  const lowerDate = all.find(d => d.id === discount2.id)?.applied_at!;
  const upperDate = all.find(d => d.id === discount3.id)?.applied_at!;
  const midAppliedAtResult: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: {
      applied_from: lowerDate,
      applied_to: upperDate,
      sort: "applied_at:asc",
    },
  });
  typia.assert(midAppliedAtResult);
  // Only discount2 (applied_at = lowerDate) is expected if inclusive lower, exclusive upper
  const apIds = midAppliedAtResult.data.map(d => d.id);
  TestValidator.equals("applied_at from/to filter")(
    [discount2.id],
  )(apIds);

  // 2d. amount_from (>= -2000)
  const minAmountResult: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { amount_from: -2000 },
  });
  typia.assert(minAmountResult);
  const idsMinAmount = minAmountResult.data.map(d => d.id);
  // discount2, 3, 4
  TestValidator.equals("amount_from filter")(
    [discount2.id, discount3.id, discount4.id].sort(),
  )(idsMinAmount.sort());

  // 2e. Pagination: limit = 2, page 2
  const paged: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(paged);
  TestValidator.equals("limit 2, page 2 length")(2)(paged.data.length);
  TestValidator.equals("pagination current page")(2)(paged.pagination.current);

  // 2f. Combined: ruleB + orderB => only discount4
  const combo: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { discount_rule_id: ruleB, order_id: orderB },
  });
  typia.assert(combo);
  TestValidator.equals("combo filter single")([discount4.id])(combo.data.map(d => d.id));

  // 3. Empty set: impossible combo
  const emptyResult: IPageIDiscount = await api.functional.paymentsDiscounts.discounts.patch(connection, {
    body: { discount_rule_id: ruleA, order_id: "never-exists-uuid-0000" as any },
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty set")(0)(emptyResult.data.length);
  TestValidator.equals("empty page current")(1)(emptyResult.pagination.current);
}

