import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import typia, { tags } from "typia";

/**
 * Fetch a discount record by valid id and validate all assigned rules, effective dates, and metadata.
 * Also test fetch by invalid id, and verify a not-found response is returned (typically 404).
 *
 * Business context: This test ensures that a discount record, once created, can be fetched by its unique identifier, and all business-relevant metadata (rule reference, order linkage, amount, timestamps, notes) are precisely retrievable. It also ensures the system securely rejects invalid/unknown IDs with the correct error status, supporting forensic and compliance traceability.
 *
 * Step-by-step process:
 * 1. Create a discount record with valid references and details.
 * 2. Fetch the newly created discount by its id; validate every returned property and data integrity.
 * 3. Attempt to fetch a discount with a random (non-existing) id; expect a 404 or not-found error.
 */
export async function test_api_discount_get_by_id_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a discount record (prerequisite for fetch)
  // Use typia.random for UUIDs; in production, likely replace with linking to created rule/order
  const discountCreate: IDiscount.ICreate = {
    discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
    order_id: typia.random<string & tags.Format<"uuid">>(),
    amount: -5000,
    notes: "Test discount for fetch by id",
  };
  const created: IDiscount = await api.functional.paymentsDiscounts.discounts.post(
    connection,
    { body: discountCreate }
  );
  typia.assert(created);

  // 2. Fetch the discount by id
  const fetched: IDiscount = await api.functional.paymentsDiscounts.discounts.getById(
    connection,
    { id: created.id }
  );
  typia.assert(fetched);
  TestValidator.equals("id matches")(created.id)(fetched.id);
  TestValidator.equals("discount_rule_id matches")(created.discount_rule_id)(fetched.discount_rule_id);
  TestValidator.equals("order_id matches")(created.order_id)(fetched.order_id);
  TestValidator.equals("amount matches")(created.amount)(fetched.amount);
  TestValidator.equals("notes matches")(created.notes)(fetched.notes);
  // Validate timestamp shape
  TestValidator.predicate("applied_at is string")(() => typeof fetched.applied_at === "string");

  // 3. Fetch by invalid (random) id, expect 404
  await TestValidator.httpError("not found for random id")(404)(() =>
    api.functional.paymentsDiscounts.discounts.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

