import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IDiscount } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscount";
import typia, { tags } from "typia";

/**
 * 할인(discount) 레코드의 허용된 필드(예: notes) 업데이트를 검증합니다.
 *
 * 1. 할인 생성(테스트용 discount 레코드 생성)
 * 2. 허용 필드(notes) 업데이트 및 반영 확인
 * 3. 존재하지 않는 id로 업데이트 시도(404 등 not-found 오류 검증)
 * 4. 금지 필드/불변 필드(id, discount_rule_id, order_id, applied_at) 변경 시도 및 정책 위배 오류 검증
 */
export async function test_api_discount_update_valid_forbidden_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. 할인 생성
  const initial: IDiscount = await api.functional.paymentsDiscounts.discounts.post(connection, {
    body: {
      discount_rule_id: typia.random<string & tags.Format<"uuid">>(),
      order_id: typia.random<string & tags.Format<"uuid">>(),
      amount: -10000,
      notes: "초기 할인 테스트 케이스"
    } satisfies IDiscount.ICreate
  });
  typia.assert(initial);

  // 2. 허용 필드(notes) 업데이트 정상 동작
  const updatedNotes = "note 필드 수정됨 (e2e)";
  const updated: IDiscount = await api.functional.paymentsDiscounts.discounts.putById(connection, {
    id: initial.id,
    body: {
      notes: updatedNotes
    } satisfies IDiscount.IUpdate
  });
  typia.assert(updated);
  TestValidator.equals("notes 업데이트 반영됨")(updatedNotes)(updated.notes ?? "");
  TestValidator.equals("amount 불변")(initial.amount)(updated.amount);
  TestValidator.equals("불변 식별자 id")(initial.id)(updated.id);

  // 3. 존재하지 않는 id 업데이트 시도(not-found)
  const wrongId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("존재하지 않는 id 업데이트 시 not-found 오류")(404)(() =>
    api.functional.paymentsDiscounts.discounts.putById(connection, {
      id: wrongId,
      body: { notes: "should-not-work" }
    })
  );

  // 4. 금지 필드(ex: amount) 혹은 불변 필드 변경 시도를 통한 정책 위배 에러 검증
  // - 만약 amount 업데이트가 예외 상황에서만 허용이라면 아래에서 검증(실제 정책에 따라 403/409 등 처리가능)
  // - id, discount_rule_id, order_id 등은 IUpdate에 아예 포함 안 됨(전송 불가), 차단 정책만 검증
  await TestValidator.httpError("amount 금액 불합리한 변경 시도 오류")(403)(() =>
    api.functional.paymentsDiscounts.discounts.putById(connection, {
      id: initial.id,
      body: { amount: -7799.22 } satisfies IDiscount.IUpdate
    })
  );
}

