import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";

/**
 * E2E test for searching and paginating personalization events with robust filters.
 *
 * This test first creates multiple personalization events with controlled parameters, then
performs advanced search and paging scenarios to validate list, filter, and paging endpoints.
 * It checks total/paging accuracy, user/event-type/timestamp filtering, edge cases such as�zero-results and page overflow, validation for maximum limit, and broken/incomplete queries.
 *
 * Steps:
 * 1. Create several (5+) personalization events with different combinations of user_id, product_id, event_type, model_version, context.
 * 2. Retrieve a paginated list of events using no filters. Verify total/records returned match expected.
 * 3. Retrieve events filtered by a specific user_id. Check only that user's events are returned.
 * 4. Retrieve events with a filter for event_type. Confirm only matching records are found.
 * 5. Retrieve events with timestamp range filter. Check correct records returned.
 * 6. Test pagination (limit=2, page=2). Confirm correct events on page 2.
 * 7. Use invalid filter (nonsense event_type)  expect zero events.
 * 8. Request for a page number greater than availableconfirm empty result, paging meta.
 * 9. Request limit over maximumexpect capping or error.
 * 10. Missing/invalid parametersexpect error or schema validation failure.
 */
export async function test_api_favoritesPersonalization_personalizationEvents_list_pagination_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create 7 events with varied parameters
  const users = [typia.random<string>(), typia.random<string>()];
  const products = [typia.random<string>(), typia.random<string>()];
  const recs = [typia.random<string>(), typia.random<string>()];
  const modelVersions = ["v1", "v2"];
  const eventTypes = ["view", "click"];
  const now = new Date();
  const contexts = ["mobile", "desktop", null];
  const timestamps: string[] = [];

  const createdEvents: IFavoritesPersonalization.IPersonalizationEvent[] = [];
  for (let i = 0; i < 7; ++i) {
    const userIdx = i % users.length;
    const prodIdx = i % products.length;
    const recIdx = i % recs.length;
    const versionIdx = i % modelVersions.length;
    const typeIdx = i % eventTypes.length;
    const ctxIdx = i % contexts.length;
    const ts = new Date(now.getTime() + i * 60000).toISOString();
    timestamps.push(ts);
    const input = {
      user_id: users[userIdx],
      product_id: products[prodIdx],
      recommendation_id: recs[recIdx],
      event_type: eventTypes[typeIdx],
      model_version: modelVersions[versionIdx],
      context: contexts[ctxIdx],
      timestamp: ts,
    } as any;
    // Remove the timestamp in the create structure (should be set by the BE)
    delete input.timestamp;
    const event = await api.functional.favoritesPersonalization.personalizationEvents.post(connection, {
      body: input satisfies IFavoritesPersonalization.IPersonalizationEventCreate,
    });
    typia.assert(event);
    createdEvents.push(event);
  }

  // 2. List all events (no filters)
  const allEventsResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { page: 1, limit: 100 },
  });
  typia.assert(allEventsResp);
  TestValidator.equals("events total")(
    allEventsResp.pagination.records >= createdEvents.length
  )(true);
  TestValidator.equals("page size")(
    allEventsResp.data.length <= 100
  )(true);

  // 3. Filter by user_id (use first user)
  const firstUser = users[0];
  const byUserResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { user_id: firstUser },
  });
  typia.assert(byUserResp);
  TestValidator.equals("filtered by user")(
    byUserResp.data.filter(e => e.user_id !== firstUser).length
  )(0);

  // 4. Filter by event_type 'click'
  const byTypeResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { event_type: "click" },
  });
  typia.assert(byTypeResp);
  TestValidator.equals("all clicks")(
    byTypeResp.data.filter(e => e.event_type !== "click").length
  )(0);

  // 5. Range query by timestamp
  const tsFrom = timestamps[2];
  const tsTo = timestamps[4];
  const byRangeResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { timestamp_from: tsFrom, timestamp_to: tsTo },
  });
  typia.assert(byRangeResp);
  for (const ev of byRangeResp.data)
    TestValidator.equals("timestamp in range")(
      new Date(ev.timestamp) >= new Date(tsFrom) &&
      new Date(ev.timestamp) <= new Date(tsTo)
    )(true);

  // 6. Paginate (page 2, limit 2)
  const page2Resp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(page2Resp);
  TestValidator.equals("page size (limit)")(page2Resp.data.length <= 2)(true);

  // 7. Invalid filter (nonsense event_type)
  const noMatchResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { event_type: "nonsense_type" },
  });
  typia.assert(noMatchResp);
  TestValidator.equals("zero result for nonsense filter")(
    noMatchResp.data.length
  )(0);

  // 8. Page out-of-bounds (page=1000)
  const highPageResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { limit: 2, page: 1000 },
  });
  typia.assert(highPageResp);
  TestValidator.equals("empty result for high page")(
    highPageResp.data.length
  )(0);

  // 9. Limit above max (limit=200 if max=100)
  const limitResp = await api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
    body: { limit: 200, page: 1 },
  });
  typia.assert(limitResp);
  TestValidator.equals("max page size")(
    limitResp.data.length <= 100
  )(true);

  // 10. Invalid required params/invalid types
  await TestValidator.error("missing required param fails")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
      body: { page: 0 } as any,
    }),
  );
  await TestValidator.error("invalid type fails")(() =>
    api.functional.favoritesPersonalization.personalizationEvents.patch(connection, {
      body: { limit: "foo" } as any,
    }),
  );
}

