import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IFavoritesPersonalization } from "@ORGANIZATION/PROJECT-api/lib/structures/IFavoritesPersonalization";
import { IPersonalizationEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationEvent";
import typia from "typia";

/**
 * Validate updating a personalization event and error responses for invalid or unauthorized update attempts.
 *
 * Scenario steps:
 * 1. Create a new personalization event with valid data.
 * 2. Update the event using valid new data and verify that all changes are reflected in the response.
 * 3. Attempt to update a personalization event using an invalid/nonexistent event ID, expect an error response (404 or 400).
 * 4. Partially update only some fields (event_type/context) and verify only those change and other fields are retained.
 * 5. Attempt to modify immutable fields (such as id or user_id), verify these are protected and error is returned or update is rejected.
 */
export async function test_api_personalization_event_update_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new personalization event
  const created: IFavoritesPersonalization.IPersonalizationEvent =
    await api.functional.favoritesPersonalization.personalizationEvents.post(
      connection,
      {
        body: {
          user_id: typia.random<string>(),
          recommendation_id: typia.random<string>(),
          product_id: typia.random<string>(),
          event_type: "view",
          model_version: "v1.0.0",
          context: "web/ko-KR",
        } satisfies IFavoritesPersonalization.IPersonalizationEventCreate,
      },
    );
  typia.assert(created);

  // 2. Update the event with new data
  const updated: IPersonalizationEvent = await api.functional.favoritesPersonalization.personalizationEvents.putById(
    connection,
    {
      id: created.id,
      body: {
        event_type: "click",
        model_version: "v2.0.0",
        product_id: created.product_id,
        recommendation_id: created.recommendation_id,
        context: "app/en-US",
        timestamp: new Date().toISOString(),
      } satisfies IPersonalizationEvent.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("id should be unchanged")(created.id)(updated.id);
  TestValidator.equals("user_id should be unchanged")(created.user_id)(updated.user_id);
  TestValidator.equals("event_type updated")("click")(updated.event_type);
  TestValidator.equals("model_version updated")("v2.0.0")(updated.model_version);

  // 3. Attempt updating with an invalid/nonexistent event ID
  await TestValidator.httpError("update with non-existent id fails")(404)(async () =>
    api.functional.favoritesPersonalization.personalizationEvents.putById(
      connection,
      {
        id: typia.random<string>(), // Not a real event id
        body: {
          event_type: "dismiss",
          model_version: "v2.1.0",
          product_id: updated.product_id,
          recommendation_id: updated.recommendation_id,
          timestamp: new Date().toISOString(),
        } satisfies IPersonalizationEvent.IUpdate,
      },
    ),
  );

  // 4. Partial update: Only update event_type and context
  const partialUpdate: IPersonalizationEvent = await api.functional.favoritesPersonalization.personalizationEvents.putById(
    connection,
    {
      id: updated.id,
      body: {
        event_type: "save",
        model_version: updated.model_version,
        product_id: updated.product_id,
        recommendation_id: updated.recommendation_id,
        context: "web/ja-JP",
        timestamp: updated.timestamp,
      } satisfies IPersonalizationEvent.IUpdate,
    },
  );
  typia.assert(partialUpdate);
  TestValidator.equals("event_type changed 2")("save")(partialUpdate.event_type);
  TestValidator.equals("context changed 2")("web/ja-JP")(partialUpdate.context!);
  TestValidator.equals("model_version retained")(updated.model_version)(partialUpdate.model_version);

  // 5. Attempt to update immutable fields (id, user_id)
  const maliciousUpdate = {
    ...partialUpdate,
    id: typia.random<string>(),
    user_id: typia.random<string>(),
  };
  await TestValidator.httpError("cannot update immutable fields")(400)(async () =>
    api.functional.favoritesPersonalization.personalizationEvents.putById(
      connection,
      {
        id: updated.id,
        body: maliciousUpdate as any, // Should fail
      },
    ),
  );
}

