      body: {
        user_id: "00000000-0000-0000-0000-000000000000",
        product_id: "00000000-0000-0000-0000-000000000000",
        limit: 10,
      } satisfies IRecommendation.IRequest,
    },
  );
  typia.assert(invalid);
  TestValidator.equals("empty by invalid filter")(invalid.data.length)(0);

  // 5. Pagination: fetch last and out-of-range page
  const pageSize = 3;
  const total = recommendations.length;
  const lastPageIdx = Math.floor((total - 1) / pageSize);

  // Fetch last page
  const lastPage: IPageIRecommendation = await api.functional.favoritesPersonalization.recommendations.patch(
    connection,
    {
      body: {
        offset: lastPageIdx * pageSize,
        limit: pageSize,
      } satisfies IRecommendation.IRequest,
    },
  );
  typia.assert(lastPage);
  TestValidator.equals("last page index")(lastPage.pagination.current)(lastPageIdx);
  // last page data count: if perfectly divisible use pageSize, else use remainder
  const expectedLastCount = total % pageSize === 0 ? pageSize : total % pageSize;
  TestValidator.equals("last page data count")(lastPage.data.length)(expectedLastCount);

  // Fetch out-of-range (empty) page
  const emptyPage: IPageIRecommendation = await api.functional.favoritesPersonalization.recommendations.patch(
    connection,
    {
      body: {
        offset: total * 2,
        limit: pageSize,
      } satisfies IRecommendation.IRequest,
    },
  );
  typia.assert(emptyPage);
  TestValidator.equals("out-of-range page is empty")(emptyPage.data.length)(0);
}

