import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IRecommendation } from "@ORGANIZATION/PROJECT-api/lib/structures/IRecommendation";

/**
 * E2E test for updating a recommendation by ID.
 *
 * Scenario steps:
 * 1. Create a new recommendation (setup - dependency for update test)
 * 2. Update the recommendation with a valid ID and new valid data.
 *    - Verify that the updated fields are reflected in the response.
 * 3. Attempt to update a nonexistent recommendation (invalid UUID)
 *    - Expect an error response (e.g. 404 Not Found)
 * 4. Attempt to update immutable/read-only fields (e.g. user_id, product_id, model_id)
 *    - Verify that such changes are rejected by the system
 */
export async function test_api_recommendation_update_valid_and_invalid_id(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a recommendation to update
  const createInput: IRecommendation.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    model_id: "model-x",
    model_version: "1.0.0",
    recommendation_time: new Date().toISOString(),
    rationale: "original rationale",
  };
  const recommendation: IRecommendation = await api.functional.favoritesPersonalization.recommendations.post(
    connection,
    { body: createInput },
  );
  typia.assert(recommendation);

  // 2. Update the recommendation with valid new data
  const updateInput: IRecommendation.IUpdate = {
    model_version: "2.0.0",
    rationale: "updated rationale",
    recommendation_time: new Date(Date.now() + 60_000).toISOString(),
  };
  const updated: IRecommendation = await api.functional.favoritesPersonalization.recommendations.putById(
    connection,
    {
      id: recommendation.id,
      body: updateInput,
    },
  );
  typia.assert(updated);
  TestValidator.equals("model_version updated")("2.0.0")(updated.model_version);
  TestValidator.equals("rationale updated")("updated rationale")((updated.rationale ?? ""));
  TestValidator.equals("recommendation_time updated")(updateInput.recommendation_time)(updated.recommendation_time);

  // 3. Attempt update with an invalid (nonexistent) ID
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("Update with invalid/nonexistent ID should fail")(404)(() =>
    api.functional.favoritesPersonalization.recommendations.putById(
      connection,
      {
        id: nonExistentId,
        body: updateInput,
      },
    ),
  );

  // 4. Attempt to update immutable fields (should be ignored or rejected)
  // We try to pass guessed immutable fields through input (should be ignored by API or trigger an error)
  const invalidUpdateInput: IRecommendation.IUpdate & { user_id: string; product_id: string; model_id: string } = {
    ...updateInput,
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    model_id: "should-not-be-allowed",
  };
  await TestValidator.httpError("Attempt to update immutable fields should be rejected")(400)(() =>
    api.functional.favoritesPersonalization.recommendations.putById(
      connection,
      {
        id: recommendation.id,
        body: invalidUpdateInput,
      },
    ),
  );
}

