import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPersonalizationAudit";
import { IPageIPersonalizationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPersonalizationAudit";
import typia from "typia";

/**
 * Paginated and filterable listing of personalization audit records.
 *
 * Validates the search and pagination features of the audit listing endpoint. Ensures proper filtering
 * by event type, user, and date range. Handles cases where filters match no records, tests boundary
 * conditions like very large result sets, and verifies error handling on invalid filters.
 *
 * In order to run meaningful tests, first creates several audit records using various combinations
 * of properties (such as user_id, action_type, etc). Uses the same users and event types later to filter.
 *
 * 1. Create several audit records for different users, actions, and timestamps
 * 2. List audits without filters and verify pagination
 * 3. List audits filtered by user_id and check returned records
 * 4. List audits filtered by action_type and check correctness
 * 5. List audits filtered by timestamp range
 * 6. Attempt to filter with parameters that shouldn't match any record
 * 7. Test large page sizes and negative/invalid pagination parameters
 */
export async function test_api_personalization_audit_list_with_pagination_and_filters(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create audit records
  const baseUserId = typia.random<string & typia.tags.Format<"uuid">>();
  const altUserId = typia.random<string & typia.tags.Format<"uuid">>();
  const now = new Date();
  const ts1 = new Date(now.getTime() - 60 * 60 * 1000).toISOString(); // 1 hr ago
  const ts2 = now.toISOString();
  const recordA = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    {
      body: {
        user_id: baseUserId,
        action_type: "ADD_FAVORITE",
        evidence_hash: "hash-A",
        timestamp: ts1,
      },
    },
  );
  typia.assert(recordA);
  const recordB = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    {
      body: {
        user_id: baseUserId,
        action_type: "REMOVE_BOOKMARK",
        evidence_hash: "hash-B",
        timestamp: ts2,
      },
    },
  );
  typia.assert(recordB);
  const recordC = await api.functional.favoritesPersonalization.personalizationAudits.post(
    connection,
    {
      body: {
        user_id: altUserId,
        action_type: "CUSTOM_ACTION_TYPE",
        evidence_hash: "hash-C",
        timestamp: ts2,
      },
    },
  );
  typia.assert(recordC);

  // 2. List all (no filter):
  const allResult = await api.functional.favoritesPersonalization.personalizationAudits.patch(
    connection,
    { body: {} },
  );
  typia.assert(allResult);
  TestValidator.equals("contains all created audits")(
    allResult.data.map((x) => x.id).sort()
  )([recordA.id, recordB.id, recordC.id].sort());

  // 3. Filter by user_id
  {
    const res = await api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { user_id: baseUserId } },
    );
    typia.assert(res);
    for (const rec of res.data) TestValidator.equals("filtered user_id")(baseUserId)(rec.user_id);
    TestValidator.equals("user_id data ids")(
      res.data.map((r) => r.id).sort()
    )([recordA.id, recordB.id].sort());
  }

  // 4. Filter by action_type
  {
    const res = await api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { action_type: "ADD_FAVORITE" } },
    );
    typia.assert(res);
    for (const rec of res.data) TestValidator.equals("action type")("ADD_FAVORITE")(rec.action_type);
    TestValidator.equals("action_type ids")(
      res.data.some((r) => r.id === recordA.id)
    )(true);
  }

  // 5. Filter by timestamp range
  {
    const res = await api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { timestamp_from: ts2 } },
    );
    typia.assert(res);
    for (const rec of res.data) TestValidator.equals("timestamp_from filter")(ts2)(rec.timestamp);
  }

  // 6. Empty result: filter for nonexistent hash
  {
    const res = await api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { evidence_hash: "nonexistent" } },
    );
    typia.assert(res);
    TestValidator.equals("no records for non-matching filter")(0)(res.data.length);
  }

  // 7. Boundary: large limit
  {
    const res = await api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { limit: 999 } },
    );
    typia.assert(res);
    TestValidator.equals("all audits returned for large limit")(
      res.data.length
    )(3);
  }

  // 8. Invalid: negative limit (should error, but if API allows it's a bug)
  await TestValidator.httpError("negative limit param")(400)(() =>
    api.functional.favoritesPersonalization.personalizationAudits.patch(
      connection,
      { body: { limit: -1 } },
    ),
  );
}

