import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";
import { IPageIAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiModel";

/**
 * E2E test: Paginated, filterable listing/search of AI models.
 *
 * - Validates listing AI models supports filtering by model type, owner, and updated timestamp.
 * - Tests behavior when the database is empty, when using valid filters that match records, invalid filters (should yield empty results), and pagination edge cases.
 * - Coverage includes creating multiple AI model records to ensure realistic search scenarios and meaningful pagination.
 *
 * 1. Ensure database is initially empty (optional: clear models if possible)
 * 2. List/search AI models with no records - expect empty results and correct pagination meta.
 * 3. Bulk-create N (N >= 3) AI model records with varying model_type, owner_id, updated_at.
 * 4. List/search all AI models with no filters - expect all records returned (possibly paginated)
 * 5. List/search with a filter (model_type = foo), expect only matching models.
 * 6. List/search with another filter (owner_id = X), expect only matching models.
 * 7. List/search with filter that should not match any record (invalid/absent model_type or owner_id), expect 0 results.
 * 8. Test pagination: page=1/limit=2, then page=2/limit=2. Results should not overlap, and total record count is correct.
 * 9. Limit parameter: limit=1 returns only one record, next page gets the second, etc.
 * 10. Optionally, test sorting by updated_at if API supports it (assumed default is descending).
 *
 * Each step validates response structure (typia.assert), correct record counts/meta, and that filters/pagination work correctly.
 */
export async function test_api_ai_models_list_search_pagination(
  connection: api.IConnection,
): Promise<void> {
  // Step 1 & 2: List with no records (assume DB is empty for isolated test)
  const emptyResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: {} satisfies IAiModel.IRequest },
  );
  typia.assert(emptyResult);
  TestValidator.equals("empty db pagination record count")(0)(emptyResult.pagination.records);
  TestValidator.equals("empty db data length")(0)(emptyResult.data.length);

  // Step 3: Create multiple AI models with various fields
  const organization_id = "00000000-0000-0000-0000-000000000001";
  const owner_ids = [
    "00000000-0000-0000-0000-000000010001",
    "00000000-0000-0000-0000-000000010002",
  ];
  const now = new Date();
  // Create 3 models
  const models: IAiModel[] = [];
  for (let i = 0; i < 3; ++i) {
    const model_type = i === 2 ? "sentiment" : "recommendation";
    const owner_id = owner_ids[i % owner_ids.length];
    const body = {
      organization_id,
      owner_id,
      name: `model_${i}`,
      model_type,
      description: `Test AI Model ${i}`,
    } satisfies IAiModel.ICreate;
    const model: IAiModel = await api.functional.advancedAI.aiModels.post(
      connection, { body },
    );
    typia.assert(model);
    models.push(model);
  }

  // Step 4: List/search, no filters
  const allResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: {} satisfies IAiModel.IRequest },
  );
  typia.assert(allResult);
  TestValidator.equals("all models count")(models.length)(allResult.pagination.records);
  TestValidator.equals("all models data")(models.length)(allResult.data.length);

  // Step 5: List/search filtered by model_type
  const filterTypeResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: { model_type: "recommendation" } satisfies IAiModel.IRequest },
  );
  typia.assert(filterTypeResult);
  TestValidator.equals("filter by model_type count")(
    models.filter((m) => m.model_type === "recommendation").length,
  )(filterTypeResult.pagination.records);

  // Step 6: List/search filtered by owner_id
  const targetOwner = owner_ids[0];
  const filterOwnerResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: { owner_id: targetOwner } satisfies IAiModel.IRequest },
  );
  typia.assert(filterOwnerResult);
  TestValidator.equals("filter by owner_id count")(
    models.filter((m) => m.owner_id === targetOwner).length,
  )(filterOwnerResult.pagination.records);

  // Step 7: List/search with non-matching/invalid filters
  const emptyTypeResult: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: { model_type: "SHOULD_NOT_MATCH_ANYTHING" } satisfies IAiModel.IRequest },
  );
  typia.assert(emptyTypeResult);
  TestValidator.equals("invalid filter yields 0 results")(0)(emptyTypeResult.pagination.records);

  // Step 8: Test pagination: page=1/limit=2, then page=2/limit=2
  const page1: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: { page: 1, limit: 2 } satisfies IAiModel.IRequest },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 data count")(Math.min(2, models.length))(page1.data.length);

  const page2: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
    connection,
    { body: { page: 2, limit: 2 } satisfies IAiModel.IRequest },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 data count")(
    models.length - 2 > 0 ? models.length - 2 : 0,
  )(page2.data.length);

  // Step 9: Limit parameter (limit = 1), traverse all pages
  let traversed = 0;
  for (let page = 1; page <= models.length; ++page) {
    const res: IPageIAiModel = await api.functional.advancedAI.aiModels.patch(
      connection,
      { body: { limit: 1, page } satisfies IAiModel.IRequest },
    );
    typia.assert(res);
    if (res.data.length > 0) traversed += 1;
  }
  TestValidator.equals("pagination, traversed all pages")(models.length)(traversed);
}

