import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";
import typia from "typia";

/**
 * E2E test: Update AI model metadata and test edge/error cases.
 *
 * Scenario:
 * 1. Create an AI model (setup for valid update tests).
 * 2. Update metadata on the created AI model using a valid ID, changing multiple fields (name, description, type) and verify changes persist.
 * 3. Attempt updating a nonexistent model (invalid/unknown ID) – expect a not found error.
 * 4. Try to alter immutable or read-only fields (created_at/updated_at/id) and verify the API rejects or ignores those changes.
 */
export async function test_api_ai_model_update_metadata_valid_and_invalid_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create an AI model (for positive update scenario)
  const model: IAiModel = await api.functional.advancedAI.aiModels.post(connection, {
    body: {
      organization_id: typia.random<string>(),
      owner_id: typia.random<string>(),
      name: `TestModel_${Date.now()}`,
      model_type: "classification",
      description: "Initial metadata for updatable model.",
    } satisfies IAiModel.ICreate,
  });
  typia.assert(model);

  // 2. Update the model metadata with valid ID
  const newName = `UpdatedModel_${Date.now()}`;
  const newDesc = "Updated model description.";
  const newType = "regression";
  const updateRes: IAiModel = await api.functional.advancedAI.aiModels.putById(connection, {
    id: model.id,
    body: {
      name: newName,
      description: newDesc,
      model_type: newType,
    } satisfies IAiModel.IUpdate,
  });
  typia.assert(updateRes);
  TestValidator.equals("updated id")(model.id)(updateRes.id);
  TestValidator.equals("updated name")(newName)(updateRes.name);
  TestValidator.equals("updated desc")(newDesc)(updateRes.description!);
  TestValidator.equals("updated type")(newType)(updateRes.model_type);

  // 3. Attempt to update a nonexistent model (invalid ID)
  await TestValidator.httpError("update nonexistent model")(404)(() =>
    api.functional.advancedAI.aiModels.putById(connection, {
      id: "9be0443c-3785-4e88-9a0a-ffffffffffff", // Unlikely-to-exist UUID
      body: { name: "ShouldFail" },
    })
  );

  // 4. Attempt to update immutable fields (should be rejected or ignored)
  // Try to overwrite id and created_at (should not be changeable)
  const badUpdate = {
    name: "TryUpdateName",
    id: "00000000-0000-0000-0000-000000000000",
    created_at: new Date(0).toISOString(),
    updated_at: new Date(0).toISOString(),
  };
  const resAfterBadUpdate: IAiModel = await api.functional.advancedAI.aiModels.putById(connection, {
    id: model.id,
    body: badUpdate as any, // Bypass TS type for negative test (API should ignore/reject illegal fields)
  });
  typia.assert(resAfterBadUpdate);
  // Ensure immutable fields were NOT changed
  TestValidator.equals("id immutable")(model.id)(resAfterBadUpdate.id);
  TestValidator.equals("created_at immutable")(model.created_at)(resAfterBadUpdate.created_at);
}

