import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";
import typia, { tags } from "typia";

/**
 * AI 모델 버전을 ID로 정확히 조회하고 정확성을 검증한다.
 *
 * 1. AI 모델 버전을 직접 생성한다 (POST /advancedAI/aiModelVersions).
 * 2. 생성된 버전의 id로 단일 상세 조회한다(GET /advancedAI/aiModelVersions/{id}).
 * 3. 받은 값이 생성 값과 일치하는지 모든 주요 필드를 검증한다.
 * 4. 존재하지 않는 임의의 UUID로 조회하면 404/Not Found 에러를 기대한다.
 * 5. soft delete 처리된 경우, 이 엔드포인트에서는 조회 불가(404)임을 확인한다.
 */
export async function test_api_ai_model_version_get_by_id_and_handle_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. AI 모델 버전 생성
  const versionCreate: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(connection, {
    body: {
      ai_model_id: typia.random<string & tags.Format<"uuid">>(),
      version: "v1.0.0-test",
      version_hash: "sha256:abc1234567890_test",
      artifact_url: "https://s3.example.com/model-obj",
      framework: "PyTorch",
      metadata: JSON.stringify({ label: "for-e2e" }),
    } satisfies IAiModelVersion.ICreate,
  });
  typia.assert(versionCreate);

  // 2. 단일 상세 조회
  const fetched: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.getById(connection, {
    id: versionCreate.id,
  });
  typia.assert(fetched);
  // 3. 주요 필드 일치 검증
  TestValidator.equals("id")(versionCreate.id)(fetched.id);
  TestValidator.equals("ai_model_id")(versionCreate.ai_model_id)(fetched.ai_model_id);
