}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IAiModel } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModel";
import { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";
import typia from "typia";

/**
 * Validate creation and validation rules of AI model version (artifact) registration.
 *
 * This test covers both positive and negative scenarios for the advancedAI.aiModelVersions endpoint:
 *
 * 1. Register prerequisite AI model (parent) to be used in the version registration.
 * 2. Successfully register an AI model version with valid data (all required fields, unique version).
 * 3. Attempt to register a model version with missing required fields (should result in validation error).
 * 4. Attempt to register a model version with invalid field formats (should result in validation error).
 * 5. Attempt to register a duplicate version string for the same parent model (should result in duplicate error).
 *
 * Guarantees business rules: unique (ai_model_id, version), all required fields, correct field types, and proper error reporting.
 */
export async function test_api_ai_model_version_validation_success_and_failure(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register prerequisite AI model
  const modelCreate: IAiModel.ICreate = {
    organization_id: "c1d6a6d8-e671-488a-9dd8-47358f892a12",
    owner_id: "1c3a97f5-7589-4b70-97f5-a083121d799b",
    name: `test-model-${Date.now()}`,
    model_type: "classification",
    description: "A model for tests.",
  };
  const aiModel: IAiModel = await api.functional.advancedAI.aiModels.post(connection, { body: modelCreate });
  typia.assert(aiModel);

  // 2. Successfully register an AI model version with valid data
  const validVersion: IAiModelVersion.ICreate = {
    ai_model_id: aiModel.id,
    version: "v1.0.0",
    version_hash: "abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890",
    artifact_url: "s3://bucket/model/v1.0.0/model.pt",
    framework: "PyTorch",
    metadata: JSON.stringify({ accuracy: 0.95, notes: "Initial release." }),
  };
  const modelVersion: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(connection, { body: validVersion });
  typia.assert(modelVersion);
  TestValidator.equals("model id")(aiModel.id)(modelVersion.ai_model_id);
  TestValidator.equals("version")("v1.0.0")(modelVersion.version);

  // 3. Attempt to create version with missing required field (artifact_url missing)
  const invalidMissingRequired: Omit<IAiModelVersion.ICreate, "artifact_url"> = {
    ai_model_id: aiModel.id,
    version: "v1.0.1",
    version_hash: "badmissing1abcdefabcdefabcdef1234567890abcdef1234567890abcdef1234567890",
    framework: "TensorFlow",
    metadata: "{}",
  };
  await TestValidator.httpError("missing artifact_url")(400)(() =>
    api.functional.advancedAI.aiModelVersions.post(connection, { body: invalidMissingRequired as any }),
  );

  // 4. Attempt to create version with invalid artifact_url format (should be a url, give a bad string)
  const invalidArtifactUrl: IAiModelVersion.ICreate = {
    ai_model_id: aiModel.id,
    version: "v1.0.2",
    version_hash: "baddataabcdefabcdefabcdef1234567890abcdef1234567890abcdef1234567890",
    artifact_url: "not-a-url",
    framework: "PyTorch",
    metadata: undefined,
  };
  await TestValidator.httpError("invalid artifact_url format")(400)(() =>
    api.functional.advancedAI.aiModelVersions.post(connection, { body: invalidArtifactUrl }),
  );

  // 5. Attempt to create a duplicate version for the same model
  await TestValidator.httpError("duplicate version string")(409)(() =>
    api.functional.advancedAI.aiModelVersions.post(connection, { body: validVersion }),
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IAiModelVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiModelVersion";

/**
 * Update an AI model version's metadata and test edge/error cases.
 *
 * Scenario:
 * 1. Create a new AI model version via POST /advancedAI/aiModelVersions.
 * 2. Update metadata field on the created version (PUT /advancedAI/aiModelVersions/{id}), verify response.
 * 3. Attempt to update immutable fields (id, ai_model_id, created_at), expect API to reject with error, or those fields remain unchanged.
 * 4. Try updating a non-existent/invalid version ID, expect error response.
 */
export async function test_api_ai_model_version_update_complete(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new model version
  const created: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(connection, {
    body: {
      ai_model_id: typia.random<string & tags.Format<"uuid">>(),
      version: "v2.0.0",
      version_hash: "abcdef1234567890abcdef",
      artifact_url: "s3://models/my-ai/v2.0.0/model.pt",
      framework: "PyTorch",
      metadata: JSON.stringify({ notes: "Initial version", owner: "tester" }),
    } satisfies IAiModelVersion.ICreate,
  });
  typia.assert(created);

  // 2. Update metadata field (should succeed)
  const updated: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.putById(connection, {
    id: created.id,
    body: {
      metadata: JSON.stringify({ notes: "Update: validated", owner: "testbot" }),
    } satisfies IAiModelVersion.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("id remains after metadata update")(created.id)(updated.id);
  TestValidator.equals("metadata updated")(
    JSON.stringify({ notes: "Update: validated", owner: "testbot" })
  )(updated.metadata ?? "");

  // 3. Attempt to update immutable fields (should fail or fields remain)
  await TestValidator.error("Cannot update immutable fields: id/ai_model_id/created_at")(
    () => api.functional.advancedAI.aiModelVersions.putById(connection, {
      id: created.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        ai_model_id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } as any, // force type error for invalid update
    })
  );

  // 4. Update a version with an invalid/nonexistent ID
  await TestValidator.error("Update with invalid id should fail")(
    () => api.functional.advancedAI.aiModelVersions.putById(connection, {
      id: "00000000-0000-4000-8000-0000000000ff" as string & tags.Format<"uuid">,
      body: {
        metadata: JSON.stringify({ notes: "attempt on invalid" }),
      } satisfies IAiModelVersion.IUpdate,
    })
  );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
