import { ICommon } from "@ORGANIZATION/PROJECT-api/lib/structures/ICommon";
import typia, { tags } from "typia";

/**
 * Delete an AI model version by ID and confirm soft-delete or removal from listing.
 * Also tests error handling when deleting with invalid or non-existent IDs.
 *
 * Scenario Background:
 * - An AI model version must exist before attempting deletion.
 * - Deletion should return a proper soft-deletion record.
 * - The deleted record should be marked or actually removed.
 * - Invalid or non-existent IDs must return an error with correct status handling.
 *
 * Test Process:
 * 1. Create an AI model version (to provide a valid deletion target)
 * 2. Delete the AI model version by its ID
 * 3. Assert correct IIdDeleted structure is returned
 * 4. Attempt to delete with a random (non-existent) UUID, expect proper error/response
 * 5. Attempt to delete with an invalid-format ID, expect validation error
 */
export async function test_api_ai_model_version_delete_by_id_and_handle_errors(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a model version to target for deletion
  const created: IAiModelVersion = await api.functional.advancedAI.aiModelVersions.post(connection, {
    body: {
      ai_model_id: typia.random<string & tags.Format<"uuid">>(),
      version: `v${Math.floor(Math.random()*10000)}`,
      version_hash: typia.random<string>(),
      artifact_url: "s3://example-bucket/model.onnx",
      framework: "TensorFlow",
      metadata: '{"notes": "Test version for delete"}',
    } satisfies IAiModelVersion.ICreate,
  });
  typia.assert(created);

  // 2. Delete the model version (happy path)
  const deleted: ICommon.IIdDeleted = await api.functional.advancedAI.aiModelVersions.eraseById(connection, {
    id: created.id,
  });
