  TestValidator.equals("deleted id")(created.id)(deleted.id);
  TestValidator.equals("delete status")("deleted")(deleted.status.toLowerCase());
  // deleted_at should exist (soft delete evidence)
  if (!deleted.deleted_at) throw new Error("deleted_at is undefined");

  // 3. Try to delete with a non-existent UUID (should fail)
  await TestValidator.httpError("delete non-existent ID should fail")(404)(() =>
    api.functional.advancedAI.aiModelVersions.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 4. Try to delete with an invalid format ID (should be 400)
  await TestValidator.httpError("delete invalid-format ID should fail")(400)(() =>
    api.functional.advancedAI.aiModelVersions.eraseById(connection, {
      id: "not-a-uuid" as any,
    })
  );
}

