 * It covers various filter scenarios, including by dataset name and creation timestamps.
 *
 * Steps:
 * 1. Create several AI training data entries with varying names and timestamps (including at least one unique name).
 * 2. Fetch all datasets using the listing API without filters; verify all records appear and pagination meta is precise.
 * 3. Filter by unique dataset name and check only those returned.
 * 4. Filter by created_from/created_to (date window) and confirm only matching items.
 * 5. Use page/limit (e.g. limit=1) to verify per-page results and empty page edge case.
 * 6. Filter with an impossible name and check for an empty result.
 * 7. Assert shape and structure of all results.
 */
export async function test_api_ai_training_data_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create test data entries
  const now = new Date();
  const earlier = new Date(now.getTime() - 1000 * 60 * 60); // 1 hour ago
  const later = new Date(now.getTime() + 1000 * 60 * 60);   // 1 hour later
  const uniqueName = `test-E2E-unique-${Math.random().toString(36).slice(2,8)}`;

  const records: IAITrainingData[] = [];

  // Entry 1: unique name, "now"
  records.push(await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      name: uniqueName,
      version: "v1",
      source_uri: "s3://bucket/unique-dataset.csv",
      schema_hash: "HASH-001",
      record_count: 10,
      ai_model_id: null,
    } satisfies IAITrainingData.ICreate,
  }));
  // Entry 2: another, "earlier"
  records.push(await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      name: "test-common",
      version: "v2",
      source_uri: "s3://bucket/common.csv",
      schema_hash: "HASH-002",
      record_count: 20,
      ai_model_id: null,
    } satisfies IAITrainingData.ICreate,
  }));
  // Entry 3: another, "later"
  records.push(await api.functional.advancedAI.aiTrainingData.post(connection, {
    body: {
      name: "test-common",
      version: "v3",
      source_uri: "s3://bucket/common-later.csv",
      schema_hash: "HASH-003",
      record_count: 30,
      ai_model_id: null,
    } satisfies IAITrainingData.ICreate,
  }));
  // manual wait adjustment for created_at if needed (assume at least seconds difference)

  // 2. List all (no filter) - check result includes all created
  const allResult: IPageIAiTrainingData = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: {},
  });
  typia.assert(allResult);
  const allIds = new Set(records.map(r => r.id));
  for (const item of allResult.data) {
    typia.assert(item);
  }
  for (const r of records) {
    TestValidator.predicate(`All record IDs present: ${r.id}`)(allResult.data.some(item => item.id === r.id));
  }
  TestValidator.equals("pagination.records should cover at least created test items")(allResult.pagination.records >= records.length)(true);

  // 3. Filter by unique name
  const filteredByName: IPageIAiTrainingData = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { name: uniqueName },
  });
  typia.assert(filteredByName);
  TestValidator.equals("filter by unique name return 1")(filteredByName.data.length)(1);
  TestValidator.equals("filtered name matches")(filteredByName.data[0].name)(uniqueName);

  // 4. Filter by date window (created_from, created_to)
  // Use now - 30min as from, now + 30min as to: should match entry 1 (uniqueName)
  const windowFrom = new Date(now.getTime() - 1000 * 60 * 30).toISOString();
  const windowTo = new Date(now.getTime() + 1000 * 60 * 30).toISOString();
  const filteredByDate: IPageIAiTrainingData = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { created_from: windowFrom, created_to: windowTo },
  });
  typia.assert(filteredByDate);
  TestValidator.predicate("only 1 or 2 records in current window?")(filteredByDate.data.length <= 2 && filteredByDate.data.length > 0);
  for (const d of filteredByDate.data) {
    TestValidator.predicate("created_at date range")(d.created_at >= windowFrom && d.created_at <= windowTo);
  }

  // 5. Pagination test: limit=1 (page size 1), page 1/2/3/... and empty pages
  for (let p = 1; p <= records.length + 1; ++p) {
    const paged: IPageIAiTrainingData = await api.functional.advancedAI.aiTrainingData.patch(connection, {
      body: { limit: 1, page: p },
    });
    typia.assert(paged);
    if (p <= records.length) {
      TestValidator.equals(`paged ${p} has 1 record`)(paged.data.length)(1);
    } else {
      TestValidator.equals(`paged ${p} is empty`)(paged.data.length)(0);
    }
  }

  // 6. Impossible filter (no match)
  const nonsense: IPageIAiTrainingData = await api.functional.advancedAI.aiTrainingData.patch(connection, {
    body: { name: "NO-SUCH-NAME-EVER-!!" },
  });
  typia.assert(nonsense);
  TestValidator.equals("empty for nonsense filter")(nonsense.data.length)(0);
}

