import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IPageIMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessageThread";
import typia from "typia";

/**
 * Test listing message threads with pagination and search.
 *
 * This test covers advanced listing, search, and sorting features for message threads (conversations). It ensures that filtering, ordering, and paginated listing work correctly and reliably in mailbox/audit-style scenarios.
 *
 * 1. Create several message threads, each with a unique subject and controlled timestamps for sorting validation.
 * 2. List threads (patch endpoint) with broad filter to confirm all created threads are listed.
 * 3. Search by partial subject to confirm fuzzy matching works.
 * 4. Paginate: fetch only N per page and verify pages/ordering are honored.
 * 5. Search for a non-existent subject and expect the results set to be empty.
 * 6. Validate that sort order matches created_at as requested.
 */
export async function test_api_communicationReview_messageThreads_list_search_pagination_sort(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create multiple message threads
  const subjects = [
    "foo exclusive sort a",
    "bar pagetest b",
    "baz searchTest c",
    "qux sortfoo d",
  ];
  const threads: IMessageThread[] = [];
  for (const subject of subjects) {
    const thread = await api.functional.communicationReview.messageThreads.post(
      connection,
      {
        body: {
          subject,
        } satisfies IMessageThread.ICreate,
      },
    );
    typia.assert(thread);
    threads.push(thread);
    // Small delay to ensure different created_at timestamps if needed
    await new Promise((res) => setTimeout(res, 15));
  }

  // 2. List all threads, no filter (should include all created, sorted by created_at desc by default)
  const allResult: IPageIMessageThread =
    await api.functional.communicationReview.messageThreads.patch(connection, {
      body: {
        limit: 10,
        page: 1,
      } satisfies IMessageThread.IRequest,
    });
  typia.assert(allResult);

  // Confirm all created subjects are in the results (may have system threads as well)
  const resultSubjects = allResult.data.map((t) => t.subject);
  for (const subject of subjects) {
    TestValidator.equals("subject in list")(
      true,
    )(resultSubjects.includes(subject));
  }

  // 3. Search by partial subject
  const searchSubject = "pagetest";
  const searchResult: IPageIMessageThread =
    await api.functional.communicationReview.messageThreads.patch(connection, {
      body: {
        subject: searchSubject,
        limit: 10,
      } satisfies IMessageThread.IRequest,
    });
  typia.assert(searchResult);
  // All results should include the search term
  for (const thread of searchResult.data) {
    TestValidator.equals("partial subject match")(
      true,
    )(thread.subject.toLowerCase().includes(searchSubject));
  }

  // 4. Paginate: fetch only 2 per page, check correct subjects and page info
  const limit = 2;
  const paged1: IPageIMessageThread =
    await api.functional.communicationReview.messageThreads.patch(connection, {
      body: {
        limit,
        page: 1,
        sort_field: "created_at",
        sort_order: "asc",
      } satisfies IMessageThread.IRequest,
    });
  typia.assert(paged1);
  TestValidator.equals("page 1 count == 2")(limit)(paged1.data.length);
  TestValidator.equals("pagination current == 1")(1)(paged1.pagination.current);

  const paged2: IPageIMessageThread =
    await api.functional.communicationReview.messageThreads.patch(connection, {
      body: {
        limit,
        page: 2,
        sort_field: "created_at",
        sort_order: "asc",
      } satisfies IMessageThread.IRequest,
    });
  typia.assert(paged2);
  TestValidator.equals("page 2 count <= 2")(
    true,
  )(paged2.data.length <= limit);
  TestValidator.equals("pagination current == 2")(2)(paged2.pagination.current);

  // 5. Search for non-existing thread (expect empty set)
  const noResult: IPageIMessageThread =
    await api.functional.communicationReview.messageThreads.patch(connection, {
      body: {
        subject: "subject-not-in-db-xyz",
        limit: 10,
      } satisfies IMessageThread.IRequest,
    });
  typia.assert(noResult);
  TestValidator.equals("no results for non-existent subject")(0)(noResult.data.length);

  // 6. Validate order (ascending by created_at on paged1 & paged2)
  const createdAts = [...paged1.data, ...paged2.data].map((m) => m.created_at);
  const isOrdered = createdAts.every(
    (t, i, arr) => i === 0 || t >= arr[i - 1],
  );
  TestValidator.equals("ascending order by created_at")(true)(isOrdered);
}

