import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";

import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IPageIMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMessage";

/**
 * Test listing/searching messages with filters and pagination.
 *
 * This test covers these scenarios:
 * - Several message threads are created.
 * - Multiple messages are inserted into different threads with various senders, content, and message types.
 * - Messages are listed with filters: by thread, by sender, by type, by content keyword.
 * - A filter is used with a random value that matches no messages; the result should be empty.
 * - Pagination is tested (page, limit) to confirm boundaries and correct ordering (asc, desc).
 *
 * Steps:
 * 1. Create two message threads (A and B)
 * 2. Post messages into both threads with different sender_user_ids, types, and times
 * 3. List messages by thread filter and check only those in that thread are found
 * 4. List messages by sender filter and check only those sent by the sender are found
 * 5. List messages by message_type filter
 * 6. List by content substring/keyword
 * 7. Attempt to filter with random thread_id, sender_user_id, and content that should match nothing; expect an empty result
 * 8. Post additional messages, then list with pagination: test first, middle, last pages and limit values
 * 9. Test ordering (sent_at asc/desc) & check order of returned results
 */
export async function test_api_communicationReview_messages_list_search_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create two message threads (A and B)
  const threadA: IMessageThread =
    await api.functional.communicationReview.messageThreads.post(connection, {
      body: {
        subject: "Thread Subject A",
      } satisfies IMessageThread.ICreate,
    });
  typia.assert(threadA);

  const threadB: IMessageThread =
    await api.functional.communicationReview.messageThreads.post(connection, {
      body: {
        subject: "Thread Subject B",
      } satisfies IMessageThread.ICreate,
    });
  typia.assert(threadB);

  // 2. Post messages in both threads with different senders and types
  const senderIdA = threadA.created_by_user_id;
  const senderIdB = threadB.created_by_user_id;
  // Message sets (at least 3 per thread for pagination test)
  const messages: IMessage[] = [];
  for (let i = 0; i < 3; ++i) {
    const messageA: IMessage = await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: threadA.id,
        content: `Hello from A #${i}`,
        message_type: i % 2 === 0 ? "user" : "notification",
      } satisfies IMessage.ICreate,
    });
    typia.assert(messageA);
    messages.push(messageA);

    const messageB: IMessage = await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: threadB.id,
        content: `Hello from B #${i}`,
        message_type: i % 2 === 0 ? "user" : "system",
      } satisfies IMessage.ICreate,
    });
    typia.assert(messageB);
    messages.push(messageB);
  }

  // 3. List messages by thread filter (threadA)
  {
    const out: IPageIMessage = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: threadA.id } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    for (const msg of out.data)
      TestValidator.equals("thread_id")(threadA.id)(msg.thread_id);
  }

  // 4. List messages by sender filter (senderIdB)
  {
    const out: IPageIMessage = await api.functional.communicationReview.messages.patch(connection, {
      body: { sender_user_id: senderIdB } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    for (const msg of out.data)
      TestValidator.equals("sender_user_id")(senderIdB)(msg.sender_user_id);
  }

  // 5. List messages by message_type
  {
    const out: IPageIMessage = await api.functional.communicationReview.messages.patch(connection, {
      body: { message_type: "notification" } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    for (const msg of out.data)
      TestValidator.equals("message_type")("notification")(msg.message_type);
  }

  // 6. List by content substring
  {
    const keyword = "from B #1";
    const out: IPageIMessage = await api.functional.communicationReview.messages.patch(connection, {
      body: { content: keyword } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    // All returned data should contain the keyword (simple substring match)
    for (const msg of out.data)
      TestValidator.equals("content includes keyword")(true)(msg.content.includes(keyword));
  }

  // 7. Filter with random thread_id, sender_user_id, content (expect empty)
  {
    // Use a random uuid (not any real id)
    const out1 = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: "9b58e89d-a11d-11ee-b9d1-000000000000" } satisfies IMessage.IRequest,
    });
    typia.assert(out1);
    TestValidator.equals("empty result")(0)(out1.data.length);

    const out2 = await api.functional.communicationReview.messages.patch(connection, {
      body: { sender_user_id: "9b58e89d-a11d-11ee-b9d1-000000000000" } satisfies IMessage.IRequest,
    });
    typia.assert(out2);
    TestValidator.equals("empty result")(0)(out2.data.length);

    const out3 = await api.functional.communicationReview.messages.patch(connection, {
      body: { content: "no-such-content-xyz123" } satisfies IMessage.IRequest,
    });
    typia.assert(out3);
    TestValidator.equals("empty result")(0)(out3.data.length);
  }

  // 8. Post more messages for pagination boundary and order tests
  const threadC = await api.functional.communicationReview.messageThreads.post(connection, {
    body: { subject: "Thread Subject C" } satisfies IMessageThread.ICreate,
  });
  typia.assert(threadC);

  // Post 10 messages to threadC for pagination
  const messagesC: IMessage[] = [];
  for (let i = 0; i < 10; ++i) {
    const m: IMessage = await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: threadC.id,
        content: `Paginated message #${i}`,
        message_type: "user",
      } satisfies IMessage.ICreate,
    });
    typia.assert(m);
    messagesC.push(m);
  }

  // List with limit/page, test first page
  {
    const out = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: threadC.id, limit: 5, page: 1, sort_field: "sent_at", sort_order: "asc" } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    TestValidator.equals("limit=5")(5)(out.data.length);
    TestValidator.equals("page=1")(1)(out.pagination.current);
    // Confirm order: ascending
    for (let i = 1; i < out.data.length; ++i) {
      const prevTime = new Date(out.data[i-1].sent_at).getTime();
      const nowTime = new Date(out.data[i].sent_at).getTime();
      TestValidator.equals("ascending sent_at")(true)(prevTime <= nowTime);
    }
  }

  // Middle page
  {
    const out = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: threadC.id, limit: 4, page: 2, sort_field: "sent_at", sort_order: "asc" } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    TestValidator.equals("limit=4")(4)(out.data.length);
    TestValidator.equals("page=2")(2)(out.pagination.current);
  }

  // Last page (should have 2 messages)
  {
    const out = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: threadC.id, limit: 4, page: 3, sort_field: "sent_at", sort_order: "asc" } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    TestValidator.equals("page=3")(3)(out.pagination.current);
    TestValidator.equals("last page length")(2)(out.data.length);
  }

  // Descending order
  {
    const out = await api.functional.communicationReview.messages.patch(connection, {
      body: { thread_id: threadC.id, limit: 5, page: 1, sort_field: "sent_at", sort_order: "desc" } satisfies IMessage.IRequest,
    });
    typia.assert(out);
    for (let i = 1; i < out.data.length; ++i) {
      const prevTime = new Date(out.data[i-1].sent_at).getTime();
      const nowTime = new Date(out.data[i].sent_at).getTime();
      TestValidator.equals("descending sent_at")(true)(prevTime >= nowTime);
    }
  }
}

