import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import typia, { tags } from "typia";

/**
 * Retrieve a single message by valid ID and check all data matches what was sent.
 * Try to retrieve a message by an invalid/non-existent ID and expect a 404 error.
 *
 * 1. Create a thread to send a message.
 * 2. Create a message in the thread.
 * 3. Retrieve the message by ID and check that all message data matches.
 * 4. Attempt to retrieve a message by invalid/non-existent ID, expect a 404 error.
 */
export async function test_api_message_get_message_by_id_success_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a thread to send a message
  const threadSubject = "Test Thread Subject";
  const thread: IMessageThread =
    await api.functional.communicationReview.messageThreads.post(connection, {
      body: {
        subject: threadSubject,
      } satisfies IMessageThread.ICreate,
    });
  typia.assert(thread);

  // 2. Create a message in the thread
  const messageContent = "This is a test message";
  const messageType = "user";
  const message: IMessage =
    await api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: thread.id,
        content: messageContent,
        message_type: messageType,
      } satisfies IMessage.ICreate,
    });
  typia.assert(message);

  // 3. Retrieve the message by ID and check all data matches
  const found: IMessage =
    await api.functional.communicationReview.messages.getById(connection, {
      id: message.id,
    });
