  // 4. Attempt to retrieve a message by invalid/non-existent ID
  const invalidId = "00000000-0000-0000-0000-000000000000" as string & tags.Format<"uuid">;
  await TestValidator.httpError("not found message")(404)(() =>
    api.functional.communicationReview.messages.getById(connection, {
      id: invalidId,
    }),
  );
}

