import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
import { IMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessage";
import typia from "typia";

/**
 * E2E test for sending messages in communication threads, covering both success and error cases.
 *
 * Scenario
 * 1. Create a message thread for baseline testing.
 * 2. Send a new message to the thread – verify creation and fields.
 * 3. Fetch the created thread and ensure message is attached via relationships.
 * 4. Attempt to send a message to a non-existent thread – check error response.
 * 5. Attempt to send a message with missing required fields (content, message_type, thread_id) – validate error responses.
 */
export async function test_create_message_success_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new thread as message target
  const thread: IMessageThread = await api.functional.communicationReview.messageThreads.post(
    connection,
    {
      body: {
        subject: "Test subject for E2E message thread",
      },
    },
  );
  typia.assert(thread);

  // 2. Send a message to the new thread
  const messageInput: IMessage.ICreate = {
    thread_id: thread.id,
    content: "First message body.",
    message_type: "user",
  };
  const message: IMessage = await api.functional.communicationReview.messages.post(
    connection,
    { body: messageInput },
  );
  typia.assert(message);
  TestValidator.equals("thread attached")(thread.id)(message.thread_id);
  TestValidator.equals("content")(messageInput.content)(message.content);
  TestValidator.equals("message_type")(messageInput.message_type)(message.message_type);

  // 3. Attempt to send message to non-existent thread
  await TestValidator.httpError("missing thread")(404)(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: "00000000-0000-4000-8000-000000000000", // unlikely to exist
        content: "ghost message",
        message_type: "user",
      },
    }),
  );

  // 4. Missing required field: content
  await TestValidator.error("missing content")(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: thread.id,
        // content: "", // omitted
        message_type: "user",
      } as any,
    }),
  );

  // 5. Missing required field: message_type
  await TestValidator.error("missing message_type")(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        thread_id: thread.id,
        content: "message with missing type",
        // message_type omitted
      } as any,
    }),
  );

  // 6. Missing required field: thread_id
  await TestValidator.error("missing thread_id")(() =>
    api.functional.communicationReview.messages.post(connection, {
      body: {
        // thread_id omitted
        content: "message with missing thread",
        message_type: "user",
      } as any,
    }),
  );
}

