/**
 * Validate updating the content of an existing message, ensuring the update is successful and changes are tracked.
 * 
 * Also test edge cases including updating with invalid fields and attempting to update a non-existent message ID, verifying error handling and HTTP status codes.
 *
 * 1. Create a message thread.
 * 2. Create a message in the thread.
 * 3. Update the content of the message and verify the update is reflected.
 * 4. Attempt to update with invalid fields (e.g., excessively long content, invalid type) and verify error handling/ge.
 * 5. Attempt to update a non-existent message ID and verify a 404 or appropriate error.
 */
export async function test_api_message_update_success_and_edge_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a message thread
  const thread: IMessageThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: "Thread for update message E2E test",
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(thread);

  // 2. Create a message in the thread
  const message: IMessage = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: thread.id,
      content: "Original message content.",
      message_type: "user",
    } satisfies IMessage.ICreate,
  });
  typia.assert(message);

  // 3. Update the content of the message
  const updatedContent = "Updated message content.";
  const updateResult: IMessage = await api.functional.communicationReview.messages.putById(connection, {
    id: message.id,
    body: {
      content: updatedContent,
    } satisfies IMessage.IUpdate,
  });
  typia.assert(updateResult);
