  // 4. Attempt to update with invalid fields (overly long content)
  await TestValidator.httpError("update with excessively long content should fail")(400)(() =>
    api.functional.communicationReview.messages.putById(connection, {
      id: message.id,
      body: {
        content: "x".repeat(10001), // assuming max length of 10000
      } satisfies IMessage.IUpdate,
    })
  );

  // 5. Attempt to update a non-existent message ID
  await TestValidator.httpError("update on non-existent message ID should fail")(404)(() =>
    api.functional.communicationReview.messages.putById(connection, {
      id: "11111111-2222-3333-4444-555555555555" as string & tags.Format<"uuid">,
      body: {
        content: "Should not work",
      } satisfies IMessage.IUpdate,
    })
  );
}

