/**
 * 메시지 삭제(아카이브) 기능의 정상 동작 및 예외 처리 검증
 *
 * 이 테스트는 사용자가 메시지를 삭제(아카이브)할 때 실제로 해당 메시지가 더 이상 일반 조회에 노출되지 않거나 archived 플래그가 true로 변경됨을 검증합니다. 또한 존재하지 않는 메시지를 삭제 시도할 때 적절한 오류 및 상태 코드(예: 404)를 반환하는 지도 확인합니다.
 *
 * 시나리오:
 * 1. 메시지 스레드를 생성한다.
 * 2. 생성된 스레드에 메시지를 등록한다.
 * 3. 해당 메시지를 삭제(아카이브)한다.
 * 4. 메시지 삭제 결과의 archived가 true임을 검증한다.
 * 5. 존재하지 않는 messageId로 삭제 시도를 하여, 적절한 404 오류를 검증한다.
 */
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IMessageThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IMessageThread";
