  // 1. 메시지 스레드 생성
  const thread: IMessageThread = await api.functional.communicationReview.messageThreads.post(connection, {
    body: {
      subject: "e2e-test thread",
    } satisfies IMessageThread.ICreate,
  });
  typia.assert(thread);

  // 2. 메시지 등록
  const message: IMessage = await api.functional.communicationReview.messages.post(connection, {
    body: {
      thread_id: thread.id,
      content: "삭제될 메시지입니다.",
      message_type: "user",
    } satisfies IMessage.ICreate,
  });
  typia.assert(message);

  // 3. 메시지 삭제(아카이브)
  const deleted: IMessage = await api.functional.communicationReview.messages.eraseById(connection, {
    id: message.id,
  });
  typia.assert(deleted);

  // 4. 삭제(archive) 플래그가 true인지 확인
