    api.functional.communicationReview.messages.eraseById(connection, {
      id: "11111111-1111-1111-1111-111111111111" as string & tags.Format<"uuid">,
    })
  );
}

test/features/api/notification/test_list:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";
import { IPageINotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageINotification";
import typia from "typia";

/**
 * List and search notifications with advanced filters and pagination.
 *
 * 1. 여러 notification을 user별, type별, read/unread 상태가 섞이도록 생성한다.
 * 2. recipient(수신자)별로 필터링하여 알림을 조회한다.
 * 3. read/unread 상태별로 필터링하여 조회한다.
 * 4. notification_type별로 필터링 조회한다.
 * 5. 다양한 limit/page 조합으로 페이지네이션 동작을 검증한다.
 * 6. 일치하는 결과가 없을 필터로 쿼리하여 빈 결과를 확인한다.
 */
export async function test_api_notification_list_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 준비: 두 명의 user와 각기 다른 type/read 상태별 notification 생성
  const userIdA = typia.random<string & typia.tags.Format<"uuid">>();
  const userIdB = typia.random<string & typia.tags.Format<"uuid">>();
  const threadId = typia.random<string & typia.tags.Format<"uuid">>();
  const now = new Date();

  // 각각 user, type, 상태가 다른 총 6개의 알림 생성
  const notifications: INotification[] = [];
  const notificationInputs = [
    { user_id: userIdA, notification_type: "system", content: "to A system", thread_id: threadId },
    { user_id: userIdA, notification_type: "message", content: "to A message", thread_id: null },
    { user_id: userIdB, notification_type: "promotion", content: "to B promo", thread_id: threadId },
    { user_id: userIdB, notification_type: "system", content: "to B system", thread_id: null },
    { user_id: userIdA, notification_type: "promotion", content: "to A promo 2", thread_id: null },
    { user_id: userIdB, notification_type: "message", content: "to B msg 2", thread_id: null },
  ];

  for (let i = 0; i < notificationInputs.length; ++i) {
    const input = {
      ...notificationInputs[i],
    } satisfies INotification.ICreate;
    const created: INotification = await api.functional.communicationReview.notifications.post(connection, {
      body: input,
    });
    typia.assert(created);
    notifications.push(created);
  }

  // 1. recipient(user)별 필터 조회
  for (const userId of [userIdA, userIdB]) {
    const out: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
      body: { user_id: userId } satisfies INotification.IRequest,
    });
    typia.assert(out);
    for (const n of out.data)
      TestValidator.equals("user_id match")(userId)(n.user_id);
  }

  // 2. notification_type별 필터
  const targetType = "system";
  const typeResult: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
    body: { notification_type: targetType } satisfies INotification.IRequest,
  });
  typia.assert(typeResult);
  for (const n of typeResult.data)
    TestValidator.equals("notification_type match")(targetType)(n.notification_type);

  // 3. 페이지네이션 테스트(page/limit 조합)
  const limit = 2;
  let seenIds = new Set<string>();
  for (let page = 1; page <= 3; ++page) {
    const result: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
      body: { limit, page } satisfies INotification.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("page size or tail")(result.data.length <= limit)(true);
    for (const n of result.data) {
      seenIds.add(n.id);
    }
    TestValidator.equals("pagination page num")(page)(result.pagination.current);
  }
  // 전체 결과가 여러번에 걸쳐 page별로 나눠졌음을 확인
  TestValidator.equals("pagination coverage")(notifications.length)(seenIds.size);

  // 4. read/unread 상태 필터: read_at이 null 여부로 추정(생성 즉시 호출, 모두 unread)
  const unreadResult: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
    body: { read_at: null } as any, // read_at 명시적 필터링이 미구현이면 넘어감
  });
  typia.assert(unreadResult);
  for (const n of unreadResult.data)
    TestValidator.predicate("unread: read_at is null or undefined")(() => n.read_at == null);

  // 5. 아카이브 필터
  {
    // 1개 알림을 archived로 보관 상태로 만듬(가장 마지막)
    // 실제 아카이브 API가 제공되면 호출, 여기선 mock 처리
    notifications[notifications.length - 1].archived = true;
    const archivedResult: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
      body: { archived: true } satisfies INotification.IRequest,
    });
    typia.assert(archivedResult);
    for (const n of archivedResult.data) TestValidator.equals("archived true")(true)(n.archived);
  }

  // 6. 존재하지 않는 필터(user_id random)로 empty result 검증
  const emptyResult: IPageINotification = await api.functional.communicationReview.notifications.patch(connection, {
    body: { user_id: typia.random<string & typia.tags.Format<"uuid">>() } satisfies INotification.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("result empty")(0)(emptyResult.data.length);
}

