test/features/api/notification/test_upda:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia from "typia";
import { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";

/**
 * Update notification and verify success and error handling.
 *
 * 1. Create a notification (prerequisite)
 * 2. Update the notification with valid data (e.g., mark as read, change content & archived)
 * 3. Verify updated fields applied correctly
 * 4. Attempt to update with missing/invalid fields (e.g., content = empty string, notification_type invalid type, archived null)
 *    - Expect validation or business rule errors
 * 5. Attempt to update a non-existent notification ID
 *    - Expect error (e.g., 404 Not Found)
 */
export async function test_api_notification_update_success_failure_and_validation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a notification
  const now = new Date().toISOString();
  const created: INotification = await api.functional.communicationReview.notifications.post(connection, {
    body: {
      user_id: typia.random<string>(),
      notification_type: "system",
      content: "This is a test notification.",
      thread_id: null,
    } satisfies INotification.ICreate,
  });
  typia.assert(created);

  // 2. Update the notification: mark as read, change content, set archived = true
  const updateBody: INotification.IUpdate = {
    content: "Updated notification content!",
    read_at: now,
    archived: true,
  };
  const updated: INotification = await api.functional.communicationReview.notifications.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("id should not change")(created.id)(updated.id);
  TestValidator.equals("content updated")(updateBody.content)(updated.content);
  TestValidator.equals("archived updated")(updateBody.archived)(updated.archived);
  TestValidator.equals("read_at updated")(updateBody.read_at)(updated.read_at);

  // 3. Attempt with missing/invalid fields
  await TestValidator.error("empty content")(async () => {
    await api.functional.communicationReview.notifications.putById(connection, {
      id: created.id,
      body: { content: "" },
    });
  });

  await TestValidator.error("invalid type for archived")(async () => {
    await api.functional.communicationReview.notifications.putById(connection, {
      id: created.id,
      body: { archived: null as any },
    });
  });

  // Notification type with illegal value
  await TestValidator.error("bad notification_type")(async () => {
    await api.functional.communicationReview.notifications.putById(connection, {
      id: created.id,
      body: { notification_type: "" },
    });
  });

  // 4. Attempt to update non-existent notification
  await TestValidator.httpError("not found")(404)(() =>
    api.functional.communicationReview.notifications.putById(connection, {
      id: "00000000-0000-0000-0000-000000000000",
      body: { content: "will not work" },
    })
  );
}

test/features/api/notification/test_dele:
import api from "@ORGANIZATION/PROJECT-api";
import { TestValidator } from "@nestia/e2e";
import typia from "typia";
import { INotification } from "@ORGANIZATION/PROJECT-api/lib/structures/INotification";
import { tags } from "typia";

/**
 * Test deleting (archiving) an existing notification and handling error cases on deletion
 *
 * 1. Create a notification using POST /communicationReview/notifications
 * 2. Delete the created notification using DELETE /communicationReview/notifications/{id}
 * 3. Validate the API response: archived=true, and that the notification cannot be deleted again (expect error/404)
 * 4. Attempt to delete a non-existent notification id and expect error/404
 */
export async function test_delete_notification_success_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a notification
  const notificationBody: INotification.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    notification_type: "system",
    content: "Test notification for deletion",
  };
  const created: INotification = await api.functional.communicationReview.notifications.post(connection, {
    body: notificationBody,
  });
  typia.assert(created);

  // 2. Delete the created notification (archive)
  const deleted: INotification = await api.functional.communicationReview.notifications.eraseById(connection, {
    id: created.id,
  });
  typia.assert(deleted);
  TestValidator.equals("archived=true after deletion")(true)(deleted.archived);
  TestValidator.equals("deleted id matches created")(created.id)(deleted.id);

  // 3. Attempt to delete again - must fail with 404 or error
  await TestValidator.httpError("delete again should 404")(404)(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: created.id,
    })
  );

  // 4. Attempt to delete a random, non-existent notification id
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("delete non-existent notification should 404")(404)(() =>
    api.functional.communicationReview.notifications.eraseById(connection, {
      id: randomId,
    })
  );
}

test/features/api/review/test_list_searc:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";
import { IPageIReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReview";
import typia from "typia";

/**
 * 다양한 필터(상품, 작성자, 실구매, 언어 등)와 페이지네이션을 이용해 리뷰 리스트 및 검색을 검증합니다.
 *
 * [비즈니스 시나리오]
 * - 리뷰 검색/목록은 다양한 조건 필터와 페이지네이션 UI의 핵심입니다.
 * - 서비스 운영/분석/관리 목적상 상품별, 작성자별, 실구매별, 언어별 등 다수 조건에서 페이징 결과가 정확히 반환되어야 합니다.
 *
 * [시나리오 순서]
 * 1. 여러 상품, 여러 유저/조건 조합으로 리뷰 여러 건 생성
 * 2. 각종 조건(상품ID, 작성자ID, 실구매여부, 언어 등)으로 검색하여 결과 데이터 및 페이징 검증
 * 3. 아무 리뷰와도 매칭되지 않는 조건(존재하지 않는 상품ID 등)으로 검색했을 때 empty 반환 확인
 * 4. 각 케이스마다 반환 리스트, pagination 필드가 정확히 기대와 일치하는지 검증
 */
export async function test_api_review_list_search_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. 여러 리뷰 생성: 각기 다른 product/user/language/verified_purchase 조합
  const users = [
    crypto.randomUUID(),
    crypto.randomUUID(),
  ];
  const products = [
    crypto.randomUUID(),
    crypto.randomUUID(),
  ];
  // 샘플 데이터 - 4건 생성
  const created: IReview[] = [];
  for (let i = 0; i < 4; ++i) {
    const review: IReview = await api.functional.communicationReview.reviews.post(
      connection,
      {
        body: {
          user_id: users[i % 2],
          product_id: products[Math.floor(i / 2)],
          content: `리뷰${i}: 내용`,
          language_code: i % 2 === 0 ? "ko" : "en",
          verified_purchase: i % 2 === 0,
        } satisfies IReview.ICreate,
      },
    );
    typia.assert(review);
    created.push(review);
  }

  // 2. product_id로 검색(각 상품별)
  for (const product_id of products) {
    const resp: IPageIReview = await api.functional.communicationReview.reviews.patch(
      connection,
      {
        body: { product_id } satisfies IReview.IRequest,
      },
    );
    typia.assert(resp);
    // data의 product_id가 모두 동일
    resp.data.forEach((r) =>
      TestValidator.equals("product match")(String(product_id))(String(r.product_id)),
    );
    // count 체크
    TestValidator.equals("records count")(
      resp.data.length,
    )(
      resp.data.length,
    );
  }

  // 3. user_id로 검색(각 유저별)
  for (const user_id of users) {
    const resp: IPageIReview = await api.functional.communicationReview.reviews.patch(
      connection,
      {
        body: { user_id } satisfies IReview.IRequest,
      },
    );
    typia.assert(resp);
    resp.data.forEach((r) =>
      TestValidator.equals("user match")(String(user_id))(String(r.user_id)),
    );
  }

  // 4. 언어별 검색
  for (const language_code of ["ko", "en"]) {
    const resp: IPageIReview = await api.functional.communicationReview.reviews.patch(
      connection,
      {
        body: { language_code } satisfies IReview.IRequest,
      },
    );
    typia.assert(resp);
    resp.data.forEach((r) =>
      TestValidator.equals("lang match")(language_code)(r.language_code),
    );
  }

  // 5. 실구매(true)/비실구매(false)별
  for (const verified_purchase of [true, false]) {
    const resp: IPageIReview = await api.functional.communicationReview.reviews.patch(
      connection,
      {
        body: { verified_purchase } satisfies IReview.IRequest,
      },
    );
    typia.assert(resp);
    resp.data.forEach((r) =>
      TestValidator.equals("verified_purchase match")(verified_purchase)(
        r.verified_purchase,
      ),
    );
  }

  // 6. 페이징 - limit 2, 각각 page 1/2
  const pagingResp1: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    {
      body: { limit: 2, page: 1 } satisfies IReview.IRequest,
    },
  );
  typia.assert(pagingResp1);
  TestValidator.equals("page1 length")(2)(pagingResp1.data.length);

  const pagingResp2: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    {
      body: { limit: 2, page: 2 } satisfies IReview.IRequest,
    },
  );
  typia.assert(pagingResp2);
  // page2: 남은 수(총 4건 생성)
  TestValidator.equals("page2 length")(2)(pagingResp2.data.length);

  // 7. 매칭 없는 조건 조회 (존재하지 않는 product/user)
  const emptyProductResp: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    {
      body: { product_id: crypto.randomUUID() } satisfies IReview.IRequest,
    },
  );
  typia.assert(emptyProductResp);
  TestValidator.equals("empty product search")([] as IReview[])(emptyProductResp.data);

  const emptyUserResp: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    {
      body: { user_id: crypto.randomUUID() } satisfies IReview.IRequest,
    },
  );
  typia.assert(emptyUserResp);
  TestValidator.equals("empty user search")([] as IReview[])(emptyUserResp.data);

  // 8. pagination 필드 일관성 & 전체건수 체크
  const allResp: IPageIReview = await api.functional.communicationReview.reviews.patch(
    connection,
    {
      body: {} satisfies IReview.IRequest,
    },
  );
  typia.assert(allResp);
  TestValidator.equals("pagination.records")(created.length)(allResp.pagination.records);
  TestValidator.equals("pagination.pages")(
    Math.ceil(created.length / allResp.pagination.limit),
  )(allResp.pagination.pages);
}

