/**
 * Validate fetching a review by its ID and error when fetching a non-existent review.
 *
 * This test ensures:
 * 1. A review can be created via POST /communicationReview/reviews, and then successfully fetched by its ID.
 * 2. The fetched review must match the originally created review data and satisfy IReview structure.
 * 3. An attempt to fetch a non-existent review by random UUID returns 404 Not Found error.
 *
 * Steps:
 * 1. Create a review (store the ID and body for check).
 * 2. Fetch the review by its ID; verify all expected fields and data integrity.
 * 3. Try to fetch a review with random UUID; assert that 404 error is returned.
 */
export async function test_api_review_get_by_id_success_and_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a review
  const createBody: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
