  // 3. Try to fetch a non-existent review
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("not found (non-existent review)")(404)(() =>
    api.functional.communicationReview.reviews.getById(connection, { id: nonExistentId }),
  );
}

