import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";
import typia from "typia";

/**
 * 신규 리뷰 작성과 유효성 검증 통합 테스트.
 *
 * 새로운 리뷰를 모든 필수 필드(user_id, product_id, content, language_code, verified_purchase)를 포함하여 정상적으로 생성할 수 있는지 검증합니다.
 * 생성 후 해당 리뷰가 재검색 시 정상적으로 존재/조회되는지 확인하며,
 * 필수 필드 누락/비정상값(예: 유효하지 않은 UUID, 빈 문자열, 잘못된 언어코드 등) 입력 시 서버가 적절하게 validation 에러(400)을 반환하는지 추가 검증합니다.
 *
 * 1. 모든 필수 필드를 포함한 정상 생성 요청 후 반환값 구조 및 필드 일관성 검증
 * 2. 생성된 리뷰가 동일 product_id, user_id로 재조회 시 존재하는지 확인(필요시 API 활용)
 * 3. 각 필수 입력값 누락/잘못된 데이터로 생성 시도 → 400 등 validation 에러 응답인지 확인
 */
export async function test_api_review_create_success_and_validation(
  connection: api.IConnection,
): Promise<void> {
  // 1. 정상 생성 요청
  const body: IReview.ICreate = {
    user_id: "3ce8c802-a91c-4472-bd2d-156eb8e49bbf",
    product_id: "b756dafe-ff2d-437f-91d1-5c16fe8cafd1",
    content: "제품이 훌륭합니다. 적극 추천!",
    language_code: "ko",
    verified_purchase: true,
  };
  const review: IReview = await api.functional.communicationReview.reviews.post(
    connection,
    { body },
  );
  typia.assert(review);
  TestValidator.equals("user_id")(body.user_id)(review.user_id);
  TestValidator.equals("product_id")(body.product_id)(review.product_id);
  TestValidator.equals("content")(body.content)(review.content);
  TestValidator.equals("language_code")(body.language_code)(review.language_code);
  TestValidator.equals("verified_purchase")(body.verified_purchase)(review.verified_purchase);
  TestValidator.equals("archived")(false)(review.archived);

  // 2. (선택 구현) 검색/재조회 시 실제 존재 여부 검증: 리뷰 리스트/조회 API도 동일한 user/product로 재검색 해볼 수 있음 (추가 API 필요)
  // 예시: const found = await api.functional.communicationReview.reviews.list(...)
  // TestValidator.equals("리뷰 존재 여부")(true)(found.some(r => r.id === review.id));
  // (여기서는 생성 API에 대한 핵심 시나리오만 구현)

  // 3. 누락/비정상 데이터 검증: 필수값 누락 및 잘못된 UUID, content·language_code 빈 문자열 등
  const wrongCases: Partial<IReview.ICreate & { purpose: string }>[] = [
    { ...body, user_id: undefined, purpose: "user_id 누락" },
    { ...body, product_id: undefined, purpose: "product_id 누락" },
    { ...body, content: undefined, purpose: "content 누락" },
    { ...body, language_code: undefined, purpose: "language_code 누락" },
    { ...body, verified_purchase: undefined, purpose: "verified_purchase 누락" },
    { ...body, user_id: "invalid-uuid", purpose: "user_id 비정상값" },
    { ...body, product_id: "bad-uuid", purpose: "product_id 비정상값" },
    { ...body, content: "", purpose: "content 빈 문자열" },
    { ...body, language_code: "", purpose: "language_code 빈 문자열" },
    // 기타 필요에 따라 추가
  ];
  for (const wrong of wrongCases) {
    await TestValidator.httpError(String(wrong.purpose) || "잘못된 입력")(400)(() =>
      api.functional.communicationReview.reviews.post(connection, { body: wrong as any }),
    );
  }
}

