 *
 * 1. 새로운 리뷰를 생성한다 (POST /communicationReview/reviews)
 * 2. 생성된 id로 정상적으로 PUT /communicationReview/reviews/{id} 요청하여 값이 변경되고 응답에 반영되는지 확인
 * 3. 존재하지 않는 id(임의 UUID)로 PUT 요청 시 404 오류 반환 검증
 * 4. 유효하지 않은 필드(예: 긴 문자열 없는 content)로 PUT 요청 시 400 또는 422 등 적절한 오류 반환 확인
 */
export async function test_api_review_update_success_and_error_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. 리뷰 생성 (정상)
  const createBody: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    content: "초기 리뷰 본문입니다.",
    language_code: "ko",
    verified_purchase: true,
  };
  const created: IReview = await api.functional.communicationReview.reviews.post(connection, {
    body: createBody,
  });
  typia.assert(created);

  // 2. 정상 리뷰 수정(본문 및 언어 변경)
  const updateBody: IReview.IUpdate = {
    content: "수정된 리뷰 본문입니다.",
    language_code: "en",
  };
  const updated: IReview = await api.functional.communicationReview.reviews.putById(connection, {
    id: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("본문 반영 여부")("수정된 리뷰 본문입니다.")(updated.content);
  TestValidator.equals("언어 반영 여부")("en")(updated.language_code);
  TestValidator.equals("id 일치 여부")(created.id)(updated.id);

  // 3. 존재하지 않는 id로 PUT → 404 에러 검증
  const nonExistId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError("존재하지 않는 리뷰 id")(404)(() =>
    api.functional.communicationReview.reviews.putById(connection, {
      id: nonExistId,
      body: updateBody,
    })
  );

  // 4. content를 빈 문자열(유효하지 않은 값)로 PUT 시도 → 400/422 등 오류 확인
  const invalidBody: IReview.IUpdate = { content: "" };
  await TestValidator.error("content 값 누락/비정상")(() =>
    api.functional.communicationReview.reviews.putById(connection, {
      id: created.id,
      body: invalidBody,
    })
  );
}

test/features/api/review/test_archive_re:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import typia, { tags } from "typia";
import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";

/**
 * E2E Test: Archive (soft-delete) a review and check it no longer appears in lists or is marked deleted.
 *
 * 이 시나리오는 리뷰를 보관(soft-delete, archive) 처리한 후, 해당 리뷰의 archived 플래그가 true가 되었는지 확인하고,
 * 리스트 등에서 조회되지 않음(비노출)도 함께 검증합니다. 또한 존재하지 않는 리뷰 ID로 삭제를 시도했을 때 not found(존재하지 않음)
 * 에러가 반환되는지도 검증합니다.
 *
 * 1. 신규 리뷰를 생성
 * 2. 해당 리뷰를 archive(soft-delete)
 * 3. 반환된 리뷰에서 archived 플래그가 true로 세팅됐는지 확인
 * 4. (TODO) 전체 리뷰 리스트에서 해당 리뷰가 더 이상 노출되지 않음을 확인(테스트 구현 시 목록 API 필요)
 * 5. 무작위 UUID로 archive(soft-delete) 요청하여 404/NotFound 에러 반환 확인
 */
export async function test_api_review_archive_and_notfound(
  connection: api.IConnection,
): Promise<void> {
  // 1. 신규 리뷰 생성
  const createInput: IReview.ICreate = {
    user_id: typia.random<string & tags.Format<"uuid">>(),
    product_id: typia.random<string & tags.Format<"uuid">>(),
    content: "Test review for archive flow.",
    language_code: "en",
    verified_purchase: true,
  };
  const review: IReview = await api.functional.communicationReview.reviews.post(connection, {
    body: createInput,
  });
  typia.assert(review);
  TestValidator.equals("archived flag - initially false")(false)(review.archived);

  // 2. 리뷰의 archive(soft-delete) 요청
  const archived: IReview = await api.functional.communicationReview.reviews.eraseById(connection, {
    id: review.id,
  });
  typia.assert(archived);
  TestValidator.equals("archived flag - after archive")(true)(archived.archived);

  // 3. archived 반환값 archived=true 확인
  // 이미 위에서 flag 확인

  // 4. (TODO): 목록 API가 있을 경우, archived 리뷰가 노출되지 않는지 확인 필요
  // 해당 프로젝트에 목록 API가 없다면 생략, 추가되면 구현

  // 5. 존재하지 않는 리뷰 ID로 삭제 시도 시 404에러 검증
  await TestValidator.httpError("archive non-existent review - not found")
    (404)(() => api.functional.communicationReview.reviews.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // 확률적으로 존재하지 않을 만한 UUID 사용
    }));
}

test/features/api/review-media/test_list:
import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IReview";
import { IReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IReviewMedia";
import { IPageIReviewMedia } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIReviewMedia";
import typia from "typia";

/**
 * Validate review media listing with filters and pagination.
 *
 * 1. Create several reviews (to attach media records to).
 * 2. Create media records for these reviews (with varying media_type and alt_text).
 * 3. Retrieve review media with no filter (should return all media).
 * 4. Retrieve by specific review_id (should return only media for that review).
 * 5. Retrieve by specific media_type (e.g., 'image', 'video').
 * 6. Retrieve by specific alt_text (partial filter).
 * 7. Retrieve using a filter that matches nothing (nonsense review_id).
 * 8. Validate that pagination metadata and content match expected values for each case.
 */
export async function test_api_review_media_list_with_filters_and_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create several reviews
  const reviews: IReview[] = [];
  for (let i = 0; i < 3; ++i) {
    const created = await api.functional.communicationReview.reviews.post(
      connection,
      {
        body: {
          user_id: typia.random<string>(),
          product_id: typia.random<string>(),
          content: `Review content ${i}`,
          language_code: i === 0 ? "en" : "ko",
          verified_purchase: i % 2 === 0,
        } satisfies IReview.ICreate,
      },
    );
    typia.assert(created);
    reviews.push(created);
  }

  // 2. Create review media for each review
  const allMedia: IReviewMedia[] = [];
  const mediaConfigs = [
    { media_type: "image", uri: "https://cdn.test/img1.png", alt_text: "product photo", sequence: 1 },
    { media_type: "image", uri: "https://cdn.test/img2.png", alt_text: "detail shot", sequence: 2 },
    { media_type: "video", uri: "https://cdn.test/vid1.mp4", alt_text: "unboxing", sequence: 3 },
    { media_type: "image", uri: "https://cdn.test/img3.png", alt_text: "box", sequence: 4 },
  ];
  // Distribute configs across reviews
  for (let i = 0; i < mediaConfigs.length; ++i) {
    const review = reviews[i % reviews.length];
    const config = mediaConfigs[i];
    const created = await api.functional.communicationReview.reviewMedia.post(
      connection,
      {
        body: {
          review_id: review.id,
          media_type: config.media_type,
          uri: config.uri,
          alt_text: config.alt_text,
          sequence: config.sequence,
        } satisfies IReviewMedia.ICreate,
      },
    );
    typia.assert(created);
    allMedia.push(created);
  }

  // 3. Retrieve all media (no filter)
  const listAll: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(
    connection,
    {
      body: {},
    },
  );
  typia.assert(listAll);
  // Should contain at least the 4 created above
  const allIds = allMedia.map((m) => m.id).sort();
  const listedIds = listAll.data.map((m) => m.id).filter((id) => allIds.includes(id)).sort();
  TestValidator.equals("all media match")(allIds)(listedIds);

  // 4. Retrieve by review_id (use the first review)
  const listByReview: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(
    connection,
    {
      body: { review_id: reviews[0].id },
    },
  );
  typia.assert(listByReview);
  const expectedReviewMedia = allMedia.filter((m) => m.review_id === reviews[0].id);
  TestValidator.equals("media for review")(expectedReviewMedia.map((m) => m.id).sort())(listByReview.data.map((m) => m.id).sort());

  // 5. Retrieve by media_type 'video'
  const listVideos: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(
    connection,
    {
      body: { media_type: "video" },
    },
  );
  typia.assert(listVideos);
  const expectedVideoMedia = allMedia.filter((m) => m.media_type === "video");
  TestValidator.equals("media_type=video")(expectedVideoMedia.map((m) => m.id).sort())(listVideos.data.map((m) => m.id).sort());

  // 6. Retrieve by alt_text 'box'
  const listByAlt: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(
    connection,
    {
      body: { alt_text: "box" },
    },
  );
  typia.assert(listByAlt);
  const expectedAltMedia = allMedia.filter((m) => m.alt_text === "box");
  TestValidator.equals("alt_text=box")(expectedAltMedia.map((m) => m.id).sort())(listByAlt.data.map((m) => m.id).sort());

  // 7. Query with nonsense filter (no matches)
  const listNone: IPageIReviewMedia = await api.functional.communicationReview.reviewMedia.patch(
    connection,
    {
      body: { review_id: "11111111-2222-3333-4444-555555555555" },
    },
  );
  typia.assert(listNone);
  TestValidator.equals("empty query")([] as IReviewMedia[])(listNone.data);

  // 8. Check basic pagination metadata (not strictly verifying all, but sanity check)
  TestValidator.equals("pagination exists")(true)(!!listAll.pagination);
  TestValidator.equals("pagination has total records")(true)(typeof listAll.pagination.records === "number");
}
